    /** СТРЕЛОК ЗА МИЛИ (v165): правило рядов, которое даёт расстановка, перенесённое в раздачу клеток. Лежало
     *  ВЫКЛЮЧЕННЫМ с выводом «расстановка осталась работать, предмета нет» — и вывод оказался неверным (v183). Замер
