    private var enemyDamageTaken = 0                      // снято с него за матч
    private var lastEnemyHitsTotal = -1
    /** Тик, с которого строй ждёт готовности (см. FORM_PATIENCE); -1 — не ждёт. */
    private var formWaitSince = -1
    private val lostTick = HashMap<String, Int>()   // потеря хитов за прошлый тик по всей армии, снятая до обновления lastHits (v109)
    private var coreShortTicks = 0                  // тиков подряд ядро без отряда ниже порога (см. USE_RECALL_PERSIST)
    private var scatteredLatched = false            // «рассыпан» с гистерезисом (см. USE_SCATTER_HYSTERESIS)
    private var scatteredAtRelease = false          // ярлык «рассыпан» на момент выпуска отряда (см. USE_RECALL_REF_LATCH)
    private var farmerOffTicks = 0                  // тиков подряд без признака фермера (см. FARMER_OFF_TICKS)
    private val ghostLogged = HashMap<String, Int>()
    private class Shooter(val cell: Int, val ranged: Double, val melee: Double)
    private var prevShooters: List<Shooter> = emptyList()

    // ---------- счёт ----------
    private var ourScore = 0.0
    private var enemyScore = 0.0
    private var ourRate = 0
    private var enemyRate = 0
    /** По прогнозу (счёт + темп × остаток) мы проигрываем: очки важнее силы (см. captureAllowed). */
    private var behindOnScore = false
    /** Сколько тиков подряд отстаём по прогнозу (см. BEHIND_PATIENCE). */
    private var behindTicks = 0
    private var lastEffectsKey = ""
    private var lastBodiesKey = ""

    private val flowFull = HashMap<Int, Boolean>()   // поле посчитано целиком (не ограничено NEAR_FLOW), см. flowTo/v131b
    private var flowSig = 0                            // подпись препятствий, при которой считан кэш
    /** Срок жизни поля к неподвижной цели (флаг, дом, угол): препятствия поля — стены, чужие рампарты, спавны,
     *  неподвижные крипы и чужие флаги — меняются редко, а считались поля каждый тик: 21–24 BFS в тик в гуще боя
     *  (семь флагов для выбора цели, девять точек выхода, цели крипов) — и три живых таймаута (матчи 16–18). Поле к
     *  цели-крипу (см. NEAR_FLOW) живёт один тик; смена подписи препятствий сбрасывает весь кэш. */
    private const val FLOW_TTL = 5
    /** ТИК В ЛИМИТЕ НА ХОЛОДНОЙ VM (v131). Живой замер прибором cpu (07.09.2026, два матча): лимит 100 мс на тик (первый — 1000),
     *  тики 2–35 стоят 60–95 мс, второй тик вылетал за лимит в обоих матчах (в одном — ещё 277-й, в бою), после сотого — 20–45 мс;
     *  на стенде те же тики стоят 6–9 мс — холодный JIT даёт восьмикратный множитель на всё, а две самые тяжёлые фазы — кандидаты
     *  бегунов (семь флагов × поток, путь, стая, цена захвата на каждого бегуна КАЖДЫЙ тик: 25–61 мс живьём) и постура (26–44 мс).
     *  Две меры: (1) поле потока к клетке ФЛАГА живёт FLOW_TTL_FLAG тиков вместо FLOW_TTL — флаг не двигается, а смена препятствий
     *  сбрасывает кэш подписью (см. flowSig); поля с обходом опасности (avoid) и ближние (near) — как прежде; (2) страховка CPU —
     *  тик, уже стоящий дороже CPU_GUARD_MS, не пересчитывает кандидатов бегунов и оставляет им прежние флаги. Тёплые тики до
     *  страховки не доходят, и исходы стенда не меняются. Тик за лимитом теряет ВСЕ интенты — 14 крипов стоят один тик. */
    private const val FLOW_TTL_FLAG = 30
    private const val CPU_GUARD_MS = 50.0
    /** ...и сторож действует на BFS полей потока (v184): счётчик BFS_BUDGET считает ПОЛЯ, а не миллисекунды, и на
     *  втором тике матча их ещё мало — сторож срабатывал, а полное поле всё равно запускалось и роняло тик в
     *  `Script execution timed out` (пять матчей из двенадцати). Сверх времени поле считается ограниченным. */
    /** Бюджет полных полей в тик (поле «вблизи» — четверть): сверх него устаревшее поле отдаётся как есть, а НОВАЯ
     *  цель получает ограниченное поле (см. NEAR_FLOW) с пометкой «устарело» — полное досчитается следующим тиком в
     *  пределах бюджета. Без этого начало боя (клетки врагов для броска и добычи, точки уклонения, флаги, вычищенные
     *  из кэша за время боя) давало 16–17 полных полей одним тиком (стенд, счётчик bfs). */
    private const val BFS_BUDGET = 8.0
    private const val FLOW_KEEP = 60   // тиков без обращения — запись кэша вычищается (иначе рост на клетках целей)
    private var bfsCost = 0.0
    private var bfsMaxCost = 0.0
    private var bfsThisTick = 0
    private var bfsMaxTick = 0
    /** Предел стоимости пути для поля «вблизи» (см. DistanceMap.flowFieldTo): цели-крипы — лекарь, раненый, бросок,
     *  добыча — в нескольких клетках; крип за пределом получает полное поле. */
    private const val NEAR_FLOW = 24

    // ---------- модель ----------

    /** ЗАМЕР CPU (07.09.2026): в живых логах «Script execution timed out» на ПЕРВОМ тике в 12 матчах из 20 каждой серии — первый
     *  тик убивается лимитом (cpuTimeLimitFirstTick), и до этого дня у бота не было ни одной своей меры CPU (строка «cpu t=» —
     *  стендовая). На первых трёх тиках после каждой фазы печатается `cpu t=N <фаза>=мс` отдельной строкой — последняя строка перед
     *  таймаутом называет фазу, съевшую бюджет; раз в сто тиков — самый долгий тик с прошлой строки. getCpuTime() — наносекунды
     *  с начала тика (на стенде — по hrtime). */
    private var cpuMaxMs = 0.0
    private var cpuMaxTick = 0
    private var cpuSlowTicks = 0
    private val cpuPhases = ArrayList<Pair<String, Double>>()
    private const val CPU_SLOW_MS = 60.0   // a tick over this prints its phases (the limit is 100 ms; the first tick 1 000)
    private fun cpuMs(): Double = try { getCpuTime() / 1_000_000.0 } catch (e: Throwable) { 0.0 }
    private fun cpuMark(phase: String) { cpuPhases.add(phase to cpuMs()) }
    private fun cpuSummary() {
        val ms = cpuMs()
        if (ms > cpuMaxMs) { cpuMaxMs = ms; cpuMaxTick = getTicks() }
        if (ms > CPU_SLOW_MS) cpuSlowTicks++
        if (DEBUG_LOG && (getTicks() <= 3 || ms > CPU_SLOW_MS || getTicks() % 100 == 0)) {
            var prev = 0.0
            val parts = cpuPhases.joinToString(" ") { (ph, at) -> val d = at - prev; prev = at; "$ph=${(d * 10).toInt() / 10.0}" }
            println("cpu t=${getTicks()} total=${(ms * 10).toInt() / 10.0}ms: $parts")
        }
        cpuPhases.clear()
        if (DEBUG_LOG && getTicks() % 100 == 0) {
            println("cpu t=${getTicks()}: max=${(cpuMaxMs * 10).toInt() / 10.0}ms at t=$cpuMaxTick slow(>${CPU_SLOW_MS.toInt()}ms)=$cpuSlowTicks limit=${arenaInfo.cpuTimeLimit / 1_000_000}/${arenaInfo.cpuTimeLimitFirstTick / 1_000_000}ms")
            cpuMaxMs = 0.0; cpuMaxTick = 0; cpuSlowTicks = 0
        }
    }

    /** Отметка «тик открыт» (см. USE_ABORT_REPAIR) и пара прибора: оборванных тиков / записей, положенных обратно. */
    private var tickOpen = false
    private var abortTicks = 0
    private var abortEntries = 0
    /** Вес тела и живые MOVE на этот тик (см. USE_BODY_MEMO); чистятся в начале тика. */
    private val bodyWeightNow = HashMap<String, Int>()
    private val liveMovesNow = HashMap<String, Int>()

    fun tick() {
        if (tickOpen) repairAfterAbort()
        tickOpen = true
        tickBody()
        tickOpen = false
    }

    private fun repairAfterAbort() {
        abortTicks++
        var maps = 0; var sets = 0; var entries = 0
        for (owner in listOf<Any>(this, InfluenceMap, DistanceMap, TrafficManager, Executor, Forecast, Memory)) {
            val r = AbortRepair.repairFields(owner)
            maps += r.maps; sets += r.sets; entries += r.entries
        }
        abortEntries += entries
        println("abort t=${getTicks()}: the previous tick did not finish — $maps maps and $sets sets rebuilt in place ($entries entries)")
    }

    private fun tickBody() {
        bodyWeightNow.clear()
        liveMovesNow.clear()
        Executor.clear()
        flagFlipNow = false
        bfsMaxTick = maxOf(bfsMaxTick, bfsThisTick)
        bfsMaxCost = maxOf(bfsMaxCost, bfsCost)
        bfsThisTick = 0
        bfsCost = 0.0
        val nowT = getTicks()
        val dead = Memory.flowCacheTick.filterValues { nowT - it > FLOW_KEEP }.keys.toList()
        for (k in dead) { Memory.flowCache.remove(k); Memory.flowCacheTick.remove(k) }
        avoidCellsCache = null

        val myCreeps = getObjectsByPrototype(Creep::class).filter { it.my && it.exists }
        val enemyCreeps = getObjectsByPrototype(Creep::class).filter { !it.my && it.exists && !it.spawning }
        val active = myCreeps.filter { !it.spawning }
        val combatEnemies = enemyCreeps.filter { val p = InfluenceMap.profileOf(it); p.melee + p.ranged + p.heal > 0.0 }

        // дома сторон — стартовые центры армий: спавнов на карте нет, половины и пост считаются от них
        if (homePos == null && active.isNotEmpty()) homePos = centroidOf(active)
        if (enemyHomePos == null && enemyCreeps.isNotEmpty()) enemyHomePos = centroidOf(enemyCreeps)
        val home = homePos ?: centroidOf(active) ?: InfluenceMap.cell(50, 50)
        val enemyHome = enemyHomePos ?: InfluenceMap.cell(99 - home.x, 99 - home.y)

        val flags = collectFlags(myCreeps, enemyCreeps, combatEnemies)
        flagsNow = flags
        applyEffects(flags, myCreeps, enemyCreeps)
        accountScore(flags)

        if (!greeted) {
            greeted = true
            probe(flags, myCreeps, enemyCreeps, home, enemyHome)
        }
        // дамп карты — четырьмя частями по 25 строк на тиках 3–6 (см. logMap)
        if (DEBUG_MAP && mapMarks == null) captureMapMarks(flags, myCreeps, enemyCreeps)
        if (DEBUG_MAP && getTicks() in 3..6) logMap((getTicks() - 3) * 25)
        logBodies(myCreeps, enemyCreeps)

        // раненый (см. wounded): боец, потерявший всё оружие, остаётся в армии, пока жив хоть один ходячий лекарь —
        // лечение возвращает части (движок: части живы по сумме хитов, лечение идёт с хвоста тела: в матче 8 melee_1
        // из M5 с 416 хитами стал M8A8 к 199-му тику у одного лекаря); прежде он уходил «бегуном» за флагами и гиб
        val healersAlive = active.any { !hasWeapon(it) && hasHeal(it) && canMove(it) }
        fun wounded(c: Creep) =  healersAlive && !hasWeapon(c) && !hasHeal(c) && c.body.any { it.type == ATTACK || it.type == RANGED_ATTACK || it.type == HEAL }
        Memory.detachedIds.retainAll { id -> active.any { it.id == id && hasWeapon(it) && canMove(it) } }
        // ...и зачисленные КОМАНДИРОМ (v160, см. commandRace): его задание на захват действует так же, как detach —
        // иначе крип, посланный за флагом, остаётся бойцом строя и флага не берёт
        val takers = { id: String -> id in Memory.detachedIds || (id in Memory.cmdDetach) }
        val army = active.filter { (hasWeapon(it) || hasHeal(it) || wounded(it)) && !takers(it.id) }
        val runners = active.filter { (!hasWeapon(it) && !hasHeal(it) && !wounded(it)) || takers(it.id) }
        val immobile = active.filter { !canMove(it) }

        val walls = getObjectsByPrototype(StructureWall::class).filter { it.exists }
        val ramparts = getObjectsByPrototype(StructureRampart::class).filter { it.exists }
        val spawns = getObjectsByPrototype(StructureSpawn::class).filter { it.exists }
        val blocked: List<Position> = walls + ramparts.filter { it.my != true } + spawns + immobile
        val blockedForEnemy: List<Position> = walls + ramparts.filter { it.my != false } + spawns

        InfluenceMap.setProtectedCells(ramparts.filter { it.my == true }.mapTo(HashSet()) { it.x * 100 + it.y })
        InfluenceMap.setEnemyBlocked(blockedForEnemy.mapTo(HashSet()) { it.x * 100 + it.y })
        // ПОЛЯ ВЛИЯНИЯ (v204): строятся ОДИН раз за тик над одним множеством крипов — прежде commandFight
        // пересобирал ту же опасность пять раз за тик, по разу на замысел, и звал profileOf внутри цикла
        // по клеткам. Опасность клетки в раздаче читается отсюда (см. inc в commandFight).
        InfluenceMap.buildFields(active, enemyCreeps)
        // скауты врага: сколько их и сколько крипо-тиков они провели в дальности наших стволов. Знаменатель
        // большой при нулевом числителе — это и есть «мы их пропускаем», сказанное числом
        for (e in enemyCreeps) if (scoutFoe(e)) {
            scoutTicks++
            if (active.any { hasRanged(it) && getRange(it, e) <= RANGED_RANGE }) scoutReach++
        }
        // остовы: считаются ПОСЛЕ построения полей, чтобы потенциал тела уже был известен
        for (e in enemyCreeps) {
            val live = InfluenceMap.profileOf(e)
            val pot = InfluenceMap.potentialOf(e)
            val armable = pot.melee + pot.ranged > 0.0
            val disarmed = armable && live.melee + live.ranged <= 0.0
            if (disarmed) {
                disarmedFoe.add(e.id)
                hulkTicks++
                if (active.any { hasRanged(it) && getRange(it, e) <= RANGED_RANGE }) hulkInReach++
            } else if (e.id in disarmedFoe) {
                disarmedFoe.remove(e.id)
                if (live.melee + live.ranged > 0.0) hulkRevived++
            }
        }
        cpuMark("fields")
        val rawDanger = InfluenceMap.dangerCostMatrix(enemyCreeps, blocked)
        // флаг берётся тем, кто на него ВСТАЛ, — и любой шаг армии через чужой флаг был захватом: в матче 3 армия
        // на марше взяла D5 и второй A3 (occupant=none в журнале) и дралась при A×0.6 D×1.1 против врага, с
        // которого сама же сняла дебаффы. Не наш флаг — стена для всех, кроме назначенного на него
        val flagCells = flags.filter { !it.ours }.mapTo(HashSet()) { it.pos.x * 100 + it.pos.y }
        val flagBlocked = flags.filter { !it.ours }.map { it.pos }
        val blockSig = blocked.sumOf { it.x * 100 + it.y + 1 } * 31 + flagBlocked.sumOf { it.x * 100 + it.y + 1 }
        // смена препятствий: поля не удаляются, а помечаются устаревшими — сверх бюджета (см. BFS_BUDGET) идут как есть
        if (blockSig != flowSig) { for (k in Memory.flowCacheTick.keys.toList()) Memory.flowCacheTick[k] = -1000; flowSig = blockSig }
        val dangerMatrix = rawDanger.clone()
        for (c in flagCells) dangerMatrix.set(c / 100, c % 100, 255)
        val passiveEnemy = combatEnemies.isNotEmpty() && combatEnemies.all { stationaryFor(it) >= PASSIVE_TICKS }

        DistanceMap.syncWalls(walls.size)
        DistanceMap.ensureBuilt(home, enemyHome)
        cpuMark("built")

        cpuMark("prep")
        val ourCentroid = centroidOf(army.ifEmpty { active }) ?: home
        val enemyCentroid = centroidOf(combatEnemies.ifEmpty { enemyCreeps })
        val ctx = Ctx(home, enemyHome, myCreeps, active, army, runners, enemyCreeps, combatEnemies, blocked, rawDanger, dangerMatrix, flags, flagCells, flagBlocked, passiveEnemy, ourCentroid, enemyCentroid)

        enemyArrivalTicks(ctx)
        // предзагрузка (v131b): потоки ко всем флагам считаются на первом тике, чей лимит 1000 мс, — второй тик (лимит 100 мс,
        // холодный JIT, 60–95 мс живьём) находит их в кэше вместо семи BFS
        if (getTicks() == 1) { for (f in ctx.flags) flowTo(ctx, f.pos); cpuMark("prefetch") }
        cpuMark("arrival")
        plannedCaptures.clear()
        // доктрина «первый флаг — их» (см. EVADE_EQUAL_RATIO) — до бегунов: их захват идёт тем же гейтом
        // сомкнутая армия (см. MASS_RANGE): россыпь по флагам и клубок фермера — не бросок, хотя их части тоже идут к нам
        val armedNow = ctx.combatEnemies.filter { threatening(it, ctx.enemyCreeps) }
        val massedByShape = armedNow.size >= 6 && centroidOf(armedNow)?.let { c -> armedNow.count { getRange(it, c) <= MASS_RANGE } * 3 >= armedNow.size * 2 } == true
        // СОМКНУТ ТОТ, КТО ПРИХОДИТ ВМЕСТЕ (v226, см. USE_MASS_BY_ARRIVAL): колонна на марше двумя эшелонами (пять впереди,
        // четверо в пятнадцати клетках позади) по форме не сомкнута — центр масс лежит в зазоре, и «в MASS_RANGE от центра»
        // даёт ноль, — а к нам она приходит целиком за шесть тиков. Мера прихода: две трети его вооружённых не дальше
        // MASS_RANGE от ближайшего к нашей массе по расстоянию до неё
        val massedByArrival =  armedNow.size >= 6 && run {
            val d = armedNow.map { getRange(it, ctx.ourCentroid) }
            val near = d.minOrNull() ?: return@run false
            d.count { it - near <= MASS_RANGE } * 3 >= armedNow.size * 2
        }
        if (massedByArrival && !massedByShape) massArrivalAdded++
        val enemyMassed = massedByShape || massedByArrival
        // с гистерезисом: темп сближения ходит вокруг порога (колонна на марше то растягивается шире MASS_RANGE, то
        // замедляется), и без него уклонение сменялось стоянием каждые десять-тридцать тиков, пока враг шёл — матч 32:
        // EVADE 57, HOLD 69 при approach=84, EVADE 94, HOLD 109 при 42, EVADE 117, HOLD 122, контакт на 127-м и 12:0.
        // Начатый бросок кончается, когда враг взял флаг, замер, разошёлся или ушёл дальше EVADE_RANGE и не приближается
        val noEnemyFlag = ctx.flags.none { it.theirs }
        // блоб, идущий к СВОБОДНОМУ ФЛАГУ, а не на нас (v127, USE_RUSH_NOT_FLAG_BOUND): ближайший к его центру свободный флаг
        // не дальше нашего центра, и его темп к этому флагу не ниже темпа к нам — он на туре. Матч 5 серии 367–386 (MetalicaX#3):
        // с 10-го по 41-й rush=true, армия на посту, захваты под вето; он взял D5 на 41-м, R3 на 45-м, оба A3 на 60-м, наш
        // первый флаг — на 54-м. Бросок сквозь центр без захвата снова читается броском, когда его темп к флагу падает
        val rushSignal = !ctx.passiveEnemy && noEnemyFlag && approachRate >= APPROACH_RUSH && enemyMassed  
        if (rushSignal) { rushSignalAll++; if (!massedByShape) rushByArrival++ }
        val rushHold = unflaggedRushNow && !ctx.passiveEnemy && noEnemyFlag && armedNow.isNotEmpty() &&
            (approachRate > 0.0 || armedNow.any { getRange(it, ctx.ourCentroid) <= EVADE_RANGE })
        unflaggedRushNow = rushSignal || rushHold
        // бой близко — для ЗАХВАТОВ флаг врага не в счёт: «безфлаговый» бросок кончился на 39-м тике, когда его армия по пути
        // взяла D5, и скаут взял R3 на 42-м (матч 47, пятый бой с けろびー подряд с R×0.8); уклонение по-прежнему только от
        // безфлагового (флагованный слабее — с ним дерёмся), а дебафф перед боем не берём ни от кого
        // ...и «идёт ОН, а не мы» (v216, см. USE_RUSH_NEEDS_HIS_MOVE): тот же корректор, что уже стоит у строя
        // стрелков, — центр его вооружённых обязан сдвинуться за окно не меньше чем на четверть окна
        val hisCentreMoved =  (Memory.hisCentHist.size >= 2 && run {
            val a = Memory.hisCentHist.first(); val b = Memory.hisCentHist.last()
            maxOf(abs(a / 100 - b / 100), abs(a % 100 - b % 100)) >= APPROACH_WINDOW / 4
        })
        fightImminentNow = unflaggedRushNow ||
            (!ctx.passiveEnemy && approachRate >= APPROACH_RUSH && enemyMassed && hisCentreMoved)
        // ...и ЗАПОМИНАЕМ РАССТОЯНИЕ НА НАЧАЛО ПОДХОДА (v215, см. USE_RUSH_VETO_EXPIRES). Первая редакция срока
        // сравнивала с ТЕКУЩИМ расстоянием между центрами — а оно по мере подхода сокращается, то есть срок
        // ужесточался ровно наоборот и вето снималось в тот момент, когда бой действительно начинался: строка
        // match20:brawl+heals перестала проходить гейт (7 674:2 503 -> 12 310:18 500). Время, которое ему нужно,
        // чтобы дойти, задаётся расстоянием НА СТАРТЕ броска, и оно не меняется, пока бросок идёт
        if (fightImminentNow && fightImminentTicks == 0)
            rushStartDist = ctx.enemyCentroid?.let { getRange(ctx.ourCentroid, it) } ?: 0
        fightImminentTicks = if (fightImminentNow) fightImminentTicks + 1 else 0
        // враг рядом, но не воюет: армия с боем в досягаемости броска, и наши хиты не падали STALL_TICKS тиков подряд — фермер
        // (けろびー v5, матчи 51 и 57: шесть флагов к 82-му, 1400 тиков рядом без единого выстрела, 10804:22779 при 12 наших
        // против его 4 к концу); гейты боя в captureAllowed («в контакте», «бой близко») к нему не применяются, паритет —
        // применяется. Атакующий стреляет через несколько тиков после контакта, и счётчик не доходит до STALL_TICKS
        // по ВСЕМ нашим (v56): сумма по армии падала на хиты только что отряжённых в бегуны, «нас ударили» — и отряд распускался
        // на следующий же тик (стенд m28 farm+weak: 6 detached на 100-м, 0 на 101-м с hurt=0, трижды за матч)
        val ourHitsSum = ctx.myCreeps.sumOf { it.hits }
        val hurt = lastOurHits >= 0 && ourHitsSum < lastOurHits
        if (hurt) ourDamageTaken += lastOurHits - ourHitsSum
        lastOurHits = ourHitsSum
        val enemyNear = armedNow.any { e -> ctx.army.any { getRange(e, it) <= ENGAGE_RANGE + RANGED_RANGE } }
        noFireTicks = if (enemyNear && !hurt) noFireTicks + 1 else 0
        // фермер — не только «не стреляет», но и «держится дальше броска»: стоящий в 3–6 экран стенда тоже не стрелял, пока
        // мы стояли на своём флаге, и перехват превратил бой, который v38 выигрывала на 439-м, в стояние до конца матча
        // (m31 screen: 16000/16000 у обоих 800 тиков, проигрыш по очкам); враг в ENGAGE_RANGE — это бой, не перехват
        val enemyWithinReach = armedNow.any { e -> ctx.army.any { getRange(e, it) <= ENGAGE_RANGE } }
        enemyNotFightingNow =  noFireTicks >= STALL_TICKS && !enemyWithinReach
        if (hurt) lastHurtTick = getTicks()
        if (enemyWithinReach) { lastReachTick = getTicks(); if (firstReachTick < 0) firstReachTick = getTicks() }
        // «он подходил» для фермера — по NEAR, не по броску (v72): застенчивый лагерь стенда (camp+shy) держит девять клеток и в
        // восемь не входит никогда — вся цепочка фермера (отряды, порог гонки, стая не преграда) молчала 800 тиков при
        // pushing=true в девяти клетках от него (m30, 9615:23822)
        if (enemyNear && firstNearTick < 0) firstNearTick = getTicks()
        runRunners(ctx)
        cpuMark("runners")
        runArmy(ctx)

        // боевые интенты уходят в API до разрешения движения: стенд разрешает конфликты за клетку в порядке первого
        // интента крипа, и порядок «удар, затем ход» — часть тождества с эталоном v235 (движку порядок безразличен)
        TrafficManager.markOrdered(commandOf.keys)
        val moves = TrafficManager.resolve(active.filter { canMove(it) }, myCreeps + enemyCreeps)
        Arbiter.audit()
        Executor.run(moves)
        cpuMark("resolve")
        cpuSummary()
        InfluenceMap.pruneStances(myCreeps.mapTo(HashSet()) { it.id })
        // кто из врагов сдвинулся за тик — для признака «стоит на месте» (см. stationary)
        for (e in enemyCreeps) {
            val cell = e.x * 100 + e.y
            if (Memory.enemyPrevCell[e.id] != cell) Memory.enemyLastMove[e.id] = getTicks()
        }
        Memory.enemyLastMove.keys.retainAll { id -> enemyCreeps.any { it.id == id } }
        Memory.enemyPrevCell.clear()
        for (e in enemyCreeps) Memory.enemyPrevCell[e.id] = e.x * 100 + e.y
        // история движения — для ловимости (см. evasive)
        val armedCentroid = centroidOf(army.filter { hasWeapon(it) }.ifEmpty { army }) ?: ourCentroid
        Memory.ourCentroidHist.addLast(armedCentroid.x * 100 + armedCentroid.y)
        while (Memory.ourCentroidHist.size > CHASE_WINDOW) Memory.ourCentroidHist.removeFirst()
        for (e in enemyCreeps) {
            val h = Memory.enemyCellHist.getOrPut(e.id) { ArrayDeque() }
            h.addLast(e.x * 100 + e.y)
            while (h.size > CHASE_WINDOW) h.removeFirst()
        }
        Memory.enemyCellHist.keys.retainAll { id -> enemyCreeps.any { it.id == id } }
        if (DEBUG_LOG && getTicks() % LOG_EVERY == 0) {
            println("bfs t=${getTicks()} max=$bfsMaxTick cost=$bfsMaxCost")
            bfsMaxTick = 0
            bfsMaxCost = 0.0
        }
        if (DEBUG_LOG) logStuck(active, enemyCreeps)
        if (DEBUG_VISUALS) InfluenceMap.drawDebug(army, myCreeps, enemyCreeps)

        if (DEBUG_LOG && getTicks() % LOG_EVERY == 0) {
            val ours = ourPowerOf(army, combatEnemies)
            val theirs = enemyPowerOf(combatEnemies, army)
            println(
                "t=${getTicks()} army=${army.size} runners=${runners.size}(${Memory.detachedIds.size} detached) enemies=${enemyCreeps.size}/${combatEnemies.size} " +
                "reach=${army.count { hasWeapon(it) && hasRanged(it) && combatEnemies.any { e -> getRange(it, e) <= RANGED_RANGE } }}/${army.count { hasWeapon(it) && hasRanged(it) }} " +
                // разброс строя (v191): диаметр группы стрелков и сколько вооружённых стоят дальше поводка от своего
                // центра. Реплеи говорят, что стирание приходит на диаметре 21, а пат — на диаметре 3
                "spread=${army.filter { hasWeapon(it) && hasRanged(it) }.let { sh -> if (sh.size > 1) sh.maxOf { a -> sh.maxOf { b -> getRange(a, b) } } else 0 }}/${army.count { hasWeapon(it) && getRange(it, armedCentroid) > LEASH_RANGE }} " +
                // ...и отдельно ЛЕКАРИ за поводком (v202): именно они разъезжались, а прибор их не считал вовсе
                "hfar=${army.count { !hasWeapon(it) && hasHeal(it) && getRange(it, armedCentroid) > LEASH_RANGE }}/${army.count { !hasWeapon(it) && hasHeal(it) }} " +
                // ЛЕКАРИ СУДЯТСЯ ВЫЖИВАНИЕМ, А НЕ ДОСТАВЛЕННЫМ ЛЕЧЕНИЕМ (этап 7): v202 поднял лечение и дал 0:3.
                // Тело лекаря — h6m6, лечащие части СПЕРЕДИ, поэтому урон уничтожает именно их и первыми; замер
                // разгрома 3d97c4 говорит, что его лекари сохраняют 100 % лечащих частей, наши 8 %. hcov — доля
                // нужды, покрытая назначенными клетками: прибор раздачи, а не исхода
                "hparts=${myCreeps.filter { hasHeal(it) }.sumOf { c -> c.body.count { it.type == HEAL && it.hits > 0 } }}/${myCreeps.filter { hasHeal(it) }.sumOf { c -> c.body.count { it.type == HEAL } }} " +
                "ehparts=${enemyCreeps.filter { hasHeal(it) }.sumOf { c -> c.body.count { it.type == HEAL && it.hits > 0 } }}/${enemyCreeps.filter { hasHeal(it) }.sumOf { c -> c.body.count { it.type == HEAL } }} " +
                "hcov=${InfluenceMap.healCoverage().let { (left, total) -> "${(total - left).toInt()}/${total.toInt()}" }} " +
                "hulk=${disarmedFoe.size} hulkreach=$hulkInReach/$hulkTicks revived=$hulkRevived chase=${Memory.chaseOf.size}/$chaseTicks kills=$chaseKills " +
                "capgate=${capBlocked.values.sum()}/$capOffered cap=" + capBlocked.entries.sortedByDescending { it.value }.joinToString(",") { "${it.key}:${it.value}" } +
                " poised=$poisedTicks/$poisedAll edge=$edgeSpot/$edgeAll capopp=$capOppSum/$capAllSum" +
                " scout=$scoutShots/$scoutReach/$scoutTicks spotm=$spotMeleeTicks spothold=$spotHoldNew/$spotHoldAll sym=$symCore/$symFree " +
                "split=$splitFight/$splitAll recall=$recalled/$fightTicksNow healgap=$healGap/$healGapN nomedic=$noMedic/$healGapN flip=$aimFlips/$aimTicks aggro=$dangerBlind/$dangerBlindFar/$dangerMoves pushheld=$pushHeldTicks/$pushTicks lethal=$lethalHits/$lethalCells ledgerw=$ledgerWindow/$ourLostWindow/$hisLostWindow breakoff=$breakOffSplit/$breakOffN " +
                "race=${race100.ifEmpty { "-" }}/${race200.ifEmpty { "-" }} poisedcost=$poisedCost objnone=${objNone.entries.sortedByDescending { it.value }.joinToString(",") { "${it.key}:${it.value}" }}/$objAll " +
                "objdrop=${objDrop.entries.sortedByDescending { it.value }.joinToString(",") { "${it.key}:${it.value}" }}/$objDropN budget=$budgetSum/$budgetTicks " +
                "runner=${runnerMode.entries.sortedByDescending { it.value }.joinToString(",") { "${it.key}:${it.value}" }}/$runnerModeN " +
                "cmdwhy=${cmdWhy.entries.sortedByDescending { it.value }.joinToString(",") { "${it.key}:${it.value}" }}/$cmdWhyN " +
                "conc=$concSum/$concTicks concall=$concAll/$concAllTicks concmax=$concMax concfan=$fanShots/$fireShots " +
                "lostrace=$lostRaceOpened/$lostRaceOffers gather=$gatherSpread/$gatherHold close3=$closeHeld/$closeTicks guard=$guardFired/$guardTicks " +
                // приборы v221: тёплый контакт (пары к USE_FIGHT_BY_LEDGER), концентрация и цель мили, погоня за
                // кайтером, сбор в бою, и стрелки обеих сторон — «кто теряет стрелков первым», что реплей показал, а
                // консоль не показывала (имя `guns=` занято прибором v200)
                "warm=$warmTicks/$warmContact warmann=$warmAnn/$warmAnnAll warmhold=$warmHold/$warmAnn warmcmd=$warmCmd/$warmCmdAll warmfight=$warmFight/$warmFightAll warmcap=$warmCap/$warmCapAll " +
                "mconc=$mconcAll/$mconcTicks mconcmax=$mconcMax mpack=$mpackHit/$mpackAll pack=$packHeld/$packTicks mpackon=$mpackOnHit/$mpackOn kchase=$kchaseTicks/$kchaseAnn kveto=$kvetoHit/$kvetoAll gathera=$gatherAnn/$gatherAnnAll " +
                "annempty=${annEmpty.entries.sortedByDescending { it.value }.joinToString(",") { "${it.key}:${it.value}" }}/$annEmptyAll " +
                "shooters=${army.count { hasWeapon(it) && hasRanged(it) }}/${combatEnemies.count { hasRanged(it) }} abort=$abortTicks/$abortEntries ovw=${Executor.ovwContact}/${Executor.ovwRanged} conf=${Arbiter.confReach}/${Arbiter.confFatigue} rtr=$rtrRemoved/$rtrOld/$rtrAdded mquiet=$mquietMoved/$mquietAll/${mquietGain.toInt()} mquietc=$cmdQuietMoved/$cmdQuietAll maj=$majOpened/$majOffers surv=$survTicks/$survLead/$survContact/$survFights adr=$adrN/${(adrE / maxOf(adrN, 1)).toInt()}/${(adrT / maxOf(adrN, 1)).toInt()}/$adrSame fhl=$fhlChosen/$fhlAvail mrush=$rushByArrival/$rushSignalAll/$massArrivalAdded zlb=$zlbTicks/$zlbZero hwall=$hwallTicks/$hwallVictimTicks hwallh=$hwallHeals/$hwallHealsAll hwalla=$hwallAddr/$hwallVictimTicks hwallp=$hwallPredA/$hwallPredL/$hwallPredN postc=$postContest/$postAll rot=$rotOut mdir=$marchFlow/$marchAll/$marchFlip hfull=$hfullN/$hfullAll hover=$hoverSum/$hdelivSum hswap=$hswapN hexp=$hexpN/$hexpAll hlost=$hlostSum hatm=$hatmN/$hatmAll hatmc=$hatmCmd/$hatmCmdAll hpick=$hpN/$hpAdj/$hpAvail/$hpGate dh=${hpDelta.joinToString(",") { (it / maxOf(hpAvail, 1)).toInt().toString() }} " +
                "retr=$retrTicks/$retrWithPoint/$retrUnderFire standfire=$standFire/$standTicks outmw=$outmTicks/$outmRetreat " +
                    "score=${ourScore.toInt()}/${enemyScore.toInt()} rate=$ourRate/$enemyRate behind=$behindOnScore passive=$passiveEnemy flags=${flagsSummary(flags)} " +
                    "obey=$orderAuditOk/$orderAuditN branch=$orderBranch fled=$orderFled clash=$orderClash lost=stay$lostStay/stuck$lostStuck/foe$lostEnemy/fat$lostFatigue/else$lostElsewhere kite=$kiteNow massed=$kiteMassed plan=$planStrict/$planLoose cmd=${commandOf.size}/$cmdTicks:$cmdBlocked mode=$cmdMode disp=$dispNow evt=$stateEventTicks fire=${fireOf.size} posture=$posture obj=${objectiveFlagId?.let { id -> flags.firstOrNull { it.id == id }?.let { "(${it.pos.x},${it.pos.y})" } } ?: "-"} hunt=$huntingThreat rush=$unflaggedRushNow " +
                    "weak=$outmatchedTicks pat=$stalemateTicks/$patMax strip=$stripTicks touch=${(touchShare * 100).toInt()}/${(touchMin * 100).toInt()}/${(hisTouchShare * 100).toInt()} out=$outOfFireTicks back=$meleeBackTicks guns=$planGunsIn/$planGunsAll mheal=$planMeleeHealed/$planMeleeAll hline=$planHealBehind/$planHealAll our=${ours.toInt()} enemy=${theirs.toInt()} ledger=${enemyDamageTaken - ourDamageTaken} wounded=${army.count { !hasWeapon(it) && !hasHeal(it) }} hits=${army.sumOf { it.hits }}/${army.sumOf { it.hitsMax }} enemyHits=${combatEnemies.sumOf { it.hits }}/${combatEnemies.sumOf { it.hitsMax }} " +
                    "centroid=(${ourCentroid.x},${ourCentroid.y}) enemyCentroid=${enemyCentroid?.let { "(${it.x},${it.y})" } ?: "-"}"
            )
            // ПЕРЕПИСЬ (v203): только ненулевые ветки, накопительно за матч. Сумма stepCount обязана равняться
            // размеру армии, умноженному на число тиков, — если не равна, перепись врёт, и всё на ней построенное тоже
            println("rung t=${getTicks()}: why=" + rungCount.entries.sortedByDescending { it.value }.joinToString(",") { "${it.key}:${it.value}" } +
                " step=" + stepCount.entries.sortedByDescending { it.value }.joinToString(",") { "${it.key}:${it.value}" } +
                " pass=" + passCount.entries.sortedByDescending { it.value }.joinToString(",") { "${it.key}:${it.value}" } +
                " sum=${stepCount.values.sum()}")
            // ПОЛЯ: пики печатаются, чтобы обнулившееся поле было ВИДНО — прибор, умеющий сказать только
            // «поле построено», прибором не является
            if (FIELD_LOG) println("fld t=${getTicks()}: hdbf=${InfluenceMap.healDebuffStats()}" +
                " eM=${InfluenceMap.fieldPeak(InfluenceMap.eMelee).toInt()} eR=${InfluenceMap.fieldPeak(InfluenceMap.eRanged).toInt()}" +
                " eH=${InfluenceMap.fieldPeak(InfluenceMap.eHeal).toInt()} aM=${InfluenceMap.fieldPeak(InfluenceMap.aMelee).toInt()}" +
                " aR=${InfluenceMap.fieldPeak(InfluenceMap.aRanged).toInt()} aH=${InfluenceMap.fieldPeak(InfluenceMap.aHeal).toInt()}" +
                " eF=${InfluenceMap.fieldPeak(InfluenceMap.eFire).toInt()} atM=${InfluenceMap.fieldPeak(InfluenceMap.attMelee).toInt()}" +
                " atR=${InfluenceMap.fieldPeak(InfluenceMap.attRanged).toInt()} atH=${InfluenceMap.fieldPeak(InfluenceMap.attHeal).toInt()}" +
                // ЦЕЛЬ (этап 5): затравок в очаге, перестроек против удержаний очага, и — главное — доля решений
                // раздачи, которые слагаемое цели ИЗМЕНИЛО. flips=0 за сто тиков есть операционное определение
                // мёртвого кода
                " seeds=${goalSeeds.size} goal=(${goalCx},${goalCy}) rebuild=$goalRebuilds/$goalHolds flips=$goalFlips/$goalDecisions" +
                // ВОРОТА (этап 6): на каком пороге выживания крип нашёл клетку. gate5..gate1 — уровни лестницы,
                // fell — сколько раз клетки не нашлось даже при пороге в один тик и сработал общий добор. Это
                // посчитанная версия прежнего МОЛЧАЛИВОГО провала требования
                " gate=${gateLevels.drop(1).take(5).joinToString("/")} fell=$gateFell" +
                " intent=" + Memory.intentHist.entries.sortedByDescending { it.value }.joinToString(",") { "${it.key}:${it.value}" })
            concSum = 0; concTicks = 0
            if (getTicks() % (LOG_EVERY * 10) == 0) println(TrafficManager.audit())
        }
    }

    // ==================== зонд ====================

    /** Число из константы арены (внешнее объявление может оказаться undefined — тогда запасное). */
    private fun num(v: dynamic, fallback: Double): Double = if (jsTypeOf(v) == "number") v.unsafeCast<Double>() else fallback

    private fun probe(flags: List<FlagInfo>, myCreeps: List<Creep>, enemyCreeps: List<Creep>, home: Position, enemyHome: Position) {
        println(
            "hello season4 pain-and-gain $BOT_VERSION: ${arenaInfo.season} - ${arenaInfo.name} level=${arenaInfo.level} " +
                "ticksLimit=${arenaInfo.ticksLimit} cpu=${arenaInfo.cpuTimeLimit}/${arenaInfo.cpuTimeLimitFirstTick}"
        )
        // подпись сборки: по ней видно, какая версия играет, даже если строку версии забыли поднять
        println(
            "tuning: pushX=$PUSH_EXCHANGE parity=$PARITY_FLOOR/$CAPTURE_FLOOR/$PARITY_FLOOR_STALLED push=$PUSH_RATIO/$PUSH_RATIO_BEHIND " +
                "stall=$STALL_TICKS/$STALL_PICKET/$STALL_DAMAGE/$STALL_COOLDOWN march=$MARCH_STALL_TICKS rush=$APPROACH_RUSH/$EVADE_EQUAL_RATIO " +
                "mass=$MASS_RANGE leash=$LEASH_RANGE meleeHold=$MELEE_HOLD_RANGE press=$PRESS_RANGE/$PRESS_PACK/$PRESS_PATIENCE/$PRESS_CLOSING/$PRESS_GIVEUP healer=$HEALER_VALUE keep=$KEEP_RANGE/$KEEP_PICKET/$KEEP_RELEASE"
        )
        println(
            "pain-and-gain: TICKS_LIMIT=${num(TICKS_LIMIT.asDynamic(), -1.0)} MAX_SCORE_PER_TICK=${num(MAX_SCORE_PER_TICK.asDynamic(), -1.0)} " +
                "FLAG_TYPES=${try { JSON.stringify(FLAG_TYPES) } catch (t: Throwable) { "?" }} " +
                "EFF: attack=$EFF_ATTACK_MODIFIER ranged=$EFF_RANGED_ATTACK_MODIFIER heal=$EFF_HEAL_MODIFIER taken=$EFF_DAMAGE_TAKEN_MODIFIER " +
                "power: R=$RANGED_ATTACK_POWER A=$ATTACK_POWER H=$HEAL_POWER/$RANGED_HEAL_POWER"
        )
        println("flags: " + flags.joinToString(" ") { "(${it.pos.x},${it.pos.y})${typeChar(it.type)}${it.score}my=${it.mine}" })
        println("home=(${home.x},${home.y}) enemyHome=(${enemyHome.x},${enemyHome.y})")
        println("my creeps (${myCreeps.size}): " + myCreeps.joinToString(" ") { "${it.id}(${it.x},${it.y})${bodySummary(it)}${if (it.spawning) "S" else ""}" })
        println("enemy creeps (${enemyCreeps.size}): " + enemyCreeps.joinToString(" ") { "${it.id}(${it.x},${it.y})${bodySummary(it)}" })
        val walls = getObjectsByPrototype(StructureWall::class).size
        val ramparts = getObjectsByPrototype(StructureRampart::class).size
        val spawns = getObjectsByPrototype(StructureSpawn::class).size
        println("structures: walls=$walls ramparts=$ramparts spawns=$spawns")
        // тела целиком (с порядком частей) — по ним видно, что выдано, и что умрёт первым
        for (c in myCreeps) println("body ${c.id}: " + c.body.joinToString("") { partChar(it.type).toString() })
        for (c in enemyCreeps) println("enemy body ${c.id}: " + c.body.joinToString("") { partChar(it.type).toString() })
    }

    private fun partChar(type: BodyPartType): Char = when (type) {
        TOUGH -> 'T'; MOVE -> 'M'; RANGED_ATTACK -> 'R'; ATTACK -> 'A'; HEAL -> 'H'; CARRY -> 'C'; WORK -> 'W'
    }

    private fun typeChar(type: String): Char = when (type) {
        EFF_ATTACK_MODIFIER -> 'A'
        EFF_RANGED_ATTACK_MODIFIER -> 'R'
        EFF_HEAL_MODIFIER -> 'H'
        EFF_DAMAGE_TAKEN_MODIFIER -> 'D'
        else -> '?'
    }

    private fun flagsSummary(flags: List<FlagInfo>): String =
        flags.joinToString(",") { "${typeChar(it.type)}${it.score}${if (it.ours) "+" else if (it.theirs) "-" else "0"}${if (it.occupant != null) (if (it.occupant.my) "s" else "e") else ""}${if (it.guards.isNotEmpty()) "g${it.guards.size}" else ""}" }

    /** Состав армий (живые части) — при каждом изменении: видно потери и покалеченных. */
    private fun logBodies(myCreeps: List<Creep>, enemyCreeps: List<Creep>) {
        if (!DEBUG_LOG) return
        val key = myCreeps.joinToString(",") { bodySummary(it) } + "|" + enemyCreeps.joinToString(",") { bodySummary(it) }
        if (key == lastBodiesKey) return
        lastBodiesKey = key
        println("armies t=${getTicks()}: ours(${myCreeps.size}) " + myCreeps.joinToString(" ") { "${bodySummary(it)}h=${it.hits}" } +
            " | enemy(${enemyCreeps.size}) " + enemyCreeps.joinToString(" ") { "(${it.x},${it.y})${bodySummary(it)}h=${it.hits}" })
    }

    // ==================== флаги и эффекты ====================

    private fun collectFlags(myCreeps: List<Creep>, enemyCreeps: List<Creep>, combatEnemies: List<Creep>): List<FlagInfo> {
        val result = ArrayList<FlagInfo>()
        val all = getObjectsByPrototype(ScoreFlag::class).filter { it.exists }
        for (f in all) {
            val occupant = (myCreeps + enemyCreeps).firstOrNull { !it.spawning && it.x == f.x && it.y == f.y }
            val guards = combatEnemies.filter { getRange(it, f) <= FLAG_GUARD_RANGE }
            result.add(FlagInfo(f, f.my, f.effectType, f.scorePerTick, occupant, guards))
        }
        // журнал захватов: смена владельца и кто стоит на клетке — проверка механики «встал — захватил»
        for (fi in result) {
            val owner = if (fi.ours) 1 else if (fi.theirs) -1 else 0
            val prev = Memory.lastFlagOwner[fi.id]
            if (prev != null && prev != owner) flagFlipNow = true       // событие для стратега (v242)
            if (prev != null && prev != owner && DEBUG_LOG) {
                println("flag t=${getTicks()}: (${fi.pos.x},${fi.pos.y})${typeChar(fi.type)}${fi.score} owner ${ownerName(prev)} -> ${ownerName(owner)} occupant=${fi.occupant?.let { "${if (it.my) "my" else "enemy"} ${bodySummary(it)}" } ?: "none"}")
            }
            Memory.lastFlagOwner[fi.id] = owner
        }
        return result
    }

    private fun ownerName(code: Int) = when (code) { 1 -> "us"; -1 -> "enemy"; else -> "none" }

    /** Множитель стека по таблице арены: удар/стрельба 0.8 → 0.6, лечение 0.75 → 0.5, входящий 1.1 (флаг один);
     *  дальше — тем же шагом (в матче сверяется с effects крипов). */
    internal fun stackMul(type: String, count: Int): Double {
        if (count <= 0) return 1.0
        return when (type) {
            EFF_ATTACK_MODIFIER, EFF_RANGED_ATTACK_MODIFIER -> 1.0 - 0.2 * count
            EFF_HEAL_MODIFIER -> 1.0 - 0.25 * count
            EFF_DAMAGE_TAKEN_MODIFIER -> 1.0 + 0.1 * count
            else -> 1.0
        }.coerceAtLeast(0.0)
    }

    private fun sideModsOf(flags: List<FlagInfo>, mine: Boolean): InfluenceMap.SideMods {
        fun n(type: String) = flags.count { it.mine == mine && it.type == type }
        return InfluenceMap.SideMods(
            attack = stackMul(EFF_ATTACK_MODIFIER, n(EFF_ATTACK_MODIFIER)),
            ranged = stackMul(EFF_RANGED_ATTACK_MODIFIER, n(EFF_RANGED_ATTACK_MODIFIER)),
            heal = stackMul(EFF_HEAL_MODIFIER, n(EFF_HEAL_MODIFIER)),
            taken = stackMul(EFF_DAMAGE_TAKEN_MODIFIER, n(EFF_DAMAGE_TAKEN_MODIFIER)),
        )
    }

    /** Эффекты сторон: по массиву effects крипов, если API его отдаёт, иначе по подсчёту флагов (таблица
     *  арены). Печатает то и другое при изменении — в матче они обязаны совпасть. */
    private fun applyEffects(flags: List<FlagInfo>, myCreeps: List<Creep>, enemyCreeps: List<Creep>) {
        val ours = sideModsOf(flags, true)
        val theirs = sideModsOf(flags, false)
        InfluenceMap.setSideMods(ours, theirs)
        val sample = myCreeps.firstOrNull { InfluenceMap.hasEffectsApi(it) }
        InfluenceMap.setOurTaken(if (sample != null) InfluenceMap.takenOf(sample) else ours.taken)
        val enemySample = enemyCreeps.firstOrNull { InfluenceMap.hasEffectsApi(it) }
        InfluenceMap.setTheirTaken(if (enemySample != null) InfluenceMap.takenOf(enemySample) else theirs.taken)
        if (DEBUG_LOG) {
            val key = "$ours|$theirs|${sample?.let { JSON.stringify(it.effects) }}|${enemySample?.let { JSON.stringify(it.effects) }}"
            if (key != lastEffectsKey) {
                lastEffectsKey = key
                println("effects t=${getTicks()}: byFlags ours=[$ours] theirs=[$theirs] api ours=${sample?.let { JSON.stringify(it.effects) } ?: "n/a"} theirs=${enemySample?.let { JSON.stringify(it.effects) } ?: "n/a"}")
            }
        }
    }

    private fun accountScore(flags: List<FlagInfo>) {
        val cap = num(MAX_SCORE_PER_TICK.asDynamic(), Double.MAX_VALUE)
        ourRate = minOf(cap, flags.filter { it.ours }.sumOf { it.score }.toDouble()).toInt()
        enemyRate = minOf(cap, flags.filter { it.theirs }.sumOf { it.score }.toDouble()).toInt()
        ourScore += ourRate
        enemyScore += enemyRate
        val remaining = maxOf(0, arenaInfo.ticksLimit - getTicks())
        behindOnScore = ourScore + ourRate * remaining < enemyScore + enemyRate * remaining
        behindTicks = if (behindOnScore) behindTicks + 1 else 0
        // СНИМОК ДЕБЮТА (v216): по собственному замеру файла забег решается в первые двести тиков, а все приборы
        // в доках сняты «по последнему тику матча». Две строки, которые называют забег там, где он решается
        if (getTicks() == 100) race100 = "$ourRate:$enemyRate"
        if (getTicks() == 200) race200 = "$ourRate:$enemyRate"
        if (DEBUG_LOG && getTicks() % 100 == 0) println("score t=${getTicks()}: our=${ourScore.toInt()} (+$ourRate/t) enemy=${enemyScore.toInt()} (+$enemyRate/t) behind=$behindOnScore lead=${(ourScore - enemyScore).toInt()} maxSwing=${(cap * remaining).toInt()}")
    }

    /**
     * Брать ли этот (не наш) флаг сейчас. Свой — да. Врага в поле нет — да. Иначе — по паритету (см. PARITY_FLOOR):
     * армия С ЭТИМ дебаффом не слабее армии врага (CAPTURE_FLOOR), а пока отрыва нет — не меньше PARITY_FLOOR их
     * мощи:
     * маргинальная цена по Ланчестеру с эффектами ОБЕИХ сторон — у флага стрельбы дешевеет только стрелковая
     * часть урона, у флага лечения растёт чистый урон врага по нам, у флага уязвимости тают хиты, а чужой флаг
     * ещё и возвращает врагу то, что снимал с него. Отставание по счёту флагов больше не открывает: оно
     * значит, что враг держит больше и слабее — ответ ему бой (PUSH_RATIO_BEHIND), а не ещё один дебафф
     * (матч 3: «отстаём» на 2 очка при 6:10 разрешило всё подряд). Исключение — последние LAST_CALL_TICKS:
     * бой уже не успеет, и очки решают.
     */
    /** ⚠️ Параметр `runner` снят в v216: он был объявлен у обеих функций и НИ РАЗУ не читался в теле
     *  `captureBlock`. `runRunners` передавал `runner = true`, и это не меняло ничего — у бегуна те же ворота, что
     *  у армии. Дифф отчёта по 135 сценариям пуст побайтово, как и обязан быть у мёртвого. */
    private fun captureAllowed(ctx: Ctx, f: FlagInfo): Boolean = captureBlock(ctx, f) == null

    /** Какие ворота держат захват — null, если разрешено (v135, прибор к разрезу `tools/flagcut.py`): пять ворот отказывали
     *  молча, и в логе стояло только POISED, поэтому нельзя было сказать, ЧТО именно держит бегуна в клетке от свободного
     *  флага. Условия и их порядок те же, что были в captureAllowed. */
    private fun captureBlock(ctx: Ctx, f: FlagInfo): String? {
        if (f.ours) return null
        if (capTick != getTicks()) { capTick = getTicks(); capSeen.clear() }
        if (f.id !in capSeen) capOffered++
        if (ctx.combatEnemies.isEmpty()) return null
        // седьмой флаг — никогда при живой его армии (v127, USE_NO_SEVENTH_FLAG): все дебаффы наши, ни одного его
        if (ctx.flags.count { it.ours } + 1 >= ctx.flags.size) return "seventh"
        // последний зов и при РАВНОМ счёте: ничья 0:0 после уклонения (см. EVADE_EQUAL_RATIO) отдана не будет
        val ticksLeft = arenaInfo.ticksLimit - getTicks()
        val losingAtTheEnd = (ourScore - enemyScore) + (ourRate - enemyRate) * ticksLeft <= 0
        if ((behindOnScore || losingAtTheEnd) && ticksLeft <= LAST_CALL_TICKS) return null
        // во время броска безфлаговой армии (см. unflaggedRushNow — тот же сигнал, что уводит армию в уклонение) флаг не берёт
        // НИКТО: бой через двадцать тиков, и дебафф ложится на него. Скаут брал R3 на 42–43-м тике во всех четырёх боях с
        // けろびー (матчи 38, 43, 44, 45) — −20 % стрелкам в решающем размене, — проходя порог паритета с запасом три очка мощи
        // (3967 против 3964: модель мощи считает мили полными, а их обезоруживают за первые двадцать тиков). Три очка в тик
        // за тридцать тиков против пятой части огня на весь бой
        // флаг перехвата (см. USE_INTERCEPT) открыт и в контакте с фермером, и при «бое близко»; остальные — нет
        val intercept = enemyNotFightingNow && f.id == interceptFlagId
        // «бой близко» закрывает НОВУЮ цель сразу, а УЖЕ выбранную снимает, лишь продержавшись RUSH_VETO_TICKS подряд (v114, матч
        // 277): его блоб, шагающий на 9–13 клетках, гонял темп подхода 31–63 % через порог 50 % каждые три тика, и цель D5 (ценность
        // 22–41) назначалась и снималась через тик — FLAG↔HOLD 17 раз за сто тиков, три шага к флагу и три назад, 520 тихих тиков
        // при отставании. Первый срез (вето целиком после 10 тиков) открывал флаги и настоящему броску — его темп тоже рвётся
        // (колонна растягивается): scatter m28 24317:18115 → 24316:24069, screen m32 −9515, army m35 из стирания в отрыв; при
        // вето только на новую цель бросок закрыт как прежде, а мигание не сбрасывает уже идущий захват
        // ...и та форма (v114b: вето сразу на новую цель, на уже идущую — после 10 тиков) тоже отвергнута: удержанная цель вела
        // армию к флагу навстречу НАСТОЯЩЕМУ броску — scatter m28 и screen m32 те же, camp m31 22868:22895 красный. Мера «он ходит,
        // а не бросается» в боте уже есть — простой «держит дистанцию» (окно DETACH_WINDOW, срабатывал в 277 на 221-м: «флаги до
        // 521» — и в этом окне цель мигала): простой снимает вето «бой близко», как снимает вето «в контакте» ниже
        // (USE_STALL_LIFTS_RUSH_VETO); настоящий бросок дистанцию сокращает и простоя не даёт
        // ⚠️ Здесь стояла `val current = f.id == objectiveFlagId` — объявлена и не читалась ни разу (остаток
        // отвергнутой липкости v114b). Снята в v215; дифф отчёта пуст побайтово, как и обязан быть у мёртвого
        // бегун берёт флаг НАШЕЙ половины и под броском (v128, USE_RUNNER_HALF_UNDER_RUSH): вето «бой близко» держало и скаутов —
        // матчи 5, 8, 19 серий 367–406: rush=true с 10-го по 39-й, бегуны 0 detached, наш первый флаг на 42–98-м при его шести к
        // 80–91-му; пол паритета ниже по-прежнему считает цену дебаффа
        // ...и у вето подхода есть СРОК (v215, см. USE_RUSH_VETO_EXPIRES). Доктрина безфлагового дебюта
        // (`unflaggedRushNow`) сроку не подлежит и остаётся глобальной
        val rushStale =  !unflaggedRushNow && fightImminentTicks > rushStartDist
        if (fightImminentNow && !rushStale && !intercept && !(stalledNow)) {
            // пара к погоне за кайтером (v221, см. kiteChaseSeen): сколько отказов доктрины безфлагового броска
            // выдано, пока мы гонимся за отходящим, который бьёт нас сильнее, чем мы его
            if (unflaggedRushNow) { kvetoAll++; if (kiteChaseSeen) kvetoHit++ }
            return capCount(f, if (unflaggedRushNow) "rush.unflagged" else "rush.approach")
        }
        if (fightImminentNow && rushStale) capCount(f, "rush.approach.expired")
        // в контакте флаги не берём, пока есть кому драться: дебафф ложится на идущий бой (матч 9: скаут взял R3 на 125-м
        // тике — −20% стрелкам в решающем размене ради трёх очков в тик); без стрелков защищать нечего, а очки — всё,
        // что осталось (стенд m4 sleeper: запрет при охоте за обломками отдал матч по очкам)
        // при бесплодной охоте (см. STALL_TICKS) контакт мнимый — висящие в трёх-шести клетках крипы россыпи мигали
        // контактом, и цель-флаг пропадала через тик после назначения (стенд m19 spread)
        // ...и ВЕТО КОНТАКТА СНИМАЕТСЯ, КОГДА МЫ ОТСТАЁМ ПО СКОРОСТИ ОЧКОВ (v180). Разбор семи поражений серии: пять из
        // них — не бой, а гонка, где обе армии целы, а мы держим ТРИ флага против его четырёх и набираем 10-12 очков в
        // тик против его 13-15. Вето контакта не давало взять четвёртый почти весь матч, а снималось лишь за
        // LAST_CALL_TICKS до конца — то есть после того, как отрыв уже сделан. Паритет мощи при этом остаётся: доктрина
        // не в том, чтобы не брать флаги, а в том, чтобы не брать их ценой армии
        // ...и снятие вето стоит АРМИИ, если брать флаг под его ударом без запаса: серия v180 дала 12-8 с рейтингом
        // +16, гонок-поражений стало три вместо пяти, но разгромов пять вместо двух — армия гибла к 200-300 тику.
        // Поэтому вето снимается только при ПЕРЕВЕСЕ, а не при простом паритете (v181)
        // ...и ЦЕЛАЯ АРМИЯ САМА ПО СЕБЕ ЕСТЬ ЗАПАС (v187, разбор Coldkimchi#2). Вето существует ради одного — не терять
        // армию за флаги; когда армия цела, оно защищает уже не её, а нулевой счёт. Против Coldkimchi#2 наша мощь
        // структурно ниже его (лечение блока перекрывает наш урон, потому Ланчестер и даёт нам около нуля), поэтому
        // порог CAPTURE_EDGE не берётся НИКОГДА, и матч кончается «обе армии целы, флаги 1:4, счёт 3 210:18 145».
        // Условие здесь не про мощь, а про потери: пока армия почти не тронута и мы отстаём по скорости очков, флаг
        // берётся. Дебафф флага ложится на владельца — эту цену считает паритетный пол ниже, он остаётся на месте
        val losingRace =  behindOnScore && enemyRate > ourRate &&
            (
                ourPowerOf(ctx.army, ctx.combatEnemies) >= enemyPowerOf(ctx.combatEnemies, ctx.army) * CAPTURE_EDGE)
        // ...и ПАТ СНИМАЕТ ВЕТО КОНТАКТА (v189): бой, в котором за целое окно ни одна сторона не потеряла заметной
        // доли хитов, армии не угрожает, а дебафф флага в нём ничего не решает — решают очки (см. stalemateNow)
        // ВЕТО КОНТАКТА — ПО МАССЕ АРМИИ, А НЕ ПО ЛЮБОМУ КРИПУ (v214, решение оператора: вето становится местным).
        // Контакт определялся в файле дважды: в runArmy по МАССЕ (см. massArmy), а здесь — по любому нашему
        // вооружённому на полной скорости. Одного отбившегося крипа, задетого его пикетом на другом конце карты,
        // хватало, чтобы закрыть разом ВСЕ семь флагов. Живой замер по 12 матчам: `contact` — 512 отказов в
        // поражениях против 99 в победах, то есть главный дискриминатор исхода.
        // ⚠️ Это НЕ отвергнутая правка про `enemyNear` (см. комментарий там же): та меняла постуру, из-за чего
        // висящий у хранителя враг переставал отменять цель-флаг, и m20 spread перешёл из победы в поражение.
        // Здесь меняется потребитель — гейт захвата, — а постура не трогается вовсе.
        val foes = ctx.combatEnemies.filter { threatening(it, ctx.enemyCreeps) }
        val mass = centroidOf(ctx.army)
        val contactArmy = if (mass == null) ctx.army else ctx.army.filter { getRange(it, mass) <= MASS_RANGE }
        if (!losingRace && !stalledNow && !intercept && contactArmy.any { fullSpeed(it) && hasWeapon(it) } && inContact(foes, contactArmy)) {
            // пара к вето контакта по размену (v221, только прибор): сколько отказов выдано контактом, в котором за
            // окно ни одна сторона не потеряла STALL_DAMAGE. Окно — прошлого тика: runRunners идёт раньше runArmy
            warmCapAll++; if (!exchangeLiveNow) warmCap++
            return capCount(f, "contact.mass")
        }
        // ...и отдельно считаем то, что этой правкой снято: стычка одиночки вне массы
        if (!losingRace && !stalledNow && !intercept && ctx.army.any { fullSpeed(it) && hasWeapon(it) } && inContact(foes, ctx.army))
            capCount(f, "contact.edge.lifted")
        // паритет (см. PARITY_FLOOR): не впереди или отрыв не растёт — флаг, оставляющий не меньше PARITY_FLOOR их
        // мощи; впереди с растущим отрывом — только не слабее
        // СИЛА ВРАГА ДЛЯ ЭТОГО ФЛАГА (v214, решение оператора: вето становится местным). Здесь стояло
        // `powerAfter(ctx, f)`, где сторона врага — ВСЯ его армия без учёта расстояния: крип в шестидесяти клетках
        // весил столько же, сколько стоящий вплотную. Дебафф флага глобален, поэтому его цену платит тот бой,
        // который РЕАЛЬНО случится, — это либо идущий бой (fightPack, «кто успевает прийти к нашей массе»), либо
        // бой за сам флаг (его боевые в FLAG_GUARD_RANGE, уже посчитаны в collectFlags как guards).
        // Кто не участвует ни в одном, не платит и не считается. Доктрина паритета остаётся: powerAfterFor
        // по-прежнему берёт нашу мощь С дебаффом флага против его без дебаффа и требует пол.
        // Взято дешёвое множество (guards вместо packAt): оно не стоит ни одного BFS. Если прибор capopp покажет,
        // что локализация мало что меняет, следующим шагом сюда войдёт packAt с полем пути к флагу.
        // ...и ПУСТО ЗНАЧИТ ПУСТО (v216, см. USE_EMPTY_OPP_MEANS_FREE): откат `.ifEmpty { ctx.combatEnemies }`
        // выключал локализацию ровно там, где она нужнее всего, — боя нет и флаг не охраняется
        val oppLocal = ctx.combatEnemies.filter { it.id in fightPackIds || f.guards.any { g -> g.id == it.id } }
        val opp = oppLocal
        capOppSum += opp.size
        capAllSum += ctx.combatEnemies.size
        val (ours, theirs) = powerAfterFor(ctx,
            ctx.army + ctx.runners.filter { hasWeapon(it) || hasHeal(it) },
            opp, f)
        // ИНВЕРСИЯ СНЯТА (v214). Здесь стояло `needed = ourScore <= enemyScore || ourRate <= enemyRate`, и когда
        // мы ВЕДЁМ по счёту и по темпу, пол становился CAPTURE_FLOOR = 1.0 — СТРОЖЕ, чем PARITY_FLOOR = 0.97 при
        // отставании. То есть выигранная позиция запрещала закреплять выигрыш. Замер по 12 живым матчам говорит,
        // что решают именно такие матчи: три поражения при ЖИВОЙ армии с разрывом 603, 1628 и 292 очка из ~18 000,
        // и одна победа с разрывом 168 — это 60–100 тиков ОДНОГО флага. Доктрина паритета остаётся: пол по-прежнему
        // сравнивает нашу мощь С дебаффом флага против его без дебаффа, просто перестаёт ужесточаться от того,
        // что мы впереди.
        // неподвижный враг — тоже армия: «пассивный» порог 0.95 пустил третий флаг против спящего, тот проснулся, и бой
        // при 0.96 был проигран (стенд m6 sleeper); порог один
        // проигранная гонка с тем, кто ни разу не ударил (v63, см. PARITY_FLOOR_LOST)
        val lostRace = lostRaceNow()
        val floor = if (lostRace) PARITY_FLOOR_LOST else if (stalledNow) PARITY_FLOOR_STALLED else PARITY_FLOOR
        // ПАРА К КЛАПАНУ (v218, см. lostRaceOpened): «послабление решило исход» — флаг прошёл по PARITY_FLOOR_LOST
        // и НЕ прошёл бы по PARITY_FLOOR. Считается ЗДЕСЬ, а не у признака, потому что вопрос прибора не «был ли
        // признак истинен», а «изменил ли он хоть один отказ»
        if (lostRace) {
            lostRaceOffers++
            if (ours >= theirs * floor && ours < theirs * PARITY_FLOOR) lostRaceOpened++
        }
        // ...и в ПАТУ паритетный пол тоже молчит: он сравнивает мощь, а в бою, где никто никого не убивает, мощь
        // обеих сторон ланчестером считается около нуля, и сравнивать нечего (v189)
        if (ours >= theirs * floor) return null
        // ФЛАГОВ БОЛЬШЕ ЦЕНОЙ НЕБОЛЬШОГО МИНУСА (v222, решение оператора, см. USE_FLAG_MAJORITY): армии СЕЙЧАС на паритете,
        // перевеса по флагам у нас нет, а этот флаг его даёт — минус ровно дебафф этого флага
        run {
            val side = ctx.army + ctx.runners.filter { hasWeapon(it) || hasHeal(it) }
            val oursNow = ourPowerOf(side, opp)
            val theirsNow = enemyPowerOf(opp, side)
            if (oursNow >= theirsNow * floor) {
                majOffers++
                val ourFlags = ctx.flags.count { it.ours }
                val hisFlags = ctx.flags.count { it.theirs }
                val ourAfter = ourFlags + 1
                val hisAfter = hisFlags - (if (f.theirs) 1 else 0)
                if (ourFlags <= hisFlags && ourAfter > hisAfter) {
                    majOpened++
                    return null
                }
            }
        }
        capCount(f, "parity")
        return "parity(${ours.toInt()}/${(theirs * floor).toInt()})"
    }

    /** Считает отказ один раз на пару «тик × флаг» и возвращает причину как есть. */
    private fun capCount(f: FlagInfo, why: String): String {
        if (capTick != getTicks()) { capTick = getTicks(); capSeen.clear() }
        if (capSeen.add(f.id)) { capBlocked[why] = (capBlocked[why] ?: 0) + 1 }
        return why
    }

    /** Проигранная гонка (v63/v88): проигрыш по проекции на конец матча при PASSIVE_TICKS без удара по нам (v99: одна и та же
     *  для порога захвата и для стаи у свободного флага, см. USE_LOST_RACE_PACK_PARITY). */
    private fun lostRaceNow(): Boolean {
        val ticksLeft = arenaInfo.ticksLimit - getTicks()
        val losingAtTheEnd = (ourScore - enemyScore) + (ourRate - enemyRate) * ticksLeft <= 0
        val quiet = lastHurtTick == 0 || getTicks() - lastHurtTick >= FARMER_QUIET   // тишина (v65, см. FARMER_QUIET)
        // КЛАПАН ПО РАЗМЕНУ, А НЕ ПО ТИШИНЕ (v218, решение оператора). Здесь стояло `quietShort` — «сто тиков
        // ПОДРЯД без единого полученного удара». Против бота, чей пикет нас постоянно задевает, такой тишины не
        // наступает никогда, и послабленный пол PARITY_FLOOR_LOST не открывался ни разу: разбор двадцати матчей
        // v217 дал 1531 отказ по паритету в поражениях против 40 в победах, а в проигранных забегах 582, 1753 и
        // 2407 — при том, что в けろびー#12 (#20) за все 1900 тиков не разменяно НИ ОДНОГО хита с обеих сторон.
        // Признак заменён на СОБСТВЕННОЕ определение боя в этом файле — `netDamage` (см. STALL_DAMAGE): «за
        // STALL_TICKS любая сторона потеряла STALL_DAMAGE хитов». Нового числа не заводится, и оно вычисляется
        // из живых хитов обеих сторон, а не названо под текущего соперника. По замеру делит правильно: в #20
        // окно показало ledgerw=0/0/0 (0 < 300 — клапан открыт), в аннигиляции #1 потери шли ~3000 за окно
        // (много больше 300 — клапан закрыт, доктрина паритета цела).
        // ⚠️ Доктрина НЕ меняется: пол по-прежнему сравнивает нашу мощь С дебаффом флага против его без дебаффа,
        // меняется только признак «бой идёт». Меру мощи оператор трогать запретил — она остаётся зажатой в ноль
        // его лечением, и это открытый предмет
        // ...и признак сужен до НАШИХ потерь (v218, замер гейта). Первая редакция брала `netDamage` целиком —
        // «за окно потеряла ЛЮБАЯ сторона», — и уронила две строки лагеря: match31:camp отрыв 5189 -> 2185,
        // match34:camp уничтожение с t=951 на t=1212. Причина в асимметрии: пока мы безнаказанно бьём лагерь,
        // потери есть У НЕГО, признак говорит «бой идёт», и строгий пол возвращается там, где мы ВЫИГРЫВАЕМ
        // бой. Пол существует ради одного — не потерять НАШУ армию за флаги; значит и спрашивать надо про наши
        // потери. Окно и порог те же (LEDGER_WINDOW = STALL_TICKS, STALL_DAMAGE), новых чисел по-прежнему нет
        val quietShort = ourLostWindow < STALL_DAMAGE || getTicks() - lastHurtTick >= PASSIVE_TICKS
        return losingAtTheEnd && quietShort
    }

    /** Флаги, на которые наши крипы уже шагают в ЭТОТ тик (см. planCapture): два захвата одним тиком — D5 армией и H4
     *  скаутом — каждый в отдельности проходил порог паритета, вместе дали 0.93 и разгром 12:0 (стенд m9 hunter, t=98). */
    private val plannedCaptures = HashSet<String>()
    private val NO_FLOW = IntArray(10000) { -1 }
    private var preyNearTicks = 0                         // тиков подряд с пикетом (см. STALL_PICKET) в досягаемости
    private var stallUntil = 0
    private var stalledNow = false                        // бесплодная охота (см. STALL_TICKS) — снимает и запрет захвата в контакте
    private var stalemateNow = false                      // отставание с меньшим темпом дольше BEHIND_PATIENCE (см. PARITY_FLOOR_LOST)
    private var standoffTicks = 0                         // тиков подряд стоящей линии врага (см. PRESS_PATIENCE)
    private var pressing = false                          // прижим включён (см. USE_PRESS)
    private var hisTouchShare = 1.0
    private var touchShare = 1.0                          // она же за окно; до заполнения окна — единица, чтобы вход в бой не менялся
    private var touchMin = 1.0                            // минимум за матч — прибор
    private var meleeBackTicks = 0                        // прибор: тиков, в которые мили ставился ПОЗАДИ строя (v195)
    private val rungCount = HashMap<String, Int>()        // перепись решений (v203): какая ветка ЦЕЛИ выбрана, сколько раз
    private val stepCount = HashMap<String, Int>()        // ...и какая ветка ШАГА
    private val passCount = HashMap<String, Int>()        // ...и какой проход раздачи командира сколько клеток назначил
    private var planGunsIn = 0; private var planGunsAll = 0        // прибор согласованности строя (v200)
    private var planMeleeHealed = 0; private var planMeleeAll = 0
    private var planHealBehind = 0; private var planHealAll = 0
    /** ЗОНД РАЗДАЧИ ЛЕКАРЕЙ (v224): раздач / выбрана клетка вплотную к бойцу вне его огня / такая свободная клетка была
     *  рядом, а выбрана другая / из них кандидат не прошёл ворота выживания; и средняя разница слагаемых оценки
     *  «выбранная минус кандидат» (положительная — слагаемое тянуло ОТ кандидата): притяжение, огонь, линия, экран,
     *  занятость, стоять, жилец, очаг. */
    private var hpN = 0; private var hpAdj = 0; private var hpAvail = 0; private var hpGate = 0
    private val hpDelta = DoubleArray(8)
    private var outOfFireTicks = 0                        // крипо-тиков, в которые мили уводился из его кольца
    private var stalemateTicks = 0                        // сколько тиков подряд бой не двигается ни в чью пользу
    private var stalemateGap = 0                          // тиков подряд без контакта (см. STALEMATE_GAP)
    private var patMax = 0                                // самый длинный пат за матч — прибор, чтобы правило не мерили вслепую
    private var stripTicks = 0                            // тиков, в которые залп сводился на ОДНОГО его лекаря
    /** Тик погони за целью прижима: дистанция от наших мили, клетка цели и клетка нашего ближайшего мили (см. PRESS_GIVEUP, v96). */
    private class ChaseSample(val d: Int, val eCell: Int, val meleeCell: Int)
    private val pressChase = HashMap<String, ArrayDeque<ChaseSample>>()  // погоня за целью прижима по тикам (см. PRESS_GIVEUP)
    private var yieldingTick = -1                        // последний тик, когда наша линия отступала (лог v96)
    private val pressGiveUp = HashMap<String, Int>()      // цель прижима, от которой отказались, → тик, до которого

    private fun planCapture(ctx: Ctx, step: Position?) {
        if (step == null) return
        ctx.flags.firstOrNull { !it.ours && it.pos.x == step.x && it.pos.y == step.y }?.let { plannedCaptures.add(it.id) }
    }

    /** Мощь сторон, если мы возьмём ещё этот флаг (и те, на которые уже шагаем в этот тик): наша — с их дебаффами;
     *  вражья — без них, если флаги были его. */
    private fun powerAfter(ctx: Ctx, f: FlagInfo): Pair<Double, Double> =
        powerAfterFor(ctx, ctx.army + ctx.runners.filter { hasWeapon(it) || hasHeal(it) }, ctx.combatEnemies, f)

    /** То же для заданной стороны и группы врага (v95: пул проверяет ядро без крипа с дебаффом его флага-цели). */
    private fun powerAfterFor(ctx: Ctx, side: List<Creep>, opp: List<Creep>, f: FlagInfo): Pair<Double, Double> {
        val taking = HashSet(plannedCaptures); taking.add(f.id)
        // и флаг-цель армии (v121): захват, который уже идёт, — часть состояния «после»
        fun mods(mine: Boolean): HypoMods {
            fun k(type: String): Double {
                val now = ctx.flags.count { it.mine == mine && it.type == type }
                // его флаги В ПОЛЁТЕ (v128, USE_HIS_FLAGS_IN_FLIGHT): свободный флаг с его вооружённым вплотную — его в состоянии «после»,
                // и пол паритета видит симметричный размен, а не наш дебафф против его чистой армии (гастролёр берёт D5 на 39–41-м)
                val after = ctx.flags.count { it.type == type && (if (mine) (it.ours || it.id in taking) else ((it.theirs && it.id !in taking))) }
                return stackMul(type, after) / stackMul(type, now).coerceAtLeast(0.01)
            }
            return HypoMods(ranged = k(EFF_RANGED_ATTACK_MODIFIER), melee = k(EFF_ATTACK_MODIFIER), heal = k(EFF_HEAL_MODIFIER), hits = 1.0 / k(EFF_DAMAGE_TAKEN_MODIFIER))
        }
        val ourMods = mods(true)
        val theirMods = mods(false)
        // для captureAllowed сторона — армия с вооружёнными и лечащими бегунами (v59): паритет захвата — страховка от
        // аннигиляции стороны, а отряженные в бегуны (см. USE_DETACH) живы и вооружены. Ядро без пяти отряжённых стояло в
        // паритете (2918 против 2954), захват был запрещён ВСЕМ, и четверо отряжённых 800 тиков стояли POISED в клетке от
        // свободных D5, A3, R3 и H4 — 3174:22931, двенадцатый проигрыш фермеру (матч 139); до отряда, при 1,41, захваты были
        // разрешены и скаутам
        return powerOf(side, opp, ourMods, theirMods) to powerOf(opp, side, theirMods, ourMods)
    }

    /** Цена флага в силе — доля нашей мощи, которая останется после захвата (1 — бесплатно): флаг лечения
     *  для армии почти без лекарей дёшев, флаг уязвимости стоит всем; дорогие берутся последними. */
    private fun captureCost(ctx: Ctx, f: FlagInfo): Double {
        if (f.ours || ctx.combatEnemies.isEmpty()) return 1.0
        // ОДИН СОСТАВ ПО ОБЕ СТОРОНЫ ДРОБИ (v216, см. USE_CAPTURE_COST_ONE_SIDE): знаменатель обязан считаться по
        // той же стороне, что и числитель в powerAfter, иначе отношение выходит больше единицы и обрезается в 1,0
        val side = ctx.army + ctx.runners.filter { hasWeapon(it) || hasHeal(it) }
        val now = ourPowerOf(side, ctx.combatEnemies)
        if (now <= 0.0) return 1.0
        return (powerAfter(ctx, f).first / now).coerceIn(0.0, 1.0)
    }

    // ==================== захватчики ====================

    /** Флаг, за которым стоит идти захватчику: не наш и без врага на клетке, или наш пустой (охрана клеткой). */
    private fun wantsRunner(f: FlagInfo): Boolean {
        val occ = f.occupant
        if (occ != null && !occ.my) return false
        return !f.ours || occ == null
    }

    private fun runRunners(ctx: Ctx) {
        val runners = ctx.runners
        Memory.idleRunnerIds.clear()
        if (runners.isEmpty()) { Memory.runnerFlag.clear(); return }
        Memory.runnerFlag.keys.retainAll { id -> runners.any { it.id == id } }
        val flagById = ctx.flags.associateBy { it.id }
        fun dbg(s: Creep, mode: String, f: FlagInfo?, step: Position? = null) {
            // ПРИБОР ЗАБЕГА (v216): все ветки поведения бегуна проходят ровно здесь, поэтому счёт стоит тут, а не
            // в каждой из них. Считается ВСЕГДА, независимо от DEBUG_LOG: прибор, который виден только в логе с
            // подробностями, нельзя сложить по серии
            val tag = mode.substringBefore(':')
            runnerMode[tag] = (runnerMode[tag] ?: 0) + 1
            runnerModeN++
            // ...и цена простоя В ОЧКАХ, а не в тиках: тик у флага, который нельзя взять, стоит его score.
            // Разбор v214 считал эту величину вручную («166 тиков x 3 очка ~ 500, матч проигран с разрывом 292»)
            if (tag == "POISED" && f != null) poisedCost += f.score
            if (DEBUG_LOG && getTicks() % LOG_EVERY == 0) {
                println("  r${s.id} (${s.x},${s.y}) ${bodySummary(s)} hits=${s.hits} $mode flag=${f?.let { "(${it.pos.x},${it.pos.y})${typeChar(it.type)}${it.score}my=${it.mine}" } ?: "-"} fatigue=${s.fatigue} step=${step?.let { "(${it.x},${it.y})" } ?: "stay"}${if (TrafficManager.isStuck(s.id)) " STUCK" else ""}")
            }
        }
        // назначение — глобальное жадное паросочетание по ценности (лучшая пара «захватчик-флаг» первой),
        // НЕ зависящее от порядка обхода: обход в порядке текущих назначений менял очерёдность от тика к
        // тику, два скаута по очереди отбирали друг у друга центральный флаг и полторы тысячи тиков
        // шагали туда-обратно на одной клетке, ни разу не выйдя за неё (матч 1). Взявший флаг идёт за
        // следующим НЕ НАШИМ; сидеть на своём — когда чужих свободных на всех не хватает
        class Cand(val runner: Creep, val flag: FlagInfo, val value: Double)
        val cands = ArrayList<Cand>()
        // страховка CPU (v131): тик уже дороже CPU_GUARD_MS — бегуны оставляют прежние флаги, кандидаты не пересчитываются
        val cpuGuard =  getTicks() > 1 && cpuMs() > CPU_GUARD_MS
        if (cpuGuard && DEBUG_LOG) println("cpu t=${getTicks()} guard: runners keep their flags (${(cpuMs() * 10).toInt() / 10.0}ms)")
        if (!cpuGuard) for (s in runners) {
            val currentId = Memory.runnerFlag[s.id]
            val armedRunner = hasWeapon(s)
            for (f in ctx.flags) {
                val occ = f.occupant
                // занято (чужим — ждём отряд; своим — тот и держит). Вооружённый бегун (отряд, см. USE_DETACH) идёт на флаг с
                // ОДИНОЧНЫМ врагом слабее себя — в матче 126 отряд стоял POISED в клетке от D5, пока на нём сидел его крип
                if (occ != null && occ.id != s.id) {
                    if (!armedRunner || occ.my) continue
                    val e = ctx.enemyCreeps.firstOrNull { it.x == f.pos.x && it.y == f.pos.y } ?: continue
                    if (ctx.enemyCreeps.any { it.id != e.id && getRange(it, f.pos) <= ENGAGE_RANGE }) continue
                    if (ourPowerOf(listOf(s), listOf(e)) <= enemyPowerOf(listOf(e), listOf(s))) continue
                }
                val flow = flowTo(ctx, f.pos)
                val ticks = pathTicks(s, flow, s.x * 100 + s.y)
                if (ticks >= Int.MAX_VALUE / 4) continue
                // стая у флага — охрана рядом И те, кто дойдёт до него раньше нас: скаут шёл к дальнему H4, пока
                // армия врага шла туда же, и вошёл в неё (матч 3, t=70–87); охраны в 11 клетках было мало.
                // Для вооружённого бегуна стая — только та, что сильнее его (v57)
                val pack = packAt(ctx, f.pos, flow, ticks)
                // тихий фермер бегуну не стая (v105, USE_FARMER_RUNNER_PACK_FREE); безоружному скауту — по-прежнему стая
                if (pack.isNotEmpty() &&
                    (!armedRunner || enemyPowerOf(pack, listOf(s)) >= ourPowerOf(listOf(s), pack))) continue
                // при охотнике (см. escapeFlows) флаг без выхода — карман: три безоружных крипа сидели на угловых флагах,
                // пока армия врага шла к ним, и были добиты по одному — последний на 545-м тике, аннигиляция при +5000
                // очков (матч 13)
                // СВОБОДНЫЙ ФЛАГ БЕГУНА (v130, USE_RUNNER_FREE_FLAG): вето запаса выхода не касается бегуна без оружия, если его ближайший
                // угрожающий крип дальше от флага, чем путь бегуна плюс порог его бегства (SCOUT_FLEE_TRIGGER): бегун дойдёт раньше,
                // чем угроза войдёт в его порог. Матч 407: армия 530 тиков в EVADE при его армии в 47 клетках, бегун scout_1 всё
                // время RESERVE — у каждого флага запас выхода отрицателен или неизвестен; бегун — M1 на 100 хитов, армию не тянет
                val hisNearestToFlag = ctx.combatEnemies.filter { threatening(it, ctx.enemyCreeps) }.minOfOrNull { getRange(it, f.pos) } ?: Int.MAX_VALUE / 4
                if (escapeFlows.isNotEmpty() && exitMargin(ctx, f.pos, ticks) < 0) continue
                // свой пустой флаг стоит половину — но СИДЯЩИЙ на нём закрывает клетку от чужих бегунов (матч 2:
                // центральный D5 забрал вражеский M1, пока армия уходила за соседним флагом, и вернуть его было
                // некому); чужой — двойной размен; флаг, который порог силы сейчас не разрешает, — пятую часть
                // (ждать у него можно, но сидеть на своём полезнее); дорогой по силе — позже дешёвого (см.
                // captureCost); текущий — с премией
                val gain = (if (f.ours) 0.5 * f.score else f.swing) * captureCost(ctx, f)
                val horizon = if (farmerQuietNow) maxOf(1, arenaInfo.ticksLimit - getTicks() - ticks).toDouble() else 1.0 / (ticks + 5)
                val value = gain * horizon *
                    (if (f.id == currentId) 1.25 else 1.0) * (if (!f.ours && !captureAllowed(ctx, f)) 0.2 else 1.0)
                cands.add(Cand(s, f, value))
            }
        }
        cpuMark("r.cands")
        cands.sortByDescending { it.value }
        val assigned = HashSet<String>()
        val taken = HashSet<String>()
        if (cpuGuard) for (s in runners) Memory.runnerFlag[s.id]?.let { id -> if (flagById[id] != null) { assigned.add(s.id); taken.add(id) } }
        for (c in cands) {
            if (c.runner.id in assigned || c.flag.id in taken) continue
            assigned.add(c.runner.id)
            taken.add(c.flag.id)
            Memory.runnerFlag[c.runner.id] = c.flag.id
        }
        // пары (v94): флаг со стаей, с которой один не справится, — двум ближайшим свободным вооружённым, если справятся вдвоём
        if (!cpuGuard) {
            for (f in ctx.flags) {
                if (f.ours || f.id in taken) continue
                if (f.occupant?.my == true) continue
                val free = runners.filter { it.id !in assigned && hasWeapon(it) }.sortedBy { getRange(it, f.pos) }.take(2)
                if (free.size < 2) continue
                val flow = flowTo(ctx, f.pos)
                val ticks = free.maxOf { pathTicks(it, flow, it.x * 100 + it.y) }
                if (ticks >= Int.MAX_VALUE / 4) continue
                val occ = ctx.enemyCreeps.filter { it.x == f.pos.x && it.y == f.pos.y }
                val pack = (packAt(ctx, f.pos, flow, ticks) + occ).distinctBy { it.id }
                if (pack.isEmpty()) continue
                if (ourPowerOf(free, pack) <= enemyPowerOf(pack, free)) continue
                if (escapeFlows.isNotEmpty() && exitMargin(ctx, f.pos, ticks) < 0) continue
                for (r in free) { assigned.add(r.id); Memory.runnerFlag[r.id] = f.id }
                taken.add(f.id)
            }
        }
        for (s in runners) if (s.id !in assigned) Memory.runnerFlag.remove(s.id)

        for (s in runners) {
            val f = Memory.runnerFlag[s.id]?.let { flagById[it] }
            val onIt = f != null && s.x == f.pos.x && s.y == f.pos.y
            val nearby = ctx.combatEnemies.filter { getRange(s, it) <= RANGED_RANGE + 2 }
            val underFire = InfluenceMap.damageAt(s.x, s.y, ctx.combatEnemies) > 0.0
            // мили-бегун (отряд) рубит вплотную (v57): healAndShoot за бегунов только стреляет, удар мили выдаёт цикл армии
            if (hasMelee(s)) ctx.enemyCreeps.filter { getRange(s, it) <= 1 }.minByOrNull { it.hits }?.let { Executor.attack(s, it) }
            // захватчик без замены: от врага «с боем» ближе SCOUT_FLEE_TRIGGER — прочь (пустой MOVE ходит клетку за тик и
            // по болоту, где стрелок вязнет), даже с флага: флаг останется нашим, пока враг сам на него не встанет
            val threats = ctx.combatEnemies.filter { getRange(s, it) <= SCOUT_FLEE_TRIGGER && threatening(it, ctx.enemyCreeps) }
            if (canMove(s) && (underFire || threats.isNotEmpty())) {
                // поиск пути бегства может не дать шага (скаут в матче 3 «бежал» на месте три тика и погиб) —
                // тогда жадно: соседняя клетка подальше от врагов и под меньшим огнём; в опасности шаг делается ВСЕГДА,
                // и на не лучшую клетку тоже: скаут у стены (4,40) «бежал» стоя тридцать тиков рядом с боем и погиб
                // (матч 12) — стоящего враг на равной скорости достаёт следующим тиком, идущего нет
                val foes = threats.ifEmpty { ctx.combatEnemies }
                val danger = underFire || nearby.isNotEmpty()
                val step = fleeStep(s, foes, ctx.dangerMatrix, SCOUT_FLEE_RANGE) ?: greedyFlee(ctx, s, foes, force = danger)
                if (step != null) TrafficManager.request(s, step, Arbiter.RUNNER_PRIORITY)
                dbg(s, "FLEE", f, step)
                continue
            }
            if (f == null) {
                // все флаги при деле: к армии, за её спиной
                val step = if (s.getRangeTo(ctx.ourCentroid) > POST_STANDOFF + 2) pathStep(s, ctx.ourCentroid, POST_STANDOFF + 2, crowdMatrixOf(ctx, -1)) else null
                if (step != null) TrafficManager.request(s, step, Arbiter.RUNNER_PRIORITY)
                Memory.idleRunnerIds.add(s.id)
                dbg(s, "RESERVE", null, step)
                continue
            }
            // выход закрывается (см. exitMargin): с флага — в лучшую точку выхода, пока устье открыто
            if (f != null && escapeFlows.isNotEmpty() && getRange(s, f.pos) <= 2 && exitMargin(ctx, f.pos, 0) < 0) {
                val to = runnerEscape(ctx, s)
                if (to != null) {
                    val step = pathStep(s, to, 1, ctx.dangerMatrix)
                    if (step != null) TrafficManager.request(s, step, Arbiter.RUNNER_PRIORITY)
                    dbg(s, "EXIT", f, step)
                    continue
                }
            }
            if (onIt) {
                dbg(s, if (f.ours) "HOLD" else "HOLD_WAIT", f)
                continue
            }
            // брать ли флаг сейчас (дебафф): нельзя — ждём рядом, шаг на клетку сделаем, когда станет можно
            val block = captureBlock(ctx, f)
            val allowed = block == null
            val range = if (allowed) 0 else 1
            // свой назначенный флаг открыт для шага, остальные не наши — стены (см. Ctx.flagCells)
            // при запрете захвата клетка флага — стена и для его же бегуна: путь к «зазору 1» шёл ЧЕРЕЗ флаг, и скаут брал R3
            // на 49-м при уклонении с 3-го (матч 56), как и в четырёх боях с けろびー до правила v34/v35
            // ПАРА ИДЁТ ВМЕСТЕ (v158): на флаг под стаей отправляются двое (см. USE_RUNNER_PAIRS), потому что один не
            // справится, — но шли они каждый своим путём и приходили порознь, то есть по одному против той же стаи.
            // Идущий впереди ждёт отставшего: тот же кулак, только на двоих
            val step = if (s.getRangeTo(f.pos) > range) pathStep(s, f.pos, range, crowdMatrixOf(ctx, if (allowed) f.pos.x * 100 + f.pos.y else -1)) else null
            if (step != null) { TrafficManager.request(s, step, Arbiter.RUNNER_PRIORITY); planCapture(ctx, step) }
            // прибор наблюдения 4: бегун дошёл до флага, и ему запрещено на него встать. Пара «стоя/всего с целью»
            poisedAll++
            if (!allowed && step == null) poisedTicks++
            dbg(s, if (allowed) "TO_FLAG" else "POISED:$block", f, step)
        }
    }

    // ==================== армия ====================

    /** Поле к цели; не наши флаги — стены (кроме самой цели: flowFieldTo всегда открывает целевую клетку). */
    private fun flowTo(ctx: Ctx, target: Position, avoid: Boolean = false, near: Boolean = false): IntArray {
        val key = target.x * 100 + target.y + (if (avoid) 10000 else 0) + (if (near) 20000 else 0)
        val now = getTicks()
        val hit = Memory.flowCache[key]
        val at = Memory.flowCacheTick[key]
        // долгий срок — только ПОЛНОМУ полю к флагу (v131b): поле, посчитанное сверх бюджета BFS, ограничено NEAR_FLOW клетками, и
        // в кэше на тридцать тиков оно тридцать тиков говорило бегунам и армии «пути нет» (blitz 4-4 → 2-6, входы 3 хуже / 0 лучше)
        val ttl = if (near) 1 else FLOW_TTL
        if (hit != null && at != null && now - at < ttl) return hit
        if (hit != null && bfsCost >= BFS_BUDGET) return hit   // сверх бюджета — устаревшее поле
        // ...и СВЕРХ ВРЕМЕНИ ТОЖЕ, а не только сверх счётчика BFS (v184). Счётчик считает поля, а не миллисекунды, и
        // на втором тике матча их ещё мало: первый тик тратит около 185 мс из тысячи (built 55, prefetch 28, plan 25),
        // сторож на втором честно срабатывает на 63 мс, а следом всё равно запускается ПОЛНОЕ поле — и тик уходит
        // целиком с `Script execution timed out` в bfs. В двенадцати тестовых играх это случилось в пяти, поровну в
        // победах и поражениях, то есть разгромов не объясняет, но тик пропадает даром
        val bounded = near || bfsCost >= BFS_BUDGET ||
            (now > 1 && cpuMs() > CPU_GUARD_MS)
        bfsThisTick++
        bfsCost += if (bounded) 0.25 else 1.0
        val f = DistanceMap.flowFieldTo(target, ctx.flagBlocked + (if (avoid) ctx.blocked + avoidCells(ctx) else ctx.blocked),
            maxDist = if (bounded) NEAR_FLOW else Int.MAX_VALUE)
        Memory.flowCache[key] = f
        flowFull[key] = !bounded
        Memory.flowCacheTick[key] = if (bounded && !near) -1000 else now
        return f
    }

    /** Клетки в AVOID_RANGE от СТОЯЩИХ боевых врагов — поле «в обход» ведёт мимо лагеря, а не сквозь него.
     *  Идущий враг не обходится: обход идущего навстречу разводил строй с поста в стороны за тик до
     *  столкновения, и рывок врага, прежде отбитый к 212-му тику, стал разгромом (стенд rush). */
    private var avoidCellsCache: List<Position>? = null
    private fun avoidCells(ctx: Ctx): List<Position> = avoidCellsCache ?: run {
        val seen = HashSet<Int>()
        val out = ArrayList<Position>()
        for (e in ctx.combatEnemies) for (dx in -AVOID_RANGE..AVOID_RANGE) for (dy in -AVOID_RANGE..AVOID_RANGE) {
            if (!stationary(e)) continue
            val x = e.x + dx; val y = e.y + dy
            if (x < 0 || y < 0 || x > 99 || y > 99) continue
            if (seen.add(x * 100 + y)) out.add(InfluenceMap.cell(x, y))
        }
        avoidCellsCache = out
        out
    }

    /** Поле к НЕ-вражеской цели (флаг, пост, сбор, отход): в обход врагов, если оттуда, где стоит крип, такой
     *  путь есть, иначе обычное (матч 2 на стенде: маршрут к дальнему флагу вёл через стоящий отряд врага). */
    private fun flowAvoiding(ctx: Ctx, target: Position, creep: Creep, near: Boolean = false): IntArray {
        val f = flowTo(ctx, target, true, near)
        return if (f[creep.x * 100 + creep.y] >= 0) f else flowTo(ctx, target, near = near)
    }

    /** Стая у цели: боевые враги рядом с ней и те, кто дойдёт до неё (своим телом по полю) не позже нас —
     *  из ХОДЯЧИХ: стоящий на месте STILL_TICKS тиков в стаю по «успеет дойти» не зачисляется (матч 1:
     *  армия врага не сделала ни шага за 1570 тиков, а «успевала» к каждому флагу, и армия простояла на посту). */
    private fun packAt(ctx: Ctx, pos: Position, flow: IntArray, ourTravel: Int): List<Creep> {
        // МЕМО СТАИ (v132): пути его крипов к клетке флага ходятся раз в тик на флаг и поле, а не на каждого бегуна: пять отцепленных
        // бегунов × семь флагов × одиннадцать его крипов давали ~150 000 шагов по полю за тик (фаза r.cands 52–73 мс из 80–99 мс боевого
        // тика, восемь таймаутов в матче с Coldkimchi 07.09). Результат тот же
        if (packTicksTick != getTicks()) { Memory.packTicksCache.clear(); packTicksTick = getTicks() }
        val key = pos.x * 100 + pos.y
        val cached = Memory.packTicksCache[key]?.takeIf { it.first === flow }
        val ticksOf = cached?.second ?: HashMap<String, Int>().also { m ->
            for (e in ctx.combatEnemies) if (!stationary(e)) m[e.id] = pathTicks(e, flow, e.x * 100 + e.y)
            Memory.packTicksCache[key] = flow to m
        }
        return ctx.combatEnemies.filter { getRange(it, pos) <= FLAG_GUARD_RANGE || (ticksOf[it.id]?.let { t -> t <= ourTravel } == true) }
    }
    private var packTicksTick = -1

    /** Сколько тиков враг не двигался (новый враг считается идущим). */
    private fun stationaryFor(e: Creep): Int = getTicks() - (Memory.enemyLastMove[e.id] ?: getTicks())

    /** Враг не двигался последние STILL_TICKS тиков. */
    private fun stationary(e: Creep): Boolean = stationaryFor(e) >= STILL_TICKS

    private class Objective(val flag: FlagInfo, val pack: List<Creep>, val value: Double, val travel: Int)

    /**
     * Флаг-цель армии: не наш, разрешённый к захвату; со стаей — по перевесу Ланчестера (ratio) и цене боя в
     * запасе хода группы (или в контакте); без стаи — просто идём. Ценность — очки размена за тик пути.
     * Текущая цель держится, пока проходит по мягкому порогу (гистерезис).
     */
    /** Враг, с которым есть бой: с уроном, либо лекарь, у которого рядом (в дальности лечения плюс шаг) свой с оружием
     *  в теле, живым или мёртвым (см. armedEnemies). */
    /**
     * МЕСТНЫЙ ПЕРЕВЕС В МАСШТАБЕ УДАРА. Поля влияния уже меряют это сами и строятся раз в тик (см. buildFields):
     * `ourBurstAt(его клетка)` — наш урон в тик ПО НЕМУ (мили штампуется радиусом 2, стрелок 3), `dangerAt(его
     * клетка)` — его урон по нашему крипу, вставшему рядом. Отношение и есть операторское «трое наших против
     * одного его»: 3×240 против его 240 читается как 3,0. Это два обращения к массиву, а не новая сущность.
     * Существующие `localAllies`/`localEnemies` меряют радиусы 8 и 11 — то есть почти всю армию, и потому на
     * вопрос «сильнее ли мы ЗДЕСЬ» ответить не могут.
     */
    /**
     * СКАУТ ВРАГА (v214, наблюдение оператора: «мы игнорируем крипов, у которых есть только мув-части — они
     * спокойно гуляют возле нашей армии, мы их пропускаем и не нападаем»). У каждой стороны их по два:
     * тело `M1h=100`, одна часть MOVE, сто хитов. Замер по записям: ОБА его скаута доживают до конца матча с
     * полными ста хитами, ни разу не обстрелянные, — и это они берут ему флаги.
     * Различитель точен и уже есть: `potentialOf` считает части ТЕЛА без проверки хитов, поэтому у остова
     * потенциал есть, а у скаута нулевой. Значит распоряжение v178 («разоружённый — не цель») не ослабляется
     * ни на йоту: оно про того, у кого оружие БЫЛО, а у скаута его не было никогда.
     */
    private fun scoutFoe(e: Creep): Boolean =
        InfluenceMap.potentialOf(e).let { it.melee + it.ranged + it.heal <= 0.0 } && canMove(e)

    private fun spotEdgeAt(e: Creep): Double {
        val k = e.x * 100 + e.y
        val d = InfluenceMap.dangerAt(k)
        return if (d <= 0.0) Double.MAX_VALUE else InfluenceMap.ourBurstAt(k) / d
    }

    private fun threatening(e: Creep, enemyCreeps: List<Creep>): Boolean {
        val q = InfluenceMap.profileOf(e)
        return q.melee + q.ranged > 0.0 || enemyCreeps.any { w -> w.id != e.id && getRange(w, e) <= HEAL_RANGE + 1 && w.body.any { it.type == ATTACK || it.type == RANGED_ATTACK } }
    }

    private fun chooseFlagObjective(ctx: Ctx, group: List<Creep>, pushRatio: Double, escapeNeeded: Boolean = false, onlyFlagId: String? = null): Objective? {
        if (group.isEmpty()) return null
        var best: Objective? = null
        for (f in ctx.flags) {
            objDropN++
            if (f.ours) { objDrop["ours"] = (objDrop["ours"] ?: 0) + 1; continue }
            if (onlyFlagId != null && f.id != onlyFlagId) { objDrop["cpu"] = (objDrop["cpu"] ?: 0) + 1; continue }   // страховка CPU (v131c)
            if (!captureAllowed(ctx, f)) { objDrop["gate"] = (objDrop["gate"] ?: 0) + 1; continue }
            // ЦЕЛЬ АРМИИ НЕ ДУБЛИРУЕТ ФЛАГ БЕГУНА (v216). Обе соседние раздачи это уже проверяют — `commandRace`
            // («флаг, взятый бегуном, не дублируем») и `grabberOf` (исключает флаг-цель), — а самая дорогая, цель
            // ВСЕЙ армии, не проверяла. При потолке в один-два работающих крипа на семи флагах дубль означает, что
            // работающий флаг остаётся ОДИН. Флаг, который бегуну брать запрещено, сюда всё равно не дойдёт: гейт
            // `captureAllowed` у них общий и стоит строкой выше
            // ...и только если бегун ДОЙДЁТ РАНЬШЕ. Первая редакция снимала флаг с любого назначения, и это
            // уронило гейт: строка match33:scatter перестала проходить, отрыв −33 691, три строки из 135 остались
            // без изменений. Причина: назначение `runnerFlag` держится и за убегающим, и за тем, кто стоит у флага
            // без права встать, — армия теряла цель, до которой бегун не дойдёт никогда
            val flow = flowTo(ctx, f.pos)
            val travel = group.maxOf { pathTicks(it, flow, it.x * 100 + it.y) }
            if (travel >= Int.MAX_VALUE / 4) { objDrop["nopath"] = (objDrop["nopath"] ?: 0) + 1; continue }
            if (escapeNeeded) {
                // покинутую точку уклонения армия не идёт «захватывать»: у R3 (13,49) счёт места упал, точка покинута — и
                // тут же выбрана целью в шести тиках, навстречу врагу (матч 12, t=188)
                val left = evadeLeft
                if (left != null && left.x == f.pos.x && left.y == f.pos.y) { objDrop["evadeLeft"] = (objDrop["evadeLeft"] ?: 0) + 1; continue }
                // только флаг с выходом (см. ESCAPE_MARGIN, REACTION_LAG): за H4 в угол (8,90) армия шла 52 тика, пока
                // враг шёл на неё с 80 клеток (матч 11); за R3 (13,49) — 41 тик вдоль западного края при спящем враге,
                // и тот пошёл на полпути (матч 12)
                if (exitMargin(ctx, f.pos, travel) < ESCAPE_MARGIN) { objDrop["exit"] = (objDrop["exit"] ?: 0) + 1; continue }
            }
            // ⚠️ ПРОБОВАНО И ОТВЕРГНУТО (матч 23): запрет марша длиннее, чем врагу дойти до нашей армии, когда мы впереди
            // с растущим отрывом. Ни одного проигрыша стенда он не предотвращает, а бот становится пассивен всякий раз,
            // когда ведёт: m23 rush 23279→21496, m22 wing 23180→21362, m17 wing 23638→21510, m7 sleeper 22462→20033.
            // Растянутую колонну чинит масса (см. MASS_RANGE), а не отказ от цели
            // стая без урона ничего не охраняет: три лекаря врага, лечащие друг друга, делали цену боя бесконечной для
            // ослабленной армии, и она 1500 тиков держала пост при шести свободных флагах (стенд m2 rush)
            val pack = packAt(ctx, f.pos, flow, travel).filter { threatening(it, ctx.enemyCreeps) }
            val current = f.id == objectiveFlagId
            val ratio = if (current) LOCAL_ENTER_RATIO else pushRatio
            // цена боя — гейт на ВХОД к охраняемому флагу (лазейка «уже в контакте» отправила армию к дальнему
            // флагу с девятью охранниками сквозь наступающую армию — стенд rush, t=61)
            // проигранная гонка (v99, USE_LOST_RACE_PACK_PARITY): стая у флага, у которого его вооружённых сейчас нет, — по паритету
            val ok = pack.isEmpty() || (farmerQuietNow) ||
                (ourPowerOf(group, pack) >= enemyPowerOf(pack, group) * ratio && fightCost(pack, group) <= group.maxOf { speedSlack(it) })
            if (!ok) { objDrop["pack"] = (objDrop["pack"] ?: 0) + 1; continue }
            objDrop["taken"] = (objDrop["taken"] ?: 0) + 1
            // гистерезис: текущая цель ценнее на четверть, чтобы не прыгать между равными; дорогой по силе — позже
            val value = f.swing * captureCost(ctx, f) / (travel + 10) * (if (current) 1.25 else 1.0)
            if (best == null || value > best.value) best = Objective(f, pack, value, travel)
        }
        return best
    }

    /** Точка отхода: дом и углы НАШЕЙ половины — достижимая и самая дальняя от центра армии врага (отход в
     *  дальний угол через всю карту вёл сквозь врага, и армию добивали по одному — стенд rush). */
    /** Враг уходит: за CHASE_WINDOW тиков отдалился от ТОГДАШНЕГО центра нашей армии больше чем на клетку. Кайтер
     *  держит дистанцию, и «дистанция до нас не растёт» его не выдаёт — выдаёт движение прочь от места, где мы были.
     *  Порог делает уходящим и блоб, шагнувший назад на две клетки: все двенадцать «неловимы» восемь тиков, huntable 0/12,
     *  наступление снято, армия к посту (матч 70, t=196–207, 223, 234, 554). ОТВЕРГНУТО стендом: порог «больше половины окна»
     *  (уходил дольше, чем стоял) — 66 строк хуже / 44 лучше: кайтеры добиваются медленнее на десятке карт (за ними гонятся
     *  дольше), россыпи m12/m19/m24/m29/m30 spread и m29/m30 farm из победы в проигрыш; гистерезис в самом наступлении —
     *  тоже (см. pushing). Открытая находка. */

    private fun evasive(e: Creep): Boolean {
        val h = Memory.enemyCellHist[e.id] ?: return false
        if (h.size < CHASE_WINDOW || Memory.ourCentroidHist.size < CHASE_WINDOW) return false
        val c0 = Memory.ourCentroidHist.first()
        val old = h.first()
        val cPos = InfluenceMap.cell(c0 / 100, c0 % 100)
        val oldPos = InfluenceMap.cell(old / 100, old % 100)
        return getRange(e, cPos) > getRange(oldPos, cPos) + 1
    }

    /** Ловим ли враг: вплотную к нашему вооружённому (MELEE_KEEP_RANGE), медленнее нашего самого быстрого или не
     *  уходит (см. evasive). Только за ловимым идут стая, охота, добивание и местный бросок (см. CHASE_WINDOW). */
    private fun catchable(e: Creep, armed: List<Creep>): Boolean {
        if (armed.any { getRange(e, it) <= MELEE_KEEP_RANGE }) return true
        // медленнее нас ТАМ, ГДЕ СТОИТ (v48): период на его клетке — в болоте тело с половиной MOVE ходит клетку в пять
        // тиков, и застрявший в болоте ловим, хотя на равнине он равен нам (матч 90, см. InfluenceMap.enemyOrigins)
        if (periodAt(e, e.x, e.y) > (armed.minOfOrNull { plainPeriod(it) } ?: 1)) return true
        if (!evasive(e)) return true
        return false
    }

    private fun retreatPoint(ctx: Ctx): Position {
        val enemy = ctx.enemyCentroid ?: return ctx.home
        // точка одна на весь отход, пока враг не ближе к ней, чем мы: смена точки на ходу ((3,96), потом (96,96))
        // развела армию по трём углам карты, и погоня добила всех поодиночке (матч 4)
        retreatTarget?.let { t -> if (getRange(t, enemy) > getRange(t, ctx.ourCentroid)) return t }
        val corners = listOf(InfluenceMap.cell(3, 3), InfluenceMap.cell(3, 96), InfluenceMap.cell(96, 3), InfluenceMap.cell(96, 96))
        // дом, пока враг не ближе к нему, чем мы; угол — только тогда: «выигрышный по дистанции» угол (3,96) в
        // матче 5 был ловушкой — армия отошла в него от кайтеров и была расстреляна, не имея куда шагнуть
        val enemyBetween = getRange(enemy, ctx.home) < getRange(ctx.ourCentroid, ctx.home)
        val candidates = if (enemyBetween) listOf(ctx.home) + corners.filter { DistanceMap.inOurHalf(it.x, it.y) } else listOf(ctx.home)
        var best = ctx.home
        var bestScore = Int.MIN_VALUE
        for (c in candidates) {
            val flow = flowTo(ctx, c)
            val reach = ctx.army.count { flow[it.x * 100 + it.y] >= 0 }
            if (reach == 0) continue
            // выигрыш дистанции от врага НА КЛЕТКУ ПУТИ: «самая дальняя от врага» точка (3,96) лежала за его
            // флангом — 66 клеток пути ради 62 дистанции, мимо его строя; дом в 17 клетках даёт 22
            val score = getRange(c, enemy) - getRange(c, ctx.ourCentroid)
            if (score > bestScore) { bestScore = score; best = c }
        }
        retreatTarget = best
        return best
    }

    /** Точки выхода: семь флагов и оба дома (углы — карманы, их нет; см. EVADE_SAFE). */
    /** Точки выхода: флаги, оба дома и ЧЕТЫРЕ угла карты. Флаги стоят между домами — на оси подхода врага, и с одними
     *  флагами «прочь» не существовало: уклонение от броска шло к R3 навстречу врагу 30 клеток и было поймано у флага
     *  (матч 34, t=3–57). Углы — то, что всегда лежит в стороне от оси. */
    private fun escapeCandidates(ctx: Ctx): List<Position> =
        ctx.flags.map { it.pos } + listOf(ctx.home, ctx.enemyHome) +
            // углы — только при броске: как постоянные кандидаты они меняли всякое уклонение (102 сценария в одну сторону,
            // 105 в другую, потеря армии m9 sleeper), а нужны они там, где флаги лежат на оси подхода
            (if (unflaggedRushNow) listOf(InfluenceMap.cell(3, 3), InfluenceMap.cell(3, 96), InfluenceMap.cell(96, 3), InfluenceMap.cell(96, 96)).map { passableNear(it) } else emptyList())

    /** Поля потока к точкам выхода и ход врага до каждой — раз в EVADE_EVAL_EVERY тиков (девять полей). */
    private fun refreshEscape(ctx: Ctx, armed: List<Creep>) {
        val now = getTicks()
        if (now - escapeAt < EVADE_EVAL_EVERY && escapeFlows.isNotEmpty()) return
        escapeAt = now
        escapeFlows.clear(); escapeTheirs.clear(); escapeNearest.clear()
        for (c in escapeCandidates(ctx)) {
            val key = c.x * 100 + c.y
            val flow = flowTo(ctx, c)
            escapeFlows[key] = flow
            var bestTicks = Int.MAX_VALUE / 4
            var bestCell = -1
            for (e in armed) {
                val t = pathTicks(e, flow, e.x * 100 + e.y)
                if (t < bestTicks) { bestTicks = t; bestCell = e.x * 100 + e.y }
            }
            escapeTheirs[key] = bestTicks
            escapeNearest[key] = bestCell
        }
    }

    /** Клетка после ticks шагов спуска по полю от start (враг идёт за нами к цели поля). */
    private fun projectAlong(flow: IntArray, start: Int, ticks: Int): Int {
        var cell = start
        var left = ticks
        while (left > 0 && flow[cell] > 0) {
            val cx = cell / 100; val cy = cell % 100
            var next = -1; var nv = flow[cell]
            for ((dx, dy) in DIRECTIONS) {
                val x = cx + dx; val y = cy + dy
                if (x < 0 || y < 0 || x > 99 || y > 99) continue
                val v = flow[x * 100 + y]
                if (v in 0 until nv) { nv = v; next = x * 100 + y }
            }
            if (next < 0) break
            cell = next; left--
        }
        return cell
    }

    /** Запас выхода из точки c при нашем прибытии туда через arrive тиков. Преследователь идёт ЗА НАМИ, к c, а не к
     *  выходам: ближайший к c враг проецируется по полю к c на approachRate × arrive шагов, и от этой клетки считается
     *  его путь к каждому другому выходу минус наш путь от c туда; лучший из них — запас. Фора «идёт к выходу
     *  мгновенно» браковала всякую цель при идущем на нас враге, и армия сидела дома до боя в кармане (стенд m10
     *  hunter, m8 army); без выхода точка — карман (матч 11). */
    private fun exitMargin(ctx: Ctx, c: Position, arrive: Int): Int {
        val ckey = c.x * 100 + c.y
        val flowC = escapeFlows[ckey] ?: return Int.MIN_VALUE / 2
        val start = escapeNearest[ckey] ?: return Int.MIN_VALUE / 2
        val theirsC = escapeTheirs[ckey] ?: return Int.MIN_VALUE / 2
        if (theirsC >= Int.MAX_VALUE / 4) return Int.MIN_VALUE / 2   // его путь неизвестен — выход не подтверждён (v54)
        // при броске (см. EVADE_EQUAL_RATIO) преследователь идёт за нами на ПОЛНОЙ скорости: проекция по замеренному
        // темпу (0.42 в паузе колонны) считала дом безопасным выходом, и армия ушла в свой угол под удар (матч 32)
        val rate = if (unflaggedRushNow) 1.0 else approachRate
        val pursuer = if (start < 0) -1 else projectAlong(flowC, start, minOf(theirsC, (rate * arrive).toInt() + REACTION_LAG))
        var best = Int.MIN_VALUE / 2
        for (d in escapeCandidates(ctx)) {
            if (d.x == c.x && d.y == c.y) continue
            val flow = escapeFlows[d.x * 100 + d.y] ?: continue
            val step = flowNear(flow, c)
            if (step < 0) continue
            val theirs = if (pursuer < 0) Int.MAX_VALUE / 4 else flowNear(flow, InfluenceMap.cell(pursuer / 100, pursuer % 100)).let { if (it < 0) Int.MAX_VALUE / 4 else it }
            best = maxOf(best, theirs - step)
        }
        return best
    }

    /** Значение поля в клетке или, если она закрыта (чужой флаг — препятствие в полях потока), в лучшей соседней плюс
     *  шаг: запас выхода читался в клетке чужого флага и был «нет пути» для всякого флага-цели (стенд m1 scouts). */
    private fun flowNear(flow: IntArray, p: Position): Int {
        val here = flow[p.x * 100 + p.y]
        if (here >= 0) return here
        var best = -1
        for ((dx, dy) in DIRECTIONS) {
            if (dx == 0 && dy == 0) continue
            val x = p.x + dx; val y = p.y + dy
            if (x < 0 || y < 0 || x > 99 || y > 99) continue
            val v = flow[x * 100 + y]
            if (v >= 0 && (best < 0 || v + 1 < best)) best = v + 1
        }
        return best
    }

    /** Точка уклонения (см. EVADE_SAFE): из точек выхода — с наибольшим счётом (меньший из запасов прибытия и выхода);
     *  где стоим — только пока счёт не меньше EVADE_SAFE; прежняя держится, пока не хуже лучшей на EVADE_HYSTERESIS;
     *  null — карман, уходить некуда. */
    /** Точка выхода для одиночного бегуна: лучшая по меньшему из запасов прибытия и выхода на ЕГО пути, не та, где он
     *  стоит (см. evadePoint для армии). */
    private fun runnerEscape(ctx: Ctx, s: Creep): Position? {
        var best: Position? = null
        var bestScore = Int.MIN_VALUE
        for (c in escapeCandidates(ctx)) {
            if (getRange(c, s) <= 2) continue
            val key = c.x * 100 + c.y
            val flow = escapeFlows[key] ?: continue
            val theirs = escapeTheirs[key] ?: continue
            val ticks = pathTicks(s, flow, s.x * 100 + s.y)
            if (ticks >= Int.MAX_VALUE / 4) continue
            val score = minOf(theirs - ticks, exitMargin(ctx, c, ticks))
            if (best == null || score > bestScore) { bestScore = score; best = c }
        }
        return best
    }

    private fun evadePoint(ctx: Ctx, armed: List<Creep>, strikers: List<Creep>): Position? {
        val now = getTicks()
        val cur = evadeTarget
        val arrived = cur != null && getRange(ctx.ourCentroid, cur) <= EVADE_ARRIVED
        if (cur != null && !arrived && now - evadeEvaluatedAt < EVADE_EVAL_EVERY) return cur
        evadeEvaluatedAt = now
        // прибыли в другую точку — покинутая снова допустима (см. evadeLeft)
        evadeLeft?.let { l -> if (arrived && cur != null && (cur.x != l.x || cur.y != l.y)) evadeLeft = null }
        val left = evadeLeft
        var best: Position? = null
        var bestScore = Int.MIN_VALUE
        var bestArrive = 0
        var bestExit = 0
        var curScore = Int.MIN_VALUE
        // при броске (см. EVADE_EQUAL_RATIO) выход обязан быть ПРОЧЬ: не ближе к центру вражеской армии, чем мы сейчас.
        // Запас «мы придём первыми» считал R3 на оси подхода безопасным, и армия шла врагу навстречу (матч 34)
        val enemyCentre = if (unflaggedRushNow) centroidOf(armed) else null
        for (c in escapeCandidates(ctx)) {
            if (left != null && c.x == left.x && c.y == left.y) continue
            if (enemyCentre != null && getRange(c, enemyCentre) <= getRange(ctx.ourCentroid, enemyCentre)) continue
            val key = c.x * 100 + c.y
            val flow = escapeFlows[key] ?: continue
            val theirs = escapeTheirs[key] ?: continue
            // «ему не дойти» — это НЕИЗВЕСТНОСТЬ, не безопасность (v54): поле за бюджетом BFS даёт Int.MAX_VALUE / 4, и точка
            // получала запас 536870903 — армия ушла в угол (96,3) при его армии в 75 клетках к югу и была там стёрта (матч 114,
            // Coldkimchi, t=333); бегство вбок (v53) не включилось, потому что «лучшая точка» была положительной
            if (theirs >= Int.MAX_VALUE / 4) continue
            val ourTicks = strikers.maxOfOrNull { pathTicks(it, flow, it.x * 100 + it.y) } ?: continue
            if (ourTicks >= Int.MAX_VALUE / 4) continue
            val exit = exitMargin(ctx, c, ourTicks)
            // он там раньше нас — это марш в него (v79); выход нулевой — это карман (v87)
            if ((theirs - ourTicks < 0 || exit <= 0)) continue
            val score = minOf(theirs - ourTicks, exit)
            if (getRange(c, ctx.ourCentroid) <= EVADE_ARRIVED && score < EVADE_SAFE) { evadeLeft = c; continue }
            if (cur != null && c.x == cur.x && c.y == cur.y) curScore = score
            if (best == null || score > bestScore) { bestScore = score; best = c; bestArrive = theirs - ourTicks; bestExit = exit }
        }
        if (cur != null && !arrived && curScore >= bestScore - EVADE_HYSTERESIS && curScore > 0) return cur
        // ни одной точки с запасом — бегство направлением (см. fleePoint); точка с нулевым или отрицательным запасом — это шаг
        // сквозь преследователя или в угол (матч 80: (3,3) −40, дом 0, (96,96) 0)
        if (best == null || bestScore <= 0) {
            val flee = fleePoint(ctx, armed)
            val edge = flee?.let { minOf(it.x, it.y, 99 - it.x, 99 - it.y) } ?: 99
            if (flee != null && edge <= FLEE_EDGE_MIN) {
                if (DEBUG_LOG && (cur != null || getTicks() % (LOG_EVERY * 5) == 0)) println("evade: t=$now flee=(${flee.x},${flee.y}) refused — ${edge} from the edge, the army stands at the post (see true)")
                evadeTarget = null
                return null
            }
            if (flee != null) {
                if (cur == null || cur.x != flee.x || cur.y != flee.y)
                    println("evade: t=$now flee=(${flee.x},${flee.y}) best=${best?.let { "(${it.x},${it.y})" } ?: "-"} score=$bestScore from=(${ctx.ourCentroid.x},${ctx.ourCentroid.y}) approach=${(approachRate * 100).toInt()}")
                evadeTarget = flee
                return flee
            }
        }
        if (best == null) { evadeTarget = null; return null }
        if (cur == null || cur.x != best.x || cur.y != best.y)
            println("evade: t=$now to=(${best.x},${best.y}) score=$bestScore arrive=$bestArrive exit=$bestExit from=(${ctx.ourCentroid.x},${ctx.ourCentroid.y}) approach=${(approachRate * 100).toInt()}")
        evadeTarget = best
        return best
    }

    /** Пост: центр наших флагов (их и держим), без флагов — дом; и НЕ БЛИЖЕ EVADE_RANGE к краю карты (v46). Матчи 78 и 80
     *  (Coldkimchi, стоячая линия при паритете, из контакта отхода нет): единственный наш флаг — угловой H4 (90,8), пост на
     *  нём, армия стояла в углу; когда он пошёл на нас, ни одна точка уклонения не имела запаса (лог evade: (96,3) 13, дальше
     *  (3,3) −40 сквозь него, дом с выходом 0, угол (96,96) с выходом 0) — контакт на 319-м и 510-м, армия стёрта при его
     *  16000/16000. Флаг остаётся нашим, пока на него не встанет чужой (хранитель встаёт, когда враг подходит, см. KEEP_RANGE);
     *  стоять на нём армии незачем, а угол — ловушка для равного по скорости. */
    private fun postPoint(ctx: Ctx): Position {
        // пост под безфлаговым броском — флаг нашей половины, ближний к ЦЕНТРУ (v129, USE_POST_TOWARD_CENTRE): армия ждёт конца
        // удержания в 25 от D5 у A3, а не в углу у R3; первый флаг по времени тот же, второй на тридцать тиков раньше (матчи 5, 8,
        // 19 серий 367–406: его шесть флагов к 80–91-му, наш второй на 83–140-м)
        val centreCell = InfluenceMap.cell(49, 49)
        val ourHalfFlag = ctx.flags.filter { DistanceMap.inOurHalf(it.pos.x, it.pos.y) }
            .minByOrNull { getRange(it.pos, ctx.ourCentroid) }?.pos
        // центральный флаг наш — пост на нём (v102, USE_POST_ON_CENTRE)
        val centre = ctx.flags.firstOrNull { it.ours && it.type == EFF_DAMAGE_TAKEN_MODIFIER }?.pos
        // ...И ПОКА У НАС НЕТ НИ ОДНОГО ФЛАГА — ПОСТ НА ЦЕНТРАЛЬНОМ ФЛАГЕ С ОБЕИХ СТОРОН (v230, см. USE_POST_CONTEST_CENTRE)
        // ...кроме центра, на котором сидит его ОДИНОЧКА при армии вдали (стенд m1 grab: его скаут на D5, армия на его R3; колонна
        // марша к занятой клетке цели пляшет в 4–10 клетках от неё 1500 тиков и не убивает скаута — затор марша у занятой
        // цели, открытая находка): такой центр не оспаривается, пост прежний
        val c = centre ?: centroidOf(ctx.flags.filter { it.ours }.map { it.pos }) ?: ourHalfFlag ?: ctx.home
        return passableNear(c)
    }

    /** Бегство направлением (v46): когда ни одна точка выхода не даёт запаса (см. evadePoint), цель — клетка в EVADE_RANGE от
     *  нашего центра в том из восьми направлений, где после шага центр вооружённого врага дальше всего, среди направлений,
     *  чья клетка не ближе EVADE_RANGE к краю (у края направлений вдвое меньше, в углу — вчетверо: матчи 78, 80). Точки
     *  выхода (флаги, дом, углы) при равной скорости преследователя все «за ним» или без выхода, и армия шла в наименее
     *  плохую — в угол. */
    private fun fleePoint(ctx: Ctx, armed: List<Creep>): Position? {
        val ec = centroidOf(armed) ?: return null
        val oc = ctx.ourCentroid
        // отступ от края — не больше нынешнего: у края все направления вдоль края запрещались, оставались только внутрь, и
        // армия с (29,6) пошла на (52,32) наискосок МИМО его центра (30,30) — перехвачена на 69-м, стёрта к 120-му (матч 83,
        // けろびー боевой, которого v45 била). Направление обязано уводить: скалярное произведение с вектором «от него к нам»
        // положительно; из допустимых — то, где его центр после шага дальше всего
        val margin = minOf(EVADE_RANGE, oc.x, oc.y, 99 - oc.x, 99 - oc.y).coerceAtLeast(0)
        val ax = oc.x - ec.x; val ay = oc.y - ec.y
        // ВБОК, когда «прочь» некуда (v53): из домашнего угла каждое направление прочь от его центра уводит за карту — матч 110,
        // бросок боевого けろびー с 3-го тика, уклонение из угла в угол, контакт у (79,81)–(93,93), армия стёрта к 150-му; тот же
        // бой в открытом поле выигран пять раз. Направление допустимо, если конец шага не ближе EVADE_RANGE к его центру:
        // сначала уводящие (скалярное произведение > 0), затем боковые; бой, если придёт, придёт в поле.
        // НАХОДКА (матч 115, не исправлено): у верхнего края при враге точно к югу «прочь» — за картой, и знак крошечного
        // бокового смещения его центра решал запад/восток: (5,3) на 56-м, (3,3) на 61-м, (50,6) на 71-м, (57,6) на 76-м —
        // центр армии за 20 тиков (30,3)→(28,3)→(25,3)→(27,3)→(30,3), контакт на 77-м. Ранжирование по расстоянию с
        // гистерезисом (v55-опыт) гейт прошло, но 25 строк хуже / 29 лучше — то же дрожание было во всех девятнадцати
        // победах над тем же соперником, решил не отход, а бой (см. covered)
        fun pick(away: Boolean): Position? {
            var best: Position? = null
            var bestD = -1
            for ((dx, dy) in DIRECTIONS) {
                if (dx == 0 && dy == 0) continue
                val dot = dx * ax + dy * ay
                if (if (away) dot <= 0 else dot < 0) continue
                val x = oc.x + dx * EVADE_RANGE; val y = oc.y + dy * EVADE_RANGE
                if (x < margin || y < margin || x > 99 - margin || y > 99 - margin) continue
                val c = passableNear(InfluenceMap.cell(x, y))
                val d = getRange(c, ec)
                if (d > bestD) { bestD = d; best = c }
            }
            return best?.takeIf { getRange(it, ec) >= (if (away) getRange(oc, ec) + 1 else EVADE_RANGE) }
        }
        return pick(true) ?: pick(false)
    }

    /** Ближайшая проходимая клетка: центр наших флагов попал в стенной блок, поле к нему было пустым (flow=-1), и
     *  армия стояла на месте, пока враг подходил (матч 11, t=90–103). */
    private fun passableNear(p: Position): Position {
        if (!DistanceMap.isTerrainWall(p.x, p.y)) return p
        for (r in 1..30) for (dx in -r..r) for (dy in -r..r) {
            if (maxOf(abs(dx), abs(dy)) != r) continue
            val x = p.x + dx; val y = p.y + dy
            if (x in 0..99 && y in 0..99 && !DistanceMap.isTerrainWall(x, y)) return InfluenceMap.cell(x, y)
        }
        return p
    }

    private fun runArmy(ctx: Ctx) {
        val army = ctx.army
        if (army.isEmpty()) return
        val allies = ctx.myCreeps
        val enemyCreeps = ctx.enemyCreeps
        val combatEnemies = ctx.combatEnemies
        updateKeepers(ctx, army)

        val strikers = army.filter { fullSpeed(it) && hasWeapon(it) && it.id !in Memory.keeperIds }
        // враги, с которыми есть бой: с уроном — и лекари, у которых рядом (в дальности лечения плюс шаг) есть свой с
        // оружием в теле, живым или мёртвым: такого лекарь вернёт в строй за шесть тиков (стенд m2 rush: армия ушла за
        // флагами от лекарей с обломками, и через сто тиков те вернулись в полном теле). Стая из одних лекарей при
        // скаутах (сила 0) не повод для боя: два уцелевших лекаря врага кайтили в четырёх клетках 1700 тиков, армия
        // в ДОБИТЬ то гналась, то сбивалась в кучу и не шла за флагами, пока скауты врага брали пять (m7 rush)
        val armedEnemies = combatEnemies.filter { threatening(it, enemyCreeps) }
        // сомкнутая масса врага — та же мера, что в postureOf (см. enemyMassed): шесть и больше вооружённых, две трети
        // которых в MASS_RANGE от их центроида. Считается раз на тик, а не на крипа (v135)
        val enemyMassedNow = armedEnemies.size >= 6 && centroidOf(armedEnemies)?.let { c ->
            armedEnemies.count { getRange(it, c) <= MASS_RANGE } * 3 >= armedEnemies.size * 2 } == true
        kiteNow = 0
        kiteMassed = enemyMassedNow
        planStrict = 0; planLoose = 0
        // чистый урон врагу за окно: сумма его хитов ниже, чем STALL_TICKS тиков назад (попадание с полным лечением в тот же
        // тик — не прогресс: стрелок россыпи с трёх клеток попадал, лечился, и «обмен уронами» сбрасывал простой);
        // простой — только когда добыча в досягаемости броска, а прогресса нет (на марше к врагу за 20+ клеток простоя
        // нет — стенд m3 army: пауза на подходе выключала давление, и обе армии простояли до конца)
        val now = getTicks()
        val enemyHitsNow = enemyCreeps.sumOf { it.hits }
        if (lastEnemyHitsTotal >= 0 && enemyHitsNow < lastEnemyHitsTotal) enemyDamageTaken += lastEnemyHitsTotal - enemyHitsNow
        lastEnemyHitsTotal = enemyHitsNow
        val ourHitsNow = army.sumOf { it.hits }
        Memory.enemyHitsHist.addLast(enemyHitsNow); Memory.ourHitsHist.addLast(ourHitsNow)
        while (Memory.enemyHitsHist.size > STALL_TICKS) Memory.enemyHitsHist.removeFirst()
        while (Memory.ourHitsHist.size > STALL_TICKS) Memory.ourHitsHist.removeFirst()
        // РАЗМЕН ЗА ОКНО ПОДНЯТ СЮДА (v221) из блока толчка: его слагаемые готовы уже здесь — наши потери копятся в
        // прологе, его строкой выше, — а читать окно нужно раньше, чем решаются бой по контакту и простой. Между
        // старым и новым местом окна не читал никто (`lostRaceNow()` зовётся из `runRunners`, до `runArmy`, и ниже
        // блока толчка; ранних выходов в этом отрезке нет), поэтому перенос без тумблера: дифф отчёта пуст побайтово
        val exchangeLedger = enemyDamageTaken - ourDamageTaken
        // ...и тот же размен ЗА ОКНО (v216, см. ledgerHist): срез берётся в одной точке тика, потому что
        // слагаемые обновляются в разных местах — наши потери в прологе, его в runArmy
        Memory.ledgerHist.addLast(exchangeLedger)
        Memory.ourLostHist.addLast(ourDamageTaken)
        Memory.hisLostHist.addLast(enemyDamageTaken)
        while (Memory.ledgerHist.size > LEDGER_WINDOW + 1) Memory.ledgerHist.removeFirst()
        while (Memory.ourLostHist.size > LEDGER_WINDOW + 1) Memory.ourLostHist.removeFirst()
        while (Memory.hisLostHist.size > LEDGER_WINDOW + 1) Memory.hisLostHist.removeFirst()
        ledgerWindow = if (Memory.ledgerHist.size >= 2) Memory.ledgerHist.last() - Memory.ledgerHist.first() else 0
        ourLostWindow = if (Memory.ourLostHist.size >= 2) Memory.ourLostHist.last() - Memory.ourLostHist.first() else 0
        hisLostWindow = if (Memory.hisLostHist.size >= 2) Memory.hisLostHist.last() - Memory.hisLostHist.first() else 0
        // РАЗМЕН ИДЁТ (v221, см. USE_FIGHT_BY_LEDGER): за LEDGER_WINDOW тиков хоть одна сторона потеряла
        // STALL_DAMAGE хитов. Та же мера, что у клапана проигранной гонки (см. lostRaceNow) и у простоя
        // (netDamage), только по обеим половинам окна: новых чисел нет. Разбор двух рейтинговых серий по реплеям
        // обеих сторон делит ею забеги начисто: в проигранных армия 38 % тиков в постуре ANNIHILATE, и в 92 %
        // этих тиков размена нет вовсе, — это 35 % матча против 4 % в выигранных (v219: 24 % против 5 %)
        val exchangeLive = ourLostWindow >= STALL_DAMAGE || hisLostWindow >= STALL_DAMAGE
        exchangeLiveNow = exchangeLive
        // наступление окупается (см. PUSH_EXCHANGE); без окна — да (нечего мерить)
        val exchangePaying = Memory.ourHitsHist.size < STALL_TICKS ||
            (Memory.enemyHitsHist.first() - enemyHitsNow) >= (Memory.ourHitsHist.first() - ourHitsNow) * PUSH_EXCHANGE
        val mobileArmy = army.filter { canMove(it) && it.id !in Memory.keeperIds }
        // ...а командир видит ВСЁ поле, включая хранителей флагов: решение снять хранителя — его, а не следствие того,
        // что он невидим (v173, оператор). Держат флаг они по-прежнему сами, пока приказа нет
        val commandArmy = army.filter { canMove(it) }
        val chasers = strikers.ifEmpty { mobileArmy }
        // кого вообще можно догнать (см. catchable): добивание по перевесу идёт только за ними, и по ним же считается
        // пикет простоя — поэтому охота посчитана здесь, до простоя
        val huntable = armedEnemies.filter { catchable(it, chasers) }
        cpuMark("a.hunt")
        // его мили вплотную к нашим — поднято сюда из блока постуры (v221, перенос без тумблера): читать его нужно и
        // прибору погони ниже, а между старым и новым местом он не менялся и не читался
        val meleeAdjacent = combatEnemies.any { e -> hasMelee(e) && army.any { getRange(e, it) <= 1 } }
        // ПАРА К ПОГОНЕ ЗА КАЙТЕРОМ (v221, только прибор; см. kchaseTicks). Разбор v220, матч с ●ω<♥♪#1: он не взял ни
        // одного флага за 700 тиков, мы 300 тиков гнались за его отходящей линией в постуре ANNIHILATE и легли 12 → 0,
        // а вето безфлагового броска отказало захвату 3329 раз. Простой «держит дистанцию» против него не наступает:
        // любой его выстрел даёт netDamage, и простой гаснет. Прибор считает тики, где погоня идёт в ОДНУ сторону —
        // за окно мы потеряли STALL_DAMAGE, он меньше нас, его центр от нас уходит, его мили не вплотную. Считается ДО
        // простоя и по тем величинам, какими простой читал бы её: постура и история дистанции — прошлого тика
        val kiteChaseNow = posture == Posture.ANNIHILATE && ourLostWindow >= STALL_DAMAGE && ledgerWindow < 0 && !meleeAdjacent &&
            Memory.enemyDistHist.size >= 2 && Memory.enemyDistHist.last() > Memory.enemyDistHist.first()
        kiteChaseSeen = kiteChaseNow
        if (posture == Posture.ANNIHILATE) { kchaseAnn++; if (kiteChaseNow) kchaseTicks++ }
        // с обеих сторон: бьют только нас — бой, не простой (матч 20, t=117)
        val netDamage = Memory.enemyHitsHist.size == STALL_TICKS &&
            (Memory.enemyHitsHist.first() - enemyHitsNow >= STALL_DAMAGE || Memory.ourHitsHist.first() - ourHitsNow >= STALL_DAMAGE)
        if (netDamage) stallUntil = 0
        // пикет в досягаемости броска все STALL_TICKS подряд (см. STALL_PICKET): армия, только что вошедшая в
        // досягаемость, простоя не даёт (матч 20, t=64). Считается пикет по ДОГОНЯЕМЫМ (см. catchable): прежде
        // «не больше STALL_PICKET вооружённых» отделяло пикет от армии по ЧИСЛУ, и блоб, который от нас уклоняется и
        // не дерётся, одним своим числом отменял простой — армия гналась за ним весь матч. Живой матч 26: huntable=0/8,
        // 902 хита урона за 1500 тиков с обеих сторон, ни одной смерти, проигрыш 12721:23408; стенд farm на карте 21:
        // три флага на одиннадцать очков в тик простояли ничьими 1500 тиков. Кого можем догнать — драка; кто
        // уклоняется — не повод стоять
        val nearArmed = armedEnemies.count { e -> strikers.any { getRange(it, e) <= ENGAGE_RANGE } }
        val nearCatchable = huntable.count { e -> strikers.any { getRange(it, e) <= ENGAGE_RANGE } }
        // пикет — МЕНЬШИНСТВО его вооружённых (v50, оператор по матчу 101: «загоняем врага в угол, а потом разворачиваемся и
        // уходим в центр, не добив»): загнанный в угол остаток из трёх-четырёх вооружённых с лекарями четыре раза за матч
        // считался пикетом («picket of 3 armed in reach for 20 ticks — flags until +300», t=161, 547, 895, 1256), и армия на
        // триста тиков уходила за флагами. Когда в досягаемости не меньше половины его вооружённых, это его армия, а не пикет
        val picket = nearArmed >= 1 && nearCatchable <= STALL_PICKET && nearArmed * 2 < armedEnemies.size
        preyNearTicks = if (picket) preyNearTicks + 1 else 0
        // ВТОРОЙ вид простоя — марш, который не идёт. Пикет ловит бесплодную погоню, только пока добыча ближе
        // ENGAGE_RANGE; за этой чертой армия «гналась» и стояла, а простой не считался ни разу. Идущая погоня обязана
        // двигать центр вооружённой массы: за MARCH_STALL_TICKS тиков он не сдвинулся НИ НА КЛЕТКУ — это не марш.
        // Матч 25: добыча стояла в 11 клетках, ближе никого, армия 990 тиков дёргалась на месте у (46,34); за весь
        // матч ни одного урона ни с одной стороны, и проигрыш по очкам 19927:24205 при 12 против 13 в тик
        val marchCell = centroidOf(army.filter { hasWeapon(it) }.ifEmpty { army })?.let { it.x * 100 + it.y } ?: -1
        Memory.marchHist.addLast(marchCell)
        // ТРЕТИЙ вид простоя — враг, который держит дистанцию: в добивании без контакта дистанция между центрами армий за
        // CHASE_WINDOW тиков не сократилась, и враг дальше броска. Матч 48 (けろびー v5, фермер): он взял шесть флагов к 80-му
        // (сам на 0,75 мощи), парил в 10–28 клетках от нас и не дрался — за 1600 тиков ни одного выстрела с нашей стороны;
        // пикет не срабатывал (враг дальше ENGAGE_RANGE), марш не «стоял» (армия за ним ходила), и ANNIHILATE держал армию
        // лицом к нему на двух-трёх флагах против его пяти: 8 в тик против 17, проигрыш 15652:22950 при 16000/16000 у обоих
        // застой по ближайшей группе (v132, USE_STALL_NEAREST_GROUP): центр его группы, ближайшей к нашему вооружённому центру
        val ourArmedCentroid = centroidOf(army.filter { hasWeapon(it) }.ifEmpty { army })
        val stallCentroid: Position? = ctx.enemyCentroid
        val armyDist = stallCentroid?.let { getRange(ourArmedCentroid ?: it, it) } ?: -1
        // бой — контакт С ОБМЕНОМ (v74, см. USE_COLD_CONTACT): выстрел наш или удар по нам не дальше STALL_TICKS назад
        val exchangeRecent = now - lastFireTick <= STALL_TICKS || (lastHurtTick > 0 && now - lastHurtTick <= STALL_TICKS)
        val fightOn = inContact(armedEnemies, army) && (exchangeRecent)
        val pauseReach = 2 * ENGAGE_RANGE   // v106: окно сквозь мигание
        val pausedChase =  posture == Posture.HOLD &&
            armedEnemies.any { e -> army.any { getRange(e, it) <= pauseReach } }
        if ((posture == Posture.ANNIHILATE || pausedChase) && !fightOn && armyDist >= 0) {
            Memory.armyDistHist.addLast(armyDist)
            // центр ВООРУЖЁННЫХ (v58): центр всех его крипов двигали два бегающих скаута, и стоящий на D5 лагерь «уходил» —
            // отряд на 566-м при his_moved=0 по реплею (матч 133, одиннадцатый проигрыш фермеру-лагерю 8346:22771)
            Memory.enemyCentHist.addLast((centroidOf(armedEnemies))?.let { it.x * 100 + it.y } ?: -1)
        } else { Memory.armyDistHist.clear(); Memory.enemyCentHist.clear() }
        while (Memory.armyDistHist.size > DETACH_WINDOW + 1) Memory.armyDistHist.removeFirst()
        while (Memory.enemyCentHist.size > DETACH_WINDOW + 1) Memory.enemyCentHist.removeFirst()
        // ...и это ОН уходит (v57): центр его вооружённых за окно сместился не меньше чем на четверть окна — стоячий лагерь, у
        // которого замираем мы, дистанцию не «держит». Окно отряда — DETACH_WINDOW (v59): по восьми тикам (CHASE_WINDOW) отряд
        // собрался на 207-м тике матча 139, когда дистанция за сто тиков сократилась с 40 до 12 — армия почти догнала, а
        // восьмитиковое окно поймало паузу; ядро без пяти встало, он ушёл и запарковался (3174:22931)
        fun kept(window: Int, needMoved: Boolean = true): Boolean {
            if (Memory.armyDistHist.size <= window || Memory.enemyCentHist.size <= window) return false
            val d0 = Memory.armyDistHist.elementAt(Memory.armyDistHist.size - 1 - window)
            val a = Memory.enemyCentHist.elementAt(Memory.enemyCentHist.size - 1 - window); val b = Memory.enemyCentHist.last()
            if (a < 0 || b < 0) return false
            val moved = maxOf(abs(a / 100 - b / 100), abs(a % 100 - b % 100))
            return Memory.armyDistHist.last() >= d0 && Memory.armyDistHist.last() > ENGAGE_RANGE && (!needMoved || moved >= window / 4)
        }
        val distanceKept = combatEnemies.isNotEmpty() && kept(DETACH_WINDOW)
        if (distanceKept) lastDistanceKeptTick = now
        // для простоя — и без его сдвига (v98, USE_KEEPS_DISTANCE_ANY_MOVE): застенчивый блоб держит дистанцию шагами на 2–3
        // загнанная группа в досягаемости (см. USE_STALL_CORNERED_GROUP): неподвижная группа его вооружённых не меньше SPLIT_MIN,
        // хотя бы один в досягаемости ударников, слабее их в PUSH_RATIO — застой «держит дистанцию» не наступает
        val corneredInReach =  armedEnemies.size >= SPLIT_MIN && run {
            val still = armedEnemies.filter { e ->
                val h = Memory.enemyCellHist[e.id]
                h != null && h.size >= CHASE_WINDOW && maxOf(abs(h.first() / 100 - h.last() / 100), abs(h.first() % 100 - h.last() % 100)) <= 1
            }
            val group = still.filter { e -> still.count { getRange(e, it) <= ENGAGE_RANGE } >= SPLIT_MIN }
            group.isNotEmpty() && group.any { e -> chasers.any { getRange(it, e) <= ENGAGE_RANGE + RANGED_RANGE } } &&
                ourPowerOf(chasers, group) >= enemyPowerOf(group, chasers) * PUSH_RATIO
        }
        // залипание (v134, см. USE_CORNERED_STICKY): условие сидит на границе и в матче 6a9fa6ad переключалось 154 раза,
        // а вместе с ним и keepsDistance — армии на чётных тиках говорили «стой», на нечётных «иди»
        if (corneredInReach) corneredUntil = now + CORNERED_STICK
        val cornered = corneredInReach 
        if (DEBUG_LOG && cornered != corneredWas) println("cornered t=$now: ${if (cornered) "a still weak group of his in reach — no distance stall" else "gone"}")
        corneredWas = cornered
        val keepsDistance = !cornered && (
            ((distanceKept || (combatEnemies.isNotEmpty() && kept(DETACH_WINDOW, needMoved = false)))))
        while (Memory.marchHist.size > MARCH_STALL_TICKS) Memory.marchHist.removeFirst()
        // в контакте стоять — законно (строй рубится на месте), и полное взаимное лечение даёт нулевой чистый урон
        val marchStalled = pushing && marchCell >= 0 && Memory.marchHist.size == MARCH_STALL_TICKS &&
            Memory.marchHist.all { it == marchCell } && !fightOn
        // сухой толчок (v86): толчок PASSIVE_TICKS без нашего выстрела и без удара по нам — не толчок
        // в любой постуре, кроме отхода и уклонения: в ПОСТУ с висящим рядом врагом «держим линию» без простоя длилось до
        // конца матча (стенд m19 spread, t=600–1600)
        // боевые враги нужны ПИКЕТУ (он из них и состоит), а простою марша — нет: зачистка идёт ровно тогда, когда
        // боевых не осталось, и там сетка не сработала ни разу (стенд m18 roost: 1500 тиков погони за двумя скаутами)
        // ...И В ОТХОДЕ ТОЖЕ (v217). Оговорка «в любой постуре, кроме отхода и уклонения» стояла без своего
        // замера, а следствие у неё было тяжёлое: `!stalled` — единственный оставшийся выключатель
        // `contactFight`, поэтому после объявления отхода выйти из него было нельзя по построению, и счёт
        // оставался нулём при живых двенадцати крипах (живой замер v216: `objnone` даёт annihilate:179-207 при
        // постуре RETREAT). Условие `!netDamage` остаётся и само по себе узко: под огнём простой не объявляется,
        // так что правка касается ровно тихого отхода — того, из которого и надо уметь выйти
        if (!netDamage && now >= stallUntil &&
            ((combatEnemies.isNotEmpty() && preyNearTicks >= STALL_TICKS) || marchStalled || keepsDistance)) {
            stallUntil = now + STALL_COOLDOWN
            if (DEBUG_LOG) println("stall t=$now: ${if (marchStalled) "the march has not moved a cell for $MARCH_STALL_TICKS ticks" else if (keepsDistance) "the enemy keeps its distance (${Memory.armyDistHist.first()} -> ${Memory.armyDistHist.last()} over $CHASE_WINDOW ticks)" else "picket of $nearArmed armed in reach for $preyNearTicks ticks"} without damage either way — flags until $stallUntil")
        }
        val stalled = now < stallUntil
        stalledNow = stalled

        // ---- постура ----
        val ours = ourPowerOf(army, combatEnemies)
        val theirs = enemyPowerOf(combatEnemies, army)
        // РЕЖИМ ВЫЖИВАНИЯ (v223, доктрина оператора, см. USE_SURVIVAL): ведём по очкам, а его армия сильнее — не деремся,
        // а уходим, беря флаги с выходом. Порог и гистерезис — как у «слабее», по мощи всей армии
        val leadingNow = ourScore > enemyScore
        if (leadingNow && armedEnemies.isNotEmpty()) survLead++
        Memory.theirsHist.addLast(theirs)
        while (Memory.theirsHist.size > MEASURE_WINDOW) Memory.theirsHist.removeFirst()
        // множители окна (v114): его мощь сейчас → его сильнейшая и слабейшая за окно; при нулевой мере — 1
        val theirsUp = if (theirs > 0.0) (Memory.theirsHist.maxOrNull() ?: theirs) / theirs else 1.0
        val theirsDown = if (theirs > 0.0) (Memory.theirsHist.minOrNull() ?: theirs) / theirs else 1.0
        val nearRange = if (posture == Posture.RETREAT) NEAR_RANGE + NEAR_RELEASE else NEAR_RANGE
        // ОТВЕРГНУТО стендом: «враг рядом — рядом с МАССОЙ армии, а не с любым нашим крипом» (хранители стоят по
        // одному на разных концах карты, и висящий у хранителя враг россыпи отменяет цель-флаг у всей армии).
        // Целевой сценарий m22 spread не сдвинулся вовсе (16622:24323), а m20 spread перешёл из победы в проигрыш
        // (24337:21666 -> 19400:24328) и m19 block из уничтожения армии врага на 389-м в победу по очкам на 1142-м;
        // выиграли только россыпи на 12, 19 и 21. Мигание постуры на россыпи — открытая находка
        val enemyNear = armedEnemies.any { e -> army.any { getRange(e, it) <= nearRange } }
        // контакт решает сам: пассивного поста в контакте нет — он отдаёт армию по одному (стенд rush: десять
        // за двоих). Отход из контакта возможен, только если он не бегство: никто из врагов-мили не вплотную
        // и наш строй не медленнее их самого быстрого — при равной скорости преследователь стреляет в спину
        // каждый тик, а обездвиженные остаются врагу (стенд rush: отход при 1250 против 1619 отдал ещё
        // шестерых). Иначе в контакте — бой всем составом, даже слабее: рубка с фокусом лучше разгрома
        // контакт армии — контакт её МАССЫ (см. MASS_RANGE): один оторвавшийся не переводит армию в бой
        val massCentroid = clusterCentroid(army.filter { hasWeapon(it) }.ifEmpty { army }) ?: ctx.ourCentroid
        val massArmy = army.filter { getRange(it, massCentroid) <= MASS_RANGE }.ifEmpty { army }
        val contact = inContact(armedEnemies, massArmy)
        // ЛЕКАРЬ ПРИ МИЛИ (v235, см. USE_HEALER_AT_MELEE): назначение и тыльная клетка считаются здесь — до командира и ступеней
        meleeWardOf.clear(); meleeWardCell.clear()
        // ТРЕТЬЯ ПОСТАНОВКА (v227, см. USE_ZERO_LEAD_BREAK): мощь ноль при отрыве по очкам STALL_TICKS подряд — армия
        // разрывает контакт СТРОЕМ: командир раздаёт клетки замыслом KITE с дальностью «вне его стрелкового огня», свободный
        // шаг отскакивает от ближайшего вооружённого на RANGED_RANGE + 1; постура не меняется, все механизмы боя живут.
        // Не бегство к точке (первая редакция выживания) и не непрерывное уклонение к выходу (вторая), а шаг назад строем
        val zeroLead = leadingNow && contact && armedEnemies.isNotEmpty() && ours <= 0.0 && theirs > 0.0
        zeroLeadTicks = if (zeroLead) zeroLeadTicks + 1 else 0
        if (zeroLead) zlbZero++
        // ИДЁТ ЛИ БОЙ (v215): контакт по МАССЕ армии либо размен за последние STALL_TICKS тиков. Считается
        // здесь, ВЫШЕ отряда и командирской гонки, — оба механизма разделения читают его этим тиком, а не
        // прошлым (порядок тика: runRunners идёт раньше runArmy, и признак, посчитанный ниже, опаздывал бы)
        fightOnNow = contact || exchangeRecent
        // ПАРА К ОТЗЫВУ ПО РАЗМЕНУ (v221, только прибор): сколько тиков «бой идёт» держится на одном слове
        // «контакт» — ни одна сторона за окно не потеряла STALL_DAMAGE. Читать вместе с recall= и budget=
        if (fightOnNow) { warmFightAll++; if (!exchangeLive) warmFight++ }
        // ПРИЗНАК ОТХОДА СЧИТАЕТСЯ ЗДЕСЬ (v217, см. USE_BREAK_OFF_HOLDS_LINE): он должен успеть погасить
        // наступление, а `pushing` решается на триста строк ниже. Величины готовы: контакт уже есть, а
        // `ourDamageTaken`/`enemyDamageTaken` копятся с начала матча
        val outmatchedNow =  contact && armedEnemies.isNotEmpty() &&
            ourDamageTaken > 0 && enemyDamageTaken < ourDamageTaken * BREAK_OFF_RATIO
        outmatchedTicks = if (outmatchedNow) outmatchedTicks + 1 else 0
        val breakOffNow = outmatchedTicks >= BREAK_OFF_TICKS
        // ОТЗЫВ (v215, см. USE_NO_SPLIT_IN_FIGHT): едва бой начался, отпущенные возвращаются в кулак. Очистка стоит
        // ЗДЕСЬ, а не внутри `commandRace`: выйдя из режима гонки, командир эту функцию не зовёт вовсе, и `cmdDetach`
        // оставался с прошлого тика — отпущенные не возвращались никогда
        if (fightOnNow) {
            fightTicksNow++
            recalled += Memory.cmdDetach.size + Memory.detachedIds.size
            Memory.cmdDetach.clear()
            Memory.detachedIds.clear()
        }
        val ourPeriod = mobileArmy.maxOfOrNull { plainPeriod(it) } ?: 1
        val theirPeriod = combatEnemies.filter { canMove(it) }.minOfOrNull { plainPeriod(it) } ?: Int.MAX_VALUE / 4
        // при РАВНОЙ скорости отход из контакта без мили вплотную — размен выстрелами в обе стороны, не бегство; из
        // точки отхода, куда уже пришли, отходить некуда — бой (матч 5: семеро в углу (3,96) при «отходе» не
        // шевелились и не били, пока их расстреливали с трёх клеток)
        val atRetreatPoint = retreatTarget?.let { getRange(ctx.ourCentroid, it) <= POST_STANDOFF + ARRIVED_SLACK } ?: false
        // из контакта отхода нет: «отход, пока мили не вплотную» мигал ДОБИТЬ/ОТХОД через тик и отдавал армию по одному
        // в матчах 4, 6 и 7 (в седьмом — при 1.53, без единой потери у врага); при равной скорости из контакта не
        // уйти, и единственный способ его кончить — бой строем
        // без стрелков строя нет — лекарей и раненых травят, и «в контакте держим строй» держало их у поста, где
        // стоял враг (стенд m7 sleeper: три лекаря с flee=true разбежались по карте и были добиты поодиночке)
        val retreatFeasible = (!contact || strikers.isEmpty()) && !atRetreatPoint
        cpuMark("a.retreat")
        // мера боя (v120, см. USE_FIGHT_PACK_MEASURE): его боевые по порядку прихода к нашей массе — первый и все, кто придёт,
        // пока стая, набранная до него, умирает под нашим огнём (окно растёт вместе со стаей: колонна входит целиком)
        val fightPack = if (combatEnemies.size <= 1 || strikers.isEmpty()) combatEnemies else run {
            // центр массы в стене даёт пустое поле (см. passableNear): все приходы MAX, стая — вся армия, и уклонение в угол
            // на 199-м тике split m28 при его шестёрке в шести клетках
            val flow = flowTo(ctx, passableNear(massCentroid))
            val arrival = combatEnemies.map { e -> e to pathTicks(e, flow, e.x * 100 + e.y) }.sortedBy { it.second }
            val pack = ArrayList<Creep>()
            val t0 = arrival.first().second
            var limit = t0
            for ((e, t) in arrival) {
                if (pack.isNotEmpty() && t > limit) break
                pack.add(e)
                val kill = fightTicks(pack, strikers)
                limit = if (kill >= Int.MAX_VALUE / 4) Int.MAX_VALUE / 2 else t0 + kill
            }
            pack
        }
        fightPackIds = fightPack.mapTo(HashSet()) { it.id }
        val fightAll = fightPack.size == combatEnemies.size
        val oursFight = if (fightAll) ours else ourPowerOf(army, fightPack)
        val theirsFight = if (fightAll) theirs else enemyPowerOf(fightPack, army)
        // стая НАСТУПЛЕНИЯ (v120, USE_PUSH_PACK_AT_HEAD): наступать — идти к его ближайшему, и бой будет у НЕГО, а не у нашей
        // массы: стая — те, кто дойдёт до головы не позже нас плюс время её смерти. Хвост колонны в десяти клетках за головой
        // приходит к ней через десять тиков после нас — он в стае; вторая группа фермера в другом углу — нет. Мера прихода
        // к нашей массе (fightPack) годится для «слабее» (стоим — кто дойдёт до нас), но для толчка она считала голову
        // колонны без хвоста: таблица входов v117 → v120g brawl 4 хуже / 1 лучше (m30 +50: 2536 → 6250 своих хитов, 13 → 9 живых)
        val pushPack = if (combatEnemies.size <= 1 || strikers.isEmpty()) fightPack else run {
            val head = combatEnemies.minByOrNull { e -> massArmy.minOf { getRange(e, it) } } ?: return@run fightPack
            val toHead = flowTo(ctx, head)
            val ourTravel = strikers.map { pathTicks(it, toHead, it.x * 100 + it.y) }.filter { it < Int.MAX_VALUE / 4 }.maxOrNull() ?: return@run fightPack
            val arrival = combatEnemies.map { e -> e to (if (e.id == head.id) 0 else pathTicks(e, toHead, e.x * 100 + e.y)) }.sortedBy { it.second }
            val pack = ArrayList<Creep>()
            var limit = ourTravel
            for ((e, t) in arrival) {
                if (pack.isNotEmpty() && t > limit) break
                pack.add(e)
                val kill = fightTicks(pack, strikers)
                limit = if (kill >= Int.MAX_VALUE / 4) Int.MAX_VALUE / 2 else ourTravel + kill
            }
            pack
        }
        val pushAll = pushPack.size == combatEnemies.size
        val oursPush = if (pushAll) ours else ourPowerOf(army, pushPack)
        val theirsPush = if (pushAll) theirs else enemyPowerOf(pushPack, army)
        val weaker = theirsFight >= oursFight * (if (posture == Posture.RETREAT) RETREAT_RELEASE_RATIO else RETREAT_RATIO)
        // из идущего боя (см. RETREAT_CONTACT_RATIO) — только при явном проигрыше
        // ⚠️ Здесь жил `weakerContact` — и после снятия вакуумной охраны в `contactFight` он остался
        // объявленным и никем не читаемым. Снят вместе с ней (v217); вместе с ним осиротела и константа
        // RETREAT_CONTACT_RATIO, которая существовала только ради него
        // ДОБИТЬ по перевесу — с гистерезисом; по контакту — пока контакт есть (без гистерезиса: см. PUSH_RELEASE_RATIO)
        val stalemate = behindTicks >= BEHIND_PATIENCE
        stalemateNow = stalemate
        val holdingFlag =  !fightOn &&
            ctx.flags.any { it.ours && getRange(it.pos, ctx.ourCentroid) <= POST_STANDOFF }
        // (размен матча и размен за окно считаются выше, у историй хитов — перенесены в v221, см. exchangeLive)
        // нулевой ледж (обмена ещё не было) допуск не закрывает — иначе толчок в стоящий лагерь стенда не начинался
        // (v87b: spread m33 24314 → 7298, 14 хуже); закрывает только проигранный размен
        val ledgerOk =  exchangeLedger >= 0
        // в проигранной гонке свой флаг порога не поднимает (v99, USE_PUSH_KEEPS_FLAG_UNLESS_LOST)
        val flagRaises = holdingFlag && !(lostRaceNow())
        val pushRatio = if (flagRaises || !ledgerOk) PUSH_RATIO else if (stalemate) PUSH_RATIO_STALEMATE else if (behindOnScore) PUSH_RATIO_BEHIND else PUSH_RATIO
        val pushRelease = if (stalemate) PUSH_RELEASE_RATIO_STALEMATE else if (behindOnScore) PUSH_RELEASE_RATIO_BEHIND else PUSH_RELEASE_RATIO
        // зачистка: у врага не осталось никого с боем, а мы позади по очкам — аннигиляция единственная победа, и остаток
        // (скауты, обломки) добивается без оглядки на «ловимость» (матч 19: последний M1 с 28 хитами сидел у нашего R3
        // пятьсот тиков, армия ходила за флагами и проиграла по очкам)
        val sweep = combatEnemies.isEmpty() && enemyCreeps.isNotEmpty() && strikers.isNotEmpty() && behindOnScore
        // и зачистка уступает простою: она стояла ВНЕ него, поэтому замерший на месте «дожим» не выключался ничем
        // перехват (см. USE_INTERCEPT): ближайший к центру фермера флаг не из его — туда; свой — пост (см. post ниже); считается до наступления — см. chaseVeto, иначе — цель
        val interceptFlag: FlagInfo? = if (!enemyNotFightingNow || armedEnemies.isEmpty()) null else ctx.enemyCentroid?.let { ec ->
            val group = strikers.ifEmpty { mobileArmy }
            // липкий: выбранный держим, пока он не его
            interceptFlagId?.let { id -> ctx.flags.firstOrNull { it.id == id && !it.theirs } }
                ?: ctx.flags.filter { !it.theirs }.sortedBy { getRange(it.pos, ec) }.firstOrNull { f ->
                    val flow = flowTo(ctx, f.pos)
                    val ours = group.maxOfOrNull { pathTicks(it, flow, it.x * 100 + it.y) } ?: 0
                    ours < Int.MAX_VALUE / 4 && ours + INTERCEPT_MARGIN <= getRange(f.pos, ec)
                }
        }
        interceptFlagId = interceptFlag?.id
        // перехват снимает наступление, только пока есть ЧТО перехватывать — флаг не наш, за которым фермер придёт; когда все
        // флаги его, «перехват» — пост у своего флага, а за ним он не придёт при 22 очках в тик. Матч 70 (けろびー v5): он сел
        // на D5 двенадцатью при 0,6 мощи (2954 против наших 4179), и армия 1000 тиков дёргалась в 10–13 клетках от него между
        // ДОБИТЬ и постом в 35 клетках позади (noFire ≥ 20 и «в досягаемости броска» мигали на границе 8 клеток, поза
        // переключалась каждые 1–4 тика) — 3174:22934 без единого выстрела с обеих сторон. Позади по очкам против врага,
        // который не дерётся и которому нечего перехватывать, стоять — проиграть наверняка; впереди — стоять верно (v42)
        // отряды (см. USE_DETACH): решение на следующий тик — Ctx строится до мощей
        // фермер: сто тиков (PASSIVE_TICKS) без единого снятого с нас хита с тех пор, как он последний раз был в досягаемости
        // броска, и был в ней не дальше ста тиков назад. Счётчик «рядом и не стреляет» по тикам (noFireTicks) сбрасывался
        // всякий раз, когда блоб отходил дальше NEAR_RANGE, и за 1800 тиков матча 108 не дошёл до ста ни разу (0 detached)
        // погоня без сближения (v57, см. lastDistanceKeptTick) не дальше PASSIVE_TICKS назад — вход; собранный отряд держится,
        // пока его вооружённые есть. Фермер — тот, кто НИ РАЗУ не ударил (lastHurtTick == 0): «сто тиков без удара» пускало
        // отряд против кайтера стенда, который бил на 76–84-м приманкой и вернулся за разделённым ядром — m31 kite 1817:23890,
        // армия стёрта к 400-му (ядро без четырёх стрелков против пяти его стрелков с лекарями: урон мили, которых кайтер не
        // подпускает, в паритете по Ланчестеру считается полностью), m28 kite при наборе из мили — 4970:23907. Живой фермер
        // (матчи 119, 126) не ударил ни разу за 1300–1600 тиков. Первый удар отзывает отряд навсегда
        val chaseDry = now - lastDistanceKeptTick <= PASSIVE_TICKS
        val quiet = lastHurtTick == 0 || now - lastHurtTick >= FARMER_QUIET   // тишина (v65, см. FARMER_QUIET)
        // второй вход (v68): противник тих FARMER_QUIET с ПЕРВОЙ досягаемости (бросок на сотом тике — не фермер) и гонка проиграна
        // (отстаём с меньшим темпом) — отряд собирается без сухой погони. Матч 161 (шестнадцатый проигрыш фермеру 19771:23843):
        // отряд вышел на 806-м, когда толчок наконец не сближал, и с 900-го мы вели 14 против 11 в тик, а 800 тиков до того
        // были проиграны 3–13 против 12–22 — качели «взяли флаги → слабее → уклонение → потеряли → сильнее → толчок»
        val quietSinceFirstReach = firstNearTick >= 0 && now - firstNearTick >= FARMER_QUIET
        farmerQuietNow = quiet && quietSinceFirstReach
        val lostRaceNow = behindOnScore && ourRate <= enemyRate
        // сухая охота (v75, см. USE_DRY_HUNT): мы уже стреляли, с тех пор PASSIVE_TICKS ни выстрела, ни удара, отстаём — и его
        // вооружённые РАССЫПАНЫ: крупнейшая группа в ENGAGE_RANGE не больше половины (бегуны матча 183: 2 по одному). «Сто
        // тиков без обмена» само по себе (v75 первая проба) выпускало отряд на сотом тике против целого лагеря (счёт от
        // начала матча, m30 camp 18891:23756) и против кайтера стенда, ходящего впятером (m31 kite 1979:23896 — 25 тиков
        // отряда на 183–214-м, и бой без четверых проигран): гейт 120/125
        val largestGroup = armedEnemies.maxOfOrNull { e -> armedEnemies.count { getRange(e, it) <= ENGAGE_RANGE } } ?: 0
        val scatteredRaw = armedEnemies.isNotEmpty() && largestGroup <= maxOf(1, armedEnemies.size / 2)
        // с гистерезисом (v115): включается по «≤ половины», гаснет по сбору «≥ SCATTER_OFF_SHARE»
        val gathered = armedEnemies.isEmpty() || largestGroup * 4 >= armedEnemies.size * 3   // три четверти (SCATTER_OFF_SHARE)
        scatteredLatched = scatteredRaw
        val scattered = scatteredLatched
        val groupSeed = armedEnemies.maxByOrNull { e -> armedEnemies.count { getRange(e, it) <= ENGAGE_RANGE } }
        val largestMembers = if (groupSeed == null) armedEnemies else armedEnemies.filter { getRange(groupSeed, it) <= ENGAGE_RANGE }
        // дебют-гонка (v91, см. USE_SCATTER_RACE): россыпь его армии до первого обмена
        // «мы ближе» — всей силой, с уже выпущенными бегунами (v120): бегун, выпущенный к свободному флагу, и был тем, кем мы
        // были ближе; без него гонка кончалась, его отзывали, а следующим тиком выпускали снова — 1260 строк detach за
        // матч (split m31), постура мигала с ним ДОБИТЬ↔ДЕРЖАТЬ через тик (наша мощь 4179↔3502)
        val raceForce = army + ctx.runners.filter { it.id in Memory.detachedIds }
        // цель гонки — и флаг под стаей, которую бьёт ПАРА наших слабейших бегунов (v125, USE_RACE_PAIR_TARGETS): быстрый
        // гастролёр (けろびー#4, серия 327–346) оставляет на каждом взятом флаге одного хранителя, тот уходит от наших в шести и
        // возвращается — «свободных» флагов нет, гонка v91 молчала (targets=0), армия толкала его пятёрку 200 тиков, а его
        // хранители держали шесть флагов (стенд blitz: 4-4 при 1:6 к 200-му)
        val racePair = army.filter { hasWeapon(it) && fullSpeed(it) && it.id !in Memory.keeperIds && it.id !in Memory.rotatingIds }
            .sortedBy { ourPowerOf(listOf(it), emptyList()) }.take(2)
        fun pairBeats(f: FlagInfo): Boolean {
            if (racePair.size < 2) return false
            val pack = armedEnemies.filter { getRange(it, f.pos) <= ENGAGE_RANGE }
            return pack.isNotEmpty() && ourPowerOf(racePair, pack) >= enemyPowerOf(pack, racePair) * PUSH_RATIO
        }
        val raceFree = ctx.flags.filter { f -> !f.ours && armedEnemies.none { getRange(it, f.pos) <= ENGAGE_RANGE } &&
            (armedEnemies.minOfOrNull { getRange(it, f.pos) } ?: 999) > (raceForce.minOfOrNull { getRange(it, f.pos) } ?: 999) }
        val racePaired = emptyList<FlagInfo>()
        val raceTargets = raceFree.size + racePaired.size
        val raceSlots = raceFree.size + racePaired.size * 2   // по два бегуна на флаг под стаей (см. USE_RUNNER_PAIRS)
        // расколот (v119): ВТОРАЯ группа его вооружённых (вне крупнейшей, в ENGAGE_RANGE друг от друга) не меньше SPLIT_MIN —
        // две группы фермера, а не отставшие от колонны на марше: первый срез «двое вне крупнейшей» стартовал гонку на
        // двадцатом тике по хвосту колонны spread, и spread m19/m31/m33 из побед в 20403:24313, 14392:24330, 14990:24318
        val rest = armedEnemies.filter { e -> largestMembers.none { it.id == e.id } }
        val secondGroup = rest.maxOfOrNull { e -> rest.count { getRange(e, it) <= ENGAGE_RANGE } } ?: 0
        val raceNow =  (scattered) && armedEnemies.size >= 4 && raceTargets > 0
        if (posture == Posture.FLAG || posture == Posture.EVADE || posture == Posture.RETREAT) lastNonHuntTick = now
        // рассыпанный остаток — вход v75 как был; блоб-остаток — под стрелковой защитой пула и только после PASSIVE_TICKS
        // охоты без FLAG/EVADE/RETREAT («охота длилась» и для россыпи задерживала отряд: spread m33 24327:24222 → 19509:24315)
        val dryHunt =  behindOnScore && lastFireTick >= 0 &&
            now - lastFireTick >= PASSIVE_TICKS && now - lastHurtTick >= PASSIVE_TICKS &&
            (scattered || (now - lastNonHuntTick >= PASSIVE_TICKS))
        fun rangedMass(cs: List<Creep>) = cs.sumOf { InfluenceMap.profileOf(it).ranged }
        val theirRangedMass = rangedMass(combatEnemies)
        val quietChain = quiet && (chaseDry || Memory.detachedIds.isNotEmpty() || (quietSinceFirstReach && lostRaceNow))
        // МИЛИ, КОТОРЫЙ НЕ ДОСТАЁТ, — НЕ АРМИЯ, А ОТРЯД (v194, USE_IDLE_MELEE_RUNS). Отряд набирается только против
        // соперника, помеченного `farmer`, а этот ярлык требует, чтобы он НЕ ДРАЛСЯ: `raceNow` хочет его россыпи,
        // `dryHunt` — тишины по огню и урону. Coldkimchi#2 дерётся и фармит флаги ОДНОВРЕМЕННО — держит плотный
        // блок в контакте (massed=true каждый тик) и отряжает 2–4 крипа за флагами, — и категории для такого у нас
        // нет. Замер по двенадцати играм v191: отряжённых бойцов ноль во ВСЕХ матчах, флаговый забег мы ведём
        // двумя разведчиками по сто хитов, и медиана скорости очков выходит 3 против его 15 к шестисотому тику;
        // пять поражений из двенадцати — это забег, проигранный в первой трети, при целой армии. Основание отряда
        // здесь не ярлык соперника, а НАША измеренная бесполезность: мили, за окно контакта ни разу не
        // дотянувшийся, в бою не участвует, и все пороги выпуска ниже считают его вклад по той же доле (v193)
        val meleeIdle =  armedEnemies.isNotEmpty() && touchShare < TOUCH_MIN
        val farmer = armedEnemies.isNotEmpty() && ((firstNearTick >= 0 && (quietChain || dryHunt)) || raceNow || meleeIdle)
        val viaDryHunt = dryHunt && !quietChain   // отряд держится только сухой охотой (v82b)
        val viaRace = raceNow && !quietChain && !dryHunt   // отряд держится только дебют-гонкой (v91)
        val detachedBefore = Memory.detachedIds.size
        // отряд без дела (v84): все отделённые DETACH_WINDOW тиков подряд без цели — отзыв, и набор ждёт то же окно
        if (Memory.detachedIds.isNotEmpty() && Memory.detachedIds.all { it in Memory.idleRunnerIds }) idleDetachTicks++ else idleDetachTicks = 0
        if (idleDetachTicks >= DETACH_WINDOW) {
            if (DEBUG_LOG) println("detach t=$now: ${Memory.detachedIds.size} recalled — nothing for a runner to take for $DETACH_WINDOW ticks")
            Memory.detachedIds.clear(); idleDetachTicks = 0; detachRecallTick = now
        }
        // поштучно (v85): отделённый DETACH_WINDOW тиков подряд без цели возвращается в ядро
        for (id in Memory.detachedIds) idleRunnerTicks[id] = if (id in Memory.idleRunnerIds) (idleRunnerTicks[id] ?: 0) + 1 else 0
        idleRunnerTicks.keys.retainAll { it in Memory.detachedIds }
        val idle = Memory.detachedIds.filter { (idleRunnerTicks[it] ?: 0) >= DETACH_WINDOW }
        if (idle.isNotEmpty()) {
            if (DEBUG_LOG) println("detach t=$now: ${idle.size} of ${Memory.detachedIds.size} recalled — without a target for $DETACH_WINDOW ticks")
            Memory.detachedIds.removeAll(idle.toSet()); idle.forEach { idleRunnerTicks.remove(it) }; detachRecallTick = now
        }
        // ОДНА ОПОРА (v95b): группа врага и порог одни для выпуска, проверки с дебаффом цели и отзыва — при гонке выпуск
        // мерился против его крупнейшей группы, а отзыв против всей армии при 1,3, и трое выходили и возвращались на
        // следующий тик (m31 camp: 173/174, 255/256). Порог ядра в проигранной гонке НЕ опускается до порога захватов
        // (PARITY_FLOOR_LOST, v88): это исключение про захват стороной, а не про раскол ядра — с 0,75 для ядра пул против
        // пар spread отпускал лишних, и spread из 6/6 стал 2/6 (m28 24322:19608 → 14960:24320); при паритете выпуска с
        // дебаффом цели просто нет, а скауты берут при 0,75 как раньше
        val coreRef = if (viaRace) largestMembers else combatEnemies
        val coreFloor = if (viaDryHunt || viaRace) PUSH_RATIO else PARITY_FLOOR
        // при россыпи (v97, USE_SCATTER_RECALL_REF) опора ОТЗЫВА — его крупнейшая группа при PUSH_RATIO; выпуск — как был
        if (Memory.detachedIds.isEmpty()) scatteredAtRelease = scattered   // без отряда ярлык свежий; с отрядом — как при выпуске (v117)
        val recallGroup = viaRace || ((scatteredAtRelease))
        val recallRef = if (recallGroup) largestMembers else combatEnemies
        val recallFloor = if (viaDryHunt || recallGroup) PUSH_RATIO else PARITY_FLOOR
        // одна мера ядра (v94): порог держится каждый тик — просело, сильнейший отделённый возвращается
        if (farmer && Memory.detachedIds.isNotEmpty()) {
            val floorNow = recallFloor
            var core = army.filter { it.id !in Memory.detachedIds }
            var recalled = 0
            val short = core.any { hasWeapon(it) } && ourPowerOf(core, recallRef) < enemyPowerOf(recallRef, core) * theirsDown * floorNow
            coreShortTicks = if (short) coreShortTicks + 1 else 0
            while (Memory.detachedIds.isNotEmpty() && core.any { hasWeapon(it) } && ourPowerOf(core, recallRef) < enemyPowerOf(recallRef, core) * theirsDown * floorNow) {
                val back = ctx.runners.filter { it.id in Memory.detachedIds }.maxByOrNull { ourPowerOf(listOf(it), emptyList()) } ?: break
                Memory.detachedIds.remove(back.id); core = core + back; recalled++
            }
            if (recalled > 0) { detachRecallTick = now; coreShortTicks = 0 }   // новый выпуск ждёт DETACH_WINDOW, как после отзыва «без цели» — иначе качели
            if (DEBUG_LOG && recalled > 0) println("detach t=$now: $recalled recalled — the core fell under ${floorNow} of him by the posture's measure")
        }
        farmerOffTicks = if (farmer) 0 else farmerOffTicks + 1
        // сброс отряда по «не фермер» — только продержавшись FARMER_OFF_TICKS (v115): одноткового моргания признака не хватает
        if (!farmer) { if (farmerOffTicks >= FARMER_OFF_TICKS) Memory.detachedIds.clear() }
        // ...и ОТПУСКАЕТ ЛИ ОТРЯД — решает командир (v164): механика выпуска проверена годом замеров и остаётся, но
        // включает её его режим, а не собственные условия. Полная замена командирской раздачей отвергнута замером:
        // 133 из 135 (roost 7 615:24 325, camp 22 304:23 966) — прежняя логика знает и сухую охоту, и гонку, и
        // охрану стрелков, чего своя раздача не покрывает
        // ...и `meleeIdle` БОЛЬШЕ НЕ СНИМАЕТ ЗАЩИТУ (v215, см. USE_NO_SPLIT_IN_FIGHT). Он стоял оговоркой к
        // обеим половинам гейта — «командир в режиме боя» и «мы в контакте», — и снимал их обе. Смысл был
        // «мили всё равно не дерутся, пусть идут за флагами», а следствие — отряд набирался посреди рубки
        // ровно тогда, когда наши мили не дотягивались, то есть по первой же жалобе оператора
        else if ((!fightOnNow &&
                      ((!contact || (!exchangeRecent)) || meleeIdle)) &&
            (now - detachRecallTick >= DETACH_WINDOW)) {
            val armed = army.filter { hasWeapon(it) && fullSpeed(it) && it.id !in Memory.keeperIds && it.id !in Memory.rotatingIds }

            val unmanned = ctx.flags.sumOf { f -> if (f.occupant?.my == true) 0 else if (armedEnemies.any { getRange(it, f.pos) <= ENGAGE_RANGE }) 2 else 1 }
            val pool = if ((viaDryHunt || viaRace || meleeIdle)) armed.sortedWith(compareBy({ InfluenceMap.profileOf(it).ranged }, { ourPowerOf(listOf(it), emptyList()) }))
                else armed.sortedBy { ourPowerOf(listOf(it), emptyList()) }
            var remaining = army.filter { it.id !in Memory.detachedIds }
            for (c in pool) {
                if (Memory.detachedIds.size >= unmanned) break
                if (viaRace && Memory.detachedIds.size >= raceSlots) break
                val without = remaining.filter { it.id != c.id }

                // без тишины (сухая охота) ядро держит охотничий перевес, не паритет
                // его мощь — против ядра-кандидата, не против полной армии (v84: пары Ланчестера)
                val theirsVsCore = (enemyPowerOf(coreRef, without)) * theirsUp
                if (without.none { hasWeapon(it) } || ourPowerOf(without, coreRef) < theirsVsCore * coreFloor) break

                if (viaDryHunt && !scattered && rangedMass(without) < theirRangedMass * PUSH_RATIO) break

                if (raceNow && InfluenceMap.profileOf(c).ranged > 0.0 && rangedMass(without) < rangedMass(largestMembers) * PUSH_RATIO) break

                // компактная крупнейшая группа (см. USE_RANGED_GUARD_COMPACT): та же защита на любой цепочке
                // ...первый срез «крупнейшая группа не меньше COMPACT_MIN» ОТВЕРГНУТ: split 6-2 → 4-4 (m28 24 307:20 109 → 18 643:24 298, m32
                // 24 291:20 558 → 23 651:24 298) — расколотый фермер (6–7 из 13 в группе) обгоняет нас по флагам, когда стрелки не бегут;
                // второй срез: компактная = не меньше двух третей его вооружённых в одной группе (けろびー#4: 11 из 11)
                val target = ctx.flags.filter { !it.ours && it.occupant?.my != true }
                    .minByOrNull { f -> getRange(c, f.pos) + (if (armedEnemies.any { getRange(it, f.pos) <= ENGAGE_RANGE }) 100 else 0) }
                if (target != null) {
                    val (oursAfter, theirsAfter) = powerAfterFor(ctx, without, coreRef, target)
                    if (oursAfter < theirsAfter * coreFloor) break
                }
                Memory.detachedIds.add(c.id)
                splitAll++; if (fightOnNow) splitFight++
                remaining = without
            }
        }
        if (DEBUG_LOG && Memory.detachedIds.size != detachedBefore)
            println("detach t=$now: ${Memory.detachedIds.size} detached (was $detachedBefore) farmer=$farmer dryHunt=$dryHunt race=$raceNow targets=$raceTargets(${racePaired.size} paired) largest=$largestGroup/${armedEnemies.size} dry=${now - lastDistanceKeptTick} hurt=${now - lastHurtTick} fire=${now - lastFireTick} reach=${now - lastReachTick} contact=$contact theirs=${theirs.toInt()}")
        val interceptDenies = interceptFlag != null && !interceptFlag.ours
        // ЗАЧИСТКА ФЛАГОВ ВМЕСТО ПОГОНИ (v124, стенд blitz m28 на v122, 3961:23980): позади по очкам против врага, который не
        // дерётся, армия 200 тиков (42–239) толкала его пятёрку в 647 мощи при своих 3575 — та уходит в шести на той же
        // скорости, — пока его одиночные хранители держали шесть флагов; флаг под одним-двумя его крипами армия берёт, а
        // группу не догоняет. Есть цель-флаг, проходящая гейт стаи, — погоня снята, как при перехвате
        // ...и не по ярлыку «не дерётся» (он гаснет, пока его хранители мелькают в досягаемости), а по сухости самой погони: ни
        // нашего выстрела, ни удара по нам PASSIVE_TICKS подряд (blitz m28: с 83-го по 239-й ни того ни другого при ANNIHILATE)
        // страховка CPU на постуре (v131c): тик уже дороже CPU_GUARD_MS — цель-флаг оценивается только текущая, потоки выхода не
        // пересчитываются; тёплые тики (6–9 мс на стенде) сюда не доходят
        val cpuGuardArmy =  now > 1 && cpuMs() > CPU_GUARD_MS
        if (cpuGuardArmy && DEBUG_LOG) println("cpu t=$now guard: posture keeps the objective (${(cpuMs() * 10).toInt() / 10.0}ms)")
        val dryNow = (lastFireTick < 0 || now - lastFireTick >= PASSIVE_TICKS) && now - lastHurtTick >= PASSIVE_TICKS
        val sweepObjective: FlagInfo? = null   // USE_SWEEP_OVER_CHASE снят (v214): см. docs
        cpuMark("a.sweep")
        val chaseVeto = (enemyNotFightingNow && (interceptDenies || !behindOnScore)) || sweepObjective != null
        // ОТКРЫТАЯ НАХОДКА (матч 70): второй источник мигания — «ловимых нет»: блоб, шагнувший назад на две клетки, делает
        // «уходящими» всех двенадцать на восемь тиков (см. evasive), и наступление снимается на эти тики, армия к посту.
        // Два устранения ОТВЕРГНУТЫ стендом: гистерезис по ловимости (наступление снимается лишь после целого CHASE_WINDOW без
        // ловимых) — 51 хуже / 51 лучше, гейтовые m28 farm+weak и m30 camp красные, кайтеры добиваются позже на десятке карт,
        // m16 kite проигран; порог evasive «больше половины окна» — 66 хуже / 44 лучше. Быстрое снятие наступления, когда
        // ловимых нет, — то, чем армия не гонится за кайтером; цена — эти тики против блоба, который отступает и возвращается
        // отрыв с темпом (v127, USE_LEAD_HOLDS): впереди по счёту и по проекции — толчка и прижима нет, бой только его
        val leadHolds =  !behindOnScore && ourScore > enemyScore && armedEnemies.isNotEmpty()
        if (DEBUG_LOG && leadHolds != leadHoldsWas) println("lead t=$now: holds ${if (leadHolds) "on" else "off"} score=$ourScore:$enemyScore rate=$ourRate:$enemyRate push=${oursPush.toInt()}:${theirsPush.toInt()}")
        leadHoldsWas = leadHolds
        val pushRaw = !stalled && !leadHolds && (sweep || (exchangePaying && !chaseVeto && huntable.isNotEmpty() && strikers.isNotEmpty() && oursPush >= theirsPush * (if (pushing) pushRelease else pushRatio)))
        // ...и СРОК (v215, см. USE_PUSH_DWELL): начатое наступление живёт минимум PUSH_DWELL тиков, и снимают его
        // досрочно только затор и настоящая слабость — мощь ниже порога отпускания. Мигание любого из пяти прочих
        // множителей за этот срок армию не разворачивает.
        // ...ТОЛЬКО В ИДУЩЕМ БОЮ, и это не осторожность, а замер: без оговорки строка match28:scatter перестала
        // проходить гейт, а отрыв упал на 40 509. Причина по существу записана соседним комментарием: быстрое
        // снятие наступления, когда ловимых нет, — это ровно то, чем армия не гонится за кайтером и за рассыпавшимся
        // фермером. Разворот, на который жалуется оператор, случается В БОЮ; вне боя мигание `huntable` полезно.
        // ⚠️ Мерились три редакции, и средняя выбрана не по вкусу, а по числам:
        //   без оговорки вовсе — строка match28:scatter НЕ ПРОХОДИТ гейт, отрыв −40 509;
        //   `fightOnNow` (эта) — FAIL нет, отрыв −3 545, 90 строк не тронуты, срок срабатывает на 0,6 % тиков,
        //      смен постуры 5,12 -> 4,74 на сто тиков, и все пять «потерянных» уничтожений стали крупными
        //      победами по очкам (match31:camp: уничтожение при ПРОИГРЫШЕ 4 391:6 400 -> отрыв 23 245:18 056);
        //   `meleeAdjacent` (его мили вплотную) — стенд ровный (134 строки без изменений), но срок срабатывает
        //      ОДИН раз на 125 110 тиков. Это не осторожная редакция, а мёртвый код, и потому отвергнута.
        // Живое основание сильнее стендового: из 1 189 быстрых смен постуры в рейтинговой серии 852 несут смену
        // `pushing`, а стенд в режим боя почти не входит (cmdwhy fight:8 из 570 тиков). Судит живая серия
        pushHeld = false
        // ...и РАЗМЕН НИЖЕ ПАРИТЕТА ГАСИТ НАСТУПЛЕНИЕ (v217, см. USE_BREAK_OFF_HOLDS_LINE), а не разворачивает
        // армию: толчка вперёд нет, строй и лекари остаются
        // ...и БЕЗ СВОЕГО pushTicks++ (v218, дефект прибора): счётчик увеличивается безусловно десятью строками
        // ниже, поэтому на тиках размена он рос ДВАЖДЫ — и `pushheld` занижался ровно на тех тиках, ради которых
        // прибор и ставился
        if (breakOffNow) { pushing = false } else
        pushing = when {
            pushRaw -> { if (!pushing) pushSince = now; true }
            pushing && fightOnNow && now - pushSince < PUSH_DWELL && !stalled && oursPush >= theirsPush * pushRelease -> {
                pushHeld = true; pushHeldTicks++; true
            }
            else -> false
        }
        pushTicks++
        // бой по контакту — пока отход невозможен: мили врага вплотную. Решение ТИК ЗА ТИКОМ, и это не дрожание, а
        // кайт погони: слабее — отходим, стреляя и рубя на ходу (strike/shoot идут в любой постуре); догнал мили —
        // вся армия разворачивается на него (авангард погони один против всех), отстал — снова отход. На стенде
        // sleeper при 0.83 это 10:0; «поймали — деремся до конца контакта» дало 2:11, «слабее — только отход» 2:6
        // ...И КОНТАКТ БЕЗ РАЗМЕНА ХИТОВ С ИДУЩИМ ВРАГОМ — НЕ БОЙ (v221, см. USE_FIGHT_BY_LEDGER): стояние в трёх–пяти
        // клетках от его тычущей линии, за окно которого ни одна сторона не потеряла STALL_DAMAGE, держало армию без
        // флаг-цели 35 % проигранных забегов. Бой, как и прежде: его мили вплотную, загнанная неподвижная группа
        // (cornered) и — см. USE_WARM_NEEDS_HIS_MOVE — любой СТОЯЩИЙ враг в контакте: стоящего атакуем мы
        // `warmNow` считается здесь один раз и читается постурой, линией и приборами — одна величина на всех
        val hisStill = Memory.hisCentHist.size >= 2 && run {
            val a = Memory.hisCentHist.first(); val b = Memory.hisCentHist.last()
            maxOf(abs(a / 100 - b / 100), abs(a % 100 - b % 100)) < APPROACH_WINDOW / 4
        }
        val warmNow = contact && !exchangeLive && !meleeAdjacent && !cornered 
        val hotContact = contact 
        // ⚠️ Здесь стояла охрана `&& !(retreatFeasible && weakerContact)`, и она ВАКУУМНО ИСТИННА всегда, когда
        // остальная конъюнкция может быть истинной. Доказательство в две строки: `hotContact` требует `contact`,
        // сама конъюнкция требует `strikers.isNotEmpty()`, а `retreatFeasible = (!contact || strikers.isEmpty())
        // && !atRetreatPoint` — при обоих этих условиях он ЛОЖЕН по построению. Значит `weakerContact` —
        // тщательно настроенное тройное отношение (1.5 в ANNIHILATE, 1.05 в RETREAT, иначе 1.15) — не читался в
        // контакте НИ РАЗУ, то есть ровно там, где задумывался. Снято в v217; дифф отчёта пуст побайтово.
        // ⚠️ И оживлять его НЕ НАДО, это отдельное решение с двумя основаниями. Первое: живая редакция сделала бы
        // `contactFight` ложным при слабости в контакте, а с ним погасли бы `annihilate` и постура ANNIHILATE —
        // то есть отменилось бы решение оператора «держать линию» (см. USE_BREAK_OFF_HOLDS_LINE), принятое
        // строкой выше по той же причине. Второе: это и есть «слабее — только отход», замеренное 2:6 против 10:0.
        // Намерение охраны теперь исполняет гашение наступления, и исполняет его, не разворачивая армию
        val contactFight = !stalled && armedEnemies.isNotEmpty() && strikers.isNotEmpty() && hotContact
        // СПЕРВА ТУШИМ МЕСТНЫЙ ОЧАГ (v214, оператор по записи: «загнали в угол 2-3 крипа, мы там значительно
        // сильнее, но армия разворачивается и убегает в другой конец карты; нужен механизм, который сперва тушит
        // местный очаг, если мы сильнее, и лишь затем бежит на помощь»).
        // Причина ухода: гаснет pushing — от leadHolds (мы ВПЕРЕДИ по счёту, значит толчок запрещён), от простоя,
        // от пустого huntable, от отношения мощи, — и строкой ниже флаг-цель выбирается ПО ВСЕЙ КАРТЕ. Вето поверх
        // результата ловит все четыре причины разом, а не каждую по отдельности.
        // Три сомножителя, все уже посчитаны: бой идёт у МАССЫ армии; среди его крипов в контакте есть тот, по
        // которому наш залп в его клетке сильнее его залпа в PUSH_RATIO раз и которого мы добиваем; и стая,
        // УСПЕВАЮЩАЯ прийти (fightPack), слабее нас с запасом наступления — то есть «выигрываем» здесь значит
        // выигрываем по Ланчестеру с лечением, а не «бьём сильнее».
        val spotFoes = armedEnemies.filter { e ->
            army.any { getRange(e, it) <= RANGED_RANGE + 1 } && spotEdgeAt(e) >= PUSH_RATIO }
        // ⚠️ добиваемость (killTicks) здесь НЕ проверяется намеренно: она объявлена ниже постуры. Её роль тут
        // исполняет третий сомножитель — oursFight >= theirsFight * PUSH_RATIO считает лечение по Ланчестеру,
        // то есть очаг у трёх его лекарей этот порог не берёт. В цепочке целей (см. spotNow) killTicks на месте
        val holdingSpot =  contact && spotFoes.isNotEmpty() && oursFight >= theirsFight * PUSH_RATIO
        if (holdingSpot) {
            spotHoldAll++
            if (!(pushing || contactFight)) spotHoldNew++     // пара: сколько раз вето ИЗМЕНИЛО постуру
        }
        // ...и в режиме выживания бой не объявляется, пока есть куда уходить (v223, см. USE_SURVIVAL). Точка уклонения
        // считается здесь, до постуры: вторая редакция — нет точки и он в контакте, значит бой строем, а не стояние в
        // отходе (первая редакция парковала армию у точки отхода, и он добивал её там, стоящую: 0-8 против Coldkimchi#1)
        // поля выхода — этим тиком, а не прошлым: на первом тике режима их ещё нет, и уходить было бы «некуда»
        val survEvade = null
        val annihilate = (pushing || contactFight || holdingSpot) 
        // ПРИБОРЫ ТЁПЛОГО КОНТАКТА (v221, пары к USE_FIGHT_BY_LEDGER, `warmNow` — см. hotContact): ровно то, что правка
        // называет «не боем». `warm` — доля такого контакта во всём контакте; `warmann` — тики, где боевую постуру
        // держал только он (не толчок и не очаг; с правкой — ноль по построению); `warmhold` — из них тики, где
        // флаг-цель подхватила бы «держим линию»
        if (contact) { warmContact++; if (warmNow) warmTicks++ }
        if (annihilate) {
            warmAnnAll++
            if (warmNow && !pushing && !holdingSpot) { warmAnn++; if (enemyNear && !stalled) warmHold++ }
        }
        // непобедимая армия (см. EVADE_SAFE): с ней не деремся — флаг-цель только с выходом, иначе уклонение на любой
        // дистанции: держимся там, откуда есть выход, и уходим, когда она подходит
        // уклонение — только от ЯВНО сильнейшей армии (см. RETREAT_RATIO): при паритете флагов (v14) бой равный, и бежать
        // от него на равной скорости — быть пойманным с растянутым хвостом (матчи 11–12); прежнее «не сильнее для
        // добивания» уводило и от равной армии. Поля выхода нужны и бегунам без армии (см. runnerEscape)
        // от безфлагового броска (см. EVADE_EQUAL_RATIO) уклоняемся уже при равной силе
        // ПРЕСЛЕДУЕМЫ ТОЛЬКО ТЕМ, КТО МОЖЕТ ДОЙТИ (v129, USE_HUNTED_NEEDS_REACH): его вооружённый центроид дальше HUNTED_FAR и темп
        // сближения ниже APPROACH_RUSH — не hunted, и цель-флаг не снимается ради уклонения. Матч 407 (MetalicaX#4, тур): с 1269-го
        // FLAG на один тик (его H4 в (8,90), travel 43) и EVADE следующим — по одной силе 3559/3044 = 1,17 при его армии в 47 клетках
        // и approach=0; 530 тиков на R3, два бегуна без дела, отставание 1750–3250 досягаемо, проигрыш у предела. Повернёт к нам
        // из-за HUNTED_FAR — окно темпа увидит это, пока он ещё в EVADE_RANGE: тот запас, на который уклонение и построено
        // ...и только при ПРОИГРАННОЙ гонке (второй срез, lostRaceNow: проекция на конец матча проиграна, PASSIVE_TICKS без удара по нам):
        // без этого армия переставала уклоняться от далёкого фермера двух групп, которого обыгрывала по очкам, и шла за флагами
        // в его группы — split без одного мили 7-1 → 3-5 при tour 5-3 → 6-2; «далеко» — его БЛИЖАЙШИЙ вооружённый (третий срез):
        // центроид фермера двух групп лежит между ними, далеко от нас при группе рядом
        val hunted = armedEnemies.isNotEmpty() && strikers.isNotEmpty() &&
            (theirsFight >= oursFight * RETREAT_RATIO || (unflaggedRushNow && theirsFight >= oursFight * EVADE_EQUAL_RATIO))
        val escapeNeeded = hunted || (armedEnemies.isNotEmpty() && strikers.isEmpty())
        // темп сближения врага (0 — стоит, 1 — идёт на нас): запас выхода даёт ему фору только в этом темпе — фора «идёт
        // к выходу мгновенно» отвергала всякую цель при враге, стоящем дома, и армия весь матч сидела дома (стенд m1 scouts)
        run {
            val ec = centroidOf(armedEnemies)
            if (ec != null) { Memory.enemyDistHist.addLast(getRange(ec, ctx.ourCentroid)); while (Memory.enemyDistHist.size > APPROACH_WINDOW) Memory.enemyDistHist.removeFirst() } else Memory.enemyDistHist.clear()
            val ac = centroidOf(armedEnemies)
            if (ac != null) { Memory.hisCentHist.addLast(ac.x * 100 + ac.y); while (Memory.hisCentHist.size > APPROACH_WINDOW) Memory.hisCentHist.removeFirst() } else Memory.hisCentHist.clear()
            if (ac != null) { Memory.ourCentHist.addLast(ctx.ourCentroid.x * 100 + ctx.ourCentroid.y); while (Memory.ourCentHist.size > APPROACH_WINDOW) Memory.ourCentHist.removeFirst() } else Memory.ourCentHist.clear()
            approachRate = if (Memory.enemyDistHist.size >= 2) ((Memory.enemyDistHist.first() - Memory.enemyDistHist.last()).toDouble() / (Memory.enemyDistHist.size - 1)).coerceIn(0.0, 1.0) else 0.0
        }
        if (escapeNeeded && !(cpuGuardArmy && escapeFlows.isNotEmpty())) refreshEscape(ctx, armedEnemies) else if (!escapeNeeded) { escapeFlows.clear(); escapeTheirs.clear(); escapeNearest.clear(); evadeLeft = null }
        cpuMark("a.escape")
        // враг близко (см. EVADE_RANGE) — уклонение раньше целей; далеко — цели с выходом, иначе безопасная точка
        val enemyClose = (hunted) && armedEnemies.any { getRange(it, ctx.ourCentroid) <= EVADE_RANGE }
        val evadeFirst = if (enemyClose && !annihilate && !contact) evadePoint(ctx, armedEnemies, strikers) else null
        // враг рядом (см. NEAR_RANGE) без нашего перевеса — не цель, а строй: армия, пошедшая за угловым флагом при
        // подходящем враге, была поймана колонной на марше (стенд m3 sleeper, t=529–540); флаги в это время — скаутам
        // ...и тёплый контакт линии не стоит (v221, см. USE_FIGHT_BY_LEDGER): иначе, погасив боевую постуру, правка
        // отдала бы флаг-цель этой же строке — и армия осталась бы у поста, как в v90
        val holdLine = enemyNear && !pushing && !annihilate && !stalled && !(farmerQuietNow)    // тихий фермер линии не стоит (v105)
        val interceptObjective: Objective? = interceptFlag?.takeIf { !it.ours && captureAllowed(ctx, it) }?.let { f ->
            val group = strikers.ifEmpty { mobileArmy }
            val flow = flowTo(ctx, f.pos)
            Objective(f, emptyList(), 1.0, group.maxOfOrNull { pathTicks(it, flow, it.x * 100 + it.y) } ?: 0)
        }
        val objective = if (annihilate || evadeFirst != null || (holdLine && interceptObjective == null)) null else interceptObjective ?: chooseFlagObjective(ctx, strikers.ifEmpty { mobileArmy }, pushRatio, hunted , if (cpuGuardArmy) objectiveFlagId else null)
        // ПОЧЕМУ У АРМИИ НЕТ ФЛАГ-ЦЕЛИ (v216). Постура HOLD занимает 43–58 % матча, и в ней армия стоит в точке,
        // которая не даёт очков, при 2,3–2,6 ничьих флагах на доске. Причин ровно четыре, и прежде чем менять
        // поведение, надо знать, которая из них держит: «пост на флаге» уже мерили дважды (v214: любой не его флаг
        // −23 570, суженный до разрешённых гейтом −6 905) и оба раза отвергли, поэтому третий заход вслепую
        // недопустим
        if (objective == null) {
            val why = when {
                annihilate -> "annihilate"
                evadeFirst != null -> "evade"
                holdLine -> "holdLine"
                else -> "gate"
            }
            objNone[why] = (objNone[why] ?: 0) + 1
        }
        objAll++
        cpuMark("a.obj")
        // дебют без угла (v100, USE_OPENING_AT_POST): бросок далеко — не уклонение, а пост. И «далеко» значит ДАЛЕКО
        // (v135, см. USE_RUSH_FAR_NEEDS_RANGE): условие правила было только про силу, поэтому при паритете оно гасило
        // уклонение и вплотную — в разгромах от блоба `rush=true` с 10-го тика, HOLD на посту до 39-го, контакт, и наша
        // мощь ноль к 81-му. Пока его вооружённый центроид дальше EVADE_RANGE, бросок — повод занять пост; ближе — повод
        // уклоняться, как и говорит доктрина (EVADE_EQUAL_RATIO: от сомкнутой безфлаговой армии не слабее нас уклоняемся)
        val rushFar =  unflaggedRushNow && theirsFight < oursFight * RETREAT_RATIO 
        // уклонение от БЛИЗКОГО сомкнутого броска не ждёт `hunted` и не мигает (v135, см. USE_EVADE_STICKY_RUSH): в первой
        // пробе EVADE появлялась на 57-м и отпускалась на 62-м, армия дёргалась и всё равно попадала в контакт
        // ⚠️ Здесь стоял `rushEvade`, тождественно ложный: `USE_EVADE_STICKY_RUSH` выключен своим замером
        // (1-5 и 1-5, ровно база), а операнд `hunted || rushEvade` из-за этого сводится к `hunted`. Снято в
        // v217; дифф отчёта пуст побайтово, как и обязан быть у мёртвого
        val evadeTo = evadeFirst ?: (if ((hunted) && !rushFar && !annihilate && (!contact) && objective == null) evadePoint(ctx, armedEnemies, strikers) else null)
        cpuMark("a.evade")
        val evade = evadeTo != null
        if (!evade) evadeTarget = null
        // ...и в выживании отход к ТОЧКЕ не берётся: стоящую у точки армию он добивает (v223, вторая редакция)
        val retreat = armedEnemies.isNotEmpty() && !annihilate && objective == null && !evade && enemyNear && weaker && retreatFeasible 
        // ---- меры, которые читает решение о режиме командира (подняты сюда в v241: одно решение — одни входы) ----
        // боеспособные: вооружённые и лекари — фокус, контакт и местные группы считаются по ним, раненые не в счёт
        val combatArmy = army.filter { hasWeapon(it) || hasHeal(it) }
        // «их мили в бою» — только ВПЛОТНУЮ к нашему вооружённому: в 2–3 клетках это экран, не атака. Матч 43 (けろびー v2):
        // его мили сорок тиков стояли в двух-трёх от наших и не били (вплотную 7 % крип-тиков, 8 ударов за бой), его стрелки в
        // трёх снимали наших мили по одному (r→melee 132 из 180), а прижим считал «мили в трёх» атакой и молчал до 104-го
        val theirMeleeIn = combatEnemies.any { e -> InfluenceMap.profileOf(e).melee > 0.0 && combatArmy.any { hasWeapon(it) && getRange(e, it) <= 1 } }
        val underTheirFire = combatArmy.any { InfluenceMap.damageAt(it.x, it.y, combatEnemies) > 0.0 }
        val retreatByDistance = Memory.enemyDistHist.size >= 2 && Memory.enemyDistHist.last() > Memory.enemyDistHist.first()
        // ...и по ЕГО шагу (v222, см. USE_RETREAT_BY_HIS_STEP): его центр сейчас против его центра в начале окна, оба — от
        // нашего центра в начале окна
        val retreatByHisStep = Memory.hisCentHist.size >= 2 && Memory.ourCentHist.size >= 2 && run {
            val o = Memory.ourCentHist.first(); val a = Memory.hisCentHist.first(); val b = Memory.hisCentHist.last()
            val op = InfluenceMap.cell(o / 100, o % 100)
            getRange(InfluenceMap.cell(b / 100, b % 100), op) > getRange(InfluenceMap.cell(a / 100, a % 100), op)
        }
        if (retreatByDistance) { rtrOld++; if (!retreatByHisStep) rtrRemoved++ } else if (retreatByHisStep) rtrAdded++
        // ...и снимается только ЛОЖНЫЙ ярлык (v222, вторая редакция): «отходит», если расстояние выросло И сдвинулся он.
        // Первая редакция (одно «его шаг») ещё и ДОБАВЛЯЛА ярлык там, где мы теснили его быстрее, чем он пятился, — и
        // командир уходил из FIGHT посреди выигрываемой погони: доля FIGHT в тиках размена 18 % -> 11 % против
        // MetalicaX#4 и 68 % -> 45 % против Coldkimchi#1, разница очков +1208 -> +232 и +3290 -> −3538
        val enemyRetreating = retreatByDistance && (retreatByHisStep)
        // сколько его вооружённых стоит у нашей армии: группа — дело командира, одиночка — нет
        val foesAtHand = armedEnemies.count { e -> massArmy.any { getRange(e, it) <= RANGED_RANGE + 1 } }

        // ОТВЕРГНУТО стендом (v58-опыт): снимать простой, когда паритет не пускает ни к одному флагу (матч 133: «марш не сдвинулся —
        // флаги до 479» при 1,32 к лагерю на D5, obj=- все 300 тиков, 18 против 7 в тик). На стенде m31 camp снятый на 536-м простой
        // дал 700 тиков ANNIHILATE pushing при 3679 против 1209 без единого убитого (центры армий в одной клетке, reach 0/5) —
        // 17133:23618 вместо «стёрт на 776-м», где к нему армию довела ЦЕЛЬ-ФЛАГ D5 (412–536). Толчок к стоящему блобу не
        // сближается — открытая находка матчей 70 и 133
        // РЕШЕНИЕ О СОСТОЯНИИ АРМИИ — ОДНО (v241, этап 6): постура, её гистерезис, режим командира и перезапись постуры
        // режимом боя считаются вместе в Strategist.decide; здесь применяется то, что относится к постуре, ниже — режим
        val decision = Strategist.decide(Strategist.Inputs(
            annihilate = annihilate, hasObjective = objective != null, evade = evade, retreat = retreat,
            marchNow = !contact && armedEnemies.none { e -> massArmy.any { getRange(e, it) <= MARCH_SAFE } },
            stalled = stalledNow, hisRetreat = enemyRetreating && !(underTheirFire && theirMeleeIn),
            outmatched = outmatchedTicks >= BREAK_OFF_TICKS, pushing = pushing, underFire = underTheirFire,
            fewFoes = !(enemyMassedNow || foesAtHand >= COMMAND_MIN_FOES),
            posture = posture, postureSince = postureSince, now = getTicks(),
            candidate = Memory.postureCandidate, candidateSince = Memory.candidateSince,
            // событие — прибор evt= (в гистерезис пока не входит, см. Strategist.decide): гибель своего (по числу живых,
            // не по составу армии — отряжённый в бегуны не потеря) и смена владельца флага. Замер v242 на стенде: события
            // в гистерезисе — любое изменение контакта 635 за матч, появившийся контакт 126, гибель + флаг 71 — и каждое
            // роняло scatter m34 (24 326:23 996 → 24 305:24 317 → 19 010:24 312) при 34/34/19 сценариях с иным счётом
            event = ctx.myCreeps.size < Memory.armyPrev || flagFlipNow))
        Memory.contactPrev = contact
        Memory.armyPrev = ctx.myCreeps.size
        Memory.postureCandidate = decision.candidate
        Memory.candidateSince = decision.candidateSince
        if (decision.event) stateEventTicks++
        // ПРИНЯЛА ЛИ ПОСТУРА НОВОЕ ЗНАЧЕНИЕ — считается ЗДЕСЬ, до всех, кто от этого зависит (v215). Прежде
        // решение принималось на сорок строк ниже, а `objectiveFlagId` присваивался выше и безусловно
        val newPosture = decision.newPosture
        val postureTakes = decision.postureTakes
        // ЦЕЛЬ-ФЛАГ НЕ ОБНУЛЯЕТСЯ, ПОКА ПОСТУРА УДЕРЖАНА (v215). Дефект был в паре: гистерезис держит ANNIHILATE,
        // а `objective` при аннигиляции равен null — и `objectiveFlagId` обнулялся, хотя постура осталась прежней.
        // Следствие через тик: `chooseFlagObjective` теряет бонус ×1,25 за текущую цель (3545) и послабление
        // LOCAL_ENTER_RATIO (3535), и цель выбирается заново ПО ВСЕЙ КАРТЕ. Ровно это оператор и видел: «пару тиков
        // погоня, потом разворот». Новое значение берётся всегда; ОБНУЛЕНИЕ — только вместе с постурой
        val newFlagId = objective?.flag?.id
        if (newFlagId != null || postureTakes) objectiveFlagId = newFlagId
        // ТОЧКА ОТХОДА БЕРЁТСЯ ИЗ ПОСТУРЫ, КОТОРАЯ БУДЕТ ПРИНЯТА (v217). Обе строки ниже спрашивали
        // `newPosture` — намерение, — а действует `posture`, и они расходятся всякий раз, когда гистерезис
        // удерживает прежнюю. Удержанный RETREAT при другом намерении обнулял `retreatTarget` и оставлял
        // `retreatTo` пустым, после чего ветка отхода в цепочке целей не срабатывала ни одного тика, и крипы
        // проваливались до последней ветки — `post`, в геометрическую точку своих флагов, спиной к врагу.
        // «Отступающая» армия при этом не отступала: у неё просто не было куда.
        val postureNow = if (postureTakes) newPosture else posture
        if (postureNow != Posture.RETREAT) retreatTarget = null
        val retreatTo = if (postureNow == Posture.RETREAT) retreatPoint(ctx) else null
        // ДЕРЖИ, ЧТО ДЕРЖИШЬ (v66): армия, стоящая на своём флаге при враге рядом, постом считает этот флаг, а не дальний пост.
        // Матч 159 (けろびー, пятнадцатый проигрыш фермеру 12009:24099): он кайтит вокруг D5 при 4075 против 3084, при huntable 0
        // армия уходила в HOLD к посту (11,68) за сорок клеток, он возвращался на D5; на 800-м и 1000-м мы стояли на D5 (хранитель
        // melee_1 на 1009-м снят на 1011-м — девять его вооружённых в десяти клетках не пикет) и снова уходили. «Держать линию,
        // где стоит» стенд отверг (v42: 58 хуже / 48 лучше — возврат к посту добивает отбитый рывок); здесь — только свой флаг под
        // ногами
        val standingFlag = if (enemyNear) ctx.flags.firstOrNull { it.ours && getRange(it.pos, ctx.ourCentroid) <= POST_STANDOFF } else null
        // ПОСТ НА ФЛАГЕ, А НЕ В ГЕОМЕТРИЧЕСКОЙ ТОЧКЕ (v214, оператор: «после битвы очень долго стоим и не идём
        // перебивать флаги, даже если сильнее»). Когда флаг-цели нет, постура становится HOLD, и цепочка целей
        // отправляет крипа на `post` — центроид наших флагов, стояние на котором не даёт НИ ОДНОГО очка.
        // `standingFlag` уже делает половину работы: при враге рядом постом становится наш флаг под ногами.
        postAll++
        val post = standingFlag?.pos ?: if (interceptFlag?.ours == true) interceptFlag.pos else postPoint(ctx)
        val postureKey = "$newPosture:${objectiveFlagId ?: ""}"
        if (DEBUG_LOG && (postureKey != postureLogged || getTicks() % (LOG_EVERY * 10) == 0)) {
            postureLogged = postureKey
            println("posture: $newPosture t=${getTicks()} our=${ours.toInt()} enemy=${theirs.toInt()} near=$enemyNear contact=$contact pushing=$pushing huntable=${huntable.size}/${combatEnemies.size} retreatFeasible=$retreatFeasible strikers=${strikers.size}/${army.size} " +
                "obj=${objective?.let { "(${it.flag.pos.x},${it.flag.pos.y})${typeChar(it.flag.type)}${it.flag.score} pack=${it.pack.size} travel=${it.travel} v=${(it.value * 100).toInt()}" } ?: "-"} " +
                "retreatTo=${retreatTo?.let { "(${it.x},${it.y})" } ?: "-"} evadeTo=${evadeTo?.let { "(${it.x},${it.y})" } ?: "-"} approach=${(approachRate * 100).toInt()} post=(${post.x},${post.y}) behind=$behindOnScore/$behindTicks hunt=$huntingThreat fight=${theirsFight.toInt()}/${fightPack.size}${if (fightAll) "" else " ourFight=${oursFight.toInt()}"} push=${theirsPush.toInt()}/${pushPack.size}${if (pushAll) "" else " ourPush=${oursPush.toInt()}"}")
        }
        // ГИСТЕРЕЗИС ПОСТУРЫ (v181, разбор разгрома 3d94bf): одиннадцать переходов за сто тиков — армия пять раз подряд
        // дёргалась EVADE↔HOLD, теряя и темп, и строй; сам диагноз это и называл («a hysteresis is missing somewhere»).
        // Постура держится минимум POSTURE_HOLD тиков, и раньше срока меняется только в сторону спасения — на RETREAT
        // или EVADE, потому что решение бежать ждать нельзя
        // ...и ИЗЪЯТИЕ ДЛЯ EVADE САМО РОЖДАЛО ПИЛУ (v183). Уход в спасение не ждёт срока, но EVADE — не спасение, а
        // «отступи на шаг», и без срока получалась ровно пила с периодом POSTURE_HOLD: EVADE на 54-м, HOLD на 59-м
        // (срок вышел), EVADE на 62-м, HOLD на 67-м, EVADE на 74-м — семь переходов за сто тиков перед контактом в
        // тестовой игре 3d95b5, и каждый EVADE отодвигал армию назад, пока он шёл вперёд: к первому выстрелу наш центр
        // стоял в восьми клетках от края, и все 37 тиков боя прошли спиной к стене. Срока не ждёт только RETREAT
        // «ПОСТАНОВКА ПРИМЕНЯЕТСЯ ОДИН РАЗ» (v242) ОТВЕРГНУТА живым A/B: постура после перезаписи режимом боя, действующая
        // отсюда (её видели бы фокус, строй и blockOn), вместе с «одним составом для прогноза» дала против MetalicaX#15 0-8
        // при контроле v241 2-6 (армия в ноль 7 из 8 против 6, леджер −53 315 против −34 943), против Coldkimchi#2 3-5
        // против 2-6 при леджере −50 855 против −29 572. Здесь применяется постура после гистерезиса, перезапись режимом
        // боя — ниже, там, где стояла (v241)
        posture = decision.posturePre
        postureSince = decision.postureSincePre
        cmdMode = decision.cmdMode
        val cmdWhyNow = decision.cmdWhy

        // ---- общие цели ----
        val centroid = ctx.ourCentroid
        val ourHalfCombat = armedEnemies.filter { DistanceMap.inOurHalf(it.x, it.y) }
        val ourHalfSoft = enemyCreeps.filter { c -> combatEnemies.none { it.id == c.id } && DistanceMap.inOurHalf(c.x, c.y) }
        fun arrivalOf(c: Creep) = arrivalById[c.id] ?: Int.MAX_VALUE / 2
        val threat = ourHalfCombat.filter { catchable(it, chasers) }.minWithOrNull(compareBy<Creep>({ arrivalOf(it) }, { getRange(it, centroid) }))
        // рейдер: чужой безоружный на нашей половине — тот, что ближе к нашему флагу (захватчик идёт к нему); гонимся,
        // только если стрелки бьют стаю вокруг него: без этой проверки армия гналась за безоружным остовом к
        // стоявшей за ним армии врага и вошла в бой при 0.77 (матч 3, t=100)
        val raider = ourHalfSoft.minByOrNull { r -> minOf(getRange(r, centroid), ctx.flags.filter { !it.theirs }.minOfOrNull { getRange(r, it.pos) } ?: 99) }
            ?.takeIf { r ->
                // стая рейдера — и те, кто дойдёт до него не позже нас: скаут в 12 клетках впереди своей армии был
                // «без охраны», и армия вышла из дома ему навстречу — прямо под удар всей армии врага (матч 6, t=50)
                val field = flowTo(ctx, r)
                val ourTravel = chasers.map { pathTicks(it, field, it.x * 100 + it.y) }.filter { it < Int.MAX_VALUE / 4 }.maxOrNull() ?: Int.MAX_VALUE / 4
                val pack = packAt(ctx, r, field, ourTravel)
                catchable(r, chasers) && (pack.isEmpty() || (strikers.isNotEmpty() && ourPowerOf(strikers, pack) >= enemyPowerOf(pack, strikers) * PUSH_RATIO))
            }
        // охота на угрозу на нашей половине — решение группы с гистерезисом: стрелки против всей стаи у угрозы
        huntingThreat = posture != Posture.RETREAT && posture != Posture.EVADE && threat != null && strikers.isNotEmpty() && run {
            val field = flowTo(ctx, threat)
            val ourTravel = strikers.map { pathTicks(it, field, it.x * 100 + it.y) }.filter { it < Int.MAX_VALUE / 4 }.maxOrNull() ?: Int.MAX_VALUE / 4
            val pack = combatEnemies.filter { getRange(it, threat) <= ENGAGE_RANGE + RANGED_RANGE || (!stationary(it) && pathTicks(it, field, it.x * 100 + it.y) <= ourTravel) }
            val o = ourPowerOf(strikers, pack)
            val t = enemyPowerOf(pack, strikers)
            o >= t * (if (huntingThreat) PUSH_RELEASE_RATIO else PUSH_RATIO) &&
                (fightCost(pack, strikers) <= (strikers.maxOfOrNull { speedSlack(it) } ?: 0) || inContact(pack, strikers))
        }
        Memory.aggressiveIds.retainAll { id -> army.any { it.id == id } }
        Memory.rallyingIds.retainAll { id -> army.any { it.id == id } }
        Memory.engagingIds.retainAll { id -> army.any { it.id == id } }
        Memory.holdSince.keys.retainAll { id -> army.any { it.id == id } }
        Memory.impatientIds.retainAll { id -> army.any { it.id == id } }
        Memory.lastHits.keys.retainAll { id -> army.any { it.id == id } }
        Memory.lastCell.keys.retainAll { id -> army.any { it.id == id } }

        val enemyPositions = enemyCreeps.mapTo(HashSet()) { it.x * 100 + it.y }
        val blockedSet: Set<Int> = ctx.blocked.mapTo(HashSet()) { it.x * 100 + it.y } + ctx.flagCells
        val meleeEnemies = enemyCreeps.filter { InfluenceMap.profileOf(it).melee > 0.0 }

        // фокус-файр: добиваемые за тик -> наибольшая угроза на хит (урон, который враг СЕЙЧАС наносит нам, плюс
        // его лечение, делённые на его хиты: мили вплотную за 1000 хитов снимает 90, стрелок за 800 — 40, лекарь
        // за 600 — 36; «лекари первыми» без учёта хитов вело огонь мимо мили, который резал наш строй)
        val inFireRange = enemyCreeps.filter { e -> combatArmy.any { it.getRangeTo(e) <= RANGED_RANGE } }
        // остовы (без оружия и лечения) — вне пула, пока есть боевые. Матч 22: разоружённый M6 с 542 хитами простоял
        // 25 тиков в 2–4 клетках от наших стрелков необстрелянным и был вылечен обратно в M8A8, пока пять его стрелков
        // добивали наших. ДВА способа перенести на него огонь ОТВЕРГНУТЫ стендом: «отрастающая угроза» (мёртвые части
        // оружия × 0.5 в угрозе любой цели) проиграла m9 hunter, m3 army и все рубки sleeper; «остов, добиваемый за
        // два залпа, — сразу после добиваемых за тик» проиграла m3 army, рубки sleeper и m18 spread. Огонь по живой
        // угрозе, а не по раненым, — то, на чём стенд стоит; остов на лечении врага — открытая находка
        fun fireAvailable(e: Creep) = army.filter { it.getRangeTo(e) <= RANGED_RANGE }.sumOf { InfluenceMap.profileOf(it).ranged } +
            army.filter { it.getRangeTo(e) <= 1 }.sumOf { InfluenceMap.profileOf(it).melee }
        // ОСТОВ, КОТОРЫЙ УМИРАЕТ ОТ ОДНОГО ЗАЛПА, — НЕ РАЗМЕН, А БЕСПЛАТНОЕ УБИЙСТВО (v210, оператор по записи:
        // «выбили все боевые части и перестали их добивать, за счёт чего они прошли мимо нас к своей второй половине,
        // где был лекарь, и вылечились до полного здоровья»). Пока у врага жив лекарь, выбитая часть не убрана, а
        // выключена: единственный способ убрать её насовсем — убить крипа. Замер по пяти матчам v208: 13
        // восстановлений; r6m6 простоял разоружённым 42 тика, из них 29 в НАШЕЙ ДАЛЬНОСТИ ВЫСТРЕЛА, с минимумом в
        // 16 хитов — залп по нему стоил одного тика огня и вернул бы шесть стрелковых частей навсегда.
        // ⚠️ Это НЕ третья попытка тех двух, что стенд уже отверг. «Отрастающая угроза» и «остов в два залпа сразу
        // после добиваемых за тик» ставили остов в очередь ПРОТИВ живой угрозы — здесь он входит в пул ТОЛЬКО когда
        // умирает от уже доступного залпа, то есть попадает ровно в верхний ярус `focusCmp` («добиваемые за тик»),
        // где живой угрозе он не мешает: та в этом ярусе стоит по своей же угрозе выше.
        // ⚠️ И это НЕ притяжение: правка v209 (цена цели по потенциалу тела) свой прибор не сдвинула ни на стенде
        // (137 -> 130 восстановлений на 135 сценариях), ни живьём (2,6 -> 3,0 на матч) и снята.
        // СКАУТ У ФЛАГА — ЦЕЛЬ ЦЕНОЙ ОДНОГО ЗАЛПА (v214). Форма взята у killableHulk и она уже проверена живьём:
        // срабатывала 739 раз в 102 логах из 135, то есть в очередь встаёт и стреляет. Остова она не спасала лишь
        // потому, что его лечили обратно, — у скаута этой причины нет, он умирает насовсем и перестаёт брать флаги.
        // Его угроза (threatOf) равна нулю, поэтому внутри верхнего яруса focusCmp он стоит ПОСЛЕДНИМ: любой живой
        // добиваемый враг выше. Условие «на флаге или в шаге от него» не даёт огню уходить в скаута, гуляющего мимо.
        val scoutTargets = inFireRange.filter { e ->
            scoutFoe(e) && ctx.flags.any { !it.ours && getRange(e, it.pos) <= 1 } &&
                e.hits <= fireAvailable(e) * InfluenceMap.takenOf(e)
        }
        scoutShots += scoutTargets.size
        val focusPool = (inFireRange.filter { e -> combatEnemies.any { it.id == e.id } } + scoutTargets)
            .ifEmpty { inFireRange }
        fun fireAvailableAt(e: Creep) = fireAvailable(e)
        // лечение, которое враг получит на этой цели: вплотную — полное, на дистанции — треть (rangedHeal 4 против 12)
        fun healOn(e: Creep) = enemyCreeps.filter { h -> h.id != e.id && getRange(h, e) <= HEAL_RANGE }.sumOf { h -> val q = InfluenceMap.profileOf(h); if (getRange(h, e) <= 1) q.heal else q.heal / 3.0 }
        // дистанция каждого врага до ближайшего нашего боеспособного сейчас и тик назад — «идёт ли» (см. threatOf)
        val prevArmedRange = HashMap(Memory.lastArmedRange)
        Memory.lastArmedRange.clear()
        for (e in enemyCreeps) Memory.lastArmedRange[e.id] = combatArmy.minOfOrNull { getRange(e, it) } ?: 99
        fun threatOf(e: Creep): Double {
            val p = InfluenceMap.profileOf(e)
            // мили — полная угроза ВПЛОТНУЮ к нашему или в двух, когда ИДЁТ на нас (v41: дистанция до наших боеспособных
            // меньше, чем тик назад). В двух он считался живым на все 240 (в четыре стрелка) всегда, и в
            // стоячей линии наш огонь шёл в него: по реплеям трёх проигрышей при его вооружённом стрелке в трёх наши выстрелы
            // уходили в стрелка на 39 / 36 / 46 % (матчи 67, 53, 43), остальное в мили и лекарей; его — в наших стрелков на
            // 65 / 70 / 62 %. Его мили в 2–3 от наших за бой махнули 56 раз на четверых (0,06 в тик — 13 урона), его стрелки
            // дали 480 выстрелов (34 в тик на каждого); мили лечился и вставал обратно в строй, а стрелки жили вооружёнными
            // 875 крип-тиков против наших 413 — и выстрелов 535 против 258 при равной дисциплине (цель в трёх 67 % против
            // 55 %, фокус 0,73 против 0,72). Вошедший вплотную мили — 240 в тот же тик (фокус считается каждый тик), а в
            // двух он — скидка кайта, как и в трёх. Чистая скидка в двух (без «идёт») на гейте: линии (wing) лучше на
            // 1,4–9,9 тыс. очков, но против атакующих пять уничтожений стали лидерством (rush/nine/fourteen/block, m5 army):
            // идущий мили в двух вплотную уже в следующий тик, и тик его огня без фокуса — цена, которую стенд заметил
            val r = Memory.lastArmedRange[e.id] ?: 99
            val meleeLive = p.melee > 0.0 && (r <= 1 || (r <= MELEE_KEEP_RANGE && (prevArmedRange[e.id] ?: 99) > r))
            val rangedLive = p.ranged > 0.0 && combatArmy.any { getRange(e, it) <= RANGED_RANGE }
            // лекарь в угрозе — треть лечения ВСЕГДА (24 против 60 у стрелка): «живой» лекарь при раненом соседе весил 72 и
            // собирал четверть-треть нашего огня (матч 44: 66 из 192, матч 45: 46 из 175, при HEALER_VALUE 1.0), пока けろびー
            // тратил на лекарей 6–15 % и снимал наших стрелков (96 выстрелов по ним против наших 24 по его). Лекаря бьют,
            // когда его добить за тик (первый ярус фокуса) или когда в дальности нет вооружённых (focusOrder)
            return (if (meleeLive) p.melee else p.melee * MELEE_KITE_DISCOUNT) + (if (rangedLive) p.ranged else p.ranged * 0.5) +
                p.heal / 3.0 * HEALER_VALUE
        }
        // тики до убийства нашим огнём в дальности за вычетом их лечения на цели; бесконечность — цель не убиваема
        fun killTicks(e: Creep): Double {
            val net = fireAvailableAt(e) * InfluenceMap.takenOf(e) - healOn(e)
            return if (net <= 0.0) Double.POSITIVE_INFINITY else e.hits / net
        }
        // фокус: добиваемые за тик, затем наибольшая угроза, снимаемая за тик боя (угроза / тики до убийства), и лишь
        // потом угроза на хит — «угроза на хит» слала огонь в лекарей врага за строем, которых лечили друг друга
        // быстрее, чем мы били (стенд m2 rush: выигранный без потерь рывок стал разгромом)
        fun armedRanged(e: Creep?) = e != null && InfluenceMap.profileOf(e).ranged > 0.0
        // его мили, стоящий вплотную к кому-то из наших: он бьёт ПРЯМО СЕЙЧАС на 240 в тик (v135)
        fun meleeHitting(e: Creep?) = e != null && InfluenceMap.profileOf(e).melee > 0.0 &&
            combatArmy.any { getRange(e, it) <= 1 }
        // его лекарь: живое лечение и никакого живого оружия (v134, см. USE_FOCUS_HEALER_FIRST)
        fun armedHealer(e: Creep?) = e != null && InfluenceMap.profileOf(e).heal > 0.0 &&
            InfluenceMap.profileOf(e).ranged == 0.0 && InfluenceMap.profileOf(e).melee == 0.0
        // лекарь, из-за которого цель не умирает: в HEAL_RANGE от вооружённого врага, которого нам не убить
        fun savesSomeone(h: Creep) = focusPool.any { c -> c.id != h.id && InfluenceMap.profileOf(c).let { it.melee + it.ranged > 0.0 } &&
            getRange(h, c) <= HEAL_RANGE && killTicks(c).isInfinite() }
        // стволов, достающих цель (v70, см. USE_FOCUS_GUNS)
        fun gunsAt(e: Creep?) = if (e == null) 0 else combatArmy.count { hasRanged(it) && it.getRangeTo(e) <= RANGED_RANGE }
        val focusCmp = compareBy<Creep> { if (it.hits <= fireAvailableAt(it) * InfluenceMap.takenOf(it)) 1 else 0 }
            // ЛЕКАРЬ В ДОСЯГАЕМОСТИ — ЦЕЛЬ ПЕРВЫМ (v224, см. USE_FOCUS_ANY_HEALER): правило соперника, снятое с реплеев
            // обеих сторон, — его ствол при нашем лекаре в досягаемости бьёт лекаря в 82–97 % выстрелов
            // ...И ТОЛЬКО ТОТ ЛЕКАРЬ, КОТОРОГО ДОТЯГИВАЮЩИЙСЯ ОГОНЬ ПРОБИВАЕТ (v224, серия): без этого условия ярус
            // ставил выше стрелка с пятью стволами лекаря в глубине его строя с одним стволом — рейтинговое поражение от
            // けろびー#1 (v223 — победа 21 242 : 1 455): 167 тиков фокуса на лекаре, его лечащих частей 18/18 весь бой,
            // убийств 0, армия в ноль на 360-м. Условие — то же `killTicks`, что у яруса v134: огонь в дальности
            // за вычетом лечения на цели больше нуля
            .thenBy { if (armedHealer(it) && gunsAt(it) > 0 && (!killTicks(it).isInfinite())) 1 else 0 }
            // ДОТЯГИВАЮЩИЕСЯ СТВОЛЫ НЕ РАСХОДЯТСЯ ПО ТРЁМ ЦЕЛЯМ (v218, см. USE_FOCUS_BREAKABLE_FIRST). Порог
            // записан в файле пятикратно — «при 216 лечения в тик цель пробивают четыре-пять стволов», — но
            // числом его писать не нужно: «стволов хватает» тождественно «сумма того, что уже дотягивается,
            // превышает лечение цели», а это у бота посчитано ровно один раз — конечным `killTicks` (см. там же:
            // net <= 0 даёт бесконечность). Поэтому ярус читает готовую величину и НЕ вводит ни одной константы.
            // Почему ярус нужен ЗДЕСЬ, а не ниже: `killTicks` уже участвует в сравнении, но на пятом ярусе, под
            // «стрелки первыми» (v60) и под `gunsAt` (v70), — и неубиваемый стрелок обгонял цель, которую мы
            // реально пробиваем. Живой замер v217: `conc` 1,67–1,94 ствола на цель при нужных четырёх-пяти
            // ...первый срез «всякий снимаемый лекарь выше стрелков» ОТВЕРГНУТ стендом: гейт 131, но входы +20 хуже 11 / лучше 9,
            // +50 хуже 15 / лучше 7, m34 split 21 210:24 100 → 15 365:24 095. Второй срез: не «лекарь вообще», а ТОТ, ИЗ-ЗА КОГО
            // цель не умирает — лекарь в HEAL_RANGE от неубиваемого кандидата (живьём его лекарь у нашей цели 62–83 % тиков)
            .thenBy { if (armedHealer(it) && !killTicks(it).isInfinite() && savesSomeone(it)) 1 else 0 }
            // стрелки первыми (v60, см. USE_FOCUS_RANGED_FIRST), и вместе с ними — его мили, КОТОРЫЙ УЖЕ БЬЁТ (v135,
            // см. USE_FOCUS_MELEE_IN_CONTACT): внутри яруса порядок решает угроза за тик, а там мили вплотную (240) выше
            // стрелка (60) сам собой
            .thenBy { if ((armedRanged(it))) 1 else 0 }
            // больше стволов (v70)
            .thenBy { gunsAt(it) }
            .thenBy { val t = killTicks(it); if (t.isInfinite()) 0.0 else threatOf(it) / t }
            // чистый урон по цели: наш огонь в дальности минус её лечение (вплотную — полное, на дистанции — треть). Когда
            // никого не убить (лечение везде не меньше огня), «угроза на хит» слала огонь в того, кого лечат три лекаря
            // вплотную; выше — цель, к которой лекари ДАЛЕКО (оператор, 05.09.2026: «лекари к ней далеки — не вылечат
            // близким хилом и потеряют ход») и которую достают больше наших стволов
            .thenBy { threatOf(it) / it.hits.coerceAtLeast(1) }
            .thenByDescending { it.hits }
            .thenByDescending { getRange(it, centroid) }
        val focusBest = focusPool.maxWithOrNull(focusCmp)
        // прибор яруса «лекарь первым» (v224): его лекарь в досягаемости наших стволов был / фокус лёг на лекаря
        if (focusPool.any { armedHealer(it) && gunsAt(it) > 0 }) { fhlAvail++; if (focusBest != null && armedHealer(focusBest)) fhlChosen++ }
        // ЛИПКИЙ фокус (v45): цель держится, пока жива с оружием или лечением и в шаге от досягаемости хоть одного нашего стрелка;
        // сменяется на ту, что добивается за тик. Замер по реплеям (матчи 78, 73, 67): наибольшее число наших выстрелов в ОДНУ
        // цель за тик — 1 в 57 тиках из 111, 2 в 42, 3 в 10, четыре и больше в 2 (1 %); у Coldkimchi 4+ в 11 % тиков, у けろびー
        // в 14 %. При 216 лечения в тик пробивают только четыре-пять стволов в одну цель — мы этого не делали почти никогда:
        // цель фокуса менялась, ряд стоял поперёк оси, каждый стрелок доставал своего (оператор: «нет фокус-файра — каждый
        // рэндж стреляет в своего соперника»)
        val focusPrev = focusId?.let { id -> focusPool.firstOrNull { it.id == id } }
        val killableNow = focusBest != null && focusBest.hits <= fireAvailableAt(focusBest) * InfluenceMap.takenOf(focusBest)
        // …и не к мили, чья угроза схлопнулась (v49): матч 91 (Coldkimchi, 430 тиков боя) — его мили тычет вплотную (угроза 240,
        // фокус на нём), отходит к лекарям, и фокус на нём держится: 395 выстрелов в мили под 727 его лечений вплотную, 101 в
        // стрелков (35 % при стрелке в трёх, у него 71 %). Мили держится, пока вплотную или идёт (см. threatOf); «отпускать
        // всякую неубиваемую цель, пока есть убиваемая» ОТВЕРГНУТО стендом — фокус перескакивал при каждом шаге его лекаря
        // (125/125, но 19 хуже / 12 лучше: screen+flagless m32 −16145, block+flagless m32 −7640, camp m34 −9294, кайтеры медленнее ×7)
        // липкость уступает стрелку (v60): прежняя цель не стрелок, а лучшая — вооружённый стрелок
        val rangedNow =  armedRanged(focusBest) && !armedRanged(focusPrev)
        // липкость уступает цели, которую достают на FOCUS_GUNS_SWITCH стволов больше (v70)
        val moreGuns =  focusBest != null && focusPrev != null && gunsAt(focusBest) >= gunsAt(focusPrev) + FOCUS_GUNS_SWITCH
        val focusTarget = if (focusPrev != null && !killableNow && !rangedNow && !moreGuns && InfluenceMap.profileOf(focusPrev).let { it.melee + it.ranged + it.heal > 0.0 } &&
            combatArmy.any { hasRanged(it) && getRange(it, focusPrev) <= RANGED_RANGE + 1 }) focusPrev else focusBest
        focusId = focusTarget?.id
        val packMelee = combatArmy.filter { isMelee(it) && !hasRanged(it) && hasMelee(it) }
        if (packMelee.isNotEmpty() && combatEnemies.isNotEmpty()) packTicks++
        // ВЕЕР НЕ РАСФОКУСИРУЕТ СОШЕДШИЕСЯ СТВОЛЫ (v218, см. USE_FAN_KEEPS_FOCUS). Признак снимается ЗДЕСЬ,
        // потому что `killTicks` живёт только в этой области видимости, а нужен он в `shoot` — на 1500 строк ниже
        focusBreakableNow = focusTarget != null && !killTicks(focusTarget).isInfinite()
        // ранжир для бойца, у которого цель фокуса вне дальности: ПЕРВАЯ по ранжиру цель в его дальности, а не «самый раненый в
        // дальности» — тот размазывал огонь: 1.91 цели в тик, 66 из 192 выстрелов в лекарей при HEALER_VALUE 1.0 (матч 44)
        val focusOrder = focusPool.sortedWith(focusCmp.reversed())
        val occupantAt = HashMap<Int, Creep>()
        for (c in ctx.active) occupantAt[c.x * 100 + c.y] = c
        // добить: цель армии — ближайший к центру армии боевой враг (по пути); в бою ПО КОНТАКТУ (без перевеса) —
        // только враг, который УЖЕ у нас в руках (в RANGED_RANGE + 2 от своих): стая «в 11 клетках» включала основную
        // массу врага, и контакт с одним забредшим мили увёл армию с дома на неё — бой при 0.97 проигран 12:1 (матч 13)
        val contactPack = combatEnemies.filter { e -> combatArmy.any { getRange(e, it) <= RANGED_RANGE + 2 } }
        // расстояние до КАЖДОГО кандидата в добычу мерилось своим полем BFS, а поля считаются под бюджетом
        // (см. BFS_BUDGET): сверх него кандидат получает ограниченное (NEAR_FLOW) или устаревшее поле, и «до него
        // неизвестно» читается как «бесконечно далеко». Сравнения кандидатов при этом нет вовсе — есть сравнение
        // качества полей. Стенд m18 roost: два скаута по разным углам карты, цель армии мигала (13,49)/(90,8) КАЖДЫЙ
        // ТИК, армия шагала туда-сюда и простояла так до конца матча — армия врага перебита к 203-му, а матч проигран
        // по очкам 17683:24331; в живом матче 25 армия ровно так же простояла 990 тиков при добыче в 11 клетках.
        // ОДНО поле от центра армии меряет всех кандидатов в одних единицах и в один тик — и стоит дешевле, чем поле
        // на каждого кандидата
        val preyField by lazy { flowTo(ctx, centroid) }
        // враг НА клетке вражеского флага недостижим по полю (такая клетка в нём стена) — читаем по соседней: нам
        // нужно дойти ДО него, а не встать на него
        fun travelTo(e: Creep): Int {
            var best = -1
            for (dx in -1..1) for (dy in -1..1) {
                val x = e.x + dx; val y = e.y + dy
                if (x !in 0..99 || y !in 0..99) continue
                val d = preyField[x * 100 + y]
                if (d >= 0 && (best < 0 || d < best)) best = d
            }
            return if (best < 0) Int.MAX_VALUE / 2 else best
        }
        // за недостижимым не гонимся: прежде «недостижим» и «очень далеко» были одним числом, и армия шла на цель,
        // до которой нет пути
        fun nearestPrey(list: List<Creep>): Creep? =
            list.filter { travelTo(it) < Int.MAX_VALUE / 4 }.minByOrNull { travelTo(it) }
        val prey = when {
            posture != Posture.ANNIHILATE -> null
            sweep -> nearestPrey(enemyCreeps)
            pushing -> nearestPrey(huntable)
            else -> nearestPrey(contactPack.filter { catchable(it, chasers) })
        }
        val armedCentroid = clusterCentroid(mobileArmy.filter { hasWeapon(it) }.ifEmpty { army }) ?: centroid
        // захватчик флага-цели — ближайший к флагу ВООРУЖЁННЫЙ член группы (одной клетки на всех не хватит; лекарь
        // ходит за подопечным, и назначенный захватчиком лекарь тысячу тиков стоял рядом с флагом — стенд greedy)
        val objectiveCapturer = objective?.let { o -> mobileArmy.filter { hasWeapon(it) }.ifEmpty { mobileArmy }.minByOrNull { getRange(it, o.flag.pos) }?.id }
        // флаг рядом (не наш, свободный, без врага в дальности, разрешён) — на него шагает ближайший из наших
        val grabberOf = HashMap<String, String>()
        for (f in ctx.flags) {
            if (f.ours || f.occupant != null || f.id == objectiveFlagId) continue
            if (combatEnemies.any { getRange(it, f.pos) <= RANGED_RANGE + 1 }) continue
            if (!captureAllowed(ctx, f)) continue
            // ...и НЕ ЛЕКАРЬ (v215, см. USE_HEALER_NEVER_PINNED): тот же отбор, что строкой выше у захватчика цели
            val near = mobileArmy.filter { getRange(it, f.pos) <= 3 && (hasWeapon(it)) }
                .minByOrNull { getRange(it, f.pos) } ?: continue
            grabberOf[near.id] = f.id
        }

        // построение перед контактом (см. FORM_RANGE): авангард — ближайший к врагу ходячий вооружённый; готовность —
        // доля вооружённых в RALLY_RANGE от него, собравшихся в FORM_RANGE; клетки под огнём — в дальности стрелка
        // враг здесь — С БОЕМ (см. threatening): построение собирается перед огнём, а у одинокого лекаря огня нет. Уцелевший
        // лекарь врага шёл за армией в семи клетках, «авангардом» становился ЗАДНИЙ боец, и построение тянуло армию назад,
        // а цель — вперёд: шаг туда, шаг обратно 140 тиков у (20,21) при флаге-цели в 30 (стенд m13 rush, v30)
        val formers = mobileArmy.filter { hasWeapon(it) }
        // авангард — только из массы (см. MASS_RANGE): оторвавшийся крип не точка сбора
        val formMass = formers.filter { getRange(it, armedCentroid) <= MASS_RANGE }.ifEmpty { formers }
        // авангард есть, только пока враг с боем в досягаемости броска от кого-то из строя: авангард «против врага где-то на
        // карте» при одиноком лекаре врага в одиннадцати клетках давал построение, которому не собраться (штраф за соседей
        // отталкивал мили от авангарда в блобе) и не дождаться терпения (оно считается по врагу с боем) — армия простояла
        // тысячу тиков в 25 клетках от флага-цели (стенд m30 block, v30)
        val formVan = if (armedEnemies.none { e -> formers.any { getRange(e, it) <= ENGAGE_RANGE + RANGED_RANGE } }) null
            else formMass.minWithOrNull(compareBy<Creep>({ f -> armedEnemies.minOf { getRange(f, it) } }, { it.id }))
        val formationGathered = formVan == null || run {
            val near = formers.filter { getRange(it, formVan) <= RALLY_RANGE }
            val needed = maxOf(2, ceil(FORM_SHARE * near.size).toInt())
            // ком — только у неподвижной цели (см. USE_FORM_CLUMP_STILL_ONLY): его вооружённые в досягаемости авангарда стоят CHASE_WINDOW
            val vanFoes = armedEnemies.filter { getRange(it, formVan) <= ENGAGE_RANGE + RANGED_RANGE }
            // ...и это БЛОК, а не одиночка фермера на флаге (v133d): не меньше SPLIT_MIN неподвижных в ENGAGE_RANGE друг от друга
            val foesStill = vanFoes.size >= (SPLIT_MIN) && vanFoes.all { e ->
                val h = Memory.enemyCellHist[e.id]
                h != null && h.size >= CHASE_WINDOW && maxOf(abs(h.first() / 100 - h.last() / 100), abs(h.first() % 100 - h.last() % 100)) <= 1
            } && (vanFoes.any { e -> vanFoes.count { getRange(e, it) <= ENGAGE_RANGE } >= SPLIT_MIN })
            if ((!foesStill)) near.count { getRange(it, formVan) <= FORM_RANGE } >= needed
            else {
                // ком (см. USE_FORM_CLUMP): в FORM_RANGE от авангарда, или вплотную к собранному и не дальше FORM_RANGE + 1
                val gathered = near.filter { getRange(it, formVan) <= FORM_RANGE }.toMutableList()
                var grew = true
                while (grew) {
                    grew = false
                    for (f in near) if (gathered.none { it.id == f.id } && getRange(f, formVan) <= FORM_RANGE + 1 && gathered.any { getRange(f, it) <= 1 }) { gathered.add(f); grew = true }
                }
                gathered.size >= needed
            }
        }
        val formWaiting = formVan != null && !formationGathered && armedEnemies.any { e -> formers.any { getRange(e, it) <= ENGAGE_RANGE + RANGED_RANGE } }
        // терпение — с появления авангарда, а не с последнего несобранного тика (v120, USE_FORM_PATIENCE_FROM_VAN): авангард,
        // шагнувший к цели, сам ломал построение (нужны 5 из 6 в двух клетках от него, оставалось 4), по formGo шагал назад,
        // построение собиралось, он шагал снова — цикл в два тика 1300 тиков на spread m31 (20579:24316) при таймере
        // терпения, сбрасываемом каждым собранным тиком
        if (!formWaiting) formWaitSince = -1 else if (formWaitSince < 0) formWaitSince = getTicks()
        val formationReady = formationGathered || (formWaitSince >= 0 && getTicks() - formWaitSince >= FORM_PATIENCE)
        // досягаемость врага для лекаря и раненого (см. reachCells): стрелок бьёт на 3, мили шагнёт и ударит на 2. Тело
        // лекаря HHHHHHMMMMMM — лечение впереди, и первое же попадание снимает 12 лечения в тик навсегда; наши лекари
        // входили в зону огня к подопечному и к 130-му были M6H4/M6H2, лекари врага за строем не получили ни царапины
        // и отрастили ему армию (матчи 14–15). Лекарь в зону не входит, изнутри уходит; раненые приходят к нему сами.
        val reachCells = HashSet<Int>()
        for (e in combatEnemies) {
            val q = InfluenceMap.profileOf(e)
            val r = if (q.ranged > 0.0) RANGED_RANGE else if (q.melee > 0.0) 2 else 0
            if (r == 0) continue
            for (dx in -r..r) for (dy in -r..r) {
                val x = e.x + dx; val y = e.y + dy
                if (x in 0..99 && y in 0..99) reachCells.add(x * 100 + y)
            }
        }
        // в контактном бою лекарь избегает только мили (2 клетки): «вне досягаемости стрелков» выкидывало слот тыла из
        // ряда back+1, лекари стояли в 4–6 клетках за фронтом, и мили гибли без лечения, пока лекари врага стояли у своей
        // линии под нашим огнём (матч 21, t=68–84: четыре мили за шестнадцать тиков, ни одного лечения)
        // только вплотную к мили (клетка в 2 — это ряд сразу за нашим фронтом, свой мили между ними)
        val meleeReachCells = HashSet<Int>()
        for (e in combatEnemies) {
            if (InfluenceMap.profileOf(e).melee <= 0.0) continue
            for (dx in -1..1) for (dy in -1..1) {
                val x = e.x + dx; val y = e.y + dy
                if (x in 0..99 && y in 0..99) meleeReachCells.add(x * 100 + y)
            }
        }
        val reachNow = if (contact) meleeReachCells else reachCells
        val fireCells = HashSet<Int>()
        for (e in combatEnemies) for (dx in -RANGED_RANGE..RANGED_RANGE) for (dy in -RANGED_RANGE..RANGED_RANGE) {
            val x = e.x + dx; val y = e.y + dy
            if (x in 0..99 && y in 0..99) fireCells.add(x * 100 + y)
        }

        val healersAlive = army.any { !hasWeapon(it) && hasHeal(it) && canMove(it) }
        // строй рядами в бою по контакту (см. USE_BLOCK); при перевесе (добивание) — прежняя охота
        val slotOf = HashMap<String, Position>()
        cpuMark("posture")
        val blockOn =  posture == Posture.ANNIHILATE && !pushing && combatEnemies.isNotEmpty() && strikers.isNotEmpty()
        // прижим (см. USE_PRESS, PRESS_PATIENCE): линия врага стоит — контакт, его огонь достаёт наших, и ни один его мили не
        // в MELEE_HOLD_RANGE + 1 от наших вооружённых; включившись, держится, пока есть контакт и строй
        // ЕСТЬ ЛИ ЛЕКАРЬ У ТОГО, КТО ДЕРЁТСЯ (v215, оператор: «без хиллеров ни один бой выиграть невозможно»).
        // Прежний `hfar` мерил другое — расстояние лекаря до центроида ВООРУЖЁННЫХ; у армии, растянутой на
        // тридцать клеток, этот центроид стоит посреди пустоты, и «лекарь при армии» там ничего не значит.
        // Здесь вопрос задан по КАЖДОМУ дерущемуся: есть ли свой лекарь в дальности лечения
        val medsNow = army.filter { !hasWeapon(it) && hasHeal(it) }
        for (c in combatArmy) {
            if (!hasWeapon(c) || armedEnemies.none { getRange(c, it) <= RANGED_RANGE + 1 }) continue
            healGapN++
            if (medsNow.none { getRange(c, it) <= HEAL_RANGE }) healGap++
            // ...и ОТДЕЛЬНО — жалоба оператора дословно: «в бою не оказывается НИ ОДНОГО хиллера». Это не «лекарь в
            // четырёх клетках вместо трёх», это «лекаря рядом нет вовсе»: боец дерётся там, куда лекарь не придёт
            if (medsNow.none { getRange(c, it) <= MASS_RANGE }) noMedic++
        }
        // СМЕНА НАПРАВЛЕНИЯ АРМИИ (v215, оператор: «пару тиков погоня, потом разворот, и так много раз»).
        // Направление — это то, КУДА армия идёт: флаг-цель, добыча или пост. Одна смена за матч — это план,
        // сто — это дрожь, и пара «смен/тиков» отличает одно от другого
        val aimNow = objective?.flag?.id?.let { "F$it" } ?: prey?.id?.let { "E$it" } ?: "P"
        aimTicks++
        if (lastAim.isNotEmpty() && aimNow != lastAim) aimFlips++
        lastAim = aimNow
        // «их мили идут» (см. PRESS_CLOSING): дистанция их мили до наших вооружённых за окно терпения
        val theirMeleeDist = combatEnemies.filter { InfluenceMap.profileOf(it).melee > 0.0 }
            .minOfOrNull { e -> combatArmy.filter { hasWeapon(it) }.minOfOrNull { getRange(e, it) } ?: 99 } ?: 99
        if (contact) Memory.meleeDistHist.addLast(theirMeleeDist) else Memory.meleeDistHist.clear()
        while (Memory.meleeDistHist.size > PRESS_PATIENCE + 1) Memory.meleeDistHist.removeFirst()
        val theirMeleeClosing = Memory.meleeDistHist.size > PRESS_PATIENCE && Memory.meleeDistHist.first() - Memory.meleeDistHist.last() >= PRESS_CLOSING
        // «армии сближаются» (v47, оператор: «признак по сближению центров армий»): дистанция между центрами ВООРУЖЁННЫХ
        // армий за окно терпения сократилась не меньше PRESS_CLOSING — атака; стоит — стоячий бой (см. standingNow). Признак
        // «его мили не вплотную» выключал расстановку ровно в боях с Coldkimchi (его мили лезут вплотную к стрелкам), а
        // «его мили не идут» (v43f) брал и остановившуюся атаку — центры армий отличают одно от другого
        val ourArmedC = centroidOf(combatArmy.filter { hasWeapon(it) }.map { InfluenceMap.cell(it.x, it.y) })
        val theirArmedC = centroidOf(armedEnemies.map { InfluenceMap.cell(it.x, it.y) })
        if (contact && ourArmedC != null && theirArmedC != null) Memory.centreDistHist.addLast(getRange(ourArmedC, theirArmedC)) else Memory.centreDistHist.clear()
        while (Memory.centreDistHist.size > PRESS_PATIENCE + 1) Memory.centreDistHist.removeFirst()
        val armiesClosing = Memory.centreDistHist.size > PRESS_PATIENCE && Memory.centreDistHist.first() - Memory.centreDistHist.last() >= PRESS_CLOSING
        // СБЛИЖЕНИЕ БЕЗ КОНТАКТА (v183, оператор: «делай строй до боя»). Изготовка требовала `!contact && armiesClosing`,
        // а armiesClosing набирается ТОЛЬКО в контакте: строкой выше история центров чистится, едва контакт пропал.
        // Условия взаимоисключающие — commandBrace не выполнялся НИ РАЗУ, и прибор это подтвердил на разгроме 3d9532:
        // за весь подход командир отдал ноль приказов (cmd=0/50 … cmd=0/90), к первому выстрелу армия стояла смазкой
        // 5,8×6,1 клетки против его кирпича 4,5×3,9. Здесь то же расстояние пишется ВСЕГДА, и «он идёт на нас»
        // становится измеримым до первого выстрела
        if (ourArmedC != null && theirArmedC != null) Memory.approachHist.addLast(getRange(ourArmedC, theirArmedC)) else Memory.approachHist.clear()
        while (Memory.approachHist.size > PRESS_PATIENCE + 1) Memory.approachHist.removeFirst()
        val enemyApproaching =  Memory.approachHist.size > PRESS_PATIENCE &&
            Memory.approachHist.first() - Memory.approachHist.last() >= PRESS_CLOSING
        // ПАТ: БОЙ, В КОТОРОМ НИКТО НИКОГО НЕ УБЬЁТ (v189, разбор Coldkimchi#2). Замер матча 3d97d8 за 1400 тиков:
        // наших выстрелов 2 639 против его 1 234, нашего урона 156 100 против его 78 310 — и при этом его лечение
        // 237 228, наше 158 400. Обе стороны перелечивают входящее, никто не гибнет, и матч решают ФЛАГИ: у него
        // четыре, у нас один, счёт 3 210:18 145. В таком бою дебафф флага БЕСПЛАТЕН: он режет урон и лечение, но
        // «убить нельзя» от этого не меняется, пока запас лечения велик, — и соперник этим пользуется, а мы нет,
        // потому что вето захвата считает нас слабее и запрещает всё. Пат меряется временем: за окно STALEMATE_WINDOW
        // ни одна сторона не потеряла больше STALEMATE_LOSS своих хитов. Именно временем, и в этом отличие от
        // отвергнутого USE_CAPTURE_WHEN_WHOLE (v187, 0:12): «армия цела» истинно и на входе в размен, до всякого пата,
        // поэтому та правка брала флаг ровно тогда, когда дебафф решал бой, — и армия гибла девять раз из двенадцати
        // ДОСТАЁТ ЛИ НАШ МИЛИ ВООБЩЕ (v192, см. USE_MELEE_OUT_OF_FIRE): доля мили, стоявших вплотную к врагу, за окно
        // контакта. Величина измеряется, а не назначается: против кайтера она падает до нуля сама, против того, кто
        // идёт в размен, держится высокой, и правило снимается без порога, подогнанного под сегодняшнего соперника
        if (contact) {
            val meleeN = combatArmy.count { isMelee(it) && !hasRanged(it) }
            val touched = combatArmy.count { isMelee(it) && !hasRanged(it) && combatEnemies.any { e -> getRange(it, e) <= 1 } }
            // ...и при НУЛЕ мили в ядре окно не трогается вовсе: иначе отряд, уведённый по этому же признаку, обнуляет
            // мили в строю, доля прыгает к единице, признак гаснет и отряд отзывается — качели через тик
            if (meleeN > 0) Memory.touchHist.addLast(100 * touched / meleeN)
            val hisMelee = combatEnemies.count { isMelee(it) && !hasRanged(it) }
            val hisTouched = combatEnemies.count { isMelee(it) && !hasRanged(it) && combatArmy.any { a -> getRange(it, a) <= 1 } }
            if (hisMelee > 0) Memory.hisTouchHist.addLast(100 * hisTouched / hisMelee)
        } else { Memory.touchHist.clear(); Memory.hisTouchHist.clear() }
        while (Memory.touchHist.size > TOUCH_WINDOW) Memory.touchHist.removeFirst()
        while (Memory.hisTouchHist.size > TOUCH_WINDOW) Memory.hisTouchHist.removeFirst()
        touchShare = if (Memory.touchHist.size >= TOUCH_WINDOW) Memory.touchHist.sum() / (100.0 * Memory.touchHist.size) else 1.0
        hisTouchShare = if (Memory.hisTouchHist.size >= TOUCH_WINDOW) Memory.hisTouchHist.sum() / (100.0 * Memory.hisTouchHist.size) else 1.0
        if (touchShare < touchMin) touchMin = touchShare
        val stalemateOurNow = combatArmy.sumOf { it.hits }
        val stalemateHisNow = combatEnemies.sumOf { it.hits }
        // ОКНО ПАТА ПЕРЕЖИВАЕТ МИГАНИЕ КОНТАКТА (v198). Окно очищалось на КАЖДОМ тике без контакта, а `contact` в
        // стоянке мигает — и в матче 3d9894, где 1700 тиков не погиб ни один крип ни у нас, ни у него, прибор дошёл
        // лишь до 48 из ста нужных (`pat=0/48`). Признак, который в чистейшем пату не может стать истинным, ничего не
        // измеряет: он и был причиной, по которой v189 не с чем было сравнивать. Разрыв короче STALEMATE_GAP окно
        // держит — сто тиков «ни одна сторона не потеряла и пяти процентов хитов» остаются теми же ста тиками
        if (contact) { Memory.stalemateOurHist.addLast(stalemateOurNow); Memory.stalemateHisHist.addLast(stalemateHisNow); stalemateGap = 0 }
        else {
            stalemateGap++
            if (stalemateGap > STALEMATE_GAP) { Memory.stalemateOurHist.clear(); Memory.stalemateHisHist.clear() }
        }
        while (Memory.stalemateOurHist.size > STALEMATE_WINDOW) Memory.stalemateOurHist.removeFirst()
        while (Memory.stalemateHisHist.size > STALEMATE_WINDOW) Memory.stalemateHisHist.removeFirst()
        // ПРИБОР, а не правило: счётчик пата считается всегда, независимо от того, кто им пользуется. Он был
        // загейчен на USE_CAPTURE_IN_STALEMATE, и когда тот выключили после отказа v189, счётчик замер на нуле —
        // вместе с ним умерло правило v190, которое на него опиралось: двенадцать игр измерили не его, а v186
        val stalemateNow = Memory.stalemateOurHist.size >= STALEMATE_WINDOW && run {
            val ourDrop = Memory.stalemateOurHist.first() - Memory.stalemateOurHist.last()
            val hisDrop = Memory.stalemateHisHist.first() - Memory.stalemateHisHist.last()
            ourDrop < Memory.stalemateOurHist.first() * STALEMATE_LOSS && hisDrop < Memory.stalemateHisHist.first() * STALEMATE_LOSS
        }
        stalemateTicks = if (stalemateNow) stalemateTicks + 1 else 0
        if (stalemateTicks > patMax) patMax = stalemateTicks
        // наша линия отступает (v96, USE_STANDING_LINE_HOLDS): центр наших вооружённых за окно терпения отдалился от его
        // НЫНЕШНЕГО центра на PRESS_CLOSING и больше — бой не стоячий, это отход под огнём, и расстановке в нём места нет
        if (contact && ourArmedC != null) Memory.ourCentreHist.addLast(ourArmedC.x * 100 + ourArmedC.y) else Memory.ourCentreHist.clear()
        while (Memory.ourCentreHist.size > PRESS_PATIENCE + 1) Memory.ourCentreHist.removeFirst()
        val ourYielding =  theirArmedC != null && Memory.ourCentreHist.size > PRESS_PATIENCE && run {
            val was = Memory.ourCentreHist.first(); val now0 = Memory.ourCentreHist.last()
            getRange(InfluenceMap.cell(now0 / 100, now0 % 100), theirArmedC) - getRange(InfluenceMap.cell(was / 100, was % 100), theirArmedC) >= PRESS_CLOSING
        }
        // их мили на подходе — в (MELEE_HOLD_RANGE + 2 .. ENGAGE_RANGE] от наших вооружённых — это не стоячая линия и не пустое
        // место: матч 56 (G1N6ERbreadMan) — прижим на 115-м при его мили в 4–7, через три тика они вошли в нашу пачку у своих же
        // стрелков (его 51 удар против наших 24, a→ranged 31), пять наших потеряны за двадцать тиков. Прижим — линии, чьи мили
        // либо у неё (Kero v2, Coldkimchi: в 2–3 и не бьют), либо далеко; подходящих строй ждёт — они входят в его фокус сами
        val theirMeleeMid = combatEnemies.any { e ->
            InfluenceMap.profileOf(e).melee > 0.0 &&
                (combatArmy.filter { hasWeapon(it) }.minOfOrNull { getRange(e, it) } ?: 99).let { it > MELEE_HOLD_RANGE + 2 && it <= ENGAGE_RANGE }
        }
        standoffTicks = if (contact && underTheirFire && !theirMeleeIn && !theirMeleeClosing && !theirMeleeMid) standoffTicks + 1 else 0
        pressing =  blockOn && contact && !leadHolds && (standoffTicks >= PRESS_PATIENCE || pressing)
        val pressOn = pressing
        // «цель уходит» (см. PRESS_GIVEUP): за два тика прижима дистанция от наших мили до неё не сократилась
        if (blockOn) {
            val ourMelee = combatArmy.filter { isMelee(it) && !hasRanged(it) && hasMelee(it) }
            for (e in combatEnemies) {
                val near = ourMelee.minByOrNull { getRange(e, it) } ?: continue
                val d = getRange(e, near)
                if (d > PRESS_RANGE + 1) { pressChase.remove(e.id); continue }
                val h = pressChase.getOrPut(e.id) { ArrayDeque() }
                h.addLast(ChaseSample(d, e.x * 100 + e.y, near.x * 100 + near.y))
                while (h.size > 3) h.removeFirst()
                // цель ушла (v96, USE_GIVEUP_HE_LEAVES): САМА отдалилась от места, где стоял наш ближайший мили в начале окна, —
                // а не «мы к ней не приблизились»: идущий за нашим отходом к тому месту приближается
                val first = h.first()
                val from = InfluenceMap.cell(first.meleeCell / 100, first.meleeCell % 100)
                val left =  getRange(e, from) > getRange(InfluenceMap.cell(first.eCell / 100, first.eCell % 100), from)
                if (h.size == 3 && d > (MELEE_HOLD_RANGE) && h.last().d >= first.d && left) {
                    pressGiveUp[e.id] = getTicks() + PRESS_GIVEUP
                    h.clear()
                    if (DEBUG_LOG) println("press t=${getTicks()}: ${e.id} keeps its distance — not pressed for $PRESS_GIVEUP ticks")
                }
            }
        } else pressChase.clear()
        pressGiveUp.entries.removeAll { it.value <= getTicks() }
        if (DEBUG_LOG && pressOn && standoffTicks == PRESS_PATIENCE) println("press t=${getTicks()}: the enemy line has stood at range for $PRESS_PATIENCE ticks under fire — the pack goes in")
        // стрелки впереди (см. USE_RANGED_FRONT) — только против линии, которая СТОИТ: признак прижима и дистанция до центра
        // врага за APPROACH_WINDOW не выросла. Уходящий (кайтер стенда, остаток) — прежний строй с мили впереди: стрелки во
        // главе погони не догоняют никого, а мили за их спиной и подавно (m11 kite: уничтожение на 395-м → лидерство, m28
        // farm+weak красный)
        // КОМАНДИР ВНЕ БЛОКА СТРОЯ (v160): весь его расчёт стоял внутри `if (blockOn)`, а blockOn требует постуры
        // ANNIHILATE, врагов в поле и отсутствия добивания — то есть командир молчал везде, кроме рубки, что бы ни
        // говорил его собственный режим: замер показал mode=FIGHT в 150 строках лога при cmdTicks=26. Теперь он
        // считается всегда и сам решает по режиму
        // РЕЖИМЫ КОМАНДИРА (v160, оператор: «командир должен оркестрировать всю игру»). Раздача клеток против его
        // строя — это ОДИН режим, и все формы, на которых расширение окна падало (camp, roost, scatter, kite),
        // просят другого: там враг строем не дерётся, а сидит на флагах, разбегается или держит дистанцию, и
        // выигрывает не кулак, а счёт. Поэтому командир сперва называет РЕЖИМ, а уже режим решает, что делать
        // ...и режим НАЗНАЧАЕТ постуру: командир решил драться — значит армия уничтожает, а не держит и не бежит
        // РАЗМЕН, КОТОРЫЙ УЖЕ ПРОИГРАН, НАДО ПРЕКРАЩАТЬ (v185, разбор серии). Прибор разделил двадцать матчей начисто:
        // в ВОСЬМИ поражениях армия стояла в бою при мощи ниже 60 % от его от 31 до 94 % боевых тиков (410 тиков из
        // 512), в ОДИННАДЦАТИ победах из двенадцати — НОЛЬ таких тиков (3 из 236 по всей пачке). Против Coldkimchi это
        // видно построчно: его мощь держится около 4 000 весь бой, наша падает до 1 500–2 000 при живых одиннадцати
        // крипах — он вылечивает своих обратно, мы нет, а армия продолжает стоять и таять. Доктрина паритета говорит
        // ровно это: не менять, когда мы слабее. Признак — ИЗМЕРЕННАЯ мощь обеих сторон, а не прогноз командира: тот
        // в минус не уходит никогда (см. USE_COMMAND_RETREAT), и потому основанием служить не может
        // ...И ПРИЗНАК СЧИТАЕТСЯ ПО ФАКТУ РАЗМЕНА (v216, см. USE_BREAK_OFF_BY_LEDGER). Обе величины считаются на
        // контактных тиках, чтобы прибор назвал числом, как часто они расходятся: старый признак стоил ровно
        // столько же — два вызова powerOf, — поэтому цена замера нулевая
        val outmatchedByPower =  contact && armedEnemies.isNotEmpty() && run {
            val oursNow = ourPowerOf(combatArmy, combatEnemies)
            val theirsNow = enemyPowerOf(combatEnemies, combatArmy)
            theirsNow > 0.0 && oursNow < theirsNow * BREAK_OFF_RATIO
        }
        // «мы теряем хиты, а он почти нет» — то же отношение BREAK_OFF_RATIO, только по фактическим потерям
        // ...и размен берётся НАКОПЛЕННЫЙ, а не за окно. Окно в STALL_TICKS тиков ловит местный размах и врёт в
        // другую сторону: на 200-м тике match35 за последние двадцать тиков мы потеряли 998 хитов против его 327 —
        // и признак объявил отход, — тогда как ЗА МАТЧ мы к этому моменту убили троих его крипов и не потеряли ни
        // одного (16 000/16 000 у нас против его 10 798/11 600). Строка перестала проходить гейт. Вопрос «стоит ли
        // прекращать размен» — про размен целиком, а не про последние двадцать тиков; окно осталось прибором
        val outmatchedByLedger =  contact && armedEnemies.isNotEmpty() &&
            ourDamageTaken > 0 && enemyDamageTaken < ourDamageTaken * BREAK_OFF_RATIO
        // ...а САМ признак посчитан выше (v217, см. outmatchedNow): здесь остаётся только прибор расхождения
        if (contact && armedEnemies.isNotEmpty()) {
            breakOffN++
            if (outmatchedByPower != outmatchedByLedger) breakOffSplit++
        }
        // признак для режима боя при наступлении (см. ниже): мы позади по размену хитов, то есть его лечение
        // перекрывает наш урон — ровно тот случай, ради которого концентрация и нужна
        val healingWins = enemyDamageTaken < ourDamageTaken
        cmdWhy[cmdWhyNow] = (cmdWhy[cmdWhyNow] ?: 0) + 1
        cmdWhyN++
        // ...и условие командира теперь ОДНО: он правит там, где сам назвал режим боя. Прежние пять множителей
        // (контакт, сомкнутость или шесть рядом, постура, огонь, отсутствие отхода и затора) целиком перешли в
        // выбор режима выше — это то же самое, сказанное один раз, и дальше режимы можно наполнять по одному
        // ...и ЗАПИСЬ ИДЁТ ЧЕРЕЗ ТЕ ЖЕ ЧАСЫ (v215). Здесь и ниже постура присваивалась в обход гистерезиса и БЕЗ
        // обновления `postureSince`: часы оставались от прошлой смены, срок POSTURE_HOLD оказывался уже вышедшим, и
        // на следующем же тике постуру можно было сменить обратно. То есть единственный гистерезис в файле ломался
        // именно там, где он нужнее всего — в бою. Замер по двадцати рейтинговым матчам: в худших матчах 352 смены
        // постуры за 1700 тиков, медиана удержания ОДИН тик, 71–81 % смен живут не дольше трёх тиков
        // ПАРА К КОМАНДИРУ (v221, см. warmNow): сколько тиков режима боя командир держит при тёплом контакте — на
        // этих тиках он вернёт ANNIHILATE сам, что бы ни решила постура
        if (cmdMode == CmdMode.FIGHT) { warmCmdAll++; if (warmNow) warmCmd++ }
        posture = decision.postureFinal
        postureSince = decision.postureSinceFinal
        // ...и выйти из режима боя МАЛО: постура остаётся ANNIHILATE сама по себе (она липкая и решает по своим
        // признакам), а именно она держит армию в размене. В разгромах серии режим прыгал FIGHT/RACE, а постура все
        // эти сотни тиков стояла ANNIHILATE при нашей мощи вдвое ниже. Отход объявляет командир — по измеренной мощи
        if (breakOffNow && DEBUG_LOG && getTicks() % LOG_EVERY == 0)
            println("cmd t=${getTicks()}: outmatched for $outmatchedTicks ticks — the advance stops, the line holds")
        // ПРИБОРЫ ОТХОДА (v217). Считаются ЗДЕСЬ, после того как постура окончательна: командир перезаписывает
        // её на 600 строк позже, чем она решается, и прибор, снятый раньше, рассказал бы про другую постуру
        if (outmatchedTicks >= BREAK_OFF_TICKS) {
            outmTicks++
            if (posture == Posture.RETREAT) outmRetreat++
        }
        // РАЗЛОЖЕНИЕ ПУСТОЙ БОЕВОЙ ПОСТУРЫ (v221, прибор). Живой A/B против MetalicaX#2: с USE_FIGHT_BY_LEDGER доля
        // тиков ANNIHILATE без размена НЕ упала (20 % против 16 % в контроле), хотя тёплый контакт в контакте упал с
        // 0,45 до 0,27. Значит, пустую постуру держит другой источник, и его надо назвать числом, а не гадать. Порядок
        // проверки — порядок власти над постурой: командир перезаписывает её последним
        if (posture == Posture.ANNIHILATE && !exchangeLive) {
            annEmptyAll++
            val src = when {
                cmdMode == CmdMode.FIGHT -> "cmd"
                pushing -> "push"
                holdingSpot -> "spot"
                meleeAdjacent -> "melee"
                cornered -> "corner"
                contact && hisStill -> "still"
                contact -> "warm"
                else -> "held"
            }
            annEmpty[src] = (annEmpty[src] ?: 0) + 1
        }
        // ПАРА К СБОРУ (v218, см. gatherSpread). Сбор (rallyTo) и сплочение (cohesionHold) намеренно молчат в
        // HOLD, и основание записано рядом с ними: «в HOLD цель — точка, к ней сходятся и так». Прибор проверяет
        // именно это основание — растянут ли строй стрелков в HOLD шире того порога, каким сбор и включается.
        // Мал числитель — основание верно, трогать сбор незачем
        if (posture == Posture.HOLD) {
            gatherHold++
            val shooters = combatArmy.filter { hasWeapon(it) && hasRanged(it) }
            if (shooters.size > 1 && shooters.maxOf { a -> shooters.maxOf { b -> getRange(a, b) } } > RALLY_RANGE) gatherSpread++
        }
        // ...И ТА ЖЕ ПАРА В ПОСТУРЕ БОЯ (v221, только прибор). Разбор v220, матч #11: ведём +1077, на 1400-м армия
        // растянута по флагам, его шестеро бьют ближайшую часть, и десять целых крипов ложатся за 80 тиков. Сбор
        // (rallyTo) в ANNIHILATE не работает по построению, а сплочение (cohesionHold) — ожидание, которое гасит
        // огонь по своим. Прибор отдельный, чтобы прежний `gather=` по HOLD остался сравним с логами v218–v220
        if (posture == Posture.ANNIHILATE) {
            gatherAnnAll++
            val sh = combatArmy.filter { hasWeapon(it) && hasRanged(it) }
            if (sh.size > 1 && sh.maxOf { a -> sh.maxOf { b -> getRange(a, b) } } > RALLY_RANGE) gatherAnn++
        }
        if (posture == Posture.RETREAT || posture == Posture.EVADE) {
            retrTicks++
            // ...и точка спрашивается ПО СВОЕЙ постуре: у отхода — `retreatTo`, у уклонения — `evadeTo`.
            // Смешивать их нельзя ровно потому, что дефект живёт в отходе: `evadeTo` почти всегда есть, и
            // общий счётчик показал бы 98 % там, где у отхода ноль
            if (if (posture == Posture.RETREAT) retreatTo != null else evadeTo != null) retrWithPoint++
            if (underTheirFire) retrUnderFire++
            for (c in combatArmy) {
                if (!hasWeapon(c)) continue
                standTicks++
                if (combatEnemies.any { getRange(c, it) <= (if (hasRanged(c)) RANGED_RANGE else 1) }) standFire++
            }
        }
        if (blockOn) {
            // расстановка (см. USE_PLAN) — только в СТОЯЧЕМ бою (признак прижима: линия стоит под огнём, его мили не идут);
            // против атаки и в погоне — ряды за передним мили: свободная расстановка рыхлее рядов, и с ней остаток
            // атакующего уходил, а кайтер добивался позже (гейт v43c: block/nine/rush «уничтожение → лидерство» ×10, кайтеры
            // медленнее ×7 при wing ×4, block+flagless ×2 и farm+weak m33 +7561 лучше)
            val standoffNow = pressOn && !enemyRetreating
            // ОТВЕРГНУТО: расстановка и в контакте, пока его мили не идут на нас (!theirMeleeClosing) — ради матча 73 (Coldkimchi:
            // его мили подходили к нашим стрелкам и лекарям вплотную, били по 240 и отходили — 46 ударов против наших 7, а
            // прижим требует «его мили не вплотную», и расстановка была выключена ровно в этом бою): едва атака врага встаёт,
            // бой берёт расстановка, и остаток уходит — 123/125, m28 wing и m31 camp проиграны, против прижима-только 21 хуже /
            // 16 лучше. Прилипший к стрелку мили — дело нашего мили (см. poker в engage), не строя
            // стоячий бой по центрам армий (v47): контакт держится дольше окна терпения, центры вооружённых армий не сближаются,
            // враг не отходит — расстановка; атака (центры сближаются) и погоня (враг отходит) — ряды
            // ...и это ЛИНИЯ, а не рубка (v62): его вооружённый мили не ближе MELEE_HOLD_RANGE + 1 к нашим вооружённым. Матч 150
            // (боевой けろびー, армия стёрта к 180-му, форма матча 140): контакт на 70-м, центры не сближались (его мили среди наших),
            // «стоячий бой» → расстановка ставила стрелков колонной x=81 в 1–3 клетках от его стрелков, к 80-му двое наших стрелков
            // стояли уже за его линией на клетках, равноудалённых от обоих центров (v61 их не режет); ярусы «подальше от его мили» в
            // рубке ведут сквозь его строй. Прижим (standoffNow) это условие и так несёт; стоячий бой по центрам (v47) — нет
            // РУБКА — его мили ВПЛОТНУЮ, не «в трёх» (v64): линия Coldkimchi держит мили в 2–3 от наших и не рубит (матч 153, восьмое
            // поражение: 2:699 и 3:1431 крип-тиков его мили, 61 удар за 700 тиков боя) — по «в трёх» v62 расстановка была выключена
            // весь бой, ряды planBlock ставили стрелков за передним мили, и наш огонь (1611 выстрелов против его 1428) шёл по
            // разным целям: 4+ в одну цель 9 тиков против его 44 при 216 лечения в тик на цели с обеих сторон
            val meleeBrawl = theirMeleeIn
            val standingNow = contact && Memory.centreDistHist.size > PRESS_PATIENCE && !armiesClosing && !enemyRetreating && !meleeBrawl && !ourYielding
            if (DEBUG_LOG && ourYielding && contact && !armiesClosing && !enemyRetreating && !meleeBrawl && yieldingTick != getTicks() - 1) println("plan t=${getTicks()}: our line has yielded ${PRESS_CLOSING}+ cells over $PRESS_PATIENCE ticks — rows behind the front melee, not the plan")
            if (ourYielding) yieldingTick = getTicks()
            val planNow =  (standoffNow || standingNow)
            // командир (v137): в бою с сомкнутым блобом решение одно на армию, и оно вытесняет оба планировщика
            // ...и НЕ против того, кто уходит (v139): в сценарии kite враг держит дистанцию, боя нет, и командир держал
            // армию в размене вместо игры за флаги — 0:21 899 и 0:21 082 при исправном CPU
            // ...и только когда рубка ИДЁТ: против лагеря у флага (camp) командир тоже держал армию в размене вместо
            // очков — 13 311:23 559. Мера уже есть: его мили внутри нашего строя (meleeBrawl)
            // КОМАНДИР ПРАВИТ ВЕСЬ БОЙ (v144): замер сказал, что он правил 27 тиков из пятисот и в большинстве из них
            // приказ получал ОДИН крип из двенадцати (cmd=1/27:noMelee) — остальное время армия шла по старым
            // правилам, и они тянули в другую сторону. Единого кулака из этого выйти не могло: командир успевал лишь
            // выдернуть крипа из строя. Теперь условие одно — контакт с сомкнутым врагом
            // ...и на ПОДХОДЕ тоже (v151): иначе армия сходится к бою врассыпную по старым правилам и собирается в кулак
            // уже под огнём — переход между двумя управлениями и есть то смешение, которое оператор назвал
            val nearFight = contact 
            // ...но «любой контакт» оказалось слишком широко: гейт уронил roost и scatter — формы, где враг сидит на
            // флагах или разбегается, и командир строил кулак против того, кто строем не дерётся. Условие по существу
            // не «сомкнут ли он», а «сколько его вооружённых стоит у нашей армии»: группа — дело командира, одиночка —
            // нет (v155)
            // цена командира отдельной строкой в разбивке (v158): она была спрятана в фазе «plan» вместе с обеими
            // расстановками, и когда живьём дважды сработал `Script execution timed out`, сказать по логу, чей это
            // расход, было нечем. На стенде вопрос не решается — там весь тик стоит 2,4 мс на пике
        cpuMark("commander")
            // РАССТАНОВКА МОЛЧИТ ПРИ КОМАНДИРЕ (v165, оператор: продолжать переносить логику в командира). Слоты и
            // командирские клетки — два ответа на один вопрос «кто где стоит»; пока командир ведёт бой, спрашивать
            // второй раз незачем, и крип, которому клетки не досталось, шёл в слот прежней расстановки
            if (planNow) planFight(mobileArmy, combatEnemies, armedEnemies, enemyCreeps, slotOf, focusTarget)
            else planBlock(mobileArmy, combatEnemies, armedEnemies, slotOf)
        }
        val ourFlagCells = ctx.flags.filter { it.ours }.mapTo(HashSet()) { it.pos.x * 100 + it.pos.y }
        val commanderNow =  cmdMode == CmdMode.FIGHT
        // ...а в гонке командир раздаёт задания по флагам (v160, см. commandRace): это второй его режим, и с ним
        // он перестаёт молчать там, где раньше просто уступал место старым правилам
        // ...и ПОХОД — тот же вопрос, что гонка, только врага рядом нет: командир так же раздаёт флаги группами,
        // а ядро держит вместе. Прежняя попытка вести поход (v151) провалилась 0-8 потому, что вела его РАЗДАЧА
        // КЛЕТОК ПРОТИВ СТРОЯ — расстановка, которой в походе нечего расставлять; здесь у похода свой режим (v160)
        val raceCommandNow = 
            (cmdMode == CmdMode.RACE || (cmdMode == CmdMode.MARCH))
        // сколько тиков командир действительно правил армией, и почему не правил: без этого спор «виноват командир
        // или базовая логика» решается догадкой, а в разгроме 6aa075ce постура была HOLD, то есть он молчал
        if (commanderNow) cmdTicks++ else cmdBlocked = cmdWhyNow
        // ПОГОНЯ НАЗНАЧАЕТСЯ ДО ПЕРЕБОРА (v211): раздача прогоняется пять раз, по разу на замысел, и отряд обязан
        // быть один и тот же во всех пяти — иначе прогноз оценивает пять разных армий.
        // ...И НЕ ЗАВИСИТ ОТ ТОГО, ПРАВИТ ЛИ КОМАНДИР (v212). Первая редакция стояла под `commanderNow`, и первый же
        // живой матч это закрыл: `cmd=8/1900` — командир правил восемь тиков из тысячи девятисот, погоня не
        // выдалась ни разу (`chase=0/0` при двух остовах). Доля командира гуляет по матчам от 8 тиков до двух
        // третей, поэтому назначение стоит выше него: приказ один, а исполняют его оба пути движения — командирская
        // раздача, когда он правит, и обычная цепочка целей (ветка `chase`), когда молчит
        assignChase(mobileArmy, enemyCreeps, armedEnemies)
        dispNow = Strategist.summary(Strategist.snapshot(army, ctx.runners, Memory.runnerFlag, Memory.detachedIds, Memory.cmdDetach,
            Memory.keeperIds, Memory.chaseOf, posture, cmdMode, objectiveFlagId, armedEnemies))
        if (commanderNow) {
            // СТРАХОВКА ПО ВРЕМЕНИ И ДЛЯ КОМАНДИРА (v158): она стояла на бегунах и на выборе цели, а на самой
            // дорогой части — переборе замыслов с прогоном каждого — не стояла. В рейтинговой серии 09.09.2026 это
            // дважды кончилось `Script execution timed out` (матчи 6aa085d7 и 6aa086d3): тик пропал целиком, армия
            // не сходила. При нехватке времени командир раздаёт клетки одним замыслом, без перебора и прогонов
            val cpuTight =  getTicks() > 1 && cpuMs() > CPU_GUARD_MS
            if (cpuTight && DEBUG_LOG) println("cpu t=${getTicks()} guard: the commander skips the search (${(cpuMs() * 10).toInt() / 10.0}ms)")
            // ...и при разрыве контакта (v227, см. USE_ZERO_LEAD_BREAK) замысел не выбирается прогоном — он задан: KITE
            if (cpuTight) commandFight(commandArmy, combatEnemies, armedEnemies, commandOf, Intent.PRESS, ourFlagCells = ourFlagCells)
            else {
                // командир предлагает несколько замыслов, симуляция выбирает лучший по мощи через Forecast.SIM_TICKS (v138)
                var bestScore = -Double.MAX_VALUE
                var bestPlan: Map<String, Position>? = null
                var bestIntent = Intent.PRESS
                // выбор цели фокуса симуляцией ОТВЕРГНУТ (v138): перебор пар (замысел, цель) дал 1-7 и 2-6 против
                // 3-13, а проведённая до стрельбы цель уронила гейт до 129/131 и дала m33:kite 0:21 135 — назначенная
                // цель ломает липкость фокуса, которая и держит наш огонь на одном. Перебираются только замыслы
                // ПОРТФЕЛЬНЫЙ ЖАДНЫЙ ПОИСК (v139, Churchill & Buro 2013): сперва лучший ЕДИНЫЙ замысел, затем
                // восхождение — крип за крипом пробуем все замыслы и оставляем тот, чей прогон лучше. Так армия
                // смешивает поведение, чего единая политика не умеет
                for (intent in Intent.values()) {
                    val trial = HashMap<String, Position>()
                    commandFight(commandArmy, combatEnemies, armedEnemies, trial, intent, ourFlagCells = ourFlagCells)
                    // прогноз считает ТОТ бой, который случится: наши в симуляции бьют ту же липкую цель фокуса,
                    // что и бот на самом деле, а не «самого раненого» (v140) — прежде прогноз и поведение расходились
                    val sc = Forecast.simulate(mobileArmy, armedEnemies, trial, Forecast.SIM_TICKS, focusTarget, intent)   // состав без хранителей: «тот же, что у плана» (v242) отвергнут A/B вместе с применением постуры один раз
                    if (sc > bestScore) { bestScore = sc; bestPlan = trial; bestIntent = intent }
                }
                // ГИСТОГРАММА ЗАМЫСЛА (этап 8): перебор из пяти стоит пяти раздач за тик, и окупается ли он —
                // вопрос к числу, а не к мнению. Счётчик стоит ЗДЕСЬ, где замысел действительно выбирается:
                // первая редакция поставила его внутрь блока USE_PORTFOLIO_SEARCH, который выключен, — то есть
                // я едва не отправил в бой мёртвый прибор, ровно тот отказ, о котором вся эта пачка
                if (bestPlan != null) Memory.intentHist[bestIntent.name] = (Memory.intentHist[bestIntent.name] ?: 0) + 1
                // ...восхождение идёт по ГРУППАМ РОЛЕЙ, а не по отдельным крипам (v139): в литературе это называют
                // кластеризацией юнитов, и при нашей грубой оценке она обязательна — назначая замысел каждому крипу
                // порознь, поиск рвал строй (гейт 128/131, m30:kite 0:21 899 при CPU всего 3,8 мс, то есть дело не
                // в цене, а в том, что смешанные наборы получают завышенную оценку)
                commandOf.clear()
                bestPlan?.let { commandOf.putAll(it) }
                // ОТХОД ПО ПРОГНОЗУ (v165, оператор: переносить логику в командира). Решение «бежать» принимала постура,
                // а у командира есть прибор, которого у неё нет, — симуляция размена. Если ЛУЧШИЙ из его замыслов
                // кончается тем, что уцелевшая мощь врага перевешивает нашу, драться незачем: он объявляет отход сам
                // ОШИБКА ПРОГНОЗА (v166): командир обещает разность мощи через Forecast.SIM_TICKS тиков — здесь она запоминается,
                // а на Forecast.SIM_TICKS-м тике сверяется с тем, что вышло на самом деле. Прибор нужен потому, что оценка НИ
                // РАЗУ не уходит в минус (см. USE_COMMAND_RETREAT): пока неизвестно, на сколько она врёт, командир
                // выбирает замысел числом, которому нельзя верить
                // ...и факт меряется ТОЙ ЖЕ формулой, что прогноз: сравнивать оценку симуляции с ланчестеровской
                // мощью — сравнивать разные величины, и первая редакция прибора именно этим и занималась
                val nowDiff = Forecast.simulate(mobileArmy, armedEnemies, emptyMap(), 0, focusTarget, null)
                Forecast.simPending[getTicks() + Forecast.SIM_TICKS] = bestScore to nowDiff
                Forecast.simPending.remove(getTicks())?.let { (predicted, was) ->
                    val actual = nowDiff - was          // как разность изменилась НА САМОМ ДЕЛЕ за Forecast.SIM_TICKS
                    val expected = predicted - was      // как её обещал изменить прогноз
                    Forecast.simErrSum += abs(actual - expected); Forecast.simErrN++
                    if (expected > 0 && actual < 0) Forecast.simErrWrongSign++
                }
                Forecast.simPending.keys.filter { it < getTicks() }.forEach { Forecast.simPending.remove(it) }
                if (DEBUG_LOG && getTicks() % LOG_EVERY == 0) println("sim t=${getTicks()}: intent=$bestIntent score=${bestScore.toInt()} obey=$orderAuditOk/$orderAuditN closer=$orderAuditCloser same=$orderAuditSame far=$orderFar clash=$orderClash fled=$orderFled branch=$orderBranch lost=stay$lostStay/stuck$lostStuck/fat$lostFatigue/else$lostElsewhere err=${if (Forecast.simErrN > 0) (Forecast.simErrSum / Forecast.simErrN).toInt() else 0} wrongSign=${Forecast.simErrWrongSign}/${Forecast.simErrN}")
            }
        // ⚠️ Здесь стояла ветка «в бою, пока по нам не стреляют, командир тоже отпускает за флагами». Она
        // НЕДОСТИЖИМА ДВАЖДЫ: стоит в `else` от `if (commanderNow)`, то есть `commanderNow` здесь ложно по
        // построению, — и вдобавок сам режим боя требует `underTheirFire`, поэтому `commanderNow && !underTheirFire`
        // противоречиво и само по себе. Комментарий при ней утверждал обратное и ссылался на замер, которого она
        // никогда не проходила. Снята в v215; дифф отчёта пуст побайтово. Оживлять её было бы и незачем: с v215
        // отпускать в бою запрещено вовсе (см. USE_NO_SPLIT_IN_FIGHT)
        // ...и ТОЛЬКО когда он ИДЁТ на нас: изготовка при всяком враге в десяти клетках вставала поперёк гонки за
        // флагами — армия строилась вместо захвата, и гейт рухнул до 122 из 135 (roost трижды)
        } else if (!contact && !pushing &&
                (armiesClosing || (enemyApproaching && enemyMassedNow)) &&
                armedEnemies.any { e -> commandArmy.any { getRange(e, it) <= BRACE_RANGE } }) {
            // ИЗГОТОВКА (v179): враг идёт, контакта ещё нет — строим фронт, а не ждём его растянутыми
            // ...и строится ЯДРО, а отпущенные за флагами своего задания не бросают (v183) — ровно как в марше ядра.
            // Изготовка отзывала в строй и захватчиков, и гонка очков от этого проседала: сценарий camp 15 983:16 266
            cmdTicks++
            // ...и гонка идёт ПАРАЛЛЕЛЬНО строю: изготовка стояла В ЦЕПОЧКЕ ПЕРЕД гонкой, поэтому, пока враг
            // подходил, командир не отпускал за флагами вовсе — ни одного захватчика не назначалось, и сценарий
            // camp кончался 15 983:16 266. Сперва раздаются задания на захват, затем ядро из оставшихся строится
            commandRace(ctx, commandArmy, armedEnemies, ctx.flags, commandOf)
            val runners = HashMap(commandOf)
            Formation.brace(commandArmy.filter { it.id !in Memory.cmdDetach }, armedEnemies, commandOf)
            commandOf.putAll(runners)
        } else if (raceCommandNow) {
            cmdTicks++
            commandRace(ctx, commandArmy, armedEnemies, ctx.flags, commandOf)
            // прибор второго тика (v222): фаза plan стоит 20–28 мс на тиках 1–2 и 0,7 мс на третьем — метки внутри неё
            // называют, что именно (строка cpu печатается на первых трёх тиках и на медленных)
            cpuMark("p.race")
            // ...и ядро, оставшееся после раздачи заданий, идёт СТРОЕМ к цели (v163): прежде командир раздавал только
            // задания на захват, а ядро шло врозь по прежним веткам и приходило к бою растянутым
            // ...и только пока враг ДАЛЕКО: рядом с ним решают тактические ветки — экран, добыча, перехват, — а строй,
            // ведущий ядро на флаг мимо них, ронял screen и scatter (гейт 131 из 135)
            if (armedEnemies.none { e -> mobileArmy.any { getRange(e, it) <= MARCH_SAFE } }) {
                // цель марша — своя (v164): раньше здесь стояла objectiveFlagId, посчитанная до командира
                val goal = commandGoal(ctx, mobileArmy, armedEnemies)
                cpuMark("p.goal")
                val steps = HashMap<String, Position>()
                commandMarch(ctx, mobileArmy.filter { it.id !in Memory.cmdDetach }, goal, steps)
                commandOf.putAll(steps)
                cpuMark("p.march")
            }
        }
            // ...и задания на захват снимаются вместе с режимом: без этого крип, отпущенный командиром за флагом,
            // оставался захватчиком НАВСЕГДА — армия таяла тик за тиком, и сценарий kite давал 0 очков (v160)
            else { commandOf.clear(); Memory.cmdDetach.clear() }

            // ИСПОЛНЕНИЕ ПРИКАЗА (v167): прогноз считает, что крип встанет туда, куда назначено, а между приказом и
        // клеткой стоят трафик, свопы и фатиг. Здесь считается доля тех, кто на следующем тике оказался ровно
        // на своей клетке: если она мала, ошибка прогноза объясняется не моделью, а неисполнением
        // КОЛЛИЗИИ ПРИКАЗОВ (v172, оператор: «не должно быть такого, что по приказам командира в одну клетку
        // собрались двое»). Внутри одной раздачи это исключено множеством taken, но приказы приходят из РАЗНЫХ
        // мест — бой, гонка, марш ядра, — и вот там пересечение возможно; здесь оно считается
        val seen = HashMap<Int, Int>()
        commandOf.values.forEach { p -> seen[p.x * 100 + p.y] = (seen[p.x * 100 + p.y] ?: 0) + 1 }
        val dup = seen.values.count { it > 1 }
        orderClash += dup
        // ГАРАНТИЯ, А НЕ НАБЛЮДЕНИЕ (v176, оператор: «не должно быть такого, что по приказам командира в одну
        // клетку собрались двое»). Раздача держит своё множество занятых, но источников приказа несколько — бой,
        // гонка, марш, хранители, отход, — и на стыке коллизия всё же случалась (одна на 431 приказ, режим боя).
        // Здесь она снимается: клетка остаётся за первым, второй теряет приказ и идёт по общим правилам
        if (dup > 0) {
            val used = HashSet<Int>()
            val drop = ArrayList<String>()
            for ((id, p) in commandOf) { val k = p.x * 100 + p.y; if (!used.add(k)) drop.add(id) }
            drop.forEach { commandOf.remove(it) }
        }
        if (dup > 0 && DEBUG_LOG) {
            val where = seen.entries.firstOrNull { it.value > 1 }?.key ?: 0
            val who = commandOf.filterValues { it.x * 100 + it.y == where }.keys.joinToString(",")
            println("clash t=${getTicks()}: mode=$cmdMode cell=(${where / 100},${where % 100}) who=$who")
        }
        Memory.orderPrev.forEach { (id, cell) ->
            // ...и захватчик из аудита исключается: его приказ — ФЛАГ, а не клетка, и ведёт его свой цикл;
            // считать его ослушником было бы неверно (v173)
            if (id in Memory.cmdDetach) return@forEach
            val c = commandArmy.firstOrNull { it.id == id } ?: return@forEach
            orderAuditN++
            // ...и ПРИКАЗ В ДВУХ ШАГАХ ИСПОЛНЕН, ЕСЛИ КРИП СТАЛ БЛИЖЕ (v184). Прибор сверял клетку крипа с
            // НАЗНАЧЕННОЙ и только с ней, а строй (`commandBrace`) назначает место в строю за несколько клеток —
            // такой приказ не мог быть засчитан НИКОГДА, и едва строй заработал, исполнение упало со 99 % до 62 %
            // при том, что крипы шли туда, куда велено. Из-за этого я успел записать в дефекты то, чего не было,
            // и починить не тот код (см. USE_BRACE_STEPS). По всей серии v183 «ушёл в другую клетку» набрал
            // 2 022 случая из 39 245 — почти все они этой природы
            val far = 
                (orderDist[id] ?: 0) > 1 && maxOf(abs(c.x - cell.x), abs(c.y - cell.y)) < (orderDist[id] ?: 0)
            if ((c.x == cell.x && c.y == cell.y) || far) orderAuditOk++
            else {
                // ...и КУДА делись остальные (v170): приказ был «стой», а крип ушёл; крип не двинулся
                // вовсе; двинулся, но в другую клетку; или не мог двигаться от усталости
                val here = orderWas[id]
                when {
                    cell.x == here?.first && cell.y == here.second -> lostStay++
                    // ...клетку мог занять ВРАГ: он ходит одновременно с нами, и его шаг делает приказ
                    // неисполнимым задним числом — это неустранимо в принципе, и считать надо отдельно (v175)
                    ctx.enemyCreeps.any { e -> e.x == cell.x && e.y == cell.y } -> lostEnemy++
                    c.x == here?.first && c.y == here.second -> lostStuck++
                    (orderFatigue[id] ?: 0) > 0 -> lostFatigue++
                    else -> lostElsewhere++
                }
            }
            // ...и отдельно: СТАЛ ЛИ БЛИЖЕ к назначенной клетке (приказ бывает в двух шагах, за тик не дойти)
            val wasD = orderDist[id] ?: 99
            val nowD = maxOf(abs(c.x - cell.x), abs(c.y - cell.y))
            if (nowD < wasD) orderAuditCloser++
            // ...и ДЕРЖИТСЯ ЛИ приказ: та же клетка, что была назначена в прошлый тик
            if (commandOf[id]?.let { it.x == cell.x && it.y == cell.y } == true) orderAuditSame++
        }
        // ...и сколько приказов вообще достижимо за тик: клетка в двух шагах не может быть занята сразу,
        // и доля исполнения ограничена этим по построению (v170)
        commandOf.forEach { (id, p) ->
            val c = commandArmy.firstOrNull { it.id == id } ?: return@forEach
            if (maxOf(abs(c.x - p.x), abs(c.y - p.y)) > 1) orderFar++
        }
        orderWas.clear(); orderFatigue.clear()
        commandArmy.forEach { c -> orderWas[c.id] = c.x to c.y; orderFatigue[c.id] = c.fatigue }
        orderDist.clear()
        commandOf.forEach { (id, p) ->
            val c = commandArmy.firstOrNull { it.id == id }
            if (c != null) orderDist[id] = maxOf(abs(c.x - p.x), abs(c.y - p.y))
        }
        Memory.orderPrev.clear()
        commandOf.forEach { (id, p) -> Memory.orderPrev[id] = p }
        // потеря за прошлый тик по всем — ДО цикла: lastHits обновляется в конце каждой итерации, и для уже обработанных она была бы нулём
        lostTick.clear()
        for (c in army) lostTick[c.id] = ((Memory.lastHits[c.id] ?: c.hits) - c.hits).coerceAtLeast(0)
        // СТЕНА ЛЕЧЕНИЯ (v228, см. USE_HEAL_WALL): жертва — терявший больше всех за прошлый тик; удержима, если её потеря не
        // больше лечения, которое наши лекари доставят в неё следующим тиком (вплотную или в шаге от вплотную — полное, в трёх
        // — треть; лекарь считается и для себя)
        // ...и стена стоит только на БЕЗОПАСНЫХ клетках (стенд m28 brawl+heals при первой редакции: лекари вплотную к жертве
        // попадали под удары его мили — 240 за удар по лечащим частям, которые у h6m6 спереди, — лечение обнулялось и
        // раздевалась вся армия; уничтожение на 298-м стало проигрышем на 1751-м). Клетка стены — свободная соседняя с жертвой,
        // от которой его вооружённые мили дальше двух (за один ход не встанут вплотную); живьём против Coldkimchi#1 такая клетка
        // у жертвы есть в 83–89 % тиков, в блобе MetalicaX#9 — в 29 %. Лекарь получает ближайшую свою клетку как слот; без
        // клеток жертва не удержима, и правило молчит
        victimNow = null; victimSaveable = false; wallCells = emptyList(); wallCellOf.clear()
        addressedDmg.clear()
        // ...И ЖЕРТВА — ПО АДРЕСНОМУ ОГНЮ ЭТОГО ТИКА (v229, см. USE_HEAL_WALL_ADDRESSED): его правило выбора цели по
        // текущим клеткам — лекарь в досягаемости первым, иначе ближайший, при равенстве с меньшими хитами
        // ...и карта адресного урона живёт тик (v233, см. USE_HEAL_BY_DEFICIT): её читает выбор пациента
        val addressed = addressedDmg
        val live = army.filter { it.hits > 0 && (hasWeapon(it) || hasHeal(it)) }
        for (e in ctx.combatEnemies) {
            val q = InfluenceMap.profileOf(e)
            if (q.ranged > 0.0) Forecast.wallTargetOf(e, live, RANGED_RANGE)?.let { t -> addressed[t.id] = (addressed[t.id] ?: 0.0) + q.ranged }
            if (q.melee > 0.0) Forecast.wallTargetOf(e, live, MELEE_STEP_REACH)?.let { t -> addressed[t.id] = (addressed[t.id] ?: 0.0) + q.melee }
        }
        val byAddress = addressed.entries.maxByOrNull { it.value }
        val lostV = army.filter { (hasWeapon(it) || hasHeal(it)) && (lostTick[it.id] ?: 0) > 0 }.maxByOrNull { lostTick[it.id] ?: 0 }
        // ...И АДРЕС БЕРЁТСЯ, ПОКА ОН ПОПАДАЕТ (v229, вторая редакция по стенду m28 brawl+heals: его сценарий стреляет «в
        // вооружённого стрелка первым», а не в лекаря, и адресная жертва промахивалась — уничтожение на 442-м стало
        // проигрышем на 1570-м). Оба предсказателя сверяются с фактом следующего тика (кто потерял больше всех) за окно
        // TOUCH_WINDOW; адресный используется, только пока попадает чаще, чем «по потере», — против того, чьё правило
        // цели другое, стена сама возвращается к v228
        if (lostV != null && (wallAddrPrev != null || wallLostPrev != null)) {
            wallAddrHits.addLast(wallAddrPrev == lostV.id); wallLostHits.addLast(wallLostPrev == lostV.id)
            while (wallAddrHits.size > TOUCH_WINDOW) wallAddrHits.removeFirst()
            while (wallLostHits.size > TOUCH_WINDOW) wallLostHits.removeFirst()
            hwallPredN++; if (wallAddrPrev == lostV.id) hwallPredA++; if (wallLostPrev == lostV.id) hwallPredL++
        }
        wallAddrPrev = byAddress?.key; wallLostPrev = lostV?.id
        val addrWins = wallAddrHits.size >= STALL_TICKS && wallAddrHits.count { it } > wallLostHits.count { it }
        val v = if (byAddress != null && addrWins) army.firstOrNull { it.id == byAddress.key } ?: lostV else lostV
        if (v != null) {
            val useAddr = byAddress != null && addrWins && v.id == byAddress.key
            if (useAddr) hwallAddr++
            val loss = if (useAddr) byAddress!!.value else (lostTick[v.id] ?: 0).toDouble()
            val hisMelee = ctx.combatEnemies.filter { hasMelee(it) }
            val hisRanged = ctx.combatEnemies.filter { hasRanged(it) }
            val occupied = HashSet<Int>()
            for (c in army) if (!hasHeal(c) || hasWeapon(c)) occupied.add(c.x * 100 + c.y)
            for (e in ctx.enemyCreeps) occupied.add(e.x * 100 + e.y)
            val cells = ArrayList<Position>()
            for (dx in -1..1) for (dy in -1..1) {
                if (dx == 0 && dy == 0) continue
                val x = v.x + dx; val y = v.y + dy
                if (x < 0 || y < 0 || x > 99 || y > 99 || DistanceMap.isTerrainWall(x, y) || (x * 100 + y) in occupied) continue
                val cell = InfluenceMap.cell(x, y)
                if (hisMelee.none { getRange(cell, it) <= 2 }) cells.add(cell)
            }
            wallCells = cells
            val healers = army.filter { hasHeal(it) && it.id != v.id }
            val free = ArrayList(cells)
            for (h in healers.sortedBy { getRange(it, v) }) {
                if (free.isEmpty() || getRange(h, v) > HEAL_RANGE + 1) break
                val best = free.minByOrNull { getRange(h, it) } ?: break
                free.remove(best)
                wallCellOf[h.id] = best
            }
            val potential = army.filter { hasHeal(it) }.sumOf { h ->
                val heal = InfluenceMap.profileOf(h).heal
                val cell = wallCellOf[h.id]
                val d = getRange(h, v)
                if (h.id == v.id || (cell != null && getRange(h, cell) <= 1)) heal else if (d <= HEAL_RANGE) heal / 3.0 else 0.0
            }
            victimNow = v
            victimSaveable = cells.isNotEmpty() && loss <= potential
            if (!victimSaveable) wallCellOf.clear()
            hwallVictimTicks++
            if (victimSaveable) hwallTicks++
        }
        cpuMark("plan")
        for (creep in army) {
            val mobile = strikers.any { it.id == creep.id }
            val healer = !hasWeapon(creep) && hasHeal(creep)
            val slot0 = slotOf[creep.id]
            val keeper = creep.id in Memory.keeperIds
            // раненый (без оружия и лечения, в армии по решению выше): ходит за ближайшим лекарем, в строй не входит
            val wounded = !healer && !hasWeapon(creep)
            // ротация (см. ROTATE_OUT): с гистерезисом, чтобы боец не дёргался у порога
            val rotating =  !healer && hasWeapon(creep) && healersAlive && run {
                val weapons = creep.body.count { it.type == ATTACK || it.type == RANGED_ATTACK }
                val live = creep.body.count { (it.type == ATTACK || it.type == RANGED_ATTACK) && it.hits > 0 }
                val frac = if (weapons == 0) 1.0 else live.toDouble() / weapons
                // возврат на одну часть ВЫШЕ порога выхода (v126, USE_ROTATE_IN_ONE_PART): 0.9 от восьми частей ATTACK — все восемь, то есть
                // полное лечение блока; под огнём у фронта оно не наступает, и мили висит в ротации 50–97 тиков при 1050–1250 хитах
                // (матч 506, melee_4 116–212; 602, melee_3 314–372) — ноль ударов. Его мили (матч 14) вернулся при 5 из 8
                val backIn = live >= kotlin.math.ceil(weapons * ROTATE_OUT).toInt() + 1
                if (creep.id in Memory.rotatingIds) { if (backIn) { Memory.rotatingIds.remove(creep.id); if (DEBUG_LOG) println("rot t=$now in ${creep.id} frac=$frac took=${now - (Memory.rotateSince[creep.id] ?: now)}"); false } else true }
                else if (frac < ROTATE_OUT) {
                    Memory.rotatingIds.add(creep.id); Memory.rotateSince[creep.id] = now; rotOut++; if (DEBUG_LOG) println("rot t=$now out ${creep.id} frac=$frac hits=${creep.hits}"); true
                } else false
            }
            val support = healer || wounded
            val nearestEnemyRange = combatEnemies.minOfOrNull { getRange(creep, it) } ?: 99
            val localAllies = combatArmy.filter { getRange(creep, it) <= (if (posture == Posture.ANNIHILATE || posture == Posture.FLAG) ENGAGE_RANGE else RANGED_RANGE + 1) }
            val localEnemies = combatEnemies.filter { getRange(creep, it) <= ENGAGE_RANGE + RANGED_RANGE }
            val ratio = if (creep.id in Memory.aggressiveIds) LOCAL_ENTER_RATIO else PUSH_RATIO
            val ghost = run {
                val prev = Memory.lastHits[creep.id]
                val cell = Memory.lastCell[creep.id]
                if (prev == null || cell == null) 0 else {
                    val lost = prev - creep.hits
                    var explained = 0.0
                    val taken = InfluenceMap.takenOf(creep)
                    for (s in prevShooters) {
                        val d = maxOf(abs(s.cell / 100 - cell / 100), abs(s.cell % 100 - cell % 100))
                        if (d <= RANGED_RANGE) explained += s.ranged * taken
                        if (d <= 1) explained += s.melee * taken
                    }
                    if (lost > explained + 1.0) lost else 0
                }
            }
            if (ghost > 0 && DEBUG_LOG && getTicks() - (ghostLogged[creep.id] ?: -100) >= 10) {
                ghostLogged[creep.id] = getTicks()
                val nearest = combatEnemies.minOfOrNull { getRange(creep, it) } ?: -1
                println("ghost damage t=${getTicks()}: ${creep.id} -$ghost at (${creep.x},${creep.y}) hits=${creep.hits} nearestCombat=$nearest — источник не виден")
            }
            // локальный перевес: бойцы, способные стрелять по той же цели через тик-другой, против врагов в их
            // досягаемости; цена боя — по ГРУППЕ (самый большой запас хода), в контакте цена больше не гейт
            val localAggressive = when {
                posture == Posture.RETREAT || posture == Posture.EVADE -> inContact(localEnemies, localAllies) && ourPowerOf(localAllies, localEnemies) >= enemyPowerOf(localEnemies, localAllies) * ratio
                // добивание: армия в целом сильнее (или в контакте без отхода), но ЯВНО слабейшая на месте группа
                // отходит к массе — «всегда агрессивен» посылал четверых на двенадцать (матч 2 на стенде). Вход в
                // бой при 0.9 (при равных силах никто не вступал в бой — рывок врага кончался ничьёй), выход — только
                // при разгроме на месте (ANNIHILATE_HOLD_RATIO): в гуще боя местный счёт скачет, и бойцы по одному
                // «отходили к центру» и гибли поодиночке (стенд rush 7:2 против прежних 0:12)
                // отходить к массе есть смысл, только если масса не здесь: когда рядом больше половины армии, это и
                // есть масса, и «отход к центру» был шагом на месте под ударами (матч 3, t=140–280: армия из
                // семи-восьми «отходила к центру» сто сорок тиков и потеряла всех по одному, не стреляя в ответ)
                posture == Posture.ANNIHILATE -> localEnemies.isEmpty() || localAllies.size * 2 >= combatArmy.size ||
                    ourPowerReach(localAllies, localEnemies) >= enemyPowerReach(localEnemies, localAllies) * (if (creep.id in Memory.aggressiveIds) ANNIHILATE_HOLD_RATIO else LOCAL_ENTER_RATIO)
                localEnemies.isEmpty() -> true
                // без боевого своего в четырёх клетках (раненый один) запаса хода нет: maxOf пустого списка бросал
                // NoSuchElementException КАЖДЫЙ тик до конца матча — армия стояла 1500 тиков после выигранного боя
                // (стенд m19 nine, v30; в v29 то же падало в m8 rush t=115–120 и m28 wing t=1200, стенд этого не считал)
                else -> ourPowerOf(localAllies, localEnemies) >= enemyPowerOf(localEnemies, localAllies) * ratio &&
                    (fightCost(localEnemies, localAllies) <= (localAllies.maxOfOrNull { speedSlack(it) } ?: 0) || inContact(localEnemies, localAllies))
            }
            if (localAggressive) Memory.aggressiveIds.add(creep.id) else Memory.aggressiveIds.remove(creep.id)
            // ОТПЕЧАТОК РАСХОЖДЕНИЯ МАСШТАБОВ (этап 0): знаменатель — мили с боевым врагом в ENGAGE_RANGE,
            // числитель — из них те, где МЕСТНАЯ арифметика в клетке врага даёт перевес не ниже PUSH_RATIO, а
            // армейская мера при этом говорит «не наступать». Ненулевой числитель и есть наблюдение оператора
            // «трое наших мили боялись подойти к одному чужому», выраженное числом
            if (isMelee(creep) && !hasRanged(creep)) {
                val near = localEnemies.filter { getRange(creep, it) <= ENGAGE_RANGE }
                if (near.isNotEmpty()) {
                    edgeAll++
                    if (!localAggressive && near.any { spotEdgeAt(it) >= PUSH_RATIO }) edgeSpot++
                }
            }
            // бросок — только на врага «с боем» (см. threatening): одинокий лекарь врага в восьми клетках был целью бойца,
            // который ждал по сплочению группу, а группа ждала его как отставшего на пути к флагу — 1500 тиков (m1 rush)
            // бросок — только в строю: построение готово и не меньше двух вооружённых в FORM_RANGE; одиночный мили, ушедший
            // вперёд на стрелков врага, погиб за восемь тиков, пока остальные держали построение (матч 14, t=71–78)
            // в бою — в строю по факту (см. USE_INLINE_CONTACT_FREE): враг с боем в MELEE_HOLD_RANGE + 1 или под огнём
            // ...первый срез «враг в трёх или в поле огня» ОТВЕРГНУТ: blitz 7-1 → 5-3 (m28 5 890:23 972, m30 5 956:22 619, m33 3 817:24 121) —
            // пикет фермера в трёх снимал ворота, и мили танцевали с ним вместо марша (то, против чего ворота и стоят); второй срез:
            // только крип, КОТОРОГО БЬЮТ (потеря хитов за прошлый тик)
            // МЕСТНЫЙ ПЕРЕВЕС (v214, решение оператора: «локальный перевес снимает требование прикрытия»).
            // Считается полем удара в ЕГО клетке (см. spotEdgeAt), а не мощью армии: наш залп по нему против его
            // залпа по клетке рядом с ним. Порог — существующий PUSH_RATIO = 1.3, нового числа не заводим:
            // у сомкнутого блока dangerAt в его клетке 700–1500 против нашего залпа 200–500, отношение меньше
            // единицы и очаг не возникает; против одиночки 720/240 = 3.0 — возникает.
            // Добиваемость обязательна (killTicks конечен): очаг у трёх его лекарей — не очаг.
            // ⚠️ Это НЕ второе издание отвергнутого USE_INLINE_CONTACT_FREE: тот открывал ворота «врагом в трёх»,
            // и одиночный пикет фермера снимал их (blitz 7-1 -> 5-3). Здесь пикет даёт 240/240 = 1.0 и ворот
            // не открывает — открывает только настоящий численный перевес.
            val spotNow =  isMelee(creep) && !hasRanged(creep) && !support && !rotating &&
                localEnemies.any { e -> getRange(creep, e) <= ENGAGE_RANGE && spotEdgeAt(e) >= PUSH_RATIO && !killTicks(e).isInfinite() }
            if (spotNow) spotMeleeTicks++
            // МИЛИ ЗАЩИЩАЕТ СВОЕГО (v220, см. USE_MELEE_GUARDS_LINE). Ворота `inLine` требуют двух ВООРУЖЁННЫХ
            // своих в FORM_RANGE = 2 — и это спираль: его мили раздевает наших стрелков, раздетый перестаёт быть
            // `hasWeapon`, ворота закрываются, наши мили перестают драться, и он раздевает следующего. Разбор
            // реплеев v219 показывает её прямо: в трёх разгромах трассировка простоя мили даёт `!inLine` 20/22/3
            // и `!covered` 20/15/6 крипо-тиков, а его мили стояли вплотную 53–73 крипо-тика против наших 14–18 —
            // «его мили нашли цели, наши держали линию, которую никто не атаковал».
            // Оговорка узкая и НЕ повторяет отвергнутое «враг в трёх снимает ворота» (blitz 7-1 -> 5-3, пикет
            // фермера снимал их и мили танцевали с пикетом): здесь ворота открывает не близость врага к НАМ, а
            // то, что его вооружённый мили УЖЕ дотянулся до нашего небоевого — стрелка, лекаря или раздетого.
            // Пикет одиночки такого не делает, а блоб делает первым же тиком
            fun guards(e: Creep) = InfluenceMap.profileOf(e).melee > 0.0 &&
                combatArmy.any { a -> a.id != creep.id && !(isMelee(a) && !hasRanged(a)) && getRange(e, a) <= MELEE_KEEP_RANGE }
            val guardNow =  isMelee(creep) && !hasRanged(creep) && !support && !rotating &&
                localEnemies.any { e -> getRange(creep, e) <= ENGAGE_RANGE && guards(e) }
            if (isMelee(creep) && !hasRanged(creep) && localEnemies.isNotEmpty()) { guardTicks++; if (guardNow) guardFired++ }
            val inLine =  spotNow || guardNow || (formationReady && combatArmy.count { it.id != creep.id && hasWeapon(it) && getRange(creep, it) <= FORM_RANGE } >= 2)
            // при бесплодной охоте (см. STALL_TICKS) броска нет: висящие крипы россыпи «ловимы» (не уходят стабильно), и
            // каждый наш крип танцевал со своим соседом вместо марша к флагу-цели (стенд m19 spread, travel=23 четыреста тиков)
            // «держит линию» — про мили В ЛИНИИ, а не про любого мили в бою: без этого условия мили, до которого враг
            // ещё не дошёл, стоял на месте весь бой. Матч 24: двое из четырёх простояли в 4–6 клетках от схватки в полном
            // здравии (M8A8 1600 на 140-м тике), пока двое дрались и армия гибла — 14:1 при равной мощи
            // прижим (см. USE_PRESS): мили в пачке — вплотную к цели фокуса в PRESS_RANGE, иначе к ближайшему ловимому врагу с
            // боем; стрелок — в кольцо ровно в RANGED_RANGE от цели фокуса
            val pack = pressOn && isMelee(creep) && !hasRanged(creep) && hasMelee(creep) && !rotating && localAggressive &&
                (combatArmy.any { it.id != creep.id && isMelee(it) && !hasRanged(it) && hasMelee(it) && getRange(creep, it) <= PRESS_PACK } ||
                    localEnemies.any { getRange(creep, it) <= 1 })
            // отказ (см. PRESS_GIVEUP) действует, пока цель не вернулась в три (v111, USE_GIVEUP_RETURNS), и снимается,
            // когда цель стоит ВПЛОТНУЮ к нашему не-мили (v135, см. USE_GIVEUP_LIFTS_ON_BACK): отказ — про погоню, а
            // враг у нашего лекаря никуда не бежит
            fun givenUp(e: Creep) = e.id in pressGiveUp && !(getRange(creep, e) <= MELEE_HOLD_RANGE + 1) 
            // прижим — только под прикрытием стрелков (v122, USE_PRESS_COVER): та же мера, что у броска (см. covered, v55) —
            // MELEE_COVER стрелков в RANGED_RANGE + 1 от цели или свой вплотную к ней; иначе мили прижимают шагающую назад линию
            // в одиночку под её огонь (серия 307–326: けろびー#1 дважды за 240 тиков, наш мили 1600 → 752 за 14 тиков погони,
            // стрелки в двух за мили не достают — 44 выстрела против 70)
            fun pressCovered(e: Creep) = 
                combatArmy.count { it.id != creep.id && hasRanged(it) && getRange(it, e) <= RANGED_RANGE + 1 } >= MELEE_COVER ||
                army.any { a -> a.id != creep.id && getRange(e, a) <= 1 }
            val pressTarget: Creep? = if (!pack) null else
                focusTarget?.takeIf { getRange(creep, it) <= PRESS_RANGE && catchable(it, chasers) && !givenUp(it) && pressCovered(it) }
                    ?: localEnemies.filter { getRange(creep, it) <= PRESS_RANGE && catchable(it, chasers) && threatening(it, enemyCreeps) && !givenUp(it) && pressCovered(it) }.minByOrNull { getRange(creep, it) }
            // против СОМКНУТОГО блоба мили не бросается (v135, см. USE_MELEE_HOLD_VS_MASS): наш мили, вошедший в двенадцать,
            // получает около 750 в тик (пять стрелков и четыре мили достают его) и живёт два-три тика — за матч наши мили
            // живут 50 крипо-тиков против его 664 и бьют 14 раз против 85. Держим линию и бьём то, что подошло; poker
            // (защита тыла) по-прежнему выше и работает
            // ...И НЕ ДЕРЖИМ ЛИНИЮ, КОГДА РЯДОМ ПЕРЕВЕС (v214): здесь мили получал цель «своя клетка», то есть
            // буквально стоял, как только любой враг оказывался в трёх клетках. Замер по 12 живым матчам: доля
            // касаний наших мили в затяжном бою 1,4 %, то есть четверо из четырнадцати не бьют вовсе
            val holdMelee =  (isMelee(creep) && !hasRanged(creep) && posture == Posture.ANNIHILATE && !pushing && contact && pressTarget == null &&
                !spotNow && localEnemies.any { getRange(creep, it) <= MELEE_HOLD_RANGE + 1 })
            // прилипший (v43): его вооружённый мили ВПЛОТНУЮ к нашему стрелку, лекарю или раненому — цель ближайшего нашего мили в
            // ENGAGE_RANGE, поверх «держать линию в двух». Матч 73 (Coldkimchi): его мили подходили к нашим стрелкам и лекарям,
            // били по 240 и отходили — 46 ударов (11 тыс. урона) против наших 7, наши мили держали линию в 2–3 от его линии и не
            // доставали; стрельба при трёх лекарях с обеих сторон вылечена целиком, армия потеряна к 240-му при его 16000/16000
            // ...и ротирующий защищает тыл (v135, см. USE_POKER_WHILE_ROTATING): ротация значит «оружия меньше половины, иду
            // лечиться», но три живых ATTACK из восьми — это 90 урона в удар, а лекарь, к которому он идёт, — тот самый,
            // которого рубят. Ротация не отменяет poker, пока у бойца есть чем ударить
            val poker: Creep? = if (isMelee(creep) && !hasRanged(creep) && !support && (!rotating) && !stalled) combatEnemies.filter { e ->
                InfluenceMap.profileOf(e).melee > 0.0 && getRange(creep, e) <= ENGAGE_RANGE && !givenUp(e) &&
                    army.any { a -> a.id != creep.id && !(isMelee(a) && !hasRanged(a)) && getRange(e, a) <= 1 }
            }.let { c ->
                // защита своего — тоже одной целью на всех (v221, см. USE_MELEE_PACK): цель пачки, если она среди них
                c.minByOrNull { getRange(creep, it) } } else null
            // прикрытие (v55): мили бросается на цель в ENGAGE_RANGE, только если её достают наши стрелки — не меньше MELEE_COVER
            // стрелков в RANGED_RANGE + 1 от неё — или она вплотную к кому-то из наших. Матч 115 (stachu3478, битый до того
            // девятнадцать раз): его одиночный стрелок подошёл на 2–6 клеток к нашим мили и отступал по клетке в тик; трое мили
            // без врага в трёх (линию не держат) шли за ним на 5–6 клеток впереди своих стрелков в его блок из четырёх мили и
            // четырёх стрелков — 1200 хитов за два тика (t=86–87), трое из четырёх мили мертвы к 100-му при равной силе на 77-м;
            // «под огнём без двух вплотную — назад» срабатывал уже под ударами. В выигранном за пять минут до того матче его
            // мили сами шли в досягаемость наших стрелков и там гибли. Гейт 125/125 при 19 лучше / 24 хуже (правило боя
            // всегда перемешивает 20–30 строк: v52c 29/20, v53 29/30; правки вне боя — 0/0). Два сужения ОТВЕРГНУТЫ стендом:
            // «только цель в блоке» (не меньше двух других вооружённых в RANGED_RANGE от неё) — 124/125, 13 лучше / 24 хуже,
            // m33 farm+weak красная; «только без толчка» (pushing) — 123/125, 10 лучше / 19 хуже, m28 farm+weak и m29 camp
            // красные. Строки «стёрт → лидируем» в rush-сценариях — не это правило: там последний крип (лекарь, равная
            // скорость) уходит от погони при любом варианте, бой окончен на 94-м
            // ...и ПЕРЕВЕС НАД ЭТОЙ ЦЕЛЬЮ снимает требование прикрытия (v214, решение оператора). Порог берётся по
            // КОНКРЕТНОЙ цели, а не по spotNow: перевес над одним не должен открывать бросок на другого
            fun covered(e: Creep) =  holdMelee || (spotEdgeAt(e) >= PUSH_RATIO) ||
                (guards(e)) ||
                combatArmy.count { it.id != creep.id && hasRanged(it) && getRange(it, e) <= RANGED_RANGE + 1 } >= MELEE_COVER ||
                army.any { a -> a.id != creep.id && getRange(e, a) <= 1 }
            // ОДНА ДОБЫЧА НА ВСЕХ в толчке (v71): бросок — только на цель в ENGAGE_RANGE от добычи армии (prey — ближайший к центру по
            // полю). Стенд camp+shy (застенчивый лагерь матчей 133/152/159: отходит от наших в шести и возвращается на флаг): его
            // блоб рассыпался вокруг армии, мили брали одну цель в (34,39), стрелки другую в (46,55), плотность держала всех у
            // центра между ними — 800 тиков pushing=true, huntable 12/12, `step=stay` у всех, 9615:23822 (m30). Живьём — толчок к
            // стоящему блобу, который не сближается (матчи 70, 133, 152, 159)
            // мили входит парой (v101, USE_MELEE_PAIR_ENGAGE): к цели в досягаемости — другой наш мили в MELEE_HOLD_RANGE + 1 от неё
            val meleeOnly = isMelee(creep) && !hasRanged(creep)
            fun mateNear(e: Creep, r: Int) = combatArmy.any { m -> m.id != creep.id && isMelee(m) && !hasRanged(m) && hasMelee(m) && getRange(m, e) <= r }
            // ...и присоединяется к напарнику, уже стоящему в MELEE_HOLD_RANGE от цели: досягаемость на клетку больше
            fun holdReach(e: Creep) = if (meleeOnly && mateNear(e, MELEE_HOLD_RANGE)) MELEE_HOLD_RANGE + 1 else MELEE_HOLD_RANGE
            val engage = if (pressTarget != null) pressTarget else poker ?: if ((localAggressive || spotNow) && !support && inLine && !rotating && !stalled) combatEnemies.filter { getRange(creep, it) <= (if (holdMelee) holdReach(it) else ENGAGE_RANGE) && catchable(it, chasers) && threatening(it, enemyCreeps) && !givenUp(it) && (!isMelee(creep) || hasRanged(creep) || covered(it))  }.let { c ->
                // ОДНА ЦЕЛЬ НА ВСЕХ МИЛИ (v221, см. USE_MELEE_PACK): цель пачки, если она среди допустимых этому мили,
                // иначе прежний ближайший — пачка ничего не запрещает, она только выбирает
                c.minByOrNull { getRange(creep, it) } } else null
            if (engage != null) Memory.engagingIds.add(creep.id) else Memory.engagingIds.remove(creep.id)
            // пара к общей цели мили (v221, см. mpackHit): как часто ноги мили и так идут к цели фокуса
            if (meleeOnly && engage != null) { mpackAll++; if (engage.id == focusTarget?.id) mpackHit++ }
            // поводок (см. LEASH_RANGE): при враге рядом дальше поводка от центра армии — к центру.
            // ПОВОДОК НЕ ТЯНУЛ ИМЕННО ТОГО, КТО УБЕЖАЛ (v191, USE_LEASH_IN_CONTACT): условие требовало врага РЯДОМ С
            // КРИПОМ, а у крипа, отставшего от боя, врагов рядом уже нет — и он оставался стоять там, где остановился.
            // Замер по реплеям против Coldkimchi#2: в матче со стиранием (3d97c4) диаметр группы наших стрелков в
            // контакте 21 клетка против восьми у него, и 3,7 крипа из 9,8 стояли дальше пяти от центра собственной
            // армии; в матче, который стиранием не кончился (3d97d8), диаметр 3 и дальше пяти — никого. Пятеро
            // стрелков, растянутые на двадцать клеток, не могут бить одну цель: conc даёт 1,3 из 5, а трое его
            // лекарей возвращают 216 хитов в тик — цель начинает терять хиты только под залпом ЧЕТЫРЁХ разом.
            // Поэтому поводок теперь действует, пока в контакте АРМИЯ, а не пока враг стоит рядом с самим крипом
            // ...И ПОВОДОК ДЕРЖИТ ЛЕКАРЕЙ (v202, оператор: «крипы разъезжаются в разные стороны и не держатся единым
            // кулаком»). Поводок исключал ВСЮ поддержку, то есть и лекарей, — и замер реплея 3d9a7c показывает, что
            // разъезжаются именно они: дальше восьми от центра армии наши мили 11 крипо-тиков из 3 428 (0,3 %),
            // стрелки 136 из 5 756 (2,4 %), а ЛЕКАРИ 1 402 из 5 379 — 26 %, с медианой отрыва 23 клетки. Это не
            // «идёт за подопечным»: подопечный по определению в строю, а двадцать три клетки — это уход с поля боя
            // ...И ЛЕКАРЯ ПОВОДОК ДЕРЖИТ ТАКЖЕ В ОТХОДЕ (v217). Оговорка про постуру снимается ТОЛЬКО для
            // лекаря: боец, отходящий сам, — это кайт, у него своя механика; а лекарь, отпущенный поводком,
            // просто перестаёт быть лекарем. Живой замер v216 по двадцати рейтинговым матчам: боевых крип-тиков,
            // где своего лекаря нет и в MASS_RANGE, — **32,1 % в поражениях против 2,5 % в победах**, а доля
            // тиков в постуре отхода — 63 % против 0 %. Замер v202, записанный рядом, называет и виновника:
            // разъезжаются именно лекари (26 % их крипо-тиков дальше восьми клеток, медиана отрыва 23 клетки).
            // ⚠️ Это НЕ повторение v202 целиком (0:3): там поводок включался ВЕЗДЕ и для всех, здесь снимается
            // ровно одна оговорка и ровно для лекаря
            val leashHolds = (healer) || (posture != Posture.RETREAT && posture != Posture.EVADE)
            val leashed = !wounded && canMove(creep) && leashHolds &&
                (localEnemies.isNotEmpty() || (contact)) && getRange(creep, armedCentroid) > LEASH_RANGE
            // СТРЕЛОК НЕ ВСТАЁТ НА ДВЕ, ПОКА У ВРАГА ЖИВ МИЛИ (v220, решение оператора: «мы принимаем бой,
            // когда у нас впереди рэнжи, в которых его мили сразу врезаются на первом тике»).
            // `CLOSE_STANDOFF` = 2 — это ровно та клетка, с которой ЕГО мили делает ОДИН шаг и бьёт на 240;
            // с трёх ему нужно два шага, а наш выстрел достаёт и оттуда (RANGED_RANGE = 3). То есть сближение
            // до двух не покупает нам ни одного очка урона и дарит ему темп.
            // Замер серии v219 по реплеям (двадцать матчей, только контактные тики): доля крипо-тиков, которые
            // наши стрелки проводят в досягаемости его мили (d <= 2), против его стрелков под нашими мили —
            // в победах 11 % против 20 % (под давлением ОН), в поражениях 13 % против 10 % (под давлением МЫ).
            // В двух разгромах от MetalicaX#13 это 57 % против 12 % и 45 % против 14 % — вчетверо, и оба раза
            // армия сложилась с 12 до 0 за шестьдесят тиков при его нулевых потерях.
            // Тот же случай уже записан в файле с другой стороны (v43, «прилипший»): «его мили подходили к нашим
            // стрелкам и лекарям, били по 240 и отходили — 46 ударов (11 тыс. урона) против наших 7».
            // Оговорка снимается, когда бить некому: если у врага не осталось живого вооружённого мили,
            // сближение до двух снова бесплатно и напор сохраняется
            // ...и ТОЛЬКО ПРОТИВ БЛОБА (v220, замер гейта). Первая редакция спрашивала про любого живого мили
            // рядом и уронила `match28:scatter`: 24 310:13 503 -> 21 781:24 307, единственный FAIL. Причина
            // прямая — против РАССЫПАННОГО соперника «держать три» значит не догнать никого, а догонять там и
            // надо. Разгромы же, ради которых правка делается, все три были против БЛОБА (форма BLOB в разборе
            // реплеев: #4, #15, #19), и против блобов серия v219 дала 1-4. Признак блоба в файле уже есть —
            // `enemyMassedNow` (не меньше шести его вооружённых, две трети из них в MASS_RANGE от их центроида),
            // новых сущностей не заводится
            val foeMeleeLive = enemyMassedNow && localEnemies.any { hasMelee(it) && InfluenceMap.profileOf(it).melee > 0.0 }
            val closeIn = if (localAggressive) CLOSE_STANDOFF else RANGED_RANGE
            if (hasRanged(creep) && localAggressive) { closeTicks++; if (foeMeleeLive) closeHeld++ }
            val melee = isMelee(creep) && !hasRanged(creep)
            val meleeMate: Creep? = if (melee) combatArmy.filter { it.id != creep.id && isMelee(it) && !hasRanged(it) && hasMelee(it) && canMove(it) }.minByOrNull { getRange(creep, it) } else null
            // мили со слотом стены (см. planBlock) оставляет его ради цели: прижим или враг в досягаемости удара
            val slot = if (melee && engage != null) null else slot0
            val grab = grabberOf[creep.id]?.let { id -> ctx.flags.firstOrNull { it.id == id } }
            // лекарь держится вплотную к самому раненому бойцу РЯДОМ (в дальности лечения плюс шаг), иначе идёт к
            // ближайшему ходячему бойцу — не к самому раненому через полкарты: два лекаря шли к обездвиженному
            // остову за стеной, а строй ждал их у флага (стенд greedy)
            val healMate = if (healer) {
                // хранитель флага — не подопечный, пока есть ходячие бойцы (v120, USE_HEALERS_NOT_WITH_KEEPERS): лекарь рядом с
                // хранителем видел в нём единственного «своего в четырёх», и трое лекарей стояли по одному у хранителей на D5 и
                // R3, а ударная шестёрка у A3 шла без лечения (spread m30 на v120i, 20291:24327); раненый хранитель снимается с
                // флага (см. updateKeepers) и становится подопечным как все
                val keptOut =  army.any { hasWeapon(it) && canMove(it) && it.id !in Memory.keeperIds }
                val fighters = army.filter { it.id != creep.id && hasWeapon(it) && !(keptOut && it.id in Memory.keeperIds) }
                // подопечные — вооружённые; вне боя рядом — и раненые (они сами идут к лекарю, см. wounded)
                val patients = army.filter { it.id != creep.id && !(hasHeal(it) && !hasWeapon(it)) && !(keptOut && it.id in Memory.keeperIds) }
                val engagedNear = fighters.any { f -> getRange(creep, f) <= HEAL_RANGE + 1 && combatEnemies.any { getRange(f, it) <= RANGED_RANGE + 1 } }
                val near = (if (engagedNear) fighters else patients).filter { getRange(creep, it) <= HEAL_RANGE + 1 }
                // подопечный под огнём (v109b, USE_WARD_UNDER_FIRE) ОТВЕРГНУТ таблицей входов стенда: лекари шли к терявшему хиты
                // ВПЕРЁД, в досягаемость его стрелков — за первые 20 тиков контакта потери выше v108 в 13 сценариях из 26 (nine,
                // hunter, fourteen, screen+focus: скрипты «лекари первыми»), ниже в 5; m28 nine 1714 → 3010, m34 nine 3504 → 4400.
                // Остаётся выбор ЦЕЛИ лечения под огнём (см. rank в healAndShoot); подопечный — самый раненый вооружённый, как прежде
                // ...а при УДЕРЖИМОЙ жертве (v228, см. USE_HEAL_WALL) подопечный — она: лечение вплотную 72 против 24 издали,
                // и именно её он бьёт сейчас, а самый раненый в дальности — уже отведённый в тыл
                (if (victimSaveable) victimNow?.takeIf { v -> v.id != creep.id && getRange(creep, v) <= HEAL_RANGE + 1 } else null)
                    ?: (null)
                    ?: near.maxByOrNull { it.hitsMax - it.hits }
                    ?: fighters.filter { canMove(it) }.minByOrNull { getRange(creep, it) }
                    ?: fighters.minByOrNull { getRange(creep, it) }
                    ?: patients.minByOrNull { getRange(creep, it) }
            } else null
            // КАЙТ ПРОТИВ СОМКНУТОГО БЛОБА (v135, см. USE_MASS_KITE): его мили достаёт на клетку, стрелок — на три, значит
            // в ДВУХ его четыре мили (960 в тик вплотную) не дают ничего, а размен стрелками идёт ровно. Держим два от
            // ближайшего его мили, пока его армия сомкнута и мы сами ещё не в контакте
            // ...и ТОТ, КТО ОТВЕТИТЬ НЕ МОЖЕТ, уходит и из контакта (v135, см. USE_KITE_HELPLESS_OUT): стрелок вплотную
            // стреляет, мили бьёт, а лекарь и раздетый под ударом — только мясо: они дают 0 урона и держат его мили
            // занятым бесплатной целью. Лечение достаёт на три, так что отойдя, лекарь лечит треть, но живёт
            // ...и пока НАШИ СТВОЛЫ НЕ ПОДТЯНУЛИСЬ (v135, см. USE_KITE_UNTIL_READY): на входе телеметрия читает reach=2/5 —
            // в дальности два наших стрелка из пяти, а он бьёт всеми двенадцатью; к 50-му тику подтягиваются все, но бой
            // уже проигран. Пока достающих меньше двух третей живых, держим дистанцию, даже если его армия не сомкнута
            val massKite: Creep? = if ((!support) && (enemyMassedNow) &&
                    (combatEnemies.none { getRange(creep, it) <= 1 }  )) {

                     // ...или стрелок выходит из-под удара, НЕ ЗАМОЛКАЯ (v135, см. USE_KITE_KEEPS_FIRE): прежний срез
                     // (USE_KITE_BREAKS_CONTACT) отвергнут за 0-6/0-6, потому что уходящий стрелок терял цель — его
                     // дальность три. Здесь шаг назад разрешён, только когда в дальности стоят двое и больше его
                (combatEnemies.filter { InfluenceMap.profileOf(it).melee > 0.0 && getRange(creep, it) <= ENGAGE_RANGE })
                    .minByOrNull { getRange(creep, it) }
            } else null
            val healerNear: Creep? = if (wounded || rotating) {
                val hs = army.filter { it.id != creep.id && !hasWeapon(it) && hasHeal(it) }
                val mine = combatEnemies.minOfOrNull { getRange(creep, it) } ?: 99
                (null)
                    ?: hs.minByOrNull { getRange(creep, it) }
            } else null
            // под огнём без двух бойцов вплотную — назад к строю, не вперёд: шип в строй врага бьют трое-четверо, а он один
            // вплотную, не «в двух клетках»: со счётом союзников в двух клетках мили под огнём не отходили и ныряли в блоб
            // врага по одному — три мили за восемь тиков при одном убитом (стенд m5 army, v22, t=300–308)
            val aloneInFire =  !support && !wounded && posture == Posture.ANNIHILATE && !pushing && InfluenceMap.damageAt(creep.x, creep.y, combatEnemies) > 0.0 &&
                combatArmy.count { it.id != creep.id && hasWeapon(it) && getRange(creep, it) <= 1 } < 2 && pressTarget == null 
            // вес огня лекаря: подопечный в бою — только разница между клетками (HEALER_W_DAMAGE_FIGHT); место за
            // подопечным и шаг от мили задают HEALER_W_FRONT и HEALER_W_MELEE, а вес 0.05 в бою держал лекаря на кромке
            // огня в 2–3 клетках (лечение 24 вместо 72) и проиграл рубки sleeper на картах 4 и 8
            val healerFireW = if (healer && healMate != null && combatEnemies.any { getRange(healMate, it) <= RANGED_RANGE + 1 }) HEALER_W_DAMAGE_FIGHT else HEALER_W_DAMAGE
            // сбор: по полю марша (флаг-цель или пост, в обход врагов) авангард — самый продвинутый из ходячих
            // вооружённых (при равном поле — меньший id); кто дальше RALLY_RANGE от авангарда, идёт к нему
            // только на марше к флагу-цели: в HOLD цель — точка, к ней сходятся и так, а в ANNIHILATE ожидание
            // «далёкого» напарника, занятого своим боем, останавливало армию (стенд greedy)
            // ходячий по canMove, не «полноскоростной»: покалеченный участник, не входящий в сбор, но ждущий
            // далёких, замыкал группу в тупик (стенд rush: 10 против 2 до конца матча)
            val groupedPre =  !support && canMove(creep) && posture == Posture.FLAG
            val marchTarget: Position? = objective?.flag?.pos
            var rallyTo: Position? = null
            if (groupedPre && marchTarget != null) {
                val mf = flowAvoiding(ctx, marchTarget, creep)
                val my = mf[creep.x * 100 + creep.y]
                var van: Creep? = null
                var vanFlow = my
                var vanId = creep.id
                // авангард — из массы (v120, USE_RALLY_VAN_FROM_MASS): оторвавшийся крип не точка сбора, как и в построении
                val rallyPool = mobileArmy.filter { hasWeapon(it) && getRange(it, armedCentroid) <= MASS_RANGE }.ifEmpty { mobileArmy }
                for (m in rallyPool) {
                    if (m.id == creep.id || !hasWeapon(m)) continue
                    val d = mf[m.x * 100 + m.y]
                    if (d < 0) continue
                    if (vanFlow < 0 || d < vanFlow || (d == vanFlow && m.id < vanId)) { vanFlow = d; vanId = m.id; van = m }
                }
                // с гистерезисом: с клетки «13 от авангарда» крип шёл к нему, со следующей («12») — снова к цели,
                // и два шага туда-обратно длились до конца матча, а авангард ждал (стенд rush)
                val rallyRange = if (creep.id in Memory.rallyingIds) RALLY_RANGE / 2 else RALLY_RANGE
                if (van != null && getRange(creep, van) > rallyRange) { rallyTo = InfluenceMap.cell(van.x, van.y); Memory.rallyingIds.add(creep.id) }
                else Memory.rallyingIds.remove(creep.id)
            } else Memory.rallyingIds.remove(creep.id)
            // построение: вне огня и без готовности авангард и собравшиеся у него стоят, остальные идут к нему
            // в контакте построение окончено: авангард — тот, кто уже дерётся, и «собраться у авангарда с дистанцией 1»
            // тянуло стрелков за ним внутрь строя врага, а стреляли они с 4–5 клеток впустую (матч 15, t=68–100)
            val forming = formVan != null && !formationReady && !support && canMove(creep) && posture != Posture.RETREAT && posture != Posture.EVADE &&
                localEnemies.any { threatening(it, enemyCreeps) } && nearestEnemyRange > RANGED_RANGE && !contact &&
                !(stalled)
            val formHold = forming && (formVan!!.id == creep.id || getRange(creep, formVan) <= FORM_RANGE)
            val formGo = forming && !formHold
            val target: Position
            val standoff: Int
            var avoid = false
            var nearFlow = false   // цель-крип рядом: поле «вблизи» (см. NEAR_FLOW)
            // в строю (см. USE_BLOCK): мили вплотную к врагу стоит и рубит, остальные — в свой слот
            val slotHold = slot != null && melee && localEnemies.any { getRange(creep, it) <= 1 }
            // ПЕРЕПИСЬ РЕШЕНИЙ (v203, этап 1): каждая ветка обеих цепочек называет себя, и счётчик копится за матч.
            // Повод — пять правил за сутки, которые прошли гейт и не исполнились ни разу: по коду нельзя было
            // сказать, какая ветка живая. Перепись отвечает на это числом, а не чтением. Она же заменяет ручной
            // дубль цепочки в TRACE_WHY, который успел рассинхронизироваться и рассказывал о боте неправду
            var whyTag = "?"
            when {
                keeper -> { whyTag = "keeper"; target = InfluenceMap.cell(creep.x, creep.y); standoff = 0 }
                slotHold -> { whyTag = "slotHold"; target = InfluenceMap.cell(creep.x, creep.y); standoff = 0 }
                // приказ командира раньше всего боевого: он уже учёл, кто где встанет и что будет опасно (v137)
                commandOf[creep.id] != null && (commandOf[creep.id]!!.x != creep.x || commandOf[creep.id]!!.y != creep.y) ->
                    { whyTag = "order"; target = commandOf[creep.id]!!; standoff = 0 }
                // ПОГОНЯ ЗА ОСТОВОМ (v212) — сразу под приказом командира: пока он правит, клетку даёт он (и тоже
                // знает про погоню, см. chaseTarget в placeScored); когда молчит, преследователь идёт сюда. Ниже
                // кайта и строя стоять нельзя: обе ветки увели бы его обратно в кулак, а весь смысл отряда в том,
                // чтобы из кулака выйти
                Memory.chaseTarget[creep.id]?.let { it.hits > 0 } == true -> {
                    whyTag = "chase"
                    target = InfluenceMap.cell(Memory.chaseTarget[creep.id]!!.x, Memory.chaseTarget[creep.id]!!.y)
                    standoff = if (hasRanged(creep)) RANGED_RANGE - 1 else 0
                    avoid = true
                }
                // кайт раньше слота: слот ставит нас в строй, а строй сходится с блобом вплотную (v135)
                // дистанция кайта зависит от того, выгоден ли ему ВЕЕР: масс-атака бьёт в радиусе трёх (10/4/1 за часть),
                // поэтому в куче держим три — там веер стоит ему шестёрки урона вместо шестидесяти, — а поодиночке два,
                // где наш собственный огонь плотнее. MetalicaX#11 даёт 63 веера за матч против 37 у #10 и наших 12 (v135)
                massKite != null -> {
                    whyTag = "kite"; kiteNow++
                    // пока стволы не подтянулись — держим на клетку дальше и в бой не входим (v135, USE_KITE_UNTIL_READY)
                    target = massKite
                    standoff = KITE_STANDOFF
                    avoid = true; nearFlow = true
                }
                // ЛЕКАРЬ ВЫШЕ СТРОЯ В БОЮ (v147): замер по записи (6aa078c0, обе стороны по три лекаря) — у него в
                // дальности лечения стоят ВСЕ ТРИ каждый тик, у нас 1,8 из трёх, и лечение выходит 1584 против 9624.
                // Причина в порядке цепочки: слот стоял выше подопечного, а расстановка не знает, кого лечить, и уводила
                // лекаря в строй за пределы дальности. Лекарь вне HEAL_RANGE не лечит вовсе — в бою подопечный главнее
                // СТЕНА ЛЕЧЕНИЯ (v228, см. USE_HEAL_WALL): назначенная клетка стены — как слот, вплотную к удержимой жертве
                 healer && victimSaveable && wallCellOf[creep.id] != null ->
                    { whyTag = "wall"; target = wallCellOf[creep.id]!!; standoff = 0 }
                // ЛЕКАРЬ ПРИ МИЛИ (v235, см. USE_HEALER_AT_MELEE): клетка при своём фронтовом мили с тыла — как слот
                 healer && healMate != null && contact ->
                    { whyTag = "healMate"; target = healMate; standoff = 1; nearFlow = true }
                slot != null -> { whyTag = "slot"; target = slot; standoff = 0 }
                // лекарь и в отходе идёт за подопечным (лечение — в тот же тик, что и шаг, 216 в тик восстанавливают
                // обломок за шесть тиков): прежде лекари шли к точке отхода сами, а раненые — врассыпную
                healer && healMate != null -> { whyTag = "healMateOut"; target = healMate; standoff = 1; nearFlow = true }
                // отход — по обычному полю: поле «в обход» стоящих врагов (а дерущиеся стоят) увело пару в обход
                // стенного блока на другой край карты (матч 4)
                posture == Posture.EVADE && evadeTo != null -> { whyTag = "evade"; target = evadeTo; standoff = 1 }
                posture == Posture.RETREAT && retreatTo != null -> { whyTag = "retreat"; target = retreatTo; standoff = 1 }
                formGo -> { whyTag = "formGo"; target = InfluenceMap.cell(formVan!!.x, formVan.y); standoff = 1 }
                wounded && healerNear != null -> { whyTag = "wounded"; target = healerNear; standoff = 1; avoid = true; nearFlow = true }
                rotating && healerNear != null -> { whyTag = "rotate"; target = healerNear; standoff = 1; avoid = true; nearFlow = true }
                // сбор пачки (см. USE_REGROUP, REGROUP_TICKS): одинокий мили под смертельным огнём — к ближайшему мили-напарнику
                 aloneInFire && melee && meleeMate != null && InfluenceMap.damageAt(creep.x, creep.y, combatEnemies) * REGROUP_TICKS >= creep.hits -> { whyTag = "regroup"; target = meleeMate; standoff = 1; avoid = true; nearFlow = true }
                aloneInFire -> { whyTag = "alone"; target = armedCentroid; standoff = CLOSE_STANDOFF; avoid = true; nearFlow = true }
                leashed -> { whyTag = "leash"; target = armedCentroid; standoff = CLOSE_STANDOFF; avoid = true; nearFlow = true }
                engage != null -> { whyTag = "engage"; target = engage; standoff = if (melee) 1 else closeIn; nearFlow = true }
                // мили держит линию (см. MELEE_HOLD_RANGE): что подошло на две клетки — рубит, за экраном не гонится
                holdMelee -> { whyTag = "holdMelee"; target = InfluenceMap.cell(creep.x, creep.y); standoff = 0 }
                grab != null -> { whyTag = "grab"; target = grab.pos; standoff = 0; avoid = true }
                // добивание без местного перевеса — отход к массе армии, а не бросок на «ближайшую добычу»; без
                // ловимой добычи (кайтеры) — тоже к массе: стоим строем и стреляем в то, что подойдёт
                posture == Posture.ANNIHILATE && !support && (!localAggressive || prey == null) -> { whyTag = "toCentroid"; target = armedCentroid; standoff = CLOSE_STANDOFF; avoid = true }
                prey != null -> { whyTag = "prey"; target = prey; standoff = if (melee) 1 else closeIn; nearFlow = true }
                rallyTo != null -> { whyTag = "rally"; target = rallyTo; standoff = CLOSE_STANDOFF; avoid = true }
                objective != null -> {
                    whyTag = "objective"
                    val capturer = objectiveCapturer == creep.id
                    target = objective.flag.pos
                    standoff = if (capturer) 0 else CLOSE_STANDOFF
                    avoid = true
                }
                threat != null && huntingThreat && mobile -> { whyTag = "threat"; target = threat; standoff = if (melee) 1 else closeIn }
                raider != null && mobile && !support -> { whyTag = "raider"; target = raider; standoff = if (melee) 1 else RANGED_RANGE }
                // ОТВЕРГНУТО стендом (v42): «держать линию там, где она стоит» (holdLine → armedCentroid вместо поста) — в матче 70
                // пост при враге рядом был точкой в 35 клетках позади, и каждый тик ДЕРЖАТЬ между тиками ДОБИТЬ разворачивал
                // армию к нему. Но возврат к посту делает работу в десятках сценариев (после отбитого рывка остаток добивается у
                // поста): 58 строк хуже / 48 лучше, гейтовая m33 farm+weak и m29 farm красные. Мигание лечится у корня — см.
                // chaseVeto и evasive
                else -> { whyTag = "post"; target = post; standoff = POST_STANDOFF; avoid = true }
            }
            val flow0 = if (slot != null || keeper) NO_FLOW else if (avoid) flowAvoiding(ctx, target, creep, nearFlow) else flowTo(ctx, target, near = nearFlow)
            // за пределом поля «вблизи» — полное поле
            val flow = if (nearFlow && slot == null && !keeper && flow0[creep.x * 100 + creep.y] < 0)
                (if (avoid) flowAvoiding(ctx, target, creep) else flowTo(ctx, target)) else flow0

            val nearbyEnemies = combatEnemies.filter { getRange(creep, it) <= 12 }
            // «в бою», плотность и передний ряд — по врагам С БОЕМ: три безоружных лекаря врага в 4–5 клетках после выигранного
            // боя держали армию в зоне плотности и не давали толкнуть своего — мили, зажатый своими лекарями, и армия
            // простояли тысячу тиков в 20 клетках от флага (стенд m16 nine)
            val inCombat = armedEnemies.any { creep.getRangeTo(it) <= RANGED_RANGE + 2 }
            val localThreats = localEnemies.filter { threatening(it, enemyCreeps) }
            val underFire = InfluenceMap.damageAt(creep.x, creep.y, combatEnemies) > 0.0 || ghost > 0
            // бегство: смертельный урон за два тика; безоружный лекарь — от врага рядом, если рядом нет ни одного
            // вооружённого своего (при нём лекарь стоит и лечит: бегущий лекарь — потерянные 72 в тик, матч 3);
            // невидимый урон
            // вооружённый бежит, только когда его ДОБИВАЮТ: за прошлый тик снято не меньше половины оставшихся хитов и
            // осталось меньше трети. Прежнее «весь возможный огонь по клетке за два тика больше хитов» в бою 12 на 12
            // верно для КАЖДОЙ клетки у вражеского блоба (1260 против 1600), и трое мили с полными хитами
            // разворачивались спиной в первый тик контакта — их резали в спину, строй рассыпался (стенд sleeper,
            // t=550; матчи 4–6 в первом размене теряли 1:5 при равной силе)
            val lostLastTick = Memory.lastHits[creep.id]?.let { it - creep.hits } ?: 0
            // лекарь и раненый бегут (врассыпную) только в одиночестве: при своём рядом — отход группой по постуре
            // раненый (без оружия и лечения) и в контакте уходит из ПОЛНОЙ досягаемости — стрелка в трёх, мили в двух (v123,
            // USE_STRIPPED_LEAVES_REACH): сужение до мили в контакте — для лекаря, которому лечить фронт; обезоруженному в
            // огне делать нечего, а живым он вернётся с лечением. Серия 307–326: наши обезоруженные стояли в трёх от его
            // вооружённых половину своего времени (131 из 258, 264 из 552 крип-тиков), его — десятую (26 из 79, 7 из 11);
            // правило «обезоруженные в досягаемости» — 3 из 6 поражений и 0 из 18 побед
            val reachMine = reachNow
            val inReach = (creep.x * 100 + creep.y) in reachMine
            // ...и для лекаря закрытые для шага клетки — полная досягаемость (v234, вторая редакция), бегство — по прежней
            val avoidCells = reachMine
            // прибор v234: лекарь в бою и в досягаемости его вооружённых; урон по лекарям
            if (healer && inCombat) { hexpAll++; if ((creep.x * 100 + creep.y) in reachCells) hexpN++; hlostSum += (lostTick[creep.id] ?: 0) }
            val mustFlee = (support && nearbyEnemies.any { getRange(creep, it) <= RANGED_RANGE + 1 } && army.none { it.id != creep.id && getRange(creep, it) <= HEAL_RANGE }) ||
                (support && inReach) ||
                (lostLastTick * 2 >= creep.hits && creep.hits * 3 < creep.hitsMax) ||
                (ghost > 0 && creep.hits <= ghost)

            // сплочение: авангард ждёт отставших группы (в тиках ИХ хода), пока сам не под огнём и напарник
            // не в бою; при враге в досягаемости зазор тесный — собираемся ДО входа под огонь
            val myFlow = flow[creep.x * 100 + creep.y]
            val grouped = !support && (posture == Posture.ANNIHILATE || posture == Posture.FLAG || (huntingThreat && threat != null && target === threat))
            // напарники строя — ходячие ВООРУЖЁННЫЕ: у лекаря своя цель (подопечный), и взаимное ожидание «лекарь
            // отстал от флага — боец отстал от подопечного лекаря» запирало группу навсегда (стенд greedy)
            val mates = if (grouped) mobileArmy.filter { it.id != creep.id && hasWeapon(it) } else emptyList()
            val mateFighting = mates.any { m -> combatEnemies.any { m.getRangeTo(it) <= RANGED_RANGE + 2 } }
            val gap = if (localEnemies.isEmpty()) COHESION_GAP else ENGAGE_COHESION_TICKS
            // идущий к авангарду (rallyTo) не ждёт никого: четверо шли к авангарду и «ждали» одиночку в 14 клетках,
            // а тот ждал их — взаимное ожидание на 1600 тиков (стенд m2 scouts, v4)
            // подбирающий флаг рядом (grab) не ждёт никого, и его никто не ждёт: он ждал по сплочению группу у своего
            // флага, а группа ждала его как «отставшего» на пути к цели — взаимное ожидание на 1200 тиков при живом
            // враге из двух скаутов на наших флагах (стенд m3 kite, проигрыш по очкам 9128:23661)
            val cohesionHold = grouped && rallyTo == null && grab == null && engage == null && !underFire && !mateFighting && myFlow >= 0 && creep.getRangeTo(target) > standoff + ARRIVED_SLACK && run {
                var lagging = false
                for (m in mates) {
                    if (getRange(creep, m) <= RANGED_RANGE) continue
                    if (grabberOf.containsKey(m.id) || m.id in Memory.engagingIds) continue
                    val d = flow[m.x * 100 + m.y]
                    if (d < 0) continue
                    // напарник на другом обходе (только на марше к флагу): далеко и не впереди — ждём его, он идёт
                    // к нам (см. rallyTo)
                    if (posture == Posture.FLAG && getRange(creep, m) > RALLY_RANGE && plainPeriod(m) <= RALLY_MAX_PERIOD && (d > myFlow || (d == myFlow && m.id > creep.id))) { lagging = true; break }
                    val lag = (d - myFlow) * plainPeriod(m)
                    if (lag in (gap + 1)..COHESION_GAP_MAX) { lagging = true; break }
                }
                lagging
            }
            // отход строем (см. RETREAT_GAP): передняя половина ждёт отставшего от тела армии, пока сама вне огня
            val retreatHold = (posture == Posture.RETREAT || posture == Posture.EVADE) && !support && canMove(creep) && !underFire && nearestEnemyRange > RANGED_RANGE + 1 && myFlow >= 0 && run {
                val flows = mobileArmy.filter { hasWeapon(it) }.map { flow[it.x * 100 + it.y] }.filter { it >= 0 }.sorted()
                if (flows.isEmpty()) return@run false
                val rear = flows.last()
                val median = flows[flows.size / 2]
                rear - median > RETREAT_GAP && myFlow <= median
            }
            // терпение (см. COHESION_PATIENCE): затянувшееся ожидание снимается до конца отставания
            if (cohesionHold) {
                val since = Memory.holdSince.getOrPut(creep.id) { getTicks() }
                if (getTicks() - since >= COHESION_PATIENCE) Memory.impatientIds.add(creep.id)
            } else { Memory.holdSince.remove(creep.id); Memory.impatientIds.remove(creep.id) }
            val hold = (cohesionHold && creep.id !in Memory.impatientIds) || formHold || retreatHold

            var stepTag = "?"
            val step: Position? = when {
                !canMove(creep) -> { stepTag = "immobile"; null }
                // ВЫЖИВАНИЕ ВЫШЕ ЗАДАНИЯ (v240, этап 5 переработки, решение оператора 13.09.2026): крип под смертельным
                // огнём бежит, даже если у него приказ командира или пост хранителя. До v240 приказ стоял выше бегства
                // (v172 «приказ — закон»), и комментарий у бегства утверждал обратное. Цена конфликта — прибор:
                // `fled=` (приказов, перебитых бегством) и `step=flee` в гистограмме шагов
                mustFlee -> {
                    stepTag = "flee"
                    if (commandOf.containsKey(creep.id)) orderFled++
                    fleeStep(creep, nearbyEnemies, ctx.dangerMatrix, if (support) RANGED_RANGE + 1 else RANGED_RANGE) ?: pathStep(creep, retreatTo ?: post, 1, ctx.dangerMatrix)
                }
                // ХРАНИТЕЛЬ ТОЖЕ СЛУШАЕТ ПРИКАЗ (v173, оператор): «уйти с флага крип должен только если командир решит
                // собрать отряд, или если крип может попасть в опасность». Прежде хранитель стоял всегда и приказа не
                // видел вовсе — он был вне командира по построению (mobileArmy исключает keeperIds)
                 keeper && commandOf.containsKey(creep.id) -> commandOf[creep.id]!!
                    .takeIf { it.x != creep.x || it.y != creep.y }.also { stepTag = "keeperOrder" }
                keeper -> { stepTag = "keeperStay"; null }
                // ПРИКАЗ — ЗАКОН (v172, оператор): «все крипы должны двигаться ТОЛЬКО по приказу командира… нельзя не
                // слушаться приказов командира». Приказ исполняется БУКВАЛЬНО: назначенная клетка и есть шаг. Прежняя
                // попытка сделать так провалилась (гейт 133, исполнение 3 %) потому, что командир раздавал клетки, не
                // считая того, что считает крип, — теперь считает (см. rankStep в commandFight), и цена ошибки лежит
                // на нём, а не на непослушании
                // ...и во ВСЕХ режимах, а не только в бою (v172, оператор): «все крипы должны двигаться ТОЛЬКО по
                // приказу командира». В гонке и походе приказ тоже закон — там он ведёт ядро строем и за флагами
                 commandOf.containsKey(creep.id) -> {
                    orderBranch++          // сколько приказов реально дошло до ветки исполнения (v173)
                    stepTag = "order"
                    val cell = commandOf[creep.id]!!
                    if (cell.x == creep.x && cell.y == creep.y) null
                    else cell
                }
                slot != null -> { stepTag = if (slotHold) "slotHold" else "slotStep"; if (slotHold) null else slotStep(creep, slot, blockedSet, enemyPositions, occupantAt, combatEnemies, if (support && !inReach) reachMine else emptySet()) }
                // ПРИКАЗ ВЫШЕ СЛОТА И ОСТАНОВКИ (v171): в выборе ШАГА приказ не участвовал вовсе — слот уводил крипа в
                // строй, а hold оставлял на месте, и приказ работал только в последней ветке. Разбор потерь показал
                // цену: из 143 приказов 50 кончались уходом в другую клетку и 36 — тем, что крип не двинулся
                // ...и только В БОЮ: в гонке очков приказ марша перебивал удержание, и camp падал 4 155:16 209
                hold -> { stepTag = "hold"; null }
                else -> {
                    stepTag = "free"
                    // клетка флага открыта только назначенному на него (захватчик цели, «подобрать» рядом)
                    val designated = grab?.pos ?: objective?.flag?.pos?.takeIf { objectiveCapturer == creep.id }
                    var myBlocked = if (designated != null) blockedSet - (designated.x * 100 + designated.y) else blockedSet
                    // плотность (см. COMPACT_RANGE): при враге в досягаемости — только на клетки строя
                    // лекарь и раненый — вне правила (их цель — свой в строю); снаружи зоны шаг К центру всегда открыт:
                    // прежде крип вне зоны не мог шагнуть никуда (все соседи тоже вне), и три лекаря простояли весь бой
                    // матча 8 в 4–5 клетках от строя
                    if (!wounded && localThreats.isNotEmpty() && posture != Posture.RETREAT && posture != Posture.EVADE && canMove(creep)) {
                        val armedMates = mobileArmy.filter { it.id != creep.id && hasWeapon(it) }
                        val myRange = getRange(creep, armedCentroid)
                        val loose = HashSet<Int>()
                        for ((dx, dy) in DIRECTIONS) {
                            val x = creep.x + dx; val y = creep.y + dy
                            if (x < 0 || y < 0 || x > 99 || y > 99) continue
                            val c = InfluenceMap.cell(x, y)
                            val r = getRange(c, armedCentroid)
                            // шаг ВПЕРЁД (по потоку к цели) открыт на клетку в COMPACT_RANGE + 1: иначе авангард не мог
                            // выйти из зоны, а центр не сдвигался, пока никто не выходил, — блоб 1200 тиков стоял в
                            // четырёх клетках от последнего лекаря врага и проиграл по очкам (стенд m5 kite); линия
                            // ползёт гусеницей — впереди не дальше трёх от центра, остальные подтягиваются
                            val fd = flow[x * 100 + y]
                            val advancing = myFlow >= 0 && fd in 0 until myFlow
                            val compact = r <= COMPACT_RANGE || (advancing && r <= COMPACT_RANGE + 1) || armedMates.count { getRange(c, it) <= 1 } >= 2 || (r < myRange)
                            if (!compact) loose.add(x * 100 + y)
                        }
                        if (loose.isNotEmpty()) myBlocked = myBlocked + loose
                    }
                    // передний ряд — вооружённым: лекарь и раненый не встают на клетку вплотную к боевому врагу (она
                    // нужна нашему мили; трое лекарей без штрафа за соседей заняли ряд перед своими мили у самого
                    // раненого бойца, и размен шёл без наших ударов — стенд m7 sleeper, 4 убитых врага против 5)
                    // уже вплотную к врагу — блок переднего ряда снят: окружённый лекарь стоял (все соседи «передний
                    // ряд»), а не уходил (матч 10, healer_2 на (14,10) между двумя мили врага)
                    // лекарь и раненый снаружи досягаемости в неё не входят (см. reachCells)
                    // лекарь с РАНЕНЫМ подопечным в дальности лечения принимает дальний огонь ради лечения вплотную (72 за часть
                    // против 24): запреты «не входить в досягаемость» и «не вставать рядом с врагом» держали его в двух-трёх
                    // клетках от того, кого бьют. Матч 34 (бой 57–550): урона получено поровну (42285 против 41684), вылечено
                    // 29275 против их 39420, у них вдвое больше событий «+144» (два лекаря вплотную на одном) — 46 против 22;
                    // наш лекарь стоял вплотную к самому раненому в 13% замеров и дальше трёх клеток — в 32%. Закрытыми
                    // остаются клетки вплотную к вражескому МИЛИ: там лекарь не лечит, а умирает
                    val healingNow = healer && healMate != null && healMate.hits < healMate.hitsMax && getRange(creep, healMate) <= HEAL_RANGE + 1
                    if (support && !inReach && avoidCells.isNotEmpty() && !(healingNow)) myBlocked = myBlocked + avoidCells
                    if (support && localThreats.isNotEmpty() && localThreats.none { getRange(creep, it) <= 1 }) {
                        val front = HashSet<Int>()
                        for ((dx, dy) in DIRECTIONS) {
                            if (dx == 0 && dy == 0) continue
                            val x = creep.x + dx; val y = creep.y + dy
                            if (x < 0 || y < 0 || x > 99 || y > 99) continue
                            val c = InfluenceMap.cell(x, y)
                            val byMelee = meleeEnemies.any { getRange(c, it) <= 1 }
                            val byPatient = healingNow && getRange(c, healMate!!) <= 1
                            if (localEnemies.any { getRange(c, it) <= 1 } && (byMelee || !byPatient)) front.add(x * 100 + y)
                        }
                        if (front.isNotEmpty()) myBlocked = myBlocked + front
                    }
                    // ПРИКАЗ ИСПОЛНЯЕТСЯ, А НЕ ПЕРЕСЧИТЫВАЕТСЯ (v167): назначенная клетка была лишь ОДНИМ слагаемым в
                    // оценке шага наравне с опасностью и соседями, и опасность её перевешивала — прибор показал, что
                    // крип доходит до своей клетки в 7 % случаев (10 из 144) и даже приближается лишь в 32 %. Прогноз
                    // при этом считает, что армия встанет по плану: он опирался на фикцию. Клетка в ОДНОМ шаге теперь
                    // запрашивается напрямую, как это делают захватчики
                    val ordered: Position? = null
                    orderPull = if (commandOf.containsKey(creep.id)) ORDER_PULL else 1.0
                    val chosen = ordered ?: bestSingleMove(creep, target, flow, standoff, localAggressive || spotNow, inCombat, enemyCreeps, allies, meleeEnemies, myBlocked, enemyPositions, occupantAt, healerFireW, focusTarget)
                    orderPull = 1.0
                    chosen
                }
            }
            // СЛЕПОТА К ОПАСНОСТИ НА ШАГЕ (v215, оператор: «линия фронта должна работать ВСЕГДА на
            // передвижение»). Пара: шагов в клетку, несущую урон, при ВЫКЛЮЧЕННОМ слагаемом опасности —
            // против всех шагов. Слагаемое выключено в двух местах: вне боя `scoreCell` возвращается до него
            // вовсе, а при агрессии оно обнуляется. Приказ командира слепым не считается: он один и считается
            // по полям (см. scoreMelee/scoreRanged/scoreHeal)
            if (step != null) {
                dangerMoves++
                if (stepTag != "order" && InfluenceMap.dangerAt(step.x * 100 + step.y) > 0.0) {
                    if (!inCombat) dangerBlindFar++ else if (localAggressive || spotNow) dangerBlind++
                }
            }
            if (TRACE_WHY && DEBUG_LOG && meleeOnly && hasMelee(creep) && engage == null && posture != Posture.RETREAT && posture != Posture.EVADE) {
                // только враг «с боем» (см. threatening): праздность при небоевых остатках после выигранного боя — не находка
                val near = combatEnemies.filter { getRange(creep, it) <= ENGAGE_RANGE && threatening(it, enemyCreeps) }.minByOrNull { getRange(creep, it) }
                if (near != null) {
                    val r = ArrayList<String>()
                    if (support) r.add("support")
                    if (rotating) r.add("rotating")
                    if (stalled) r.add("stalled")
                    if (!localAggressive) r.add("!aggr(${ourPowerOf(localAllies, localEnemies).toInt()}/${enemyPowerOf(localEnemies, localAllies).toInt()}x${ratio} cost=${fightCost(localEnemies, localAllies).let { if (it >= Double.MAX_VALUE / 2) "inf" else it.toInt().toString() }} slack=${localAllies.maxOfOrNull { speedSlack(it) } ?: 0} le=${localEnemies.size} la=${localAllies.size})")
                    if (!inLine) r.add("!inLine")
                    val d = getRange(creep, near)
                    if (holdMelee && d > holdReach(near)) r.add("hold:d$d>${holdReach(near)}")
                    if (!catchable(near, chasers)) r.add("!catchable")
                    if (givenUp(near)) r.add("giveup")
                    if (!covered(near)) r.add("!covered")
                    if (r.isEmpty()) r.add("?")
                    // ДУБЛЬ ЦЕПОЧКИ УДАЛЁН (v203): здесь стояла вторая, написанная руками копия цепочки целей — и она
                    // успела рассинхронизироваться (в ней не было guardMate, rallyBlob, shieldMate, приказа, поиска,
                    // кайта, ухода из кольца и кольца прижима). Прибор, повторяющий решение вручную, рассказывает о
                    // боте неправду ровно тогда, когда бот меняется; настоящая ветка называет себя сама
                    val did = whyTag
                    val short = { id: String -> id.replace(Regex("^pg_player\\d_"), "") }
                    whyLines.add("${short(creep.id)}@(${creep.x},${creep.y})d$d>${short(near.id)}[${r.joinToString(",")}]$did${if (hold) "+hold" else ""}/${step?.let { "(${it.x},${it.y})" } ?: "stay"}")
                    for (k in r) whySum[k] = (whySum[k] ?: 0) + 1
                    whySum["idle"] = (whySum["idle"] ?: 0) + 1
                }
            }
            if (DEBUG_LOG && getTicks() % LOG_EVERY == 0) {
                println("  f${creep.id} (${creep.x},${creep.y}) ${bodySummary(creep)} hits=${creep.hits}/${creep.hitsMax} tgt=(${target.x},${target.y}) so=$standoff flow=$myFlow flee=$mustFlee combat=$inCombat aggr=$localAggressive hold=$hold${if (formHold) "(form)" else if (retreatHold) "(rear)" else ""}${if (leashed) " leash" else ""}${if (wounded) " WOUNDED" else ""}${if (pressTarget != null || false) " PRESS" else ""} spd=${plainPeriod(creep)} fatigue=${creep.fatigue} step=${step?.let { "(${it.x},${it.y})" } ?: "stay"}${if (TrafficManager.isStuck(creep.id)) " STUCK" else ""}")
            }
            // СОГЛАСОВАНИЕ ДВИЖЕНИЙ — ЗА КОМАНДИРОМ (v170, оператор). Разрешение конфликтов уже устроено правильно:
            // поиск в глубину с цепочками и свопами, по ПРИОРИТЕТУ. Но приоритет задавали разрозненные места — раненый,
            // боец, захватчик, — и замысел в нём не участвовал. Теперь очередь назначает командир: крип, исполняющий
            // приказ, идёт первым, а среди приказов вперёд пропускается тот, чья клетка важнее для боя — мили,
            // выходящий в контакт, затем стрелок с целью, затем лекарь к подопечному, и лишь потом все прочие
            val prio = Arbiter.pushRank(ordered = commandOf.containsKey(creep.id), melee = hasWeapon(creep) && hasMelee(creep) && !hasRanged(creep),
                armed = hasWeapon(creep), healer = hasHeal(creep), wounded = wounded)
            rungCount[whyTag] = (rungCount[whyTag] ?: 0) + 1
            stepCount[stepTag] = (stepCount[stepTag] ?: 0) + 1
            if (step != null) { TrafficManager.request(creep, step, prio); planCapture(ctx, step) }
            Memory.lastHits[creep.id] = creep.hits
            Memory.lastCell[creep.id] = creep.x * 100 + creep.y
        }

        cpuMark("moves")
        if (TRACE_WHY && DEBUG_LOG && whyLines.isNotEmpty()) { println("why t=${getTicks()}: " + whyLines.joinToString(" ")); whyLines.clear() }
        if (TRACE_WHY && DEBUG_LOG && getTicks() % (LOG_EVERY * 10) == 0 && whySum.isNotEmpty()) {
            println("why-sum t=${getTicks()}: " + whySum.entries.sortedByDescending { it.value }.joinToString(" ") { "${it.key}=${it.value}" })
            whySum.clear()
        }
        prevShooters = combatEnemies.map { val p = InfluenceMap.profileOf(it); Shooter(it.x * 100 + it.y, p.ranged, p.melee) }
        // ...командирская цель НЕ подменяет цель стрельбы (v138): проведённая сюда, она уронила гейт до 129/131 и
        // дала m33:kite 0:21 135 — армия бросала всё ради назначенной цели. Она влияет мягко, через порядок focusOrder
        // огонь тоже по приказу командира (v161): назначения считаются на всю силу, включая захватчиков с оружием
        commandFire(army + ctx.runners.filter { hasWeapon(it) }, enemyCreeps, focusTarget, focusOrder, fireOf)
        commandHeal(army, enemyCreeps, healOf)
        // ...и отряжённый лекарь без оружия лечит (v240): до этого healAndShoot получал бегунов только с оружием
        healAndShoot(army + ctx.runners.filter { hasWeapon(it) || hasHeal(it) }, allies, enemyCreeps, focusTarget, focusOrder)
        cpuMark("shoot")
    }

    /** Удар мили: фокус-цель вплотную, иначе самый раненый сосед. */
    private fun strike(creep: Creep, enemyCreeps: List<Creep>, focusTarget: Creep?, focusOrder: List<Creep>) {
        if (!hasMelee(creep)) return
        val adjacent = enemyCreeps.filter { creep.getRangeTo(it) <= 1 }
        val focusDying = focusTarget != null && creep.getRangeTo(focusTarget) <= 1 && focusTarget.hits <= InfluenceMap.profileOf(creep).melee
        val ordered = fireOf[creep.id]?.let { id -> adjacent.firstOrNull { it.id == id } }
        val target: Creep? = when {
            // приказ командира и для удара (v161): цель назначена по всей армии, а не по тому, кто оказался рядом.
            // Исключение одно — крип, которого мы ДОБИВАЕМ этим ударом: добить дороже, чем исполнить приказ
            focusDying -> focusTarget
            ordered != null -> ordered
            focusTarget != null && creep.getRangeTo(focusTarget) <= 1 -> focusTarget
            adjacent.isNotEmpty() -> focusOrder.firstOrNull { creep.getRangeTo(it) <= 1 } ?: adjacent.minByOrNull { it.hits }
            else -> null
        }
        target?.let { Executor.attack(creep, it); lastFireTick = getTicks(); strikesAt[it.id] = (strikesAt[it.id] ?: 0) + 1 }
    }

    /** Через сколько тиков боевые враги дойдут до нашего дома — по темпу сближения за APPROACH_WINDOW;
     *  новый враг — по ходу его тела вдоль поля. Заполняет approachingIds/arrivalById (для приоритета угроз). */
    private fun enemyArrivalTicks(ctx: Ctx) {
        val now = getTicks()
        Memory.approachHistory.keys.retainAll { id -> ctx.combatEnemies.any { it.id == id } }
        Memory.approachingIds.clear()
        arrivalById.clear()
        val enemyApproach = flowTo(ctx, ctx.home)
        for (e in ctx.combatEnemies) {
            val approach = enemyApproach[e.x * 100 + e.y]
            if (approach < 0) continue
            val h = Memory.approachHistory.getOrPut(e.id) { ArrayDeque() }
            h.addLast(now to approach)
            while (h.isNotEmpty() && h.first().first < now - APPROACH_WINDOW) h.removeFirst()
            val (t0, a0) = h.first()
            val arrival = if (now - t0 < APPROACH_WINDOW / 2) pathTicks(e, enemyApproach, e.x * 100 + e.y) else {
                val rate = (a0 - approach).toDouble() / (now - t0)
                if (rate > 0.0) (approach / rate).toInt() else Int.MAX_VALUE / 2
            }
            arrivalById[e.id] = arrival
            if (arrival < Int.MAX_VALUE / 2) Memory.approachingIds.add(e.id)
        }
    }

    private fun healAndShoot(active: List<Creep>, allies: List<Creep>, enemyCreeps: List<Creep>, focusTarget: Creep?, focusOrder: List<Creep>) {
        shotsAt.clear()
        strikesAt.clear()
        val healDone = HashMap<String, Int>()
        val incoming = HashMap<String, Int>()
        // подтверждённый входящий (v233, см. USE_HEAL_BY_DEFICIT): адресный огонь этого тика или потеря прошлого
        fun confirmed(target: Creep) = (addressedDmg[target.id] ?: 0.0) > 0.0 || (lostTick[target.id] ?: 0) > 0
        fun need(target: Creep): Int {
            val deficit = target.hitsMax - target.hits
            val expected = incoming.getOrPut(target.id) {
                InfluenceMap.damageAt(target.x, target.y, enemyCreeps).toInt() }
            return deficit + expected - (healDone[target.id] ?: 0)
        }
        // нужда по подтверждённому — для прибора и для переназначения соседу (не зависит от тумблера)
        fun needConfirmed(target: Creep): Int {
            val deficit = target.hitsMax - target.hits
            val expected = if (confirmed(target)) maxOf((addressedDmg[target.id] ?: 0.0).toInt(), lostTick[target.id] ?: 0) else 0
            return deficit + expected - (healDone[target.id] ?: 0)
        }
        fun book(target: Creep, amount: Int) {
            hfullAll++; if (target.hits >= target.hitsMax) hfullN++
            hoverSum += maxOf(0, amount - maxOf(0, needConfirmed(target))); hdelivSum += amount
            healDone[target.id] = (healDone[target.id] ?: 0) + amount
        }
        // под огнём (v109): терявший хиты в прошлый тик — впереди любого дефицита (см. USE_HEAL_UNDER_FIRE), но только пока не покрыт
        // его запас «дефицит + HEAL_FIRE_ROOM × потеря»: первый срез слал всех троих на потерявшего 60 (216 лечения в дефицит 60),
        // и призрак 273 терял на входе 2710 против 1688 у v108 — покрытый возвращается к обычному выбору по need
        fun rank(target: Creep): Int {
            val n = need(target)
            val lost = lostTick[target.id] ?: 0
            return n
            val fireRoom = (target.hitsMax - target.hits) + HEAL_FIRE_ROOM * lost - (healDone[target.id] ?: 0)
            return if (fireRoom > 0) HEAL_FIRE_RANK + fireRoom else n
        }
        for (creep in active) {
            strike(creep, enemyCreeps, focusTarget, focusOrder)
            val healParts = creep.body.count { it.type == HEAL && it.hits > 0 }
            if (healParts > 0) {
                val candidates = allies.filter { !it.spawning && need(it) > 0 && creep.getRangeTo(it) <= HEAL_RANGE }
                // приказ командира первым (v162): он назначил пациента, зная, кого враг добивает и кого лечение спасёт
                val ordered = healOf[creep.id]?.let { id -> candidates.firstOrNull { it.id == id } }
                // ...И ПРИКАЗ ДЕЙСТВУЕТ НА ВСЕЙ ЛЕЧЕБНОЙ ДАЛЬНОСТИ (v183, оператор: «не должно быть ничего, что идёт
                // мимо командира»). Прежде назначенный пациент брался, только если он ВПЛОТНУЮ; иначе выбор перехватывал
                // местный ранг соседей — и приказ отбрасывался тем, что рядом просто кто-то стоит
                // СТЕНА ЛЕЧЕНИЯ (v228, см. USE_HEAL_WALL): удержимую жертву лечит каждый лекарь в дальности, вплотную — полностью
                if (victimSaveable) hwallHealsAll++
                val wallTarget = if (victimSaveable) victimNow?.takeIf { v -> !v.spawning && creep.getRangeTo(v) <= HEAL_RANGE } else null
                if (wallTarget != null) {
                    hwallHeals++
                    if (creep.getRangeTo(wallTarget) <= 1) {
                        Executor.heal(creep, wallTarget)
                        book(wallTarget, InfluenceMap.modified(creep, EFF_HEAL_MODIFIER, healParts * HEAL_POWER.toDouble()).toInt())
                        shoot(creep, enemyCreeps, focusTarget, focusOrder)
                    } else {
                        Executor.rangedHeal(creep, wallTarget)
                        book(wallTarget, InfluenceMap.modified(creep, EFF_HEAL_MODIFIER, healParts * RANGED_HEAL_POWER.toDouble()).toInt())
                    }
                    continue
                }
                // ...и СОСЕДСТВО НЕ ВАЖНЕЕ РАНЫ (v183, оператор: «лекари лечат себя фулловыми, хотя могли бы лечить
                // того, кто под огнём»). Ближняя ветка бралась раньше дальней всегда, поэтому полный сосед — включая
                // самого лекаря — обходил раненого в двух клетках. Замер разгрома 3d9532: 8 лечений из 55 (14 %) ушли
                // в цель на полных хитах, не получившую в этот тик урона, — у него таких 0 из 172; в трёх из этих
                // случаев рядом стоял крип с потерей 900–1 060. Полный сосед лечится, только если раненых нет вовсе
                val anyWounded =  candidates.any { it.hitsMax - it.hits > 0 }
                val closeTarget0 = candidates.filter { creep.getRangeTo(it) <= 1 && (!anyWounded || it.hitsMax - it.hits > 0) }
                    .maxByOrNull { rank(it) }
                val closeTarget = closeTarget0
                if (closeTarget != null) {
                    Executor.heal(creep, closeTarget)
                    book(closeTarget, InfluenceMap.modified(creep, EFF_HEAL_MODIFIER, healParts * HEAL_POWER.toDouble()).toInt())
                    shoot(creep, enemyCreeps, focusTarget, focusOrder)
                    continue
                }
                val farTarget = ordered?.takeIf { creep.getRangeTo(it) <= HEAL_RANGE }
                    ?: candidates.filter { it.hitsMax - it.hits > 0  }.maxByOrNull { rank(it) }
                if (farTarget != null) {
                    Executor.rangedHeal(creep, farTarget)
                    book(farTarget, InfluenceMap.modified(creep, EFF_HEAL_MODIFIER, healParts * RANGED_HEAL_POWER.toDouble()).toInt())
                    continue
                }
            }
            shoot(creep, enemyCreeps, focusTarget, focusOrder)
        }
        damageBooked.clear()
        val most = shotsAt.values.maxOrNull() ?: 0
        if (most > 0) {
            concSum += most; concTicks++
            concAll += most; concAllTicks++
            if (most > concMax) concMax = most
        }
        // ...и то же ДЛЯ МИЛИ (v221, см. mconcAll): удар не кладёт ничего в `shotsAt`, поэтому `conc` про мили
        // слеп — сложены ли четыре удара в одну цель, не измерял ни один прибор
        val mostStrikes = strikesAt.values.maxOrNull() ?: 0
        if (mostStrikes > 0) {
            mconcAll += mostStrikes; mconcTicks++
            if (mostStrikes > mconcMax) mconcMax = mostStrikes
        }
    }

    /** Урон, уже расписанный по цели в этом тике (v140, отказ от перебоя): чистится вместе с shotsAt. */
    private val damageBooked = HashMap<String, Double>()

    private fun shoot(creep: Creep, enemyCreeps: List<Creep>, focusTarget: Creep?, focusOrder: List<Creep>) {
        if (!hasRanged(creep)) return
        val creepsInRange = enemyCreeps.filter { creep.getRangeTo(it) <= RANGED_RANGE }
        if (creepsInRange.isEmpty()) return
        val combatInRange = creepsInRange.filter { c -> val p = InfluenceMap.profileOf(c); p.melee + p.ranged + p.heal > 0.0 }
        val massPool = if (combatInRange.isNotEmpty()) combatInRange else creepsInRange
        val massValue = massPool.sumOf { InfluenceMap.rangedRate(creep.getRangeTo(it)) }
        // против армии с лекарями — только фокус: веер размазывает урон по трём-пяти целям, и три лекаря (216 в тик)
        // вылечивают его целиком, пока враг сосредоточенно снимает 540 в тик с одного нашего (стенд sleeper: наш чистый
        // урон 200 в тик против 540). Веер — когда врагу нечем лечить или он даёт не меньше двух с половиной выстрелов
        val enemyHeals = enemyCreeps.any { InfluenceMap.profileOf(it).heal > 0.0 }
        // ...и ВЕЕР ОТСТУПАЕТ ПЕРЕД СОШЕДШИМИСЯ СТВОЛАМИ (v218, см. focusBreakableNow). Три его крипа вплотную
        // дают massValue = 3.0, то есть порог 2.5 берётся сам собой — и ветка веера игнорирует `focusTarget`
        // ЦЕЛИКОМ. Пока стволы размазаны, это верно: веер бьёт по всем. Но ровно в тот момент, когда фокус стал
        // пробиваемым тем, что до него дотягивается (это и есть «четыре-пять стволов» из записанного порога),
        // веер развёл бы их обратно и отдал бы цель его лекарям. Побочно ветка чинит и ПРИБОР: веерный выстрел
        // не кладёт ничего в `shotsAt`, поэтому такие тики не входили в `conc` даже знаменателем (см. concfan)
        if (massValue > (if (enemyHeals) 2.5 else 1.0)) {
            Executor.rangedMassAttack(creep); lastFireTick = getTicks(); fanShots++; fireShots++
        } else {
            // ПЕРЕБОЙ (v140, приём из литературы по микроменеджменту RTS): выстрел в цель, которая и так умрёт от уже
            // назначенного в этом тике урона, пропадает целиком. `damageBooked` считает, сколько по ней уже расписано
            // нашими за тик; если этого хватает с учётом её лечения, стрелок переходит к следующей цели по ранжиру
            fun booked(t: Creep) = damageBooked[t.id] ?: 0.0
            // фокус-цель вне дальности — добиваем самого раненого боевого в дальности (безоружных — в последнюю очередь)
            val ordered = fireOf[creep.id]?.let { id -> enemyCreeps.firstOrNull { it.id == id } }
            val target = when {
                // приказ командира — первым: он назначал цель, зная всю армию и всё, что до цели дотягивается (v161)
                ordered != null && creep.getRangeTo(ordered) <= RANGED_RANGE  -> ordered
                focusTarget != null && creep.getRangeTo(focusTarget) <= RANGED_RANGE  -> focusTarget
                else -> focusOrder.firstOrNull { creep.getRangeTo(it) <= RANGED_RANGE  }
                    ?: massPool.minByOrNull { it.hits }
            }
            target?.let {
                Executor.rangedAttack(creep, it); shotsAt[it.id] = (shotsAt[it.id] ?: 0) + 1; lastFireTick = getTicks(); fireShots++
                damageBooked[it.id] = booked(it) + InfluenceMap.profileOf(creep).ranged * InfluenceMap.takenOf(it)
            }
        }
    }

    internal fun sgn(v: Int) = if (v > 0) 1 else if (v < 0) -1 else 0

    /** Хранители флагов (см. KEEP_RANGE): снятие, потом назначение. */
    private fun enemyCreeps(ctx: Ctx): List<Creep> = ctx.enemyCreeps
    private fun updateKeepers(ctx: Ctx, army: List<Creep>) {
        val armedEnemies = ctx.combatEnemies.filter { threatening(it, ctx.enemyCreeps) }
        val iter = Memory.keeperIds.entries.iterator()
        while (iter.hasNext()) {
            val e = iter.next()
            val c = army.firstOrNull { it.id == e.key }
            val f = ctx.flags.firstOrNull { it.id == e.value }
            // враг с боем в KEEP_RANGE от флага — хранителя нет: стрелок стоял на R3 весь бой, пока в десяти клетках
            // висели скауты врага, и не стрелял (матч 18)
            val stay = c != null && f != null && f.ours && c.x == f.pos.x && c.y == f.pos.y && c.hits * 2 >= c.hitsMax &&
                enemyCreeps(ctx).any { it.id != c.id && getRange(f.pos, it) <= KEEP_RELEASE } &&
                armedEnemies.count { getRange(f.pos, it) <= KEEP_RANGE } <= KEEP_PICKET
            if (!stay) {
                if (DEBUG_LOG) println("keeper t=${getTicks()}: ${e.key} released from ${e.value}")
                iter.remove()
            }
        }
        for (f in ctx.flags) {
            if (!f.ours) continue
            val occ = f.occupant ?: continue
            if (occ.my != true || army.none { it.id == occ.id } || occ.id in Memory.keeperIds) continue
            // ...и хранителем не становится лекарь (v215, см. USE_HEALER_NEVER_PINNED): ветка `keeper` первая в
            // цепочке целей, и пришпиленный к флагу лекарь выключается из боя целиком
            if (army.any { it.id == occ.id && !hasWeapon(it) && hasHeal(it) }) continue
            if (Memory.runnerFlag.values.contains(f.id)) continue
            if (enemyCreeps(ctx).none { getRange(f.pos, it) <= KEEP_RANGE }) continue
            if (armedEnemies.count { getRange(f.pos, it) <= KEEP_RANGE } > KEEP_PICKET) continue
            Memory.keeperIds[occ.id] = f.id
            if (DEBUG_LOG) println("keeper t=${getTicks()}: ${occ.id} keeps ${f.id} at (${f.pos.x},${f.pos.y})")
        }
    }

    /** План строя (см. USE_BLOCK): фронт — наши мили (без слотов, дерутся по своим правилам), стрелки — в ряду за центром
     *  мили на RANGED_RANGE − d клеток, где d — дистанция фронта до ближайшей угрозы (вплотную — в 2, достают на клетку
     *  за фронт, как стрелки врага за его мили; враг в 3 — в одном ряду с мили, иначе не достают вовсе: матч 17 — линия
     *  врага встала в 3 от наших мили, его мили не лезли, наши стрелки «в 2 за мили» стояли в 5–6 от целей и молчали, а
     *  наш фронт били бесплатно), тыл на клетку дальше. Первая правка делила случаи «есть их мили в 3 / нет» и меняла
     *  местами ряды стрелков и мили — при подходе толпы случай менялся через пару тиков, и строй переворачивался под
     *  ударами (стенд m6 sleeper, армия потеряна). Ряды поперёк оси центр → ближайшая группа врагов с боем; слоты по
     *  порядку SLOT_ORDER от середины ряда, стены и клетки мили пропускаются; крип берёт ближайший свободный слот
     *  своего ряда. */
    /** КОМАНДИР (v137, см. USE_COMMANDER): одно решение на всю армию в бою с сомкнутым блобом. Раздаёт КЛЕТКИ — по одной
     *  на крипа, — считая для каждой опасность СЕЙЧАС и опасность НА СЛЕДУЮЩИЙ ТИК (его мили в MELEE_KEEP_RANGE шагнёт и
     *  ударит). Мили ставятся первыми — туда, где они достают его вооружённых; стрелки вторыми — где есть цель в
     *  RANGED_RANGE и меньше всего входящего на следующий тик; лекари последними — в HEAL_RANGE от раненого и вне огня.
     *  Клетка занимается один раз, крипы обслуживаются от самого стеснённого, поэтому свои друг друга не загораживают.
     *  Атаки идут своим проходом и назначением не затрагиваются: крип, уже стоящий где надо, просто бьёт. */
    /** Замысел, по которому командир раздаёт клетки (v138): напор, удержание или уступка. */
    /** Замыслы командира (v138). SPREAD (рассредоточение против веера) отвергнут гейтом — 130/131 в двух формах,
     *  и живьём проверить не успели: лимит загрузок кода на сервере кончился. */
    internal enum class Intent { PRESS, HOLD, YIELD, FOCUS, KITE }

    /** РЕЖИМ ГОНКИ (v160, оператор: командир оркестрирует всю игру, «в случае затишья — раздавать задания по захватам
     *  флагов небольшими группами»). Здесь враг строем не дерётся — сидит на флагах, разбегается или держит дистанцию,
     *  — и решает не кулак, а счёт. Командир раздаёт ЗАДАНИЯ: каждому незанятому флагу — ближайшая горстка, по одному
     *  крипу на свободный флаг и по двое на тот, у которого стоят его вооружённые; ядро (половина армии) остаётся
     *  целым, потому что аннигиляция проигрывает матч при любом счёте. Назначение идёт той же картой commandOf, что и
     *  в бою, поэтому исполняют его те же правила движения. */
    /** ОГОНЬ ПО ПРИКАЗУ (v161, оператор: перевести выбор целей на командира). Прежде «кто куда встал» решал командир, а
     *  «кто в кого бьёт» — отдельный проход со своим липким фокусом, и это два решения об одном размене. Здесь цель
     *  назначается ПОИМЁННО, одной политикой: сперва ищем того, кого армия ДОБИВАЕТ этим тиком (залп всех, кто его
     *  достаёт, перекрывает хиты вместе с лечением, которое до него дотягивается) — на него идут все достающие; если
     *  добить некого, огонь сходится на прежней липкой цели, а кто её не достаёт, бьёт ближайшего вооружённого. */
    /** ЯДРО ИДЁТ СТРОЕМ (v163, оператор: перевести на командира и движение вне боя). Ведёт ядро как одно тело: шаг в
     *  сторону цели, клетки раздаются по одной на крипа, отставший подтягивается к якорю, и ни одна клетка не выходит
     *  за FIST_RADIUS. Это НЕ отвергнутый USE_COMMANDER_APPROACH: тот вёл поход РАССТАНОВКОЙ ПРОТИВ СТРОЯ, которой в
     *  походе нечего расставлять, и потому упирался в фолбэк «ближе к врагу». */
    /** ЦЕЛЬ ПОХОДА ВЫБИРАЕТ КОМАНДИР (v164, оператор). Прежде он вёл ядро строем к цели, которую выбрал НЕ ОН:
     *  objectiveFlagId считается раньше, отдельной логикой ценности флага. Здесь цель — его решение, и по его же
     *  правилам: флаг, который БРАТЬ МОЖНО (флаг дебаффает владельца, поэтому мимо гейта захвата ходить незачем),
     *  ближайший к армии, со штрафом за его вооружённых рядом — заслонённый берётся боем, а не строевым шагом. */
    private fun commandGoal(ctx: Ctx, army: List<Creep>, armedEnemies: List<Creep>): Position? {
        if (army.isEmpty()) return null
        // ...и оценку флага командир не изобретает заново, а ВЫЗЫВАЕТ: chooseFlagObjective считает ценность, путь,
        // пачку у флага и возможность отхода — всё, чего не знает «ближайший разрешённый». Своя формула была написана
        // и отвергнута замером: по близости 131 из 135 (camp дважды, screen, brawl+heals), по ценности на шаг 132,
        // с квадратичным штрафом расстояния снова 131. Решение остаётся командирским — он спрашивает и решает
        return chooseFlagObjective(ctx, army, PUSH_RATIO)?.flag?.pos
        val best = ctx.flags.filter { !it.ours && it.occupant?.my != true && captureAllowed(ctx, it) }
            .maxByOrNull { f ->
                val near = army.minOf { getRange(it, f.pos) }
                val guards = armedEnemies.count { getRange(it, f.pos) <= ENGAGE_RANGE }
                f.score.toDouble() / (near + 1 + guards * GOAL_GUARD_COST)
            }
        return best?.pos
    }

    private fun commandMarch(ctx: Ctx, army: List<Creep>, goal: Position?, out: MutableMap<String, Position>) {
        out.clear()
        if (goal == null) return
        val core = army.filter { canMove(it) && !it.spawning }
        if (core.size < 2) return
        val (ax, ay) = Formation.median(core)
        // ...и направление задаёт ПУТЬ, а не прямая на цель: жадный шаг упирался в стену и строй застревал целиком —
        // сценарий screen шёл в режиме марша все 185 строк лога и проигрывал счёт 10 782:14 471. Ведущий — тот, кто
        // ближе всех к якорю; его шаг по полю потока и есть направление колонны (v163)
        val lead = core.minByOrNull { maxOf(abs(it.x - ax), abs(it.y - ay)) }!!
        marchAll++
        val sx: Int; val sy: Int
        val descent = flowDescent(ctx, goal, ax, ay, lead)
        if (descent != null) { marchFlow++; sx = descent.first; sy = descent.second }
        else {
            val step = pathStep(lead, goal, 1, crowdMatrixOf(ctx, goal.x * 100 + goal.y))
            sx = if (step != null) (step.x - lead.x).coerceIn(-1, 1) else (goal.x - ax).coerceIn(-1, 1)
            sy = if (step != null) (step.y - lead.y).coerceIn(-1, 1) else (goal.y - ay).coerceIn(-1, 1)
        }
        if ((sx != 0 || sy != 0) && sx == -marchPrevSx && sy == -marchPrevSy) marchFlip++
        marchPrevSx = sx; marchPrevSy = sy
        if (sx == 0 && sy == 0) return
        Formation.marchColumn(core, ax, ay, sx, sy, out)
    }

    /** Шаг колонны по полю потока к цели (v232, см. USE_MARCH_FLOW_DIRECTION): сосед клетки якоря с наименьшим расстоянием
     *  до цели; якорь на стене — от клетки ведущего; null — цель по полю недостижима; (0,0) — якорь на цели. */
    private fun flowDescent(ctx: Ctx, goal: Position, ax: Int, ay: Int, lead: Creep): Pair<Int, Int>? {
        val field = flowTo(ctx, goal)
        val fx: Int; val fy: Int
        if (field[ax * 100 + ay] >= 0) { fx = ax; fy = ay }
        else if (field[lead.x * 100 + lead.y] >= 0) { fx = lead.x; fy = lead.y }
        else return null
        var bestD = field[fx * 100 + fy]; var bx = 0; var by = 0
        for (dx in -1..1) for (dy in -1..1) {
            if (dx == 0 && dy == 0) continue
            val nx = fx + dx; val ny = fy + dy
            if (nx < 0 || ny < 0 || nx > 99 || ny > 99) continue
            val d = field[nx * 100 + ny]
            if (d >= 0 && d < bestD) { bestD = d; bx = dx; by = dy }
        }
        return Pair(bx, by)
    }

    private fun commandFire(army: List<Creep>, enemies: List<Creep>, focus: Creep?, order: List<Creep>,
                            out: MutableMap<String, String>) {
        out.clear()
        val shooters = army.filter { hasWeapon(it) && !it.spawning }
        if (shooters.isEmpty() || enemies.isEmpty()) return
        val live = enemies.filter { it.hits > 0 }
        fun reach(c: Creep, e: Creep) = if (hasRanged(c)) c.getRangeTo(e) <= RANGED_RANGE else c.getRangeTo(e) <= 1
        // ...кого добиваем ЭТИМ тиком: залп достающих минус лечение, дотягивающееся до цели
        // РАЗОРУЖЁННЫЙ — НЕ ЦЕЛЬ (v178, оператор: «наши крипы во время боя зачем-то начали добивать разоружённых,
        // которые в текущий момент нам никак не вредят, вместо того чтобы снимать хиты тем, кто наносит урон прямо
        // сейчас»). Добиваемость считалась по ХИТАМ, а у разоружённого их мало — он и выходил лучшей целью, тогда как
        // не бьёт вовсе. Огонь идёт по тем, кто ещё вооружён; безоружные оставляются на потом
        // ...И СКАУТ У ФЛАГА (v214): без этого приказ командира расходится с фокусом — `order.firstOrNull { ... in
        // dangerous }` ниже отфильтровал бы его обратно, и стрелок, которому фокус назначил скаута, молчал бы.
        // Распоряжение v178 не тронуто: остов сюда по-прежнему не попадает (у него потенциал есть, у скаута нет)
        val scoutsHere = live.filter { e ->
            scoutFoe(e) && flagsNow.any { !it.ours && getRange(e, it.pos) <= 1 } }
        val dangerous = live.filter { e -> InfluenceMap.profileOf(e).let { it.melee + it.ranged + it.heal > 0.0 } } + scoutsHere
        val pool = if (dangerous.isNotEmpty()) dangerous else live
        val killable = pool.filter { e ->
            val burst = shooters.filter { reach(it, e) }.sumOf { c ->
                val pr = InfluenceMap.profileOf(c)
                (if (hasRanged(c)) pr.ranged else pr.melee) * InfluenceMap.takenOf(e)
            }
            val cover = enemies.sumOf { h ->
                val pr = InfluenceMap.profileOf(h)
                val d = h.getRangeTo(e)
                if (pr.heal <= 0.0 || d > HEAL_RANGE) 0.0 else if (d <= 1) pr.heal else pr.heal / 3.0
            }
            burst >= e.hits + cover
        }.minByOrNull { it.hits }
        for (c in shooters) {
            // ПРЕСЛЕДОВАТЕЛЬ СТРЕЛЯЕТ В СВОЙ ОСТОВ (v211). Общее правило «разоружённый — не цель» поставил оператор
            // в v178 и оно остаётся в силе для ВСЕЙ армии: пока идёт бой, огонь идёт по тем, кто бьёт сейчас.
            // Но преследователь для того и отделён, чтобы добить одного конкретного, — и назначение ему делается
            // ЗДЕСЬ, потому что commandFire начинается с out.clear() и всякий приказ, поставленный раньше, стирает.
            // Первая редакция ставила приказ в assignChase, и он не доживал до выстрела: крип догонял и молчал
            val chased = Memory.chaseTarget[c.id]
            if (chased != null && chased.hits > 0 && reach(c, chased)) { out[c.id] = chased.id; continue }
            val t = when {
                killable != null && reach(c, killable) -> killable
                focus != null && focus.hits > 0 && reach(c, focus) -> focus
                else -> order.firstOrNull { reach(c, it) && it.hits > 0 && (it in dangerous) }
                    ?: pool.filter { reach(c, it) }.minByOrNull { it.hits }
                    ?: live.filter { reach(c, it) }.minByOrNull { it.hits }
            }
            if (t != null) out[c.id] = t.id
        }
    }

    /** ЛЕЧЕНИЕ ПО ПРИКАЗУ (v162, оператор: перевести всё на командира). Лекарь выбирал пациента сам — по дефициту
     *  хитов плюс ожидаемый входящий урон, — и не знал того, что командир уже посчитал: кого враг ДОБИВАЕТ этим тиком.
     *  Здесь пациент назначается поимённо: сперва тот, кого убивают сейчас и кого лечение ещё СПАСАЕТ (иначе это
     *  лечение в труп), и на него ставится ровно столько лекарей, сколько нужно, чтобы перекрыть входящий; остальные
     *  идут по наибольшей нужде. Порядок лекарей — от дальнего к ближнему, чтобы ближний добирал остаток. */
    private fun commandHeal(army: List<Creep>, enemies: List<Creep>, out: MutableMap<String, String>) {
        out.clear()
        val healers = army.filter { hasHeal(it) && !it.spawning }
        if (healers.isEmpty()) return
        val mates = army.filter { it.hits < it.hitsMax || InfluenceMap.damageAt(it.x, it.y, enemies) > 0.0 }
        if (mates.isEmpty()) return
        val incoming = HashMap<String, Double>()
        for (m in mates) incoming[m.id] = InfluenceMap.damageAt(m.x, m.y, enemies) * InfluenceMap.takenOf(m)
        // сколько лечения дотянется до цели от ещё не занятых лекарей
        fun healPool(t: Creep, free: List<Creep>) = free.sumOf { h ->
            val d = h.getRangeTo(t); val pr = InfluenceMap.profileOf(h)
            if (d <= 1) pr.heal else if (d <= HEAL_RANGE) pr.heal / 3.0 else 0.0
        }
        val free = healers.toMutableList()
        // ...сперва те, кого убивают ЭТИМ тиком и кого лечение ещё спасает
        val dying = mates.filter { (incoming[it.id] ?: 0.0) >= it.hits }
            .sortedByDescending { it.hits }
        for (t in dying) {
            if (free.isEmpty()) break
            if (healPool(t, free) + t.hits < (incoming[t.id] ?: 0.0)) continue   // не спасаем — не тратим лечение в труп
            var got = 0.0
            for (h in free.sortedByDescending { it.getRangeTo(t) }.toList()) {
                if (got + t.hits >= (incoming[t.id] ?: 0.0)) break
                val d = h.getRangeTo(t); val pr = InfluenceMap.profileOf(h)
                if (d > HEAL_RANGE) continue
                got += if (d <= 1) pr.heal else pr.heal / 3.0
                out[h.id] = t.id; free.remove(h)
            }
        }
        // ...остальные — по ДОШЕДШЕМУ лечению, а не по наибольшей нужде (v183). Ранг по нужде не знает, сколько этот
        // лекарь реально снимет: вплотную он лечит вчетверо сильнее, чем издали (HEAL_POWER против RANGED_HEAL_POWER),
        // и приказ уводил его лечить издали чуть более нуждающегося вместо соседа. Пока приказ отбрасывался ближней
        // веткой исполнителя, это было незаметно; едва приказ стал действовать на всей дальности (USE_HEAL_ORDER_WINS),
        // гейт потерял обе строки kite. Ценность цели — min(нужда, сколько дойдёт), нужда остаётся тай-брейком
        for (h in free) {
            val pr = InfluenceMap.profileOf(h)
            val t = mates.filter { h.getRangeTo(it) <= HEAL_RANGE && it.id != h.id }
                .maxByOrNull { m ->
                    val need = (m.hitsMax - m.hits) + (incoming[m.id] ?: 0.0)
                    need
                }
            if (t != null) out[h.id] = t.id
        }
    }

    /**
     * Назначает погоню за остовами: крипами врага, у которых выбито всё оружие, но тело его помнит, — пока у него
     * жив лекарь, такой крип это полная его мощь на таймере. Условие на цель одно и оно из той же модели, что всё
     * остальное: ОПАСНОСТЬ В ЕГО КЛЕТКЕ должна быть настолько мала, чтобы преследователь прожил там CHASE_TTL
     * тиков. Этим одним условием сказано и «он оторвался от своего блока», и «нашему там не смертельно», и
     * отзыв погони: как только остов вернулся под прикрытие, опасность растёт и назначение само перестаёт
     * выдаваться. Отдельного правила отзыва не нужно.
     */
    private fun assignChase(army: List<Creep>, enemyCreeps: List<Creep>, armedEnemies: List<Creep>) {
        Memory.chaseOf.clear()
        Memory.chaseTarget.clear()
        val fighters = army.filter { canMove(it) && !it.spawning && hasWeapon(it) }
        if (fighters.size < CHASE_MIN_ARMY) return
        if (enemyCreeps.none { InfluenceMap.profileOf(it).heal > 0.0 }) return   // лечить некому — остов и так труп
        val hulks = enemyCreeps.filter { e ->
            val pot = InfluenceMap.potentialOf(e)
            val live = InfluenceMap.profileOf(e)
            pot.melee + pot.ranged > 0.0 && live.melee + live.ranged <= 0.0
        }
        if (hulks.isEmpty()) return
        val free = fighters.toMutableList()
        // ...и НЕ БОЛЬШЕ ПОЛОВИНЫ, как у гонки за флагами: ядро остаётся сильнее его армии, иначе погоня покупает
        // остова ценой боя. Та же проверка паритета, тот же довод — аннигиляция это поражение при любом счёте
        var budget = minOf(CHASE_MAX, (free.size - 1) / 2)
        for (h in hulks.sortedBy { e -> free.minOfOrNull { getRange(it, e) } ?: 99 }) {
            if (budget <= 0) break
            val key = h.x * 100 + h.y
            val danger = InfluenceMap.dangerAt(key)
            // преследователь выбирается ближайший, стрелок вперёд мили: он добивает с трёх и не лезет под ответ
            // ТРИ СУЖЕНИЯ ОТРЯДА ЗАМЕРЕНЫ И ОТВЕРГНУТЫ (v213). Базовая линия стенда — 137 восстановлений при 65
            // решающих уничтожениях армии врага. Отряд из ДВУХ: погонь 1689, добито 411, восстановлений 104
            // (−24 %), уничтожений 55. Отряд из ОДНОГО: 1507/317, восстановлений 131 (−4 %, то есть выгоды нет),
            // уничтожений 61. «Только тот, чей огонь и так пропадает» (у кого в своей дальности нет живого
            // вооружённого): 1475/362, восстановлений 143 — ХУЖЕ базовой линии, потому что незанятый крип по
            // построению стоит далеко от боя и доходит до остова позже, чем тот до лекаря.
            // Работает только отряд из двух, и его цена — не поражения (наша армия не уничтожена ни разу, отрыв по
            // очкам ровный, −0,65 %), а десять сценариев, где вместо аннигиляции врага матч кончается по очкам с
            // нами впереди. Это размен формы победы на снятые восстановления, и он принят.
            val chaser = free.filter { c -> c.hits > danger * CHASE_TTL }
                .minWithOrNull(compareBy({ if (hasRanged(it)) 0 else 1 }, { getRange(it, h) })) ?: continue
            val without = free.filter { it.id != chaser.id }
            if (without.none { hasWeapon(it) }) break
            if (ourPowerOf(without, armedEnemies) < enemyPowerOf(armedEnemies, without) * PARITY_FLOOR) break
            Memory.chaseOf[chaser.id] = h.id
            Memory.chaseTarget[chaser.id] = h
            free.remove(chaser)
            budget--
        }
        if (Memory.chaseOf.isNotEmpty()) chaseTicks++
        // прибор: остов, за которым была погоня и который перестал существовать, — это её результат
        for (id in Memory.chasedIds.toList()) if (enemyCreeps.none { it.id == id }) { chaseKills++; Memory.chasedIds.remove(id) }
        Memory.chasedIds.addAll(Memory.chaseOf.values)
    }

    private fun commandRace(ctx: Ctx, army: List<Creep>, armedEnemies: List<Creep>, flags: List<FlagInfo>,
                            out: MutableMap<String, Position>) {
        out.clear()
        // ...и состав берётся ДО очистки (v215, см. USE_RACE_COUNTS_RELEASED): очистка стояла строкой выше чтения
        val alreadyOut = ctx.runners.filter { it.id in Memory.cmdDetach }
        Memory.cmdDetach.clear()
        // В БОЮ НЕ ОТПУСКАЕМ НИКОГО (v215, см. USE_NO_SPLIT_IN_FIGHT). Проверки «мы в контакте» здесь не было вовсе,
        // а RACE — ветка `else` в выборе режима, то есть значение по умолчанию: достаточно, чтобы по нам на тик
        // перестали стрелять, и командир раздавал задания на захват посреди рубки
        if (fightOnNow) return
        // ...и состав считается ЦЕЛИКОМ, вместе с уже отпущенными командиром: иначе он каждый тик берёт половину
        // ОСТАВШИХСЯ и отпускает ещё, а ушедшие ему не видны — армия распадалась экспоненциально, до двух крипов к
        // концу матча (match29:kite, cmd=0/1090, army=2, 0 очков). Задание раздаётся заново на всех, а не поверх
        val mine = army + (alreadyOut)
        val free = mine.filter { canMove(it) && !it.spawning && hasWeapon(it) }.toMutableList()
        if (free.isEmpty()) return
        // СИММЕТРИЧНАЯ АРМИЯ (v214, решение оператора): «держать в основной армии столько же крипов, сколько у
        // врага, симметрично по типам боевых; лекари всегда остаются в основной армии; остальных отпустить».
        // Считается по ВСЕМ его живым боевым крипам, как он и просил. Лекари сюда не попадают вовсе: `free`
        // отбирается по hasWeapon, а лекарь без оружия в него не входит.
        // ⚠️ Арифметика, о которой надо помнить: при целых армиях 14 на 14 у нас 4 мили и 5 стрелков, у него
        // столько же — симметрия оставляет в ядре все девять и не отпускает НИКОГО. Это ровно то, чего просит
        // оператор, и это безопаснее прежней половины (match29:kite: армия таяла до двух крипов при нуле очков).
        // Флаговый забег при этом ложится на двух наших скаутов и на флаг-цель армии, открытую локализацией вето.
        val core = run {
            // ...и «сколько у врага» значит «сколько у врага ЗДЕСЬ» (v216, см. USE_SYMMETRY_BY_NEAR)
            val near = ctx.combatEnemies.filter { e ->
                e.id in fightPackIds || getRange(e, ctx.ourCentroid) <= MARCH_SAFE
            }
            val hisMelee = near.count { hasMelee(it) }
            val hisRanged = near.count { hasRanged(it) }
            minOf(free.count { hasMelee(it) && !hasRanged(it) }, hisMelee) + minOf(free.count { hasRanged(it) }, hisRanged)
        }
        symCore += core
        symFree += free.size
        var budget = free.size - core
        budgetSum += maxOf(0, budget)
        budgetTicks++
        if (budget <= 0) return
        // флаги — от ближайшего к армии; занятые нами пропускаем
        // ...и только те, которые БРАТЬ МОЖНО: флаг вешает дебафф на ВЛАДЕЛЬЦА (−20 % удару, −25 % лечению, +10 %
        // получаемому урону за штуку), поэтому доктрина паритета держит захват в узде через captureAllowed, и гонка
        // мимо неё — не гонка, а разоружение. Первая редакция это правило игнорировала, и гейт поймал: camp
        // 7 911:17 364, scatter 15 273:24 303 против 22 810:19 091 и 24 268:17 098 без режима
        val wanted = flags.filter { !it.ours && it.occupant?.my != true && captureAllowed(ctx, it) }

            .sortedBy { f -> free.minOf { getRange(it, f.pos) } }
        for (f in wanted) {
            if (budget <= 0) break
            // ...и размер горстки задаёт НЕ флаг, а его армия: пока она цела и на ходу, одиночку она перехватывает и
            // бьёт — на match29:kite наши уходили за флагами по одному, армия таяла до двух крипов, а очков не было
            // вовсе (0 : 22 469). Одиночка посылается, только когда перехватывать некому
            val guarded = armedEnemies.any { getRange(it, f.pos) <= ENGAGE_RANGE }
            val loose = armedEnemies.count { e -> canMove(e) } >= COMMAND_MIN_FOES
            // ...идущий туда бегун ЗАСЧИТЫВАЕТСЯ в группу, а не отменяет её: прежний фильтр выкидывал флаг целиком, и
            // когда бегуны разбирали все доступные флаги, командир не отпускал никого вовсе — гейт терял roost
            // (7 597:24 268) и camp, где прежняя логика отряда выпускала бойцов
            // ...а флаг, который уже берёт бегун, командир не дублирует: засчитывать бегуна в группу и досылать бойца
            // замерено хуже — 131 из 135 против 133 (roost трижды, camp)
            if (ctx.runners.any { r -> Memory.runnerFlag[r.id] == f.id }) continue
            val need = if (guarded) 2 else if (loose) RACE_PARTY else 1
            if (budget < need) continue
            val party = free.sortedBy { getRange(it, f.pos) }.take(need)
            if (party.size < need) continue
            // ...и ЯДРО ОБЯЗАНО ОСТАТЬСЯ СИЛЬНЕЕ ЕГО АРМИИ — та же проверка, которой держится отряд (см. USE_DETACH):
            // аннигиляция проигрывает матч при любом счёте, поэтому отпускать можно лишь до тех пор, пока оставшиеся
            // держат паритет. Без неё командир растаскивал армию грубее прежней логики и ронял army-сценарии (гейт 127)
            val without = free.filter { c -> party.none { it.id == c.id } }
            if (without.none { hasWeapon(it) }) break
            if (ourPowerOf(without, armedEnemies) < enemyPowerOf(armedEnemies, without) * PARITY_FLOOR) break
            // ...и ЗАДАНИЕ — это зачисление в захватчики с целью, а не клетка: вооружённый крип, приведённый к флагу
            // как боец, флага НЕ БЕРЁТ (захват делают бегуны), и первая редакция на сценарии kite набрала 0 очков.
            // Командир решает КТО и КУДА, а ведёт и берёт существующий механизм захвата (v160)
            for (c in party) { Memory.cmdDetach.add(c.id); Memory.runnerFlag[c.id] = f.id; free.remove(c); splitAll++; if (fightOnNow) splitFight++ }
            budget -= need
        }
    }

    /**
     * Поле расстояний до ОЧАГА — клеток, откуда наш строй достаёт самое ценное у врага. Спуск по нему и есть
     * многотиковое направление: `COMMAND_REACH = 1` предлагает только соседнюю клетку, и требование роли,
     * которому ни одна из восьми не удовлетворяет, прежде молча отбрасывалось в общий добор.
     * Очаг ОДИН на армию — это и есть починка «армия развалилась на две половины»: покриповая цель уводила
     * соседей по строю в разные бои. Затравок при этом много, и армия растекается по ФРОНТУ, приходя к
     * ближайшему его участку, а не толпясь в одной точке.
     */
    private fun ensureGoalField(fighters: List<Creep>, combatEnemies: List<Creep>): IntArray? {
        if (goalTick == getTicks()) return goalField
        goalTick = getTicks()
        if (fighters.isEmpty() || combatEnemies.isEmpty()) { goalField = null; goalSeeds = IntArray(0); return null }
        val xs = fighters.map { it.x }.sorted(); val ys = fighters.map { it.y }.sorted()
        val ax = xs[xs.size / 2]; val ay = ys[ys.size / 2]
        var peak = 0
        for (x in maxOf(0, ax - SEED_BOX)..minOf(99, ax + SEED_BOX))
            for (y in maxOf(0, ay - SEED_BOX)..minOf(99, ay + SEED_BOX)) {
                val v = InfluenceMap.attRanged[x * 100 + y]
                if (v > peak) peak = v
            }
        if (peak <= 0) { goalField = null; goalSeeds = IntArray(0); return null }
        val held = goalSeeds.toHashSet()
        val enter = (peak * SEED_ENTER).toInt()
        val hold = (peak * SEED_HOLD).toInt()
        val seeds = ArrayList<Int>(64)
        for (x in maxOf(0, ax - SEED_BOX)..minOf(99, ax + SEED_BOX))
            for (y in maxOf(0, ay - SEED_BOX)..minOf(99, ay + SEED_BOX)) {
                val key = x * 100 + y
                if (DistanceMap.isTerrainWall(x, y)) continue
                val v = InfluenceMap.attRanged[key]
                if (v >= enter || (key in held && v >= hold)) seeds.add(key)
            }
        if (seeds.isEmpty()) { goalField = null; goalSeeds = IntArray(0); return null }
        val cx = seeds.sumOf { it / 100 } / seeds.size
        val cy = seeds.sumOf { it % 100 } / seeds.size
        // очаг держится, пока его центр не уехал: без этого армия ходит между двумя равными очагами и не доходит
        // ни до одного. Геометрия при этом СВЕЖАЯ каждый тик — держится решение, а не карта: враг ходит, и поле,
        // сохранённое на десять тиков, показывало бы на то место, где он был
        if (goalCx >= 0 && maxOf(abs(cx - goalCx), abs(cy - goalCy)) < SEED_MOVE && goalSeeds.isNotEmpty()) {
            goalHolds++
        } else {
            goalCx = cx; goalCy = cy; goalSeeds = seeds.toIntArray(); goalRebuilds++
        }
        goalField = DistanceMap.goalField(goalSeeds, combatEnemies.map { InfluenceMap.cell(it.x, it.y) })
        return goalField
    }

    private fun commandFight(army: List<Creep>, combatEnemies: List<Creep>, armedEnemies: List<Creep>,
                             out: MutableMap<String, Position>, intent: Intent = Intent.PRESS,
                             per: Map<String, Intent>? = null, ourFlagCells: Set<Int> = emptySet()) {
        out.clear()
        val fighters = army.filter { canMove(it) && !it.spawning }
        if (fighters.isEmpty() || armedEnemies.isEmpty()) return
        val enemyAt = HashSet<Int>()
        for (e in combatEnemies) enemyAt.add(e.x * 100 + e.y)
        // кандидаты: всё проходимое в двух клетках от любого нашего бойца
        val cells = HashMap<Int, Position>()
        for (c in fighters) for (dx in -2..2) for (dy in -2..2) {
            val x = c.x + dx; val y = c.y + dy
            val key = x * 100 + y
            if (key in cells || x < 0 || y < 0 || x > 99 || y > 99) continue
            if (DistanceMap.isTerrainWall(x, y) || key in enemyAt) continue
            cells[key] = InfluenceMap.cell(x, y)
        }
        if (cells.isEmpty()) return
        val (ax, ay) = Formation.fist(fighters, cells)
        // ОПАСНОСТЬ КЛЕТКИ ЧИТАЕТСЯ ИЗ ПОЛЯ (v204, этап 4). Прежде она строилась здесь, то есть ПЯТЬ раз за тик —
        // по разу на замысел, над одним и тем же множеством врагов, — и внутри цикла по клеткам звалась profileOf,
        // читающая тело крипа через границу изоляции. Поле строится один раз в прологе тика (см. buildFields), и
        // этап 3 доказал равенство: fldcmp = 0 на 304 950 клетках 135 сценариев.
        // Мёртвыми оказались incNow и hits: обе карты считались в том же цикле и не читались НИКЕМ — их удалила
        // перепись, а не чтение кода
        // АДРЕСНАЯ ОПАСНОСТЬ (v224, см. USE_ADDRESSED_DANGER): E складывает всех, кто достаёт клетку, а его ствол бьёт
        // ОДНОГО — лекаря в досягаемости, иначе ближайшего, при равенстве того, у кого меньше хитов (реплеи обеих сторон:
        // 89–94 % выстрелов в ближайшего, 82–97 % в лекаря при лекаре в досягаемости). T(c, p) записывает крипу c в
        // клетке p урон только тех стволов, для которых он был бы этой целью при остальных наших на назначенных клетках
        // (план сравнивается с планом, как у согласованности строя). Досягаемости те же, что у ядер E: стрелок 3, мили 2.
        // Лучший «другой» кандидат считается один раз на крипа и пересчитывается, когда раздача перешла к другому крипу
        class AddrShooter(val x: Int, val y: Int, val ranged: Double, val melee: Double)
        val addrShooters = ArrayList<AddrShooter>()
        for (e in armedEnemies) {
            val q = InfluenceMap.profileOf(e)
            if (q.ranged > 0.0 || q.melee > 0.0) addrShooters.add(AddrShooter(e.x, e.y, q.ranged, q.melee))
        }
        val addrLive = army.filter { it.hits > 0 }
        fun healerOnly(f: Creep) = !hasWeapon(f) && hasHeal(f)
        var addrFor: String? = null
        val addrRH = DoubleArray(addrShooters.size); val addrRA = DoubleArray(addrShooters.size)
        val addrMH = DoubleArray(addrShooters.size); val addrMA = DoubleArray(addrShooters.size)
        fun addrPrepare(c: Creep) {
            addrFor = c.id
            for (i in addrShooters.indices) { addrRH[i] = Double.MAX_VALUE; addrRA[i] = Double.MAX_VALUE; addrMH[i] = Double.MAX_VALUE; addrMA[i] = Double.MAX_VALUE }
            for (f in addrLive) {
                if (f.id == c.id) continue
                val p = out[f.id] ?: InfluenceMap.cell(f.x, f.y)
                val h = healerOnly(f)
                for (i in addrShooters.indices) {
                    val s = addrShooters[i]
                    val d = maxOf(abs(p.x - s.x), abs(p.y - s.y))
                    if (d > RANGED_RANGE) continue
                    val r = d * 100000.0 + f.hits
                    if (s.ranged > 0.0) { if (r < addrRA[i]) addrRA[i] = r; if (h && r < addrRH[i]) addrRH[i] = r }
                    if (d <= 2 && s.melee > 0.0) { if (r < addrMA[i]) addrMA[i] = r; if (h && r < addrMH[i]) addrMH[i] = r }
                }
            }
        }
        fun addressedAt(c: Creep, x: Int, y: Int): Double {
            if (addrFor != c.id) addrPrepare(c)
            val h = healerOnly(c)
            var sum = 0.0
            for (i in addrShooters.indices) {
                val s = addrShooters[i]
                val d = maxOf(abs(x - s.x), abs(y - s.y))
                if (d > RANGED_RANGE) continue
                val r = d * 100000.0 + c.hits
                if (s.ranged > 0.0 && (if (h) r <= addrRH[i] else (addrRH[i] == Double.MAX_VALUE && r <= addrRA[i]))) sum += s.ranged
                if (d <= 2 && s.melee > 0.0 && (if (h) r <= addrMH[i] else (addrMH[i] == Double.MAX_VALUE && r <= addrMA[i]))) sum += s.melee
            }
            return sum
        }
        /** Опасность клетки ДЛЯ ЭТОГО крипа: адресная при тумблере, иначе поле E — байт в байт прежняя раздача. */
        fun danOf(c: Creep, key: Int): Double =
            InfluenceMap.dangerAt(key)
        val goal = ensureGoalField(fighters, combatEnemies)
        /** Цена клетки по направлению: сколько тиков пути от неё до ближайшего очага. */
        fun goalCost(key: Int): Double {
            val g = goal ?: return 0.0
            val d = g[key]
            return if (d < 0) GOAL_UNREACHABLE else d.toDouble()
        }
        val taken = HashSet<Int>()
        // клетки, где стоят СВОИ: назначать их нельзя — приказ туда неисполним, пока сосед не ушёл, а прибор показал,
        // что до назначенной клетки доходят 7 % (v167). Своя собственная клетка при этом разрешена: это «стой»
        val allyAt = HashSet<Int>()
        for (a in army) if (a.hits > 0) allyAt.add(a.x * 100 + a.y)
        // кто стоит в клетке (для цепочек): ключ клетки → крип
        val allyOf = HashMap<Int, Creep>()
        for (a in army) if (a.hits > 0) allyOf[a.x * 100 + a.y] = a
        // ПЛАН СТРОИТСЯ ВГЛУБЬ (v168, оператор): «если крипу необходимо уйти на клетку, на которой сейчас стоит крип,
        // зачем этому крипу необходимо сдвинуться на другую, и если там стоит крип, то сдвинуть и его, и так далее».
        // Раздача рекурсивна: занятая клетка не отвергается и не просто дорожает — её жилец получает приказ уйти,
        // а если и его клетка занята, цепочка идёт дальше, до CHAIN_DEPTH звеньев. Обмен местами — вырожденная
        // цепочка длины два, и он разрешён отдельно: ротация состава (раненого назад, свежего вперёд) это ровно своп
        // ОПАСНОСТЬ ПУТИ, А НЕ ТОЛЬКО КЛЕТКИ (v169, оператор). Клетка в двух шагах достигается ЧЕРЕЗ промежуточную, и
        // если та под огнём, приказ либо не исполняется, либо исполняется ценой крипа: движение честно отказывается
        // идти сквозь огонь, и именно так приказ терялся. Стоимость пути — самая безопасная из промежуточных клеток
        fun pathDanger(c: Creep, p: Position): Double {
            if (getRange(c, p) <= 1) return 0.0
            var best = Double.MAX_VALUE
            for (dx in -1..1) for (dy in -1..1) {
                if (dx == 0 && dy == 0) continue
                val x = c.x + dx; val y = c.y + dy
                if (maxOf(abs(x - p.x), abs(y - p.y)) > 1) continue          // должна быть смежной с целью
                if (x < 0 || y < 0 || x > 99 || y > 99 || DistanceMap.isTerrainWall(x, y)) continue
                val d = danOf(c, x * 100 + y)
                if (d < best) best = d
            }
            return if (best == Double.MAX_VALUE) PATH_BLOCKED_COST else best * PATH_DANGER_W
        }
        // кандидаты вокруг крипа: приказ ровно на шаг, значит их девять — а цикл шёл по всей раздаче (около трёхсот
        // клеток) и отбрасывал лишние проверкой дальности. При рекурсии цепочек и переборе замыслов это и давало
        // `Script execution timed out` почти в каждом матче (v181)
        fun nearCells(c: Creep): List<Pair<Int, Position>> {
            val near = ArrayList<Pair<Int, Position>>(9)
            for (dx in -COMMAND_REACH..COMMAND_REACH) for (dy in -COMMAND_REACH..COMMAND_REACH) {
                val key = (c.x + dx) * 100 + (c.y + dy)
                cells[key]?.let { near.add(key to it) }
            }
            return near
        }
        // ПЕРЕПИСЬ ПРОХОДОВ (v203): какой проход раздачи сколько клеток реально назначил. Пара «удалось/попыток» —
        // ноль в числителе при живом знаменателе значит «проход отказался», оба нуля значат «до прохода не дошли»
        var passTag = "-"
        fun place(c: Creep, wants: (Position) -> Boolean, rank: (Position) -> Double, depth: Int = 0,
                  rescue: Boolean = false): Boolean {
            var best: Position? = null; var bestScore = Double.MAX_VALUE
            var bestTenant: Creep? = null
            // ПРИБОР СЛАГАЕМОГО — «сколько решений ИЗМЕНИЛОСЬ», а не «сколько раз код исполнился». Ровно этого не
            // хватало v196: счётчик доказывал, что код работает, и не доказывал, что он поменял хоть одну клетку
            var bare: Position? = null; var bareScore = Double.MAX_VALUE
            // свободные, прошедшие ворота клетки (v222, см. USE_MELEE_QUIET_CELL): из них мили выбирает тихую клетку удара
            // ПРИКАЗ ОБЯЗАН БЫТЬ ИСПОЛНИМ (v172, оператор): «командир должен быть уверен, что каждый крип на следующем
            // шагу сможет выполнить приказ». Уставший крип в этот тик не двинется вовсе — ему можно приказать только
            // стоять, и приказ «шагни» от него был бы ложью, которую потом считает прогноз
            val canStep = canMove(c) && c.fatigue == 0
            // ...дальность проверяется по координатам, а не вызовом getRange: порядок перебора остаётся прежним (его
            // смена меняла выбор при равных оценках и роняла строку гейта), но отбрасывание дальних клеток становится
            // дешёвым — а их около трёхсот на каждого крипа при девяти нужных (v181)
            for ((key, p) in cells) {
                if (abs(p.x - c.x) > COMMAND_REACH || abs(p.y - c.y) > COMMAND_REACH) continue
                if (!canStep && !(p.x == c.x && p.y == c.y)) continue
                if (key in taken) continue
                if (!wants(p)) continue
                val self = p.x == c.x && p.y == c.y
                // ...и жилец, которому приказано СТОЯТЬ, остаётся препятствием (v175): прежде всякий, кто уже получил
                // приказ, считался уходящим — а приказ «стой» (хранитель флага, крип на своём месте) никуда его не
                // уводит, и назначенная поверх него клетка оказывалась неисполнимой. Это и есть весь оставшийся
                // процент неисполнения: 17 случаев на 5 294 приказа, все вида «крип остался на месте»
                val tenant = if (self) null else allyOf[key]?.takeIf { t ->
                    t.id != c.id && (t.id !in out || out[t.id]?.let { it.x == t.x && it.y == t.y } == true)
                }

                // клетка под своим дороже: приказ туда исполним, только если жильца удастся сдвинуть
                // СМЕРТЕЛЬНАЯ КЛЕТКА НЕ ПРЕДЛАГАЕТСЯ (v178, оператор: «наш мили крип шагнул сразу под 2 мили крипов
                // соперника — для него это должно было быть смертельно, и эта точка никак не могла ему выдаваться»).
                // Опасность клетки входила слагаемым и её перевешивали другие члены; теперь клетка, где входящий за
                // тик снимает крипу всю жизнь, стоит запретительно дорого и берётся, только если других нет вовсе
                val lethal =  danOf(c, key) >= c.hits
                // БОЛОТО ДЕРЖИТ КРИПА НЕСКОЛЬКО ТИКОВ (v183, оператор: «часть нашей армии часто вязнет в болоте и
                // дальше не может двигаться»). Про болото знала только СТАРАЯ ветка движения — штраф в выборе слота и
                // расчёт периода шага; командир, забравший себе все приказы, о нём не знал вовсе и посылал крипов в
                // трясину. Замер по четырём разгромам: наши крипы несут усталость 489 крипо-тиков против его 36 (в
                // тринадцать раз), стоят на месте 22 % против его 7 %, самый долгий непрерывный простой у нас 47 тиков
                // против семи у него. Шаг В болото стоит четырёх тиков неподвижности; стоять НА болоте бесплатно,
                // поэтому дорожает только переход
                val bog =  !self && DistanceMap.isSwamp(p.x, p.y)
                val sc0 = rank(p) + (if (tenant != null) ALLY_CELL_COST else 0.0) + pathDanger(c, p) +
                    (if (lethal) LETHAL_CELL_COST else 0.0) + (if (bog) SWAMP_CELL_COST else 0.0)
                // СПУСК К ОЧАГУ (v204, этап 5) — слагаемое в той же оценке, а не отдельная ветка: вблизи врага все
                // затравки на нуле и оно плоское, решает тактика; вдали оно единственное, что отличает клетки друг
                // от друга. Переход непрерывный, режима, который можно перепутать, нет
                val sc = sc0 + GOAL_STEP_COST * goalCost(key)
                // ...и при РАВНЫХ оценках выбор не должен зависеть от порядка перебора: раньше порядок задавала общая
                // раздача, теперь — обход соседей, и одна строка гейта поменяла исход именно из-за этого (v181)
                if (sc < bestScore) { bestScore = sc; best = p; bestTenant = tenant }
                if (sc0 < bareScore) { bareScore = sc0; bare = p }
            }
            val b = best ?: return false
            goalDecisions++
            val bs = bare
            if (bs == null || bs.x != b.x || bs.y != b.y) goalFlips++
            val tenant = bestTenant
            if (tenant != null) {
                if (depth >= CHAIN_DEPTH) return false
                // СПАСЕНИЕ СТАРШЕ ЛЮБОГО ПРИКАЗА (v176, оператор): если самая безопасная клетка занята крипом, которому
                // велено стоять, приказ стоять снимается и жилец уводится цепочкой — беречь расстановку ценой крипа
                // армия из четырнадцати не может. Снимается он ТОЛЬКО у выбранного жильца: первая редакция снимала
                // приказы прямо в переборе кандидатов, у всех подряд, и прибор поймал это коллизией (clash=1)
                var undo: Position? = null
                if (rescue) { undo = out.remove(tenant.id); taken.remove(tenant.x * 100 + tenant.y) }
                // своп: жилец встаёт на клетку просителя — так делается ротация состава
                val swapCell = cells[c.x * 100 + c.y]
                val moved = (swapCell != null && place(tenant, { p -> p.x == c.x && p.y == c.y }, { 0.0 }, depth + 1)) ||
                    place(tenant, { p -> p.x != b.x || p.y != b.y }, { p -> danOf(tenant, p.x * 100 + p.y) }, depth + 1)
                // ...и при неудаче цепочки снятый приказ ВОЗВРАЩАЕТСЯ: без отката жилец оставался без приказа, его
                // клетка свободной, и позже она доставалась двоим — прибор ловил это как clash=1 (v176)
                if (!moved) {
                    // ...и вернуть приказ можно, только если его клетку за это время никто не занял: слепое
                    // восстановление отдавало одну клетку двоим (clash в режиме боя, t=808)
                    val back = undo
                    if (back != null && back.x * 100 + back.y !in taken) { out[tenant.id] = back; taken.add(back.x * 100 + back.y) }
                    return false
                }
            }
            taken.add(b.x * 100 + b.y); out[c.id] = b
            // прибор адресной опасности (v224): E и T выбранной клетки, в обеих сборках
            if (depth == 0) {
                val e = InfluenceMap.dangerAt(b.x * 100 + b.y)
                val t = addressedAt(c, b.x, b.y)
                adrN++; adrE += e; adrT += t
                if (t >= e) adrSame++
            }
            // временное отталкивание в занятой клетке (Hagelbäck & Johansson): следующий крип видит её как
            // тесную. Без этого двое выбирают одну клетку, третий загораживает четвёртого — записанная причина
            // провала USE_FORWARD_SEARCH: «каждый крип считает за себя»
            InfluenceMap.addClaim(b.x, b.y)
            if (b.x != c.x || b.y != c.y) allyOf.remove(c.x * 100 + c.y)
            if (depth == 0) passCount[passTag] = (passCount[passTag] ?: 0) + 1
            return true
        }
        // ОТХОД — ТОЖЕ ПРИКАЗ (v174, оператор: «не должно быть ничего, что идёт мимо него»): бегство было веткой ВЫШЕ
        // командира. Теперь он сам уводит того, кому грозит гибель, — потерявшего за тик больше половины остатка или
        // стоящего под огнём без лечения рядом
        passTag = "retreat"
        for (c in fighters) {
            if (c.id in out) continue
            val hurtBadly = (lostTick[c.id] ?: 0) * 2 >= c.hits && c.hits * 3 < c.hitsMax
            val alone = InfluenceMap.damageAt(c.x, c.y, combatEnemies) > 0.0 &&
                army.none { it.id != c.id && hasHeal(it) && getRange(c, it) <= HEAL_RANGE }
            if (!hurtBadly && !alone) continue
            place(c, { true }, rescue = true, rank = { p -> danOf(c, p.x * 100 + p.y) * 100 -
                (armedEnemies.minOfOrNull { getRange(p, it) } ?: 0).toDouble() })
        }
        // ОТСТАВШИЙ И ВЫРВАВШИЙСЯ ПОДТЯГИВАЮТСЯ (v177, оператор: «в момент начала боя у нас всегда был 1 крип где-то
        // впереди, и его очень быстро убивали»). Кулак ограничивал КАНДИДАТНЫЕ клетки, но крипа, уже стоящего вне
        // кулака, никто не возвращал: замер по записи разгрома — боевой крип отрывался от своих на 10 клеток при
        // среднем 1,8. Такому назначается шаг К ЯКОРЮ, и раньше всех прочих назначений
        passTag = "straggler"
        if (fighters.size >= 3) {
            val (ax, ay) = Formation.median(fighters)
            for (c in fighters.sortedByDescending { maxOf(abs(it.x - ax), abs(it.y - ay)) }) {
                if (c.id in out) continue
                if (maxOf(abs(c.x - ax), abs(c.y - ay)) <= FIST_RADIUS + STRAGGLER_SLACK) continue
                // ...но НЕ того, кто уже бьёт: увести мили из контакта — отдать разменную клетку даром (гейт 134/135)
                if (armedEnemies.any { getRange(c, it) <= 1 }) continue
                place(c, { p -> maxOf(abs(p.x - ax), abs(p.y - ay)) < maxOf(abs(c.x - ax), abs(c.y - ay)) },
                    { p -> danOf(c, p.x * 100 + p.y) + maxOf(abs(p.x - ax), abs(p.y - ay)) })
            }
        }
        val weakestMelee = armedEnemies.minByOrNull { it.hits }
        // МЁРТВЫЙ meleeCommit УДАЛЁН (v214). Правило v143 обещало: мили идёт вплотную, только когда цель
        // добивается этим тиком или у нас перевес по силе, — но переменная была ОБЪЯВЛЕНА И НИКЕМ НЕ ЧИТАЛАСЬ,
        // то есть обещанного не было вовсе, и тумблер USE_MELEE_COMMIT не гейтил ничего. Оба её слагаемых теперь
        // есть в лучшем виде: перевес — местный (см. spotEdgeAt, поле удара в клетке врага, а не мощь армии),
        // добиваемость — killTicks/killableNow, которыми уже пользуется фокус. Замеры из прежнего комментария
        // перенесены в docs/pain-and-gain.md.
        val hisMelee = armedEnemies.filter { InfluenceMap.profileOf(it).melee > 0.0 }
        // СОГЛАСОВАННОСТЬ СТРОЯ (v200, оператор: «все ходы должны быть согласованными... не должно быть такого, что
        // наш крип пошёл в наступление без прикрытия; командир не должен отправлять крипов в строй врага, если он там
        // может сильно пострадать и без возможности быть вылеченным»). Клетка крипа считается ОТНОСИТЕЛЬНО уже
        // назначенных клеток остальных, а не их нынешних позиций: иначе «согласованность» сравнивает план с прошлым
        fun cellOf(f: Creep): Position = out[f.id] ?: InfluenceMap.cell(f.x, f.y)
        fun foeDist(x: Int, y: Int) = armedEnemies.minOfOrNull { maxOf(abs(x - it.x), abs(y - it.y)) } ?: 99
        val melees = fighters.filter { hasWeapon(it) && hasMelee(it) && !hasRanged(it) }
        val rangeds = fighters.filter { hasWeapon(it) && hasRanged(it) }
        val healers = fighters.filter { !hasWeapon(it) && hasHeal(it) }
        // РАЗДЕТЫЕ ТОЖЕ ПОД ПРИКАЗОМ (v144): крип, потерявший все боевые части, не попадал НИ В ОДНУ группу — ни
        // оружия, ни лечения, — и приказа не получал вовсе, оставаясь стоять под огнём. Диагноз называл это в каждом
        // разборе: наши раздетые в трёх клетках от его вооружённых 172 крипо-тика из 238, у него 7 из 11
        val stripped = fighters.filter { !hasWeapon(it) && !hasHeal(it) }
        // ...и замысел может быть СВОЙ у каждого крипа (v139, портфельный поиск): армия смешивает поведение
        fun intentOf(c: Creep) = per?.get(c.id) ?: intent
        // клетки лекарей — прибор согласованности `mheal` ниже: сколько мили осталось в дальности лечения
        val healerCells = healers.map { InfluenceMap.cell(it.x, it.y) }
        // ==================== ОЦЕНКА КЛЕТКИ ПОЛЕМ (v206, этап 6) ====================
        // Заменяет собой отборы `safeForRanged`, `behindMelee`, `behindLine`, `inHealReach` и россыпь ранговых
        // формул. Все они говорили ЗАПРЕТАМИ то, что является предпочтением, и потому запирали друг друга:
        // v200 нашёл круг, где «стрелок не впереди мили» и «мили стоит позади» вместе выталкивали стрелка за
        // дальность выстрела, отбор пустел, и крип падал в общий добор, который про дальность не знает вовсе.
        // Запрет здесь ровно один и он о жизни: клетка, где крип не переживёт хода.
        InfluenceMap.clearClaim()
        InfluenceMap.stampHealNeed(army.filter { it.hits > 0 })
        var maxV = 0.0
        for ((k, _) in cells) {
            val v = InfluenceMap.vulnerabilityOf(k)
            if (v > maxV) maxV = v
        }
        // ГДЕ ФРОНТ ПРОСЕДАЕТ: уязвимость (2·min(наши, его)) выделяет линию контакта, влияние (наши − его)
        // говорит, чья она. Проседание — участок линии, где влияние отрицательно, то есть где нас продавливают
        fun sagAt(key: Int): Double {
            if (maxV <= 0.0) return 0.0
            if (InfluenceMap.vulnerabilityOf(key) < FRONT_RIDGE * maxV) return 0.0
            return maxOf(0.0, -InfluenceMap.influenceOf(key))
        }
        // тела своих вокруг клетки — по УЖЕ НАЗНАЧЕННЫМ клеткам, а не по нынешним позициям: план сравнивается
        // с планом, иначе «согласованность» сравнивает будущее с прошлым
        fun screenAt(c: Creep, p: Position): Int = fighters.count { f ->
            f.id != c.id && cellOf(f).let { maxOf(abs(it.x - p.x), abs(it.y - p.y)) <= 1 } }
        /**
         * ВОРОТА — ВЫЖИВАЕМОСТЬ КРИПА, А НЕ СРАВНЕНИЕ СИЛ. Прежнее `netDamageAt·2 > hits` истинно для КАЖДОЙ
         * клетки фронта (наш мили 1600 хитов против его полного блока даёт 2520), и это ровно записанный в
         * доках провал «трое мили развернулись спиной в первый тик контакта». Здесь считается, сколько тиков
         * крип проживёт в клетке: экран своих тел входит ДЕЛИТЕЛЕМ входящего, лечение — вычитаемым, и на
         * собственное лечение уходящий крип не рассчитывает.
         */
        fun ttlAt(c: Creep, key: Int, p: Position): Double {
            val e = danOf(c, key)
            if (e <= 0.0) return 99.0
            val heal = maxOf(0.0, InfluenceMap.healReachAt(key) - InfluenceMap.healFromSelf(c, p.x, p.y))
            val net = maxOf(0.0, e - heal) / (1.0 + SCREEN_SHARE * screenAt(c, p))
            return if (net <= 1.0) 99.0 else c.hits / net
        }
        val weakestFoe = armedEnemies.minByOrNull { it.hits }
        fun stayBonus(c: Creep, p: Position) = if (p.x == c.x && p.y == c.y) STAY_BONUS else 0.0
        // МИЛИ: к тому, что достанет ногами; по гребню фронта и туда, где он проседает; не выходя из-под лечения.
        // «Не выходя из-под лечения» было ЗАПРЕТОМ (inHealReach) и потому либо не давало клеток вовсе, либо
        // отбрасывалось молча; здесь это слагаемое, и оно конкурирует с притяжением честно
        fun scoreMelee(c: Creep, key: Int, p: Position, att: Double, dan: Double, focus: Creep?): Double {
            val pull = if (focus != null) InfluenceMap.attractionTo(focus, p.x, p.y, true) else InfluenceMap.attMeleeAt(key)
            return -W_ATT * att * pull + W_DAN * dan * danOf(c, key) -
                W_FRONT * InfluenceMap.vulnerabilityOf(key) - W_SAG * sagAt(key) -
                W_HEALCOVER * InfluenceMap.healReachAt(key) +
                CLAIM_COST * InfluenceMap.claimAt(key) - stayBonus(c, p)
        }
        // СТРЕЛОК: притяжение с пиком на дальности 3 (он останавливается сам, вместо запрета «не ближе мили»),
        // плюс влияние — стоять там, где сильнее мы. Это и есть «не быть первой линией», сказанное числом
        fun scoreRanged(c: Creep, key: Int, p: Position, att: Double, dan: Double, focus: Creep?): Double {
            val pull = if (focus != null) InfluenceMap.attractionTo(focus, p.x, p.y, false) else InfluenceMap.attRangedAt(key)
            return -W_ATT * att * pull + W_DAN * dan * danOf(c, key) -
                W_LINE * InfluenceMap.influenceOf(key) +
                CLAIM_COST * InfluenceMap.claimAt(key) - stayBonus(c, p)
        }
        // ЛЕКАРЬ: тянется туда, где помощь ВЕРОЯТНЕЕ ВСЕГО ПОНАДОБИТСЯ (нужда = опасность в клетке подопечного,
        // а не его нынешняя рана — прежнее правило брало раненых, то есть по определению тех, кто уже на фронте,
        // и тянуло лекаря вперёд). Смотрит на огонь ЭТИМ тиком, а не на E: иначе клетка рядом с подопечным,
        // которого уже рубят, читается как 720 опасности и выталкивает лекаря на три клетки
        fun scoreHeal(c: Creep, key: Int, p: Position, att: Double, dan: Double): Double {
            val scr = screenAt(c, p)
            val fire = InfluenceMap.fireFieldAt(key)
            val shielded = fire * (1.0 - 1.0 / (1.0 + SCREEN_SHARE * scr))   // урон, который снимут тела своих
            // ПРИТЯЖЕНИЕ ЛЕКАРЯ НАСЫЩАЕТСЯ ТЕМ, ЧТО ОН МОЖЕТ ДОСТАВИТЬ (v208, замер серии v206: лекарей за линией
            // 0.695 против 0.944 у v205 — они полезли в первую линию). Нужда складывается по всем подопечным в
            // радиусе и не ограничена ничем, поэтому доходила до тысяч против сотен опасности, и лекарь нырял в
            // рубку. Но доставить он может только своё лечение за тик: 72 у полного h6m6. Мягкое насыщение
            // deliver·att/(att + deliver) сохраняет ФОРМУ поля (порядок клеток тот же) и ставит потолок в тех же
            // единицах, что и урон. Тогда оценка лекаря честно читается как «доставленное лечение минус
            // полученный урон», и клетка под огнём в 500 ради 72 лечения проигрывает сама, без запрета
            val deliver = InfluenceMap.healOf(c)
            val raw = InfluenceMap.attHealAt(key)
            // ...И ПРИТЯЖЕНИЕ — ЭТО ТО, ЧТО ОН ДОСТАВИТ ИЗ ЭТОЙ КЛЕТКИ (v224, см. USE_HEAL_PULL_DELIVERED): лучший
            // подопечный, а не насыщенная сумма — у суммы при нужде в тысячи нет разницы между «вплотную» и «в двух»
            val pull = if (deliver <= 0.0 || raw <= 0.0) 0.0 else deliver * raw / (raw + deliver)
            // ...И БЕЗ СЛАГАЕМОГО ВЛИЯНИЯ (v224, третья редакция, см. USE_HEALER_NO_LINE): у лекаря оно тянет туда, где
            // наш залп гуще, — в глубину строя, от бойца первой линии; зонд назвал его единственным решающим
            // ...И ПРИ УДЕРЖИМОЙ ЖЕРТВЕ ЦЕНА КЛЕТКИ — ДОСТАВЛЕННОЕ В НЕЁ ЛЕЧЕНИЕ (v228, см. USE_HEAL_WALL): вплотную полное, в трёх
            // треть, без насыщенной суммы и без слагаемого влияния — клетка вплотную к жертве получает положительную цену, которой
            // обе редакции v224 ей дать не смогли (72 против 24)
            val victim = victimNow
            if (victimSaveable && victim != null) {
                val d = getRange(p, victim)
                val wall = if (d <= 1 && wallCells.any { it.x == p.x && it.y == p.y }) deliver else if (d <= HEAL_RANGE) deliver / 3.0 else 0.0
                return -W_ATT * att * wall + W_DAN * dan * fire - W_SCREEN * shielded + CLAIM_COST * InfluenceMap.claimAt(key) - stayBonus(c, p)
            }
            return -W_ATT * att * pull + W_DAN * dan * fire -
                (W_LINE * InfluenceMap.influenceOf(key)) - W_SCREEN * shielded +
                CLAIM_COST * InfluenceMap.claimAt(key) - stayBonus(c, p)
        }
        /**
         * ЗАМЫСЕЛ = ВЕКТОР ВЕСОВ над одной оценкой: множитель притяжения, множитель опасности, порог выживания.
         * Пять веток `when` на роль превращаются в пять троек чисел — этап 8 проверит, окупается ли перебор.
         */
        fun weightsOf(i: Intent): Triple<Double, Double, Int> = when (i) {
            Intent.PRESS -> Triple(1.5, 0.7, 2)
            Intent.HOLD -> Triple(1.0, 1.0, 3)
            Intent.YIELD -> Triple(0.3, 2.0, 5)
            Intent.FOCUS -> Triple(1.5, 0.7, 2)
            Intent.KITE -> Triple(1.0, 1.3, 3)
        }
        /**
         * Раздача по оценке с МЯГКИМИ воротами: порог выживания снижается по лестнице, пока клетка не найдётся,
         * и уровень записывается счётчиком. Сегодняшний молчаливый провал требования в общий добор становится
         * печатаемым числом — `gate=...`. Ниже единицы порог не опускается: клетка, где крип умирает за ход,
         * не предлагается никогда.
         */
        fun placeScored(c: Creep, role: Int, i: Intent): Boolean {
            val (att, dan, ttlMin) = weightsOf(i)
            // ПРЕСЛЕДОВАТЕЛЬ СМОТРИТ НА СВОЙ ОСТОВ (v211) — тем же полем притяжения, что и фокус: у мили пик
            // вплотную, у стрелка на дальности три. Отдельной формулы у погони нет и не нужно
            val chased = Memory.chaseTarget[c.id]
            // ...и ЦЕЛЬ ПАЧКИ МИЛИ во всех замыслах (v221, см. USE_MELEE_PACK_CELLS): притяжение к одной его цели
            // вместо суммы по всем — четыре мили в одну клетку-соседа, а не каждый к своей
            val focus = chased ?: (null)
                ?: if (i == Intent.FOCUS) (if (role == 0) weakestMelee else weakestFoe) else null
            val kite = i == Intent.KITE
            val rank = { p: Position ->
                val key = p.x * 100 + p.y
                when (role) {
                    0 -> scoreMelee(c, key, p, att, dan, focus)
                    1 -> scoreRanged(c, key, p, att, dan, focus)
                    else -> scoreHeal(c, key, p, att, dan)
                }
            }
            for (lvl in ttlMin downTo 1) {
                val ok = place(c, { p ->
                    (!kite || hisMelee.isEmpty() || hisMelee.minOf { getRange(p, it) } >= MELEE_HOLD_RANGE) &&
                        ttlAt(c, p.x * 100 + p.y, p) >= lvl
                }, rank)
                if (ok) { gateLevels[minOf(lvl, gateLevels.size - 1)]++; return true }
            }
            gateFell++
            return false
        }
        passTag = "melee"
        // мили: по замыслу — вплотную к его вооружённому (напор), в самую безопасную клетку с целью (удержание) или
        // как можно дальше от его мили (уступка); среди равных всегда меньше входящего на следующий тик
        for (c in melees.sortedBy { c -> armedEnemies.minOfOrNull { getRange(c, it) } ?: 99 }) {
            val ok = placeScored(c, 0, intentOf(c))
            // ДОБОР МИЛИ ПОМЕНЯЛ СМЫСЛ ВМЕСТЕ С ВОРОТАМИ (v208). Прежде `ok = false` значило «нет клетки вплотную
            // к его вооружённому, куда дотягивается лекарь», и шаг к врагу был верным ответом. С воротами
            // выживания `ok = false` значит «нет клетки, где я переживу ход», и тот же шаг посылает крипа
            // умирать: на стенде этот добор срабатывает в 3 % размещений. Ответ обратный — самая безопасная
            if (!ok) place(c, { true }, { p -> danOf(c, p.x * 100 + p.y) })
        }
        passTag = "ranged"
        // стрелки: цель в дальности, меньше всего входящего на следующий тик; при равенстве — дальше от его мили
        for (c in rangeds.sortedBy { c -> cells.values.count { p -> getRange(c, p) <= 2 && armedEnemies.any { getRange(p, it) <= RANGED_RANGE } } }) {
            val ok = placeScored(c, 1, intentOf(c))
            // ...и КОГДА ВЫБОРА НЕТ, СТРЕЛОК ВЫХОДИТ ИЗ-ПОД МИЛИ, А НЕ ОСТАЁТСЯ СТРЕЛЯТЬ (v183, оператор: «рэнжи не
            // должны быть рядом с его мили»). Все замыслы требуют разом двух вещей — быть вне досягаемости его мили и
            // при этом доставать цель, — а такой клетки рядом с его строем часто нет вовсе, и общий фолбэк «любая
            // клетка, где меньше входящего» оставлял стрелка под ударом: замер тестовой игры 3d95be — наши стрелки в
            // одной клетке от его вооружённого 28 крипо-тиков и в двух ещё 31 из 117. Между «выстрелить» и «уцелеть»
            // выбирается уцелеть: выстрел стоит 60, стрелок — 1 200
            if (c.id !in out) place(c, { true }, { p -> danOf(c, p.x * 100 + p.y) })
        }
        // лекари: в лечебной дальности от раненого бойца, вне огня следующего тика
        passTag = "healer"
        for (c in healers) {
            // ЛЕКАРЬ ПРИ БОЙЦЕ (v142): близость главная, опасность лишь тай-брейк — прежний порядок весил опасность
            // стократно, и лекарь уходил в безопасную клетку ВНЕ дальности лечения; фолбэк вёл его туда же
            // ...и САМАЯ БЕЗОПАСНАЯ ИЗ ТЕХ, ОТКУДА ДОСТАЁТ (v183). Ранг вёл лекаря к БЛИЖАЙШЕМУ раненому (дистанция
            // ×100, опасность — тай-брейк), а ближайший раненый — тот, кто в контакте, поэтому лекарь шёл в рубку.
            // Замер тестовой игры 3d95ad: наши лекари в трёх клетках от его вооружённого 84 крипо-тика из 107 (78 %),
            // его — 64 из 129 (49 %); вплотную наши 21 против его 4, выстрелов по нашим лекарям 52 против 18 по его.
            // Первым умирал лекарь (t=64), и с ним рассыпался весь бой. Условие «достаёт» уже задано отбором клеток
            // (HEAL_RANGE − 1 с запасом на его шаг), поэтому внутри отбора решать должна опасность, а не близость —
            // прежний вариант с опасностью ×100 (USE_HEALERS_CLOSE=false) уводил лекаря ВНЕ дальности, потому что
            // менял вместе с рангом и сам отбор
            // ...и «безопасная» НЕ ЗНАЧИТ «на краю дальности»: вплотную лекарь лечит вчетверо сильнее, чем издали, и
            // ранг по одной опасности выталкивал его на два шага, где лечение падает втрое, — сценарий brawl+heals
            // проседал 12 056:17 958. Порядок такой же, как у него: сперва клетка ВПЛОТНУЮ К СВОЕМУ (полное лечение),
            // и среди таких — самая безопасная. Его лекари стоят рядом со своими стрелками 60 % крипо-тиков и при
            // этом в трёх клетках от наших вооружённых лишь 49 % — быть при своих и быть под огнём это разные вещи
            // ЛЕКАРЬ СТОИТ ПРИКРЫТЫМ, А НЕ В ПУСТОЙ КЛЕТКЕ (v186, разбор Coldkimchi#2). Тело лекаря — `h6m6`, лечащие
            // части СПЕРЕДИ, поэтому урон уничтожает именно их и делает это первыми. Замер разгрома 3d97c4: у обеих
            // сторон одно и то же тело, его лекари сохраняют лечащие части 804 крипо-тика из 804 (100 %), наши — 72
            // из 804 (8 %). К семидесятому тику двое наших из трёх уже без лечения вовсе, и дальше армия тает: лечение
            // за бой 4 604 против его 14 256, он заканчивает матч с 16 000 из 16 000 хитов, не потеряв ничего.
            // Разница не в открытости, а в ПРИКРЫТИИ: его лекари стоят ВНУТРИ строя (рядом с мили 86 % крипо-тиков,
            // со стрелками 63 %), наши — на фланге (16 % и 15 %) при глубине −2,7 и разбросе 3,6. «Самая безопасная
            // клетка» (v183) как раз и уводила их на фланг: пустая клетка безопаснее по входящему, но её достаёт его
            // стрелок, а тела своих не заслоняют. Здесь считается число СВОИХ вплотную — тех, кто примет выстрел
            // ЛЕКАРЬ НЕ ВСТАЁТ ВПЕРЕДИ СТРОЯ (v200, оператор): «наши хилеры оказались в первой линии и моментально
            // получили несколько выстрелов и потеряли возможность лечения». Экран (v186) считает ТЕЛА вокруг клетки и
            // ничего не знает о глубине, а `mates` — это раненые, то есть ровно те, кто на фронте: ранг тянул лекаря
            // вперёд по построению. Замер реплея 3d9943: глубина по оси на врага у мили −1,35, у стрелков +0,68, у
            // ЛЕКАРЕЙ +0,32 — они впереди мили, и в 155 тиках из 335 лекари в среднем ближе к врагу, чем мили; на
            // t=63, через три тика после контакта, один лекарь уже без лечащих частей. Условие простое и жёсткое:
            // хотя бы один свой боец стоит к врагу БЛИЖЕ, чем клетка лекаря, — считая по уже назначенным клеткам
            val ok = placeScored(c, 2, intentOf(c)).also { placed ->
                if (placed) out[c.id]?.let { InfluenceMap.saturateHeal(c, it.x, it.y, army.filter { a -> a.hits > 0 }) }
            }
            // ...и добор тоже вне досягаемости, пока такая клетка есть (v234)
            if (c.id !in out) place(c, { true }, { p -> danOf(c, p.x * 100 + p.y) })
            // ЗОНД РАЗДАЧИ ЛЕКАРЕЙ (v224, `hpick=`): по реплеям обеих сторон его лекари стоят вплотную к крипу под нашим
            // огнём 37 % лекаре-тиков, наши — 10 %, и в FIGHT свободная клетка вплотную к бойцу не опаснее своей есть в
            // 30–51 % лекаре-тиков. Зонд отвечает, какое слагаемое оценки увело лекаря от такой клетки: считает те же
            // слагаемые, что scoreHeal и place, для выбранной клетки и для лучшего свободного кандидата вплотную к бойцу
            // вне его стрелкового огня, и копит разницу «выбранная минус кандидат» по слагаемым
            run {
                val b = out[c.id] ?: return@run
                val (att, dan, ttlMin) = weightsOf(intentOf(c))
                // кандидат — вплотную к бойцу ПЕРВОЙ ЛИНИИ (его клетка в его стрелковом огне) и сам вне огня: первое
                // чтение зонда (4 игры) показало, что «вплотную к любому бойцу вне огня» выбирается в 63 % раздач — строй
                // глубокий, боец рядом есть всегда, — а к тому, кого бьют, лекарь по реплеям стоит в 10 %
                fun adjSafe(p: Position): Boolean = foeDist(p.x, p.y) > RANGED_RANGE &&
                    fighters.any { f -> f.id != c.id && hasWeapon(f) && cellOf(f).let { foeDist(it.x, it.y) <= RANGED_RANGE && maxOf(abs(it.x - p.x), abs(it.y - p.y)) <= 1 } }
                fun terms(p: Position): DoubleArray {
                    val key = p.x * 100 + p.y
                    val scr = screenAt(c, p)
                    val fire = InfluenceMap.fireFieldAt(key)
                    val shielded = fire * (1.0 - 1.0 / (1.0 + SCREEN_SHARE * scr))
                    val deliver = InfluenceMap.healOf(c)
                    val raw = InfluenceMap.attHealAt(key)
                    val pull = if (deliver <= 0.0 || raw <= 0.0) 0.0 else deliver * raw / (raw + deliver)
                    val self = p.x == c.x && p.y == c.y
                    val tenant = if (self) null else allyOf[key]?.takeIf { t -> t.id != c.id && (t.id !in out || out[t.id]?.let { it.x == t.x && it.y == t.y } == true) }
                    return doubleArrayOf(-W_ATT * att * pull, W_DAN * dan * fire, -W_LINE * InfluenceMap.influenceOf(key),
                        -W_SCREEN * shielded, CLAIM_COST * InfluenceMap.claimAt(key), -stayBonus(c, p),
                        if (tenant != null) ALLY_CELL_COST else 0.0, GOAL_STEP_COST * goalCost(key))
                }
                hpN++
                if (adjSafe(b)) { hpAdj++; return@run }
                var best: Position? = null; var bestSc = Double.MAX_VALUE; var gated = 0
                for ((key, p) in nearCells(c)) {
                    if (p.x == b.x && p.y == b.y) continue
                    if (key in taken || !adjSafe(p)) continue
                    if (allyOf[key] != null && !(p.x == c.x && p.y == c.y)) continue
                    if (ttlAt(c, key, p) < ttlMin) { gated++; continue }
                    val sc = terms(p).sum()
                    if (sc < bestSc) { bestSc = sc; best = p }
                }
                val a = best
                if (a == null) { if (gated > 0) hpGate++; return@run }
                hpAvail++
                val tb = terms(b); val ta = terms(a)
                for (i in tb.indices) hpDelta[i] += tb[i] - ta[i]
            }
        }
        // ХРАНИТЕЛЬ ФЛАГА — ПО ПРИКАЗУ (v174): крип на НАШЕМ флаге стоит по приказу командира, а не по отдельной ветке
        // удержания; снять его может только командир — решив собрать отряд — или опасность, которая приходит приказом
        for (c in fighters) {
            if (c.id in out) continue
            // ...и клетку, уже отданную кому-то приказом, хранитель не занимает повторно: без этой проверки одна
            // клетка доставалась двоим — прибор ловил это как clash=1 (v176)
            val key = c.x * 100 + c.y
            if (ourFlagCells.contains(key) && key !in taken) { taken.add(key); out[c.id] = InfluenceMap.cell(c.x, c.y) }
        }
        // раздетые: прочь из огня — в бою от них пользы нет, а его выстрелы они на себя собирают исправно
        passTag = "stripped"
        for (c in stripped)
            place(c, { true }, { p -> danOf(c, p.x * 100 + p.y) * 100 -
                (armedEnemies.minOfOrNull { getRange(p, it) } ?: 0).toDouble() })
        // ...и ВООРУЖЁННЫЙ не остаётся без места (v165): расстановка при командире молчит, и тот, кому клетки не
        // хватило, уходил по общим веткам — гейт ловил это как уничтоженную армию (match32:army). Лекарей и раздетых
        // этот добор не трогает: у них свои назначения выше, и перехват их портил (133 из 135)
        passTag = "catchall"
        for (c in melees + rangeds) {
            if (c.id in out) continue
            place(c, { true }, { p -> danOf(c, p.x * 100 + p.y) * 10 +
                maxOf(abs(p.x - c.x), abs(p.y - c.y)).toDouble() })
        }
        // ПРИБОР СОГЛАСОВАННОСТИ (v200): меряется РЕЗУЛЬТАТ раздачи, а не факт вызова правила — сколько стрелков
        // получили клетку с целью в дальности, сколько мили остались в дальности лечения, сколько лекарей стоят за
        // линией. Три числа отвечают ровно на три замечания оператора и видны в строке `t=` каждым тиком
        planGunsAll = rangeds.size
        planGunsIn = rangeds.count { c -> out[c.id]?.let { p -> armedEnemies.any { e -> getRange(p, e) <= RANGED_RANGE } } == true }
        planMeleeAll = melees.size
        planMeleeHealed = melees.count { c -> out[c.id]?.let { p -> healerCells.any { h -> maxOf(abs(p.x - h.x), abs(p.y - h.y)) <= HEAL_RANGE } } == true }
        planHealAll = healers.size
        planHealBehind = healers.count { c ->
            val p = out[c.id] ?: return@count false
            val dp = foeDist(p.x, p.y)
            fighters.any { f -> f.id != c.id && hasWeapon(f) && cellOf(f).let { foeDist(it.x, it.y) } < dp }
        }
    }

    /** Мини-состояние для симуляции (v138): позиция, хиты и профиль крипа. */

    private fun planBlock(army: List<Creep>, combatEnemies: List<Creep>, armedEnemies: List<Creep>, slotOf: MutableMap<String, Position>) {
        val melees = army.filter { hasWeapon(it) && hasMelee(it) && !hasRanged(it) && it.id !in Memory.rotatingIds }
        val rangeds = army.filter { hasWeapon(it) && hasRanged(it) && it.id !in Memory.rotatingIds }
        val rear = army.filter { c -> melees.none { it.id == c.id } && rangeds.none { it.id == c.id } }
        val armed = melees + rangeds
        if (armed.isEmpty()) return
        val threats = armedEnemies.ifEmpty { combatEnemies }
        // его первый ряд — стрелки (v113, USE_RANGED_FRONT_VS_RANGED): ближайший к нашему фронту его вооружённый — стрелок без мили,
        // и это БЛОБ — не меньше RANGED_FRONT_GROUP его вооружённых в ENGAGE_RANGE от него (первый срез без этого условия включал
        // ряд вровень против гарнизона-стрелка россыпи: гейт m30 scatter 21613:24313 красный)
        // ...и блоб ПОДХОДИТ САМ — его темп к нам за окно подхода не ниже темпа броска (approachRate, см. APPROACH_RUSH) — либо ряд уже
        // защёлкнут этим контактом: стоящий у флага лагерь (гейт m31 camp 15105:22908 красный при ряде вровень против любого блоба,
        // и тот же счёт при «дистанция сократилась» — она сокращается и от нашего марша к лагерю) — не вход в рубку, там игра на очки
        // approachRate — темп сокращения дистанции центров, он растёт и от НАШЕГО марша к стоящему лагерю (m31 camp красный при
        // «сокращается» и при approachRate): нужен сдвиг ЕГО центра за окно — не меньше четверти окна (v57: «это он уходит»)
        val hisMoved = Memory.hisCentHist.size >= 2 && run {
            val a = Memory.hisCentHist.first(); val b = Memory.hisCentHist.last()
            maxOf(abs(a / 100 - b / 100), abs(a % 100 - b % 100)) >= APPROACH_WINDOW / 4
        }
        val closing = approachRate >= APPROACH_RUSH && hisMoved
        val inReach = threats.any { e -> armed.any { getRange(it, e) <= ENGAGE_RANGE } }
        if (!inReach) rangedLevelLatched = false
        // ...и это уже ВХОД: его ближайший в RANGED_RANGE + 1 от нашего фронта — проходящий мимо на 5–8 блоб-фермер (m31 camp,
        // тот же счёт при любом признаке подхода) ряда не получает
        val hisFrontRanged =  (closing || rangedLevelLatched) && threats.minByOrNull { e -> armed.minOf { getRange(it, e) } }
            ?.let { n -> val pr = InfluenceMap.profileOf(n); pr.ranged > 0.0 && pr.melee <= 0.0 && armed.minOf { getRange(it, n) } <= RANGED_RANGE + 1 && threats.count { getRange(n, it) <= ENGAGE_RANGE } >= RANGED_FRONT_GROUP } == true
        if (hisFrontRanged && inReach) rangedLevelLatched = true
        Formation.rows(melees, rangeds, rear, threats, combatEnemies, standoffLine = rangeds.isNotEmpty() && hisFrontRanged, slotOf)
    }

